/* 자동 생성 파일 — 직접 수정하지 마세요. data-src/gua_NN.json 을 고친 뒤 node data-src/build-yijing-data.js */
const YIJING_DATA = {"version":1,"guas":{"1":{"n":1,"name":"건위천","han":"乾爲天","upper":"건","lower":"건","upperHan":"乾","lowerHan":"乾","bits":[1,1,1,1,1,1],"binary":"111111","gua":{"text":"元亨利貞","reading":"원형이정","modern":"크게 형통하고, 이로우며, 곧고 바릅니다.","symbol":"하늘 위에 하늘이 거듭된 괘로, 순수한 양의 기운이 끝없이 뻗어 나가는 창조와 추진의 힘을 뜻합니다.","situation":"스스로 방향을 정하고 일을 열어 가야 하는 국면입니다. 시작하는 힘, 성장하는 힘, 결실을 맺는 힘이 한 흐름으로 이어지는 때라서 주도권이 내게 있다는 느낌이 들기 쉽습니다. 그만큼 책임도 함께 커집니다.","positive":"의욕과 추진력이 충분하고 큰 뜻을 세우기에 알맞은 시기입니다. 바른 목표를 잡으면 힘이 한 방향으로 모이기 쉽습니다.","caution":"강함만 믿고 밀어붙이면 독단으로 흐르거나 주변과 부딪힐 수 있습니다. 잘 풀릴수록 속도와 겸손을 점검하세요.","direction":"단계마다 알맞게 움직이는 것이 이 괘의 조언입니다. 때가 아니면 힘을 아끼고, 때가 오면 과감히 나서며, 정상에 가까울수록 한 걸음 물러서서 전체를 살펴보세요.","message":"바른 뜻을 세우고 때에 맞게 힘을 쓰세요."},"yao":[{"guaN":1,"guaName":"건위천","pos":1,"label":"初九","yinyang":"yang","text":"潛龍勿用","reading":"잠룡물용","modern":"물속에 잠긴 용이니 쓰지 않습니다.","meaning":"용이 아직 물속에 숨어 있는 맨 아래 단계로, 재능과 가능성은 크지만 드러낼 때가 아닌 시작의 자리입니다.","positive":"조급해하지 않고 실력과 뜻을 속으로 키울 수 있는 귀한 준비 기간입니다.","caution":"서둘러 나서면 아직 덜 여문 힘이 꺾이기 쉽고, 기다림이 답답하다고 흔들리면 방향을 잃을 수 있습니다.","advice":"당장 성과를 내려 하기보다 기본기와 계획을 다지세요. 눈에 띄지 않아도 꾸준히 준비해 두는 편이 도움이 됩니다.","message":"드러낼 때를 기다리며 힘을 기르세요."},{"guaN":1,"guaName":"건위천","pos":2,"label":"九二","yinyang":"yang","text":"見龍在田 利見大人","reading":"현룡재전 리견대인","modern":"용이 밭에 나타났으니, 훌륭한 사람을 만나면 이롭습니다.","meaning":"아래 괘의 한가운데에 놓여, 재능이 처음 세상에 모습을 드러내고 인정받기 시작하는 단계입니다.","positive":"실력을 알아보는 사람이나 이끌어 줄 멘토를 만나 배움과 기회가 넓어지기 쉬운 때입니다.","caution":"아직 높은 자리가 아니므로 드러난 것에 들떠 과시하면 신뢰를 잃을 수 있습니다.","advice":"믿고 배울 만한 사람을 찾아 가르침을 구하고, 말과 행동을 성실하게 이어 가세요.","message":"눈 밝은 이를 만나 배우고 드러내세요."},{"guaN":1,"guaName":"건위천","pos":3,"label":"九三","yinyang":"yang","text":"君子終日乾乾 夕惕若厲 无咎","reading":"군자종일건건 석척약려 무구","modern":"군자가 하루 종일 힘써 노력하고 저녁에도 조심하며 두려워하면, 위태로워도 허물이 없습니다.","meaning":"아래 괘의 끝이자 위 괘로 넘어가는 전환기입니다. 책임이 커지고 압박도 가장 큰, 쉬기 어려운 자리입니다.","positive":"긴장을 늦추지 않고 하루를 돌아보는 자세를 지키면 큰 위험을 피해 가기 쉽습니다.","caution":"과로하거나 무리하게 속도를 내면 몸과 관계가 함께 상할 수 있고, 위아래 어느 쪽에서도 애매한 처지가 되기 쉽습니다.","advice":"낮에는 성실히 일하고 저녁에는 하루를 점검하세요. 쉬는 시간도 일정에 넣어 오래 가는 페이스를 만드세요.","message":"부지런히 하되 밤에는 돌아보세요."},{"guaN":1,"guaName":"건위천","pos":4,"label":"九四","yinyang":"yang","text":"或躍在淵 无咎","reading":"혹약재연 무구","modern":"혹 뛰어오르기도 하고 연못에 머물기도 하니, 허물이 없습니다.","meaning":"위 괘의 첫 자리로 높은 곳 가까이에 이르렀으나, 아직 하늘로 오를지 물러설지 선택해 볼 수 있는 경계의 단계입니다.","positive":"시험 삼아 도전해 보고 아니다 싶으면 물러설 수 있는 유연함이 있어 부담이 덜합니다.","caution":"확신 없이 크게 걸거나, 반대로 계속 망설이기만 하면 좋은 기회를 놓치기 쉽습니다.","advice":"작게 시도해 반응을 확인한 뒤 키울지 정하세요. 도전과 후퇴의 기준을 미리 정해 두면 마음이 편합니다.","message":"작게 시도하고 신중히 판단하세요."},{"guaN":1,"guaName":"건위천","pos":5,"label":"九五","yinyang":"yang","text":"飛龍在天 利見大人","reading":"비룡재천 리견대인","modern":"용이 하늘을 나니, 훌륭한 사람을 만나면 이롭습니다.","meaning":"위 괘의 한가운데이자 가장 중심이 되는 자리로, 능력과 지위가 맞아 뜻을 크게 펼칠 수 있는 단계입니다.","positive":"영향력이 커지고 사람들이 따르기 쉬워서 큰 일을 이끌기에 알맞은 때입니다.","caution":"자리가 높아질수록 판단의 무게도 커지므로 독선이나 자만에 빠지면 주변이 등을 돌릴 수 있습니다.","advice":"넓은 시야로 다양한 의견을 들으며 공정하게 이끄세요. 함께할 인재와 조언자를 곁에 두는 것이 도움이 됩니다.","message":"높은 자리일수록 널리 듣고 이끄세요."},{"guaN":1,"guaName":"건위천","pos":6,"label":"上九","yinyang":"yang","text":"亢龍有悔","reading":"항룡유회","modern":"너무 높이 오른 용은 후회가 있습니다.","meaning":"가장 높은 끝자리로, 힘이 극에 이르러 더 오를 곳이 없는 상태입니다. 지나침과 고립을 경계하는 자리입니다.","positive":"정점에서 한 걸음 물러서 돌아볼 줄 알면 다음 흐름을 준비할 여유가 생깁니다.","caution":"더 높이, 더 많이를 고집하면 사람들과 멀어지고 오히려 있던 것을 잃을 수 있습니다.","advice":"욕심을 내려놓고 성과를 나누며 마무리를 준비하세요. 새로운 시작을 위해 비워 둘 자리를 만들어 두면 좋습니다.","message":"가득 찼다면 물러설 줄도 아세요."}],"yong":{"guaN":1,"guaName":"건위천","label":"用九","yinyang":"yang","text":"見羣龍无首 吉","reading":"견군룡무수 길","modern":"여러 용이 나타났으나 우두머리가 되지 않으니 길합니다.","meaning":"양의 여섯 효가 모두 움직여 변하는 경우를 가리키는 말입니다. 모두가 강한 힘을 지닌 상황에서 서로 앞서려 하지 않는 태도를 뜻합니다.","positive":"앞서려는 마음을 내려놓고 서로를 존중하면 강한 사람들이 모여도 조화를 이루기 쉽습니다.","caution":"모두가 자기가 으뜸이라 여기면 다툼이 생기고 힘이 흩어질 수 있습니다.","advice":"지위나 공을 앞세우지 말고 역할을 나누어 협력하세요. 내가 이끌어야 한다는 생각을 잠시 내려놓는 편이 도움이 됩니다.","message":"우두머리를 내세우지 않는 것이 지혜입니다."}},"2":{"n":2,"name":"곤위지","han":"坤爲地","upper":"곤","lower":"곤","upperHan":"坤","lowerHan":"坤","bits":[0,0,0,0,0,0],"binary":"000000","gua":{"text":"元亨 利牝馬之貞 君子有攸往 先迷後得主 利 西南得朋 東北喪朋 安貞吉","reading":"원형 리빈마지정 군자유유왕 선미후득주 리 서남득붕 동북상붕 안정길","modern":"크게 형통합니다. 암말처럼 유순하고 곧게 나아가는 것이 이롭습니다. 군자가 갈 곳이 있을 때 먼저 나서면 길을 잃고, 뒤따르면 주인을 얻어 이롭습니다. 서남쪽에서는 벗을 얻고 동북쪽에서는 벗을 잃으니, 편안하고 곧게 지키면 길합니다.","symbol":"땅 위에 땅이 거듭된 괘로, 만물을 품어 기르는 유순함과 포용, 따르고 받쳐 주는 힘을 뜻합니다.","situation":"앞에서 이끌기보다 받아들이고 뒷받침하는 쪽에서 힘이 나는 국면입니다. 서두르지 않고 순리를 따르며 기반을 다질수록 안정감이 생기기 쉽습니다. 협력할 사람과 환경을 어떻게 만나느냐가 중요한 때입니다.","positive":"인내와 포용, 협력으로 오래 버틸 바탕을 만들기에 좋습니다. 사람과 흐름을 받쳐 주면 신뢰가 쌓입니다.","caution":"소극적으로 끌려다니거나 주관 없이 따르기만 하면 힘이 소진될 수 있습니다. 순응과 방관은 다르다는 점을 기억하세요.","direction":"먼저 앞서기보다 때와 사람을 살피며 따르고 돕는 자세로 시작하세요. 믿을 만한 사람과 협력하되 스스로의 중심은 지키는 것이 좋습니다.","message":"부드럽게 받치고 순리를 따르세요."},"yao":[{"guaN":2,"guaName":"곤위지","pos":1,"label":"初六","yinyang":"yin","text":"履霜 堅冰至","reading":"리상 견빙지","modern":"서리를 밟으면 단단한 얼음이 곧 이르게 됩니다.","meaning":"맨 아래에서 변화의 작은 조짐이 나타나는 단계입니다. 서리는 아직 약하지만 겨울이 다가오고 있다는 신호입니다.","positive":"작은 징후를 일찍 알아차리면 대비할 시간을 얻을 수 있습니다.","caution":"사소하다고 넘기면 문제가 쌓여 나중에 다루기 어려워질 수 있습니다.","advice":"작은 변화나 불편한 신호를 가볍게 보지 말고 미리 살피고 정리해 두세요.","message":"작은 조짐에서 큰 흐름을 읽으세요."},{"guaN":2,"guaName":"곤위지","pos":2,"label":"六二","yinyang":"yin","text":"直方大 不習 无不利","reading":"직방대 불습 무불리","modern":"곧고 반듯하며 크니, 익히지 않아도 이롭지 않음이 없습니다.","meaning":"아래 괘의 한가운데로, 음의 자리에 음이 바르게 놓여 땅의 덕이 가장 자연스럽게 드러나는 단계입니다.","positive":"꾸미지 않고 곧고 성실하게 하면 따로 애쓰지 않아도 일이 순조롭게 풀리기 쉽습니다.","caution":"요령이나 계산을 앞세우면 이 자연스러운 힘이 흐려질 수 있습니다.","advice":"본래의 성실함과 정직함을 그대로 지키며 맡은 일을 꾸준히 해 나가세요.","message":"곧고 성실한 본바탕을 믿으세요."},{"guaN":2,"guaName":"곤위지","pos":3,"label":"六三","yinyang":"yin","text":"含章可貞 或從王事 无成有終","reading":"함장가정 혹종왕사 무성유종","modern":"아름다움을 안에 품고 곧게 지킬 수 있으니, 혹 나랏일을 따르더라도 이루었다 자랑하지 않고 끝을 맺습니다.","meaning":"아래 괘의 끝으로 능력이 드러나기 쉬운 자리입니다. 재능을 품되 윗사람을 돕는 역할에서 성과를 내세우지 않는 태도를 말합니다.","positive":"공을 앞세우지 않고 맡은 일을 끝까지 해내면 신뢰가 오래 남기 쉽습니다.","caution":"능력이 있다고 앞에 나서거나 성과를 독점하려 하면 질시를 받을 수 있습니다.","advice":"실력은 꾸준히 쌓되 드러내는 시기를 조절하세요. 성과는 팀과 나누고 마무리에 집중하는 편이 좋습니다.","message":"재능은 품고 공은 나누세요."},{"guaN":2,"guaName":"곤위지","pos":4,"label":"六四","yinyang":"yin","text":"括囊 无咎无譽","reading":"괄낭 무구무예","modern":"자루 주둥이를 묶어 두니, 허물도 없고 칭찬도 없습니다.","meaning":"위 괘의 첫 자리로 가까이 높은 이가 있어 말과 행동이 조심스러운 경계의 단계입니다. 입을 다무는 것이 곧 몸을 지키는 방법이 됩니다.","positive":"말을 아끼고 몸가짐을 조심하면 불필요한 구설과 위험을 줄일 수 있습니다.","caution":"지나치게 입을 닫으면 기회와 인정도 함께 줄어들 수 있으며 소통이 막힐 수 있습니다.","advice":"민감한 문제는 말을 신중히 고르고, 꼭 필요한 말만 정확하게 전하세요. 드러나는 것보다 안정을 우선하세요.","message":"말을 아끼고 몸가짐을 지키세요."},{"guaN":2,"guaName":"곤위지","pos":5,"label":"六五","yinyang":"yin","text":"黃裳 元吉","reading":"황상 원길","modern":"누런 치마를 입으니 크게 길합니다.","meaning":"위 괘의 한가운데로 높은 자리에 있되 낮추고 갖추는 덕을 지닌 단계입니다. 누런색은 중심을, 치마는 겸손한 아랫사람의 차림을 뜻합니다.","positive":"높은 자리에서도 겸손하고 예의를 지키면 사람들의 신뢰와 지지를 얻기 쉽습니다.","caution":"자리가 높아졌다고 권위를 내세우거나 지나치게 화려해지면 이 좋은 균형이 흐트러질 수 있습니다.","advice":"중심을 지키면서 겸손과 절제로 사람을 대하세요. 겉치레보다 안정된 태도와 내실을 보여 주는 것이 좋습니다.","message":"높을수록 겸손하게 중심을 지키세요."},{"guaN":2,"guaName":"곤위지","pos":6,"label":"上六","yinyang":"yin","text":"龍戰于野 其血玄黃","reading":"룡전우야 기혈현황","modern":"용이 들판에서 싸우니 그 피가 검고 누렇습니다.","meaning":"음의 기운이 극에 이르러 양과 맞부딪히는 끝자리입니다. 한쪽으로 지나치게 치우친 힘이 마지막에 충돌하는 장면을 그립니다.","positive":"갈등이 커지기 전에 방향을 바꾸는 계기로 삼는다면 오히려 정리와 마무리를 시작할 수 있습니다.","caution":"더 가지려 하거나 주도권을 놓지 않으려 하면 양쪽 모두 큰 상처를 입기 쉽습니다.","advice":"끝까지 이기려 하기보다 한 걸음 물러나 대화와 타협의 여지를 찾으세요. 상황이 격해지면 한 번 멈추는 것이 도움이 됩니다.","message":"끝까지 다투기 전에 멈추고 조율하세요."}],"yong":{"guaN":2,"guaName":"곤위지","label":"用六","yinyang":"yin","text":"利永貞","reading":"리영정","modern":"오래도록 곧게 지키는 것이 이롭습니다.","meaning":"음의 여섯 효가 모두 움직여 변하는 경우를 가리키는 말입니다. 부드러운 힘이 흩어지지 않도록 곧은 마음을 길게 이어 가라는 뜻입니다.","positive":"꾸준하고 변치 않는 태도가 신뢰와 안정을 키워 줍니다.","caution":"유순함이 지나치면 중심 없이 흔들릴 수 있고, 오래 하다 보면 처음의 뜻이 흐려질 수 있습니다.","advice":"부드럽게 대응하되 지켜야 할 원칙은 분명히 하세요. 작은 일을 꾸준히 이어 가는 습관이 도움이 됩니다.","message":"부드러움 속에 곧은 중심을 오래 지키세요."}},"3":{"n":3,"name":"수뢰둔","han":"水雷屯","upper":"감","lower":"진","upperHan":"坎","lowerHan":"震","bits":[1,0,0,0,1,0],"binary":"100010","gua":{"text":"元亨利貞 勿用有攸往 利建侯","reading":"원형이정 물용유유왕 이건후","modern":"크게 형통하고 바르게 하면 이롭습니다. 서둘러 어디론가 나아가는 일은 하지 마시고, 도울 사람을 세우는 것이 이롭습니다.","symbol":"아래에는 우레(震), 위에는 물·구름(坎)이 있어, 땅속의 움직임이 험난한 기운에 막혀 있는 모습입니다. 새싹이 흙을 뚫고 나오려 애쓰는 시작의 어려움을 뜻하는 괘입니다.","situation":"무언가를 막 시작하려는데 사방이 어수선하고 길이 잘 보이지 않는 국면입니다. 에너지는 충분히 있으나 질서가 아직 잡히지 않아 혼란스럽기 쉽습니다. 큰 성과를 서두르기보다 기반과 협력자를 갖추는 데 무게를 두는 편이 좋습니다.","positive":"처음의 어려움은 성장의 과정이며, 함께할 사람과 체계를 갖추면 큰 가능성으로 이어질 수 있습니다.","caution":"조급하게 혼자 앞서 나가면 길을 잃거나 지치기 쉽습니다. 상황이 정리되기 전의 무리한 확장은 조심하세요.","direction":"당장 멀리 가기보다 기초를 다지고 믿을 만한 동료와 역할을 나누는 쪽으로 방향을 잡아 보세요. 작은 일부터 질서를 세우며 천천히 나아가는 편이 도움이 됩니다.","message":"시작의 혼란 속에서는 기반과 동료가 먼저입니다."},"yao":[{"guaN":3,"guaName":"수뢰둔","pos":1,"label":"初九","yinyang":"yang","text":"磐桓 利居貞 利建侯","reading":"반환 리거정 리건후","modern":"머뭇거리며 서성이니, 바르게 머무르는 것이 이롭고 도울 사람을 세우는 것이 이롭습니다.","meaning":"막 시작하는 단계에서 큰 바위 앞에 선 듯 쉽게 나아가지 못하는 장면입니다. 힘은 있지만 아직은 제자리에서 뜻을 굳히고 사람을 모을 때입니다.","positive":"서두르지 않고 방향을 다지면 이후의 발걸음이 단단해집니다.","caution":"답답함에 성급히 뛰쳐나가면 준비 없이 어려움을 맞기 쉽습니다.","advice":"목표와 원칙을 분명히 하고, 함께할 사람과 작은 협력 체계부터 만들어 보세요.","message":"머뭇거림은 뜻을 굳히는 시간입니다."},{"guaN":3,"guaName":"수뢰둔","pos":2,"label":"六二","yinyang":"yin","text":"屯如邅如 乘馬班如 匪寇婚媾 女子貞不字 十年乃字","reading":"둔여전여 승마반여 비구혼구 녀자정부자 십년내자","modern":"어렵고 맴돌며 말을 탄 이들이 나아가지 못하고 서성입니다. 도적이 아니라 혼인을 청하는 사람입니다. 여인은 바르게 지켜 혼약하지 않다가 십 년이 지나서야 허락합니다.","meaning":"아래 괘의 중심에서 가까운 사람의 접근이 오히려 길을 막는 듯한 장면입니다. 멀리 있는 믿을 만한 인연을 기다리며 원칙을 지키는 인내가 필요한 자리입니다.","positive":"당장의 유혹이나 제안 대신 본래의 뜻에 맞는 인연을 오래 기다릴 수 있습니다.","caution":"눈앞의 제안이 급하다고 해서 뜻과 맞지 않는 선택을 하기 쉽습니다.","advice":"가까운 제안이 정말 나에게 맞는지 천천히 따져 보고, 원칙을 지키며 시간을 두고 판단하세요.","message":"서두르지 않고 맞는 때를 기다립니다."},{"guaN":3,"guaName":"수뢰둔","pos":3,"label":"六三","yinyang":"yin","text":"即鹿无虞 惟入于林中 君子幾不如舍 往吝","reading":"즉록무우 유입우림중 군자기불여사 왕린","modern":"사냥터 안내자도 없이 사슴을 쫓다가 숲속으로 들어갑니다. 군자는 낌새를 보고 그만두는 편이 낫습니다. 계속 가면 아쉬운 일이 생깁니다.","meaning":"아래 괘의 끝에서 의욕이 앞서 길잡이 없이 깊이 들어가는 장면입니다. 도와줄 사람이 마땅치 않은 상태에서 욕심을 따르면 길을 잃기 쉬운 전환기입니다.","positive":"무리라는 낌새를 알아차리고 멈추면 손실을 크게 줄일 수 있습니다.","caution":"눈앞의 기회에 이끌려 준비나 조언 없이 깊이 들어가는 일을 조심하세요.","advice":"계속 갈지 물러설지 정해야 한다면 조언해 줄 사람을 먼저 찾고, 확신이 서지 않으면 한 걸음 멈추세요.","message":"길잡이 없는 추격은 멈추는 편이 낫습니다."},{"guaN":3,"guaName":"수뢰둔","pos":4,"label":"六四","yinyang":"yin","text":"乘馬班如 求婚媾 往吉 无不利","reading":"승마반여 구혼구 왕길 무불리","modern":"말을 탄 채 서성이다가 혼인할 사람을 찾아 나서면 길하고 이롭지 않은 것이 없습니다.","meaning":"위 괘의 시작에서 스스로 한계를 알고 도움을 구하려는 장면입니다. 아래 초효의 믿음직한 협력자와 짝을 이루려 나서는 겸손한 태도가 길을 엽니다.","positive":"도움을 청하는 겸손함이 막힌 흐름을 풀어 줄 수 있습니다.","caution":"자존심 때문에 혼자 해결하려 하면 기회를 놓치기 쉽습니다.","advice":"혼자 힘이 부족하다고 느껴지면 믿을 만한 사람에게 먼저 손을 내밀어 보세요.","message":"도움을 구하는 용기가 길을 엽니다."},{"guaN":3,"guaName":"수뢰둔","pos":5,"label":"九五","yinyang":"yang","text":"屯其膏 小貞吉 大貞凶","reading":"둔기고 소정길 대정흉","modern":"은택이 쌓이기만 하고 퍼지지 못합니다. 작은 일을 바르게 하면 길하지만, 큰일을 바르게 하려 하면 어려움이 따릅니다.","meaning":"위 괘의 중심 핵심 자리이지만 험난한 시기라 베풀 힘이 아래로 잘 닿지 않는 장면입니다. 크게 벌이기보다 작은 일부터 차근차근 풀어 가야 하는 때입니다.","positive":"작고 확실한 일부터 신뢰를 쌓으면 점차 영향력이 퍼질 수 있습니다.","caution":"한꺼번에 크게 개혁하려 하면 반발과 어려움이 커지기 쉽습니다.","advice":"큰 계획은 나누어 작은 단계로 진행하고, 주변의 지지를 확인하며 속도를 조절하세요.","message":"크게 벌이지 말고 작게 풀어 갑니다."},{"guaN":3,"guaName":"수뢰둔","pos":6,"label":"上六","yinyang":"yin","text":"乘馬班如 泣血漣如","reading":"승마반여 읍혈련여","modern":"말을 탄 채 나아가지 못하고 서성이며, 피눈물을 줄줄 흘립니다.","meaning":"어려움의 끝자리에서 도움도 방향도 보이지 않아 눈물이 나는 장면입니다. 그러나 괘의 맨 위는 곧 국면이 바뀔 시점이기도 합니다.","positive":"한계에 이르렀다는 자각이 새로운 방식을 찾는 계기가 될 수 있습니다.","caution":"혼자 끌어안고 절망에 머무르면 더 지치기 쉽습니다.","advice":"감정을 털어놓을 사람을 찾아 마음을 돌보고, 방법을 바꾸거나 잠시 쉬어 가는 선택도 살펴보세요.","message":"지친 마음을 돌보며 방식을 바꿉니다."}],"yong":null},"4":{"n":4,"name":"산수몽","han":"山水蒙","upper":"간","lower":"감","upperHan":"艮","lowerHan":"坎","bits":[0,1,0,0,0,1],"binary":"010001","gua":{"text":"亨 匪我求童蒙 童蒙求我 初筮告 再三瀆 瀆則不告 利貞","reading":"형 비아구동몽 동몽구아 초서고 재삼독 독즉불고 리정","modern":"형통합니다. 내가 어린 몽매한 이를 찾는 것이 아니라 몽매한 이가 나를 찾습니다. 처음 점칠 때는 알려 주지만, 두세 번 거듭 물으면 번거롭게 하는 것이니 알려 주지 않습니다. 바르게 하면 이롭습니다.","symbol":"위에는 산(艮), 아래에는 물(坎)이 있어, 산 아래 샘물이 막 솟아 나오는 모습입니다. 아직 흐릿하고 서툰 상태에서 배우고 깨우쳐 가는 과정을 뜻하는 괘입니다.","situation":"아직 정보나 경험이 부족해 판단이 흐릿한 국면입니다. 모르는 것이 있다는 사실이 약점이 아니라 배움의 출발점이 될 수 있는 때입니다. 겸손히 묻고, 얻은 답을 곱씹는 태도가 중요합니다.","positive":"배우려는 진지한 마음이 있으면 길이 열리고 성장의 속도도 빨라질 수 있습니다.","caution":"같은 것을 의심하며 반복해서 묻거나, 배움 없이 결론부터 내려는 태도는 조심하세요.","direction":"먼저 스스로 생각해 보고 한 번 진지하게 물으세요. 얻은 조언은 시간을 들여 소화하고 실행으로 옮기는 편이 도움이 됩니다.","message":"모름을 인정하는 데서 배움이 시작됩니다."},"yao":[{"guaN":4,"guaName":"산수몽","pos":1,"label":"初六","yinyang":"yin","text":"發蒙 利用刑人 用說桎梏 以往吝","reading":"발몽 리용형인 용탈질곡 이왕린","modern":"어리석음을 깨우칩니다. 사람에게 규율을 세우는 데는 이롭습니다. 차꼬와 수갑을 벗겨 주기만 하고 계속 가면 아쉬운 일이 생깁니다.","meaning":"배움이 막 시작되는 단계에서 기본 규칙과 틀을 잡아 주어야 하는 장면입니다. 다만 규율에만 머물고 속박을 풀어 주지 못하면 성장이 막힐 수 있습니다.","positive":"처음에 분명한 기준을 세우면 이후의 배움이 안정됩니다.","caution":"엄격함만 앞세우면 의욕을 꺾고 관계가 굳어지기 쉽습니다.","advice":"기본 규칙은 분명히 하되 때가 되면 틀을 풀고 스스로 해 보게 하세요.","message":"기본기는 단단히, 틀은 적절히 풉니다."},{"guaN":4,"guaName":"산수몽","pos":2,"label":"九二","yinyang":"yang","text":"包蒙吉 納婦吉 子克家","reading":"포몽길 납부길 자극가","modern":"몽매한 이를 품어 주니 길합니다. 아내를 받아들이니 길하고, 자식이 집안을 감당합니다.","meaning":"아래 괘의 중심에서 아랫사람들을 넉넉히 감싸 안는 역할을 맡은 장면입니다. 서툰 사람을 포용하는 너그러움이 관계와 집안, 조직을 키웁니다.","positive":"포용하는 태도가 주변의 신뢰와 성장의 바탕이 될 수 있습니다.","caution":"모든 것을 혼자 짊어지려 하면 지치기 쉽습니다.","advice":"서툰 사람을 탓하기보다 기다려 주고 역할을 나누며 맡겨 보세요.","message":"품어 주는 너그러움이 힘이 됩니다."},{"guaN":4,"guaName":"산수몽","pos":3,"label":"六三","yinyang":"yin","text":"勿用取女 見金夫 不有躬 无攸利","reading":"물용취녀 견금부 불유궁 무유리","modern":"이런 여자를 취하지 마십시오. 돈 많은 남자를 보고는 몸을 지키지 못하니 이로울 바가 없습니다.","meaning":"아래 괘의 끝에서 눈앞의 이득과 화려함에 흔들려 중심을 잃는 장면입니다. 배움의 길을 가다 주관 없이 이끌리는 모습을 경계하는 효입니다.","positive":"스스로 흔들리는 지점을 알아차리면 방향을 바로잡을 수 있습니다.","caution":"이익이 크게 보이는 쪽에 쉽게 따라가면 자기 줏대를 잃을 수 있습니다.","advice":"끌리는 제안일수록 한 번 멈추고, 내 기준에 맞는지 적어 보며 확인하세요.","message":"눈앞의 이익에 줏대를 잃지 마세요."},{"guaN":4,"guaName":"산수몽","pos":4,"label":"六四","yinyang":"yin","text":"困蒙 吝","reading":"곤몽 린","modern":"몽매함에 갇혀 있으니 아쉬운 일이 있습니다.","meaning":"위 괘의 시작이지만 곁에 가르쳐 주는 강한 효가 없어 홀로 막혀 있는 장면입니다. 모르는 것을 모르는 채로 두고 도움을 구하지 않아 답답함이 쌓입니다.","positive":"막혔다는 자각이 새로 배우려는 동기가 될 수 있습니다.","caution":"자존심이나 고립 때문에 묻지 못하면 같은 자리를 맴돌기 쉽습니다.","advice":"가까이에서 도움을 줄 수 있는 스승이나 동료를 찾아 묻는 것부터 시작해 보세요.","message":"막힐 때는 스스로 물을 사람을 찾습니다."},{"guaN":4,"guaName":"산수몽","pos":5,"label":"六五","yinyang":"yin","text":"童蒙 吉","reading":"동몽 길","modern":"어린아이처럼 배우려 하니 길합니다.","meaning":"위 괘의 중심에서 가장 높은 자리에 있으면서도 어린아이처럼 순수하게 배우려는 태도를 가진 장면입니다. 낮은 자세로 아래의 현명한 이를 믿고 따르는 모습입니다.","positive":"겸손하게 배우고 믿고 맡기는 태도가 좋은 결과로 이어지기 쉽습니다.","caution":"지위나 경험이 있다고 해서 배움을 멈추면 시야가 좁아질 수 있습니다.","advice":"전문성이 있는 사람의 의견을 열린 마음으로 듣고 의사결정에 반영해 보세요.","message":"높은 자리에서도 배우는 마음이 중요합니다."},{"guaN":4,"guaName":"산수몽","pos":6,"label":"上九","yinyang":"yang","text":"擊蒙 不利爲寇 利禦寇","reading":"격몽 불리위구 리어구","modern":"몽매함을 쳐서 깨우칩니다. 도적이 되는 것은 이롭지 않고 도적을 막는 것은 이롭습니다.","meaning":"배움의 끝에서 굳어진 고집을 단호히 깨뜨려야 하는 장면입니다. 다만 지나치게 몰아붙이면 상대를 해치는 쪽이 되니 목적은 지키고 보호하는 데 있어야 합니다.","positive":"굳은 편견을 단호히 깨면 새로운 이해가 열릴 수 있습니다.","caution":"교정한다는 이유로 과하게 몰아붙이면 오히려 반발을 부르기 쉽습니다.","advice":"필요한 지적은 분명히 하되 상대가 받아들일 수 있는 선에서, 보호하려는 의도를 함께 전하세요.","message":"단호하되 해치지 않는 가르침이어야 합니다."}],"yong":null},"5":{"n":5,"name":"수천수","han":"水天需","upper":"감","lower":"건","upperHan":"坎","lowerHan":"乾","bits":[1,1,1,0,1,0],"binary":"111010","gua":{"text":"有孚 光亨 貞吉 利涉大川","reading":"유부 광형 정길 리섭대천","modern":"믿음이 있으면 빛나게 형통하고, 바르게 하면 길합니다. 큰 내를 건너는 것이 이롭습니다.","symbol":"아래에는 하늘(乾), 위에는 물·구름(坎)이 있어, 하늘 위에 구름이 모여 비를 기다리는 모습입니다. 힘은 갖추었으나 때가 무르익기를 기다리는 괘입니다.","situation":"준비는 되어 있는데 앞에 험한 물이 있어 곧바로 건너기 어려운 국면입니다. 기다림은 포기가 아니라 힘을 아끼며 때를 보는 일입니다. 초조함을 달래고 일상을 안정적으로 유지하는 것이 중요합니다.","positive":"믿음을 지키며 때를 기다리면 흐름이 열릴 가능성이 큽니다. 기다리는 동안 몸과 마음을 정돈할 수 있습니다.","caution":"기다림이 길어진다고 무리하게 건너거나, 반대로 아무 준비 없이 손 놓고 있는 것은 조심하세요.","direction":"지금은 계획을 다듬고 체력과 자원을 아끼며 신호를 살피는 편이 좋습니다. 때가 오면 주저하지 않도록 준비해 두세요.","message":"기다림은 준비된 사람의 힘입니다."},"yao":[{"guaN":5,"guaName":"수천수","pos":1,"label":"初九","yinyang":"yang","text":"需于郊 利用恒 无咎","reading":"수우교 리용항 무구","modern":"교외에서 기다립니다. 변함없는 마음을 쓰는 것이 이로우며 허물이 없습니다.","meaning":"위험(물)에서 가장 먼 곳에서 막 기다림을 시작하는 장면입니다. 아직은 급하게 움직일 이유가 없으니 평소의 리듬을 지키는 것이 좋습니다.","positive":"위험과 거리가 있어 평정심을 지키며 준비하기 좋습니다.","caution":"거리가 멀다고 방심하거나 일상의 규율을 놓치기 쉽습니다.","advice":"일상의 습관을 유지하고 필요한 준비물과 계획을 차분히 점검하세요.","message":"멀리서 변함없이 기다립니다."},{"guaN":5,"guaName":"수천수","pos":2,"label":"九二","yinyang":"yang","text":"需于沙 小有言 終吉","reading":"수우사 소유언 종길","modern":"모래 위에서 기다립니다. 조금 구설이 있으나 끝내 길합니다.","meaning":"위험이 조금 가까워져 불안과 말이 오가는 장면입니다. 아래 괘의 중심이라 침착하게 감내하면 큰 문제 없이 지나갑니다.","positive":"작은 말썽을 침착하게 넘기면 결국 안정을 찾을 수 있습니다.","caution":"불안한 마음에 반박하거나 날 세운 말을 하면 갈등이 커지기 쉽습니다.","advice":"가볍게 오가는 말에 일일이 대응하지 말고, 사실 확인과 침착한 대화를 우선하세요.","message":"작은 말은 흘리며 침착하게 기다립니다."},{"guaN":5,"guaName":"수천수","pos":3,"label":"九三","yinyang":"yang","text":"需于泥 致寇至","reading":"수우니 치구지","modern":"진흙 속에서 기다립니다. 도적이 오는 것을 불러들입니다.","meaning":"아래 괘의 끝에서 위험에 바싹 다가선 장면입니다. 발이 빠지기 쉬운 곳에서 서성이면 곤란한 일을 스스로 불러올 수 있는 전환기입니다.","positive":"위험을 가까이서 알아본 만큼 대비를 단단히 할 수 있습니다.","caution":"물러서지 않고 위험 가까이에서 버티면 불필요한 문제를 끌어들이기 쉽습니다.","advice":"위험한 곳과는 거리를 두고, 경계심을 갖고 조심스럽게 행동하며 대비책을 마련하세요.","message":"위험 곁에서는 경계를 늦추지 마세요."},{"guaN":5,"guaName":"수천수","pos":4,"label":"六四","yinyang":"yin","text":"需于血 出自穴","reading":"수우혈 출자혈","modern":"피 흘리는 곳에서 기다리다가 구덩이에서 빠져나옵니다.","meaning":"위 괘의 시작으로 험한 물에 발을 들인 상황입니다. 순하게 몸을 낮추면 곤경의 굴에서 빠져나올 수 있습니다.","positive":"유연하게 대처하면 큰 피해 없이 어려움을 벗어날 수 있습니다.","caution":"맞서 싸우려 들면 상처가 더 깊어질 수 있습니다.","advice":"충돌이 있다면 한 발 물러서 순리를 따르고, 안전하게 빠져나올 길을 우선 찾으세요.","message":"굽히고 낮추면 빠져나올 길이 열립니다."},{"guaN":5,"guaName":"수천수","pos":5,"label":"九五","yinyang":"yang","text":"需于酒食 貞吉","reading":"수우주식 정길","modern":"술과 음식을 나누며 기다립니다. 바르게 하면 길합니다.","meaning":"위 괘의 중심이자 핵심 자리에서 여유 있게 기다림을 즐기는 장면입니다. 힘을 비축하며 사람들과 어울리는 안정된 때입니다.","positive":"여유와 화합 속에서 힘을 기르고 신뢰를 다질 수 있습니다.","caution":"여유가 지나쳐 방종하거나 일의 흐름을 놓칠 수 있습니다.","advice":"사람들과 식사나 대화를 나누며 관계를 다지되, 해야 할 준비는 놓지 마세요.","message":"즐기되 바른 마음으로 때를 기다립니다."},{"guaN":5,"guaName":"수천수","pos":6,"label":"上六","yinyang":"yin","text":"入于穴 有不速之客三人來 敬之終吉","reading":"입우혈 유불속지객삼인래 경지종길","modern":"구덩이로 들어갑니다. 청하지 않은 손님 세 사람이 오는데 공경하면 끝내 길합니다.","meaning":"기다림의 끝에서 예상치 못한 변화나 사람이 찾아오는 장면입니다. 뜻밖의 상황을 경계하기보다 예의 있게 맞이하면 도움이 될 수 있습니다.","positive":"뜻밖의 만남과 변화를 예의로 맞으면 오히려 도움이 될 수 있습니다.","caution":"불청객으로만 여겨 문을 닫거나 거칠게 대하면 기회를 놓칠 수 있습니다.","advice":"예상 밖의 일이 생기면 먼저 들어 보고 정중히 대하며, 내 입장을 차분히 정리해 보세요.","message":"뜻밖의 손님도 예로 맞이합니다."}],"yong":null},"6":{"n":6,"name":"천수송","han":"天水訟","upper":"건","lower":"감","upperHan":"乾","lowerHan":"坎","bits":[0,1,0,1,1,1],"binary":"010111","gua":{"text":"有孚窒 惕中吉 終凶 利見大人 不利涉大川","reading":"유부질 척중길 종흉 리견대인 불리섭대천","modern":"믿음이 있어도 막힙니다. 두려워하며 중도를 지키면 길하나 끝까지 다투면 흉합니다. 대인을 만나는 것은 이롭고, 큰 내를 건너는 것은 이롭지 않습니다.","symbol":"위에는 하늘(乾), 아래에는 물(坎)이 있어, 하늘은 위로 향하고 물은 아래로 흐르며 서로 어긋나는 모습입니다. 뜻이 엇갈려 시비를 다투는 상황을 뜻하는 괘입니다.","situation":"당당하게 옳다고 생각하지만 상대와 입장이 부딪혀 막힌 국면입니다. 이기고 지는 것보다 어디서 멈출지가 중요한 때입니다. 중재할 수 있는 사람의 조언을 구하는 편이 도움이 됩니다.","positive":"조심스러운 태도로 중도를 지키면 큰 충돌 없이 해결 방안을 찾을 수 있습니다.","caution":"끝까지 다투어 이기려 하면 관계도 신뢰도 잃기 쉽고, 크게 일을 벌이는 것도 조심해야 합니다.","direction":"한발 물러나 사실과 쟁점을 정리하고, 공정한 사람이나 중재 장치의 도움을 받는 방향을 살펴보세요. 결말을 서두르지 않는 편이 좋습니다.","message":"끝까지 이기려 하지 않는 것이 지혜입니다."},"yao":[{"guaN":6,"guaName":"천수송","pos":1,"label":"初六","yinyang":"yin","text":"不永所事 小有言 終吉","reading":"불영소사 소유언 종길","modern":"다투는 일을 길게 끌지 않으면 조금 말이 있으나 끝내 길합니다.","meaning":"다툼이 막 시작되는 단계에서 오래 끌지 않는 장면입니다. 작은 말은 오가겠지만 일찍 멈추면 크게 번지지 않습니다.","positive":"초기에 멈추면 감정의 골이 깊어지기 전에 정리할 수 있습니다.","caution":"억울한 마음에 시비를 가리려 끌고 가면 일이 커질 수 있습니다.","advice":"사소한 오해라면 일찍 사과하거나 해명하고, 더 길게 끌지 않을 지점을 정해 두세요.","message":"일찍 멈추면 작은 말로 끝납니다."},{"guaN":6,"guaName":"천수송","pos":2,"label":"九二","yinyang":"yang","text":"不克訟 歸而逋 其邑人三百戶 无眚","reading":"불극송 귀이포 기읍인삼백호 무생","modern":"다툼에서 이기지 못하고 돌아와 피해 숨습니다. 그 고을 삼백 호가 재앙을 면합니다.","meaning":"아래 괘의 중심에서 강한 상대와 맞서 보았자 불리함을 알고 물러서는 장면입니다. 물러남이 자신과 주변을 보호하는 현명한 선택이 됩니다.","positive":"한발 물러나 피해를 줄이면 주변까지 안전하게 지킬 수 있습니다.","caution":"체면 때문에 불리한 싸움을 이어 가면 주변 사람까지 힘들어질 수 있습니다.","advice":"객관적으로 힘의 차이를 따져 보고, 물러설 때는 낮은 자세로 갈등에서 거리를 두세요.","message":"물러남은 자신과 주변을 지킵니다."},{"guaN":6,"guaName":"천수송","pos":3,"label":"六三","yinyang":"yin","text":"食舊德 貞厲 終吉 或從王事 无成","reading":"식구덕 정려 종길 혹종왕사 무성","modern":"옛 덕으로 먹고삽니다. 바르게 지키면 위태로우나 끝내 길합니다. 혹 왕의 일을 따르더라도 이루려 하지 마십시오.","meaning":"아래 괘의 끝에서 새로운 것을 다투기보다 기존에 쌓아 온 것으로 버티는 장면입니다. 자리가 불안정해 보여도 겸손히 지키면 끝이 좋을 수 있습니다.","positive":"쌓아 온 신뢰와 실적을 지키면 흔들리는 상황에서도 중심을 잡을 수 있습니다.","caution":"공을 내세워 성과를 가로채려 하면 위태로워지기 쉽습니다.","advice":"새로 얻으려 하기보다 이미 가진 것을 성실히 지키고, 맡은 일을 해내되 공을 앞세우지 마세요.","message":"지금 가진 것을 지키며 공을 앞세우지 않습니다."},{"guaN":6,"guaName":"천수송","pos":4,"label":"九四","yinyang":"yang","text":"不克訟 復卽命渝 安貞吉","reading":"불극송 복즉명투 안정길","modern":"다툼에서 이기지 못하니 돌아가 명을 따르고 마음을 바꿉니다. 편안히 바르게 하니 길합니다.","meaning":"위 괘의 시작에서 다투려는 마음을 접고 원칙으로 돌아오는 장면입니다. 고집을 바꿔 순리를 따르는 선택이 평안을 가져옵니다.","positive":"마음을 돌려 순리를 따르면 갈등이 가라앉고 평안을 찾기 쉽습니다.","caution":"체면 때문에 마음을 바꾸지 못하면 소모가 길어질 수 있습니다.","advice":"주장이 지나쳤다고 느껴지면 원칙으로 돌아가 상황을 다시 조율해 보세요.","message":"고집을 내려놓으면 평안이 옵니다."},{"guaN":6,"guaName":"천수송","pos":5,"label":"九五","yinyang":"yang","text":"訟元吉","reading":"송원길","modern":"송사에서 크게 길합니다.","meaning":"위 괘의 중심이자 핵심 자리에서 공정하게 판단하는 위치의 장면입니다. 올바르고 치우치지 않는 판단이 큰 신뢰를 얻는 때입니다.","positive":"공정한 기준과 판단이 갈등을 크게 풀어 줄 수 있습니다.","caution":"편을 들거나 감정에 휘둘리면 공정함이 흐려지기 쉽습니다.","advice":"사실과 원칙에 따라 판단하고, 당사자들의 이야기를 고루 들어 보세요.","message":"공정함이 갈등을 풀어 줍니다."},{"guaN":6,"guaName":"천수송","pos":6,"label":"上九","yinyang":"yang","text":"或錫之鞶帶 終朝三褫之","reading":"혹사지반대 종조삼치지","modern":"혹 가죽 띠를 상으로 받더라도 아침이 끝나기 전에 세 번 빼앗깁니다.","meaning":"다툼에서 이겨 상을 받는 극에 이른 장면이지만, 다투어 얻은 영광은 오래가지 못하는 모습입니다. 승리에 취할수록 반발이 따르기 쉽습니다.","positive":"얻은 성과를 돌아보며 겸손해지는 계기로 삼을 수 있습니다.","caution":"이겼다는 만족감에 더 몰아붙이면 얻은 것을 도로 잃기 쉽습니다.","advice":"이긴 후에는 상대를 존중하며 갈등을 마무리하고, 성과를 과시하지 마세요.","message":"다투어 얻은 것은 오래가기 어렵습니다."}],"yong":null},"7":{"n":7,"name":"지수사","han":"地水師","upper":"곤","lower":"감","upperHan":"坤","lowerHan":"坎","bits":[0,1,0,0,0,0],"binary":"010000","gua":{"text":"貞 丈人 吉 无咎","reading":"정 장인 길 무구","modern":"바르게 하되 덕 있는 어른이 이끌면 길하고 허물이 없습니다.","symbol":"위에는 땅(坤), 아래에는 물(坎)이 있어, 땅속에 물이 모이듯 많은 사람이 힘을 모으는 모습입니다. 규율을 갖춘 조직과 지도자의 역할을 뜻하는 괘입니다.","situation":"여러 사람이 한 목표를 향해 움직여야 하는 국면입니다. 명분이 바르고 이끄는 사람이 믿음직스러울 때 힘이 모입니다. 감정보다 질서와 책임이 중요한 때입니다.","positive":"바른 명분과 신뢰받는 리더십, 분명한 규율이 있으면 집단의 힘이 커질 수 있습니다.","caution":"명분이 약하거나 지휘가 흔들리면 사람들이 지치고 희생이 커지기 쉽습니다. 힘으로만 밀어붙이는 것은 조심하세요.","direction":"목표와 역할, 규칙을 분명히 하고 믿을 만한 사람에게 중심을 맡기는 방향을 살펴보세요. 무리한 확대보다 안정적인 운영을 우선하는 편이 좋습니다.","message":"바른 명분과 규율이 힘을 모읍니다."},"yao":[{"guaN":7,"guaName":"지수사","pos":1,"label":"初六","yinyang":"yin","text":"師出以律 否臧凶","reading":"사출이률 비장흉","modern":"군대를 내보낼 때는 규율로 해야 합니다. 규율이 선하지 않으면 흉합니다.","meaning":"일을 막 시작하는 단계에서 원칙과 규율을 세워야 하는 장면입니다. 출발점의 질서가 이후의 결과를 좌우하기 쉽습니다.","positive":"처음에 규칙과 목표를 분명히 하면 이후 혼란을 줄일 수 있습니다.","caution":"명분이나 질서 없이 시작하면 처음부터 어려움이 따르기 쉽습니다.","advice":"팀이나 계획을 시작하기 전에 목적, 역할, 지켜야 할 규칙을 문장으로 정리해 보세요.","message":"시작할 때 질서가 결과를 좌우합니다."},{"guaN":7,"guaName":"지수사","pos":2,"label":"九二","yinyang":"yang","text":"在師中 吉 无咎 王三錫命","reading":"재사중 길 무구 왕삼사명","modern":"군대 가운데 있으니 길하고 허물이 없습니다. 왕이 세 번 명을 내려 줍니다.","meaning":"아래 괘의 중심에서 집단의 중심을 잡고 책임을 지는 장면입니다. 위로부터 신뢰를 얻고 구성원과 함께하는 지도자의 모습입니다.","positive":"현장에서 함께하는 리더십이 신뢰와 지원을 이끌어 낼 수 있습니다.","caution":"권한을 믿고 독단으로 운영하면 신뢰가 흔들리기 쉽습니다.","advice":"구성원 곁에서 상황을 살피고, 윗선의 신뢰와 지원을 받는 만큼 투명하게 보고하세요.","message":"현장에서 함께하는 리더가 신뢰를 얻습니다."},{"guaN":7,"guaName":"지수사","pos":3,"label":"六三","yinyang":"yin","text":"師或輿尸 凶","reading":"사혹여시 흉","modern":"군대가 혹 시체를 수레에 싣고 오게 됩니다. 흉합니다.","meaning":"아래 괘의 끝에서 자리에 맞지 않게 앞서 나가거나 여럿이 제각각 지휘하다 큰 손실을 입는 장면입니다. 무리한 전진과 혼란스러운 지휘를 경계하는 효입니다.","positive":"위험을 미리 알아차리면 지휘 체계를 정비하고 피해를 줄일 수 있습니다.","caution":"능력 이상의 일에 나서거나 여러 사람이 지휘하면 큰 손실이 날 수 있습니다.","advice":"역할과 지휘 체계를 정리하고, 감당하기 어려운 일은 무리하지 말고 조정하세요.","message":"무리한 전진과 이중 지휘를 경계하세요."},{"guaN":7,"guaName":"지수사","pos":4,"label":"六四","yinyang":"yin","text":"師左次 无咎","reading":"사좌차 무구","modern":"군대가 왼쪽에 머물러 물러나 있으니 허물이 없습니다.","meaning":"위 괘의 시작에서 형세가 불리함을 알고 물러나 진을 정비하는 장면입니다. 물러남이 곧 후퇴가 아니라 피해를 막는 현명한 판단이 됩니다.","positive":"불리할 때 물러나 재정비하면 큰 손실을 피할 수 있습니다.","caution":"체면 때문에 물러나지 못하면 상황이 더 나빠질 수 있습니다.","advice":"상황이 불리하다고 판단되면 속도를 늦추고 자원을 모아 다시 점검하세요.","message":"물러나 정비하는 것도 전략입니다."},{"guaN":7,"guaName":"지수사","pos":5,"label":"六五","yinyang":"yin","text":"田有禽 利執言 无咎 長子帥師 弟子輿尸 貞凶","reading":"전유금 리집언 무구 장자솔사 제자여시 정흉","modern":"밭에 짐승이 있으니 잡는 것이 이롭고 허물이 없습니다. 맏아들이 군대를 이끌어야 하고, 아우들이 이끌면 시체를 싣게 되어 바르더라도 흉합니다.","meaning":"위 괘의 중심 핵심 자리에서 침입에 대응해야 하는 명분이 분명한 장면입니다. 적임자를 지휘자로 세우고 여러 사람이 간섭하지 않는 것이 중요합니다.","positive":"명분이 분명하고 적임자에게 맡기면 안정적으로 해결할 수 있습니다.","caution":"믿음직하지 못한 사람에게 맡기거나 여럿이 지휘하면 위험이 커집니다.","advice":"대응이 필요한 일에는 경험과 신뢰가 있는 사람에게 권한을 주고 나머지는 지원하세요.","message":"적임자에게 맡기고 간섭하지 않습니다."},{"guaN":7,"guaName":"지수사","pos":6,"label":"上六","yinyang":"yin","text":"大君有命 開國承家 小人勿用","reading":"대군유명 개국승가 소인물용","modern":"대군이 명을 내려 나라를 열고 집안을 잇게 합니다. 소인은 쓰지 마십시오.","meaning":"싸움이 끝나고 공을 가려 상을 주는 마무리의 장면입니다. 공이 있어도 사사로운 이익만 좇는 사람에게 중요한 자리를 맡기지 않는 분별이 필요합니다.","positive":"성과를 합당하게 나누고 새 질서를 세우면 안정이 이어질 수 있습니다.","caution":"공만 보고 자리를 주면 이후 조직이 흔들리기 쉽습니다.","advice":"공로는 보상하되 책임이 큰 자리는 인품과 역량을 함께 보고 맡기세요.","message":"공은 보상하되 자리는 분별해 줍니다."}],"yong":null},"8":{"n":8,"name":"수지비","han":"水地比","upper":"감","lower":"곤","upperHan":"坎","lowerHan":"坤","bits":[0,0,0,0,1,0],"binary":"000010","gua":{"text":"吉 原筮 元永貞 无咎 不寧方來 後夫凶","reading":"길 원서 원영정 무구 불녕방래 후부흉","modern":"길합니다. 처음 점치듯 근본을 살피고, 크고 오래도록 바름을 지키면 허물이 없습니다. 편치 못한 이들도 찾아오지만 늦게 오는 사람은 흉합니다.","symbol":"위에는 물(坎), 아래에는 땅(坤)이 있어, 물이 땅 위에 스며들듯 서로 가까이 붙어 친해지는 모습입니다. 믿음으로 사람과 가까워지고 하나가 되는 것을 뜻하는 괘입니다.","situation":"좋은 사람, 좋은 모임과 가까워지고 관계를 맺는 국면입니다. 누구와 함께하느냐가 앞으로의 방향을 크게 좌우합니다. 진실한 마음으로 먼저 다가가고, 때를 놓치지 않는 것이 중요합니다.","positive":"믿음 위에 맺는 관계는 서로에게 힘이 되고 안정을 줄 수 있습니다.","caution":"이익만 보고 사람을 따르거나 망설이다 늦게 다가가면 관계가 어색해지기 쉽습니다. 아무에게나 휩쓸리는 것은 조심하세요.","direction":"함께할 사람의 됨됨이와 뜻을 먼저 살피고, 마음이 정해지면 너무 늦지 않게 진심으로 다가가 보세요. 한 번 맺은 관계는 꾸준히 가꾸는 편이 도움이 됩니다.","message":"좋은 관계는 믿음으로 가까워집니다."},"yao":[{"guaN":8,"guaName":"수지비","pos":1,"label":"初六","yinyang":"yin","text":"有孚比之 无咎 有孚盈缶 終來有他 吉","reading":"유부비지 무구 유부영부 종래유타 길","modern":"믿음으로 가까이하니 허물이 없습니다. 믿음이 질그릇에 가득 차 있으니 끝내 뜻밖의 좋은 일이 찾아와 길합니다.","meaning":"관계가 막 시작되는 단계에서 꾸밈없이 믿음으로 다가가는 장면입니다. 소박한 그릇에 진심을 가득 채우듯, 겉치레 없는 마음이 이후의 인연을 키웁니다.","positive":"진실한 첫인상이 이후 신뢰의 바탕이 됩니다.","caution":"잇속을 위한 가벼운 접근은 관계를 오래 이어 가기 어렵습니다.","advice":"처음부터 꾸미지 말고 솔직하고 성실하게 마음을 보여 주세요.","message":"꾸밈없는 믿음이 관계의 시작입니다."},{"guaN":8,"guaName":"수지비","pos":2,"label":"六二","yinyang":"yin","text":"比之自內 貞吉","reading":"비지자내 정길","modern":"안에서부터 가까워집니다. 바르게 지키면 길합니다.","meaning":"아래 괘의 중심에서 핵심 자리의 효와 응하며 안쪽으로부터 자연스럽게 관계를 맺는 장면입니다. 서두르지 않고 안정된 태도로 인연이 이어집니다.","positive":"자연스럽게 마음이 통하는 사람과 안정된 관계를 쌓을 수 있습니다.","caution":"상대의 눈치만 보며 자신을 잃으면 관계가 불균형해지기 쉽습니다.","advice":"자신의 중심을 지키며 마음이 통하는 사람과 천천히 신뢰를 쌓아 보세요.","message":"안에서 우러난 마음으로 가까워집니다."},{"guaN":8,"guaName":"수지비","pos":3,"label":"六三","yinyang":"yin","text":"比之匪人","reading":"비지비인","modern":"가까이하는 상대가 사람답지 못합니다.","meaning":"아래 괘의 끝에서 손을 잡은 상대가 맞지 않는 장면입니다. 주변에 이끌려 어울려도 뜻이나 신뢰가 맞지 않으면 득보다 실이 되기 쉽습니다.","positive":"관계를 돌아볼 계기를 얻어 거리를 조정할 수 있습니다.","caution":"이익이나 외로움 때문에 맞지 않는 사람과 가까워지면 손해가 따르기 쉽습니다.","advice":"함께 있는 사람이 나의 가치관과 방향에 도움이 되는지 점검하고, 필요하면 거리를 두세요.","message":"맞지 않는 사람과는 거리를 둡니다."},{"guaN":8,"guaName":"수지비","pos":4,"label":"六四","yinyang":"yin","text":"外比之 貞吉","reading":"외비지 정길","modern":"밖으로 가까이합니다. 바르게 지키면 길합니다.","meaning":"위 괘의 시작에서 가까운 핵심 자리의 현명한 사람과 손잡는 장면입니다. 믿을 만한 상대에게 마음을 열면 함께 큰 힘을 낼 수 있습니다.","positive":"믿을 만한 윗사람이나 동료와 연결되면 든든한 지원을 얻기 쉽습니다.","caution":"아첨처럼 보이거나 바르지 않은 방식으로 가까워지면 신뢰가 흔들립니다.","advice":"존경할 만한 사람에게 정당한 방식으로 다가가 배우고 협력해 보세요.","message":"믿을 만한 사람과 바르게 손잡습니다."},{"guaN":8,"guaName":"수지비","pos":5,"label":"九五","yinyang":"yang","text":"顯比 王用三驅 失前禽 邑人不誡 吉","reading":"현비 왕용삼구 실전금 읍인불계 길","modern":"드러나게 친근합니다. 왕이 세 방향만 몰아 사냥하니 앞으로 달아나는 짐승을 놓쳐도 고을 사람들은 경계하지 않아 길합니다.","meaning":"위 괘의 중심이자 핵심 자리에서 공개적이고 너그럽게 사람을 품는 장면입니다. 오는 이는 받아들이고 가는 이는 붙잡지 않는 열린 태도가 신뢰를 만듭니다.","positive":"너그럽고 공개적인 태도가 사람들의 마음을 편하게 하고 신뢰를 높입니다.","caution":"오는 사람을 모두 붙들려 하거나 떠나는 이에게 집착하면 관계가 무거워집니다.","advice":"사람을 대할 때 투명하고 열린 태도를 유지하고, 떠나는 인연은 억지로 잡지 마세요.","message":"오고 가는 인연을 너그럽게 대합니다."},{"guaN":8,"guaName":"수지비","pos":6,"label":"上六","yinyang":"yin","text":"比之无首 凶","reading":"비지무수 흉","modern":"가까이하는 데 시작이 없으니 흉합니다.","meaning":"관계의 끝에서 먼저 다가갈 때를 놓쳐 이미 늦어진 장면입니다. 우두머리 격인 이에게 가까이할 기회를 놓친 모습으로, 머뭇거림의 대가를 말합니다.","positive":"늦었다는 점을 인정하면 앞으로의 관계를 새로 정비할 수 있습니다.","caution":"망설이다 때를 놓치고 후회만 하면 어려움이 이어지기 쉽습니다.","advice":"이미 지나간 일은 인정하고, 지금 할 수 있는 작은 연락이나 사과부터 시작해 보세요.","message":"망설이다 때를 놓치지 마세요."}],"yong":null},"9":{"n":9,"name":"풍천소축","han":"風天小畜","upper":"손","lower":"건","upperHan":"巽","lowerHan":"乾","bits":[1,1,1,0,1,1],"binary":"111011","gua":{"text":"亨 密雲不雨 自我西郊","reading":"형 밀운불우 자아서교","modern":"형통합니다. 구름은 빽빽한데 비는 내리지 않으니, 내가 사는 서쪽 교외에서부터 일어나는 것입니다.","symbol":"위에는 바람(巽), 아래에는 하늘(乾)이 있어, 바람이 하늘 위를 스치며 큰 기운을 잠시 붙잡아 두는 모습입니다. 작은 힘이 큰 흐름을 조금씩 모아 가는 괘입니다.","situation":"조건은 갖추어지고 있지만 결과가 눈에 보이기에는 아직 이른 국면입니다. 구름이 잔뜩 끼었는데 비가 내리지 않는 하늘처럼 답답함이 있으나, 방향이 틀린 것은 아닙니다. 지금은 큰 성과보다 작은 신뢰와 실력을 쌓는 데 무게를 두기 쉬운 때입니다.","positive":"작은 노력과 부드러운 태도가 쌓여 나중의 바탕이 될 수 있습니다. 서두르지 않고 준비하는 시간이 힘이 됩니다.","caution":"답답한 마음에 판을 크게 흔들거나 감정을 터뜨리면 쌓아 온 것이 흐트러지기 쉽습니다. 성과가 늦다고 조급해하지 마세요.","direction":"큰 도약보다 작은 단계를 꾸준히 밟는 쪽으로 방향을 잡아 보세요. 말과 태도를 부드럽게 하며 주변의 협조를 모으고, 때가 무르익었는지 살피며 움직이는 편이 도움이 됩니다.","message":"작게 쌓으며 때를 기다리는 시기입니다."},"yao":[{"guaN":9,"guaName":"풍천소축","pos":1,"label":"初九","yinyang":"yang","text":"復自道 何其咎 吉","reading":"복자도 하기구 길","modern":"제 길로 돌아오니 무슨 허물이 있겠습니까. 길합니다.","meaning":"막 시작하는 단계에서 방향이 흔들렸다면 본래 가려던 길로 되돌아오는 장면입니다. 양의 자리에 양이 있어 바른 뜻이 있으니, 돌아오는 것 자체가 큰 허물이 되지 않습니다.","positive":"초기에 방향을 바로잡으면 손실이 작고 마음도 가벼워집니다.","caution":"남의 속도에 휩쓸려 본래 목표를 잊고 앞서 나가려는 마음을 조심하세요.","advice":"처음 세웠던 목표와 원칙을 다시 적어 보고, 어긋난 부분이 있다면 지금 바로 조정하세요.","message":"처음 길로 돌아오면 됩니다."},{"guaN":9,"guaName":"풍천소축","pos":2,"label":"九二","yinyang":"yang","text":"牽復 吉","reading":"견복 길","modern":"이끌려서 돌아오니 길합니다.","meaning":"아래 괘의 중심에서 이웃한 초효와 함께 이끌리듯 제자리로 돌아오는 모습입니다. 혼자 애쓰기보다 뜻이 맞는 사람과 함께 물러서며 흐름을 조정하는 때입니다.","positive":"뜻이 같은 동료와 보조를 맞추면 무리 없이 방향을 정리할 수 있습니다.","caution":"혼자 버티거나 고집을 부리면 오히려 동료의 도움을 놓치기 쉽습니다.","advice":"믿을 만한 사람과 현재 상황을 나누고, 함께 속도를 늦추거나 방향을 맞추는 방법을 의논해 보세요.","message":"함께 이끌며 돌아옵니다."},{"guaN":9,"guaName":"풍천소축","pos":3,"label":"九三","yinyang":"yang","text":"輿說輻 夫妻反目","reading":"여탈복 부처반목","modern":"수레의 바퀴살이 빠졌습니다. 부부가 서로 눈을 흘깁니다.","meaning":"아래 괘의 끝에서 나아가려는 힘이 앞서다 수레가 멈추는 장면입니다. 가장 가까운 사람과도 마음이 어긋나기 쉬운 전환기이며, 무리한 전진이 관계의 균열로 나타날 수 있습니다.","positive":"멈춤을 계기로 관계와 방식을 점검할 기회가 생깁니다.","caution":"서두르며 밀어붙이면 가까운 사람과 말다툼이나 불신으로 번지기 쉽습니다.","advice":"일을 멈추고 상대의 이야기부터 들어 보세요. 부서진 부분은 서둘러 덮기보다 차분히 고쳐 쓰는 편이 낫습니다.","message":"무리한 전진은 관계를 상하게 합니다."},{"guaN":9,"guaName":"풍천소축","pos":4,"label":"六四","yinyang":"yin","text":"有孚 血去惕出 无咎","reading":"유부 혈거척출 무구","modern":"믿음이 있으니 피가 사라지고 두려움이 물러가 허물이 없습니다.","meaning":"위 괘의 시작이자 괘의 유일한 음으로, 여러 강한 기운 사이에서 진실함으로 처신하는 자리입니다. 위험과 두려움이 있어도 신뢰로 풀어 가면 허물을 피할 수 있습니다.","positive":"진실한 태도가 긴장된 관계를 풀고 위험을 덜어 줍니다.","caution":"혼자 중간에 끼어 눈치만 보다 지치기 쉬우니, 불안을 방치하지 마세요.","advice":"숨기지 말고 솔직하게 상황을 알리고, 믿을 만한 윗사람이나 동료의 도움을 구하세요.","message":"진심이 두려움을 덜어 줍니다."},{"guaN":9,"guaName":"풍천소축","pos":5,"label":"九五","yinyang":"yang","text":"有孚攣如 富以其鄰","reading":"유부련여 부이기린","modern":"믿음이 있어 서로 이어져 있으니, 이웃과 함께 풍요를 누립니다.","meaning":"위 괘의 중심이자 핵심 자리에서 아래 사람들과 끈끈하게 묶여 함께 나아가는 모습입니다. 혼자 쌓은 것을 독차지하지 않고 나누는 태도가 힘이 됩니다.","positive":"신뢰로 얽힌 관계에서 서로 도우며 함께 안정과 여유를 얻을 수 있습니다.","caution":"얻은 것을 혼자 쥐려 하면 연결의 끈이 느슨해지기 쉽습니다.","advice":"성과와 자원을 주변과 나누고, 함께하는 사람들의 몫을 먼저 챙겨 보세요.","message":"나눌수록 단단해지는 관계입니다."},{"guaN":9,"guaName":"풍천소축","pos":6,"label":"上九","yinyang":"yang","text":"旣雨旣處 尙德載 婦貞厲 月幾望 君子征凶","reading":"기우기처 상덕재 부정려 월기망 군자정흉","modern":"이미 비가 내리고 이미 멈추었으니 덕이 쌓여 가득 실렸습니다. 아내가 고집하면 위태롭고, 달이 거의 보름에 가까우니 군자가 나아가면 흉합니다.","meaning":"오래 쌓아 온 것이 마침내 비로 내리듯 결실을 맺은 끝자리입니다. 그러나 가득 차 가는 달처럼 지나치게 차면 기울기 쉬우니, 이제는 더 밀어붙이기보다 멈추고 지키는 때입니다.","positive":"쌓은 덕과 실력이 결실로 나타나고 안정을 얻을 수 있습니다.","caution":"성과에 들떠 더 크게 벌이거나 고집을 부리면 어려움이 따르기 쉽습니다.","advice":"이룬 것을 정리하고 감사와 겸손으로 다지며, 확장은 여유를 갖고 천천히 판단하세요.","message":"가득 찼을 때는 멈춰 지켜야 합니다."}],"yong":null},"10":{"n":10,"name":"천택리","han":"天澤履","upper":"건","lower":"태","upperHan":"乾","lowerHan":"兌","bits":[1,1,0,1,1,1],"binary":"110111","gua":{"text":"履虎尾 不咥人 亨","reading":"리호미 부질인 형","modern":"호랑이 꼬리를 밟아도 사람을 물지 않으니 형통합니다.","symbol":"위에는 하늘(乾), 아래에는 연못(澤)이 있어, 부드럽고 기쁜 이가 강한 존재 뒤를 조심스럽게 따라 걷는 모습입니다. 예의와 분수를 지키며 위험한 길을 걷는 괘입니다.","situation":"윗사람이나 까다로운 상대, 격식이 필요한 자리처럼 조심스러운 관계 속에 있는 국면입니다. 위험이 가까이 있지만 태도와 순서를 잘 지키면 큰 탈 없이 지나갈 수 있습니다. 용기보다 예의와 신중함이 결과를 좌우하기 쉬운 때입니다.","positive":"부드럽고 공손한 태도가 강한 상대의 경계를 풀고 길을 열어 줄 수 있습니다.","caution":"자신의 능력을 과신하여 선을 넘거나 상대의 영역을 가볍게 보면 위험이 커집니다.","direction":"상대의 위치와 입장을 먼저 살피고, 절차와 말씨를 지키며 한 걸음씩 나아가 보세요. 위험이 느껴지면 정면 돌파보다 완충 장치와 우회로를 마련하는 편이 도움이 됩니다.","message":"예의와 신중함이 길을 안전하게 합니다."},"yao":[{"guaN":10,"guaName":"천택리","pos":1,"label":"初九","yinyang":"yang","text":"素履 往无咎","reading":"소리 왕무구","modern":"꾸밈없이 소박하게 걸으니 나아가도 허물이 없습니다.","meaning":"막 길을 나서는 단계에서 꾸미거나 욕심내지 않고 본래의 모습으로 걷는 장면입니다. 아직 아무것도 얻지 않았기에 가장 단순하고 진실한 태도가 힘이 됩니다.","positive":"소박하고 꾸밈없는 시작은 부담이 적고 신뢰를 얻기 쉽습니다.","caution":"남과 비교하며 겉모습을 부풀리면 시작부터 흔들리기 쉽습니다.","advice":"지금 가진 그대로의 실력과 형편에 맞게 첫걸음을 내딛고, 필요 이상의 포장은 줄여 보세요.","message":"꾸밈없는 첫걸음이 가장 안전합니다."},{"guaN":10,"guaName":"천택리","pos":2,"label":"九二","yinyang":"yang","text":"履道坦坦 幽人貞吉","reading":"리도탄탄 유인정길","modern":"걷는 길이 평탄하고 평탄합니다. 조용히 지내는 사람이 바르게 하면 길합니다.","meaning":"아래 괘의 중심에서 마음이 차분하여 평탄한 길을 걷는 모습입니다. 앞에 나서기보다 고요하고 안정된 태도를 지킬 때 순조롭습니다.","positive":"마음이 안정되어 있어 크게 흔들리지 않고 길을 이어 갈 수 있습니다.","caution":"평탄하다고 방심하거나 일부러 주목받으려 하면 균형이 깨질 수 있습니다.","advice":"화려한 성과를 서두르지 말고, 조용히 자기 리듬을 지키며 해야 할 일을 이어 가세요.","message":"조용히 중심을 지키면 길이 평탄합니다."},{"guaN":10,"guaName":"천택리","pos":3,"label":"六三","yinyang":"yin","text":"眇能視 跛能履 履虎尾 咥人 凶 武人爲于大君","reading":"묘능시 파능리 리호미 질인 흉 무인위우대군","modern":"애꾸눈이 잘 볼 수 있다 하고 절름발이가 잘 걸을 수 있다 합니다. 호랑이 꼬리를 밟아 사람을 무니 흉합니다. 무인이 큰 임금이 되려 하는 격입니다.","meaning":"아래 괘의 끝에서 자신의 능력이 부족한데도 지나치게 자신하여 위험한 자리로 나서는 장면입니다. 짝수 자리에 약한 음이 있으면서 강한 척하는 형국이라 무리가 되기 쉽습니다.","positive":"자신의 한계를 알아차리는 순간이 큰 사고를 막는 계기가 됩니다.","caution":"실력보다 앞선 자신감으로 위험에 뛰어들면 어려움이 따르기 쉽습니다.","advice":"현재 감당할 수 있는 범위를 정직하게 가늠하고, 모자란 부분은 도움을 구하거나 물러서세요.","message":"능력 이상의 자신감은 위험합니다."},{"guaN":10,"guaName":"천택리","pos":4,"label":"九四","yinyang":"yang","text":"履虎尾 愬愬終吉","reading":"리호미 삭삭종길","modern":"호랑이 꼬리를 밟았으나 두려워하며 삼가니 끝내는 길합니다.","meaning":"위 괘의 시작이자 가장 높은 자리 곁에서 위험을 정면으로 마주하는 모습입니다. 강한 자리에 있지만 두려움을 알고 조심하기에 결국 무사히 넘어갑니다.","positive":"경계심과 신중함 덕분에 위험한 자리에서도 끝까지 안전하게 갈 수 있습니다.","caution":"두려움에 지나치게 굳으면 결단의 시점을 놓칠 수 있습니다.","advice":"위험 요소를 미리 목록으로 정리하고, 조심하되 필요한 판단은 미루지 말고 단계적으로 하세요.","message":"두려움을 알기에 끝이 좋습니다."},{"guaN":10,"guaName":"천택리","pos":5,"label":"九五","yinyang":"yang","text":"夬履 貞厲","reading":"쾌리 정려","modern":"결단하여 걷습니다. 바르더라도 위태롭습니다.","meaning":"위 괘의 중심이자 핵심 자리에서 과감히 결단하며 나아가는 모습입니다. 옳다고 믿는 확신이 강할수록 오히려 위태로움을 의식하며 살펴야 합니다.","positive":"결단력과 책임감이 일을 힘 있게 이끌어 가는 원동력이 됩니다.","caution":"옳다는 확신에 빠져 독단으로 흐르면 주변의 반발을 살 수 있습니다.","advice":"결정을 내리기 전에 반대 의견을 한 번 더 듣고, 위험 신호가 없는지 점검한 뒤 실행하세요.","message":"결단할수록 위태로움을 살피세요."},{"guaN":10,"guaName":"천택리","pos":6,"label":"上九","yinyang":"yang","text":"視履考祥 其旋元吉","reading":"시리고상 기선원길","modern":"걸어온 길을 돌아보고 좋고 나쁜 징조를 살피며 한 바퀴 돌아보니 크게 길합니다.","meaning":"길의 끝에서 지나온 발자취를 되짚어 보고 완성하는 자리입니다. 걸어온 행동을 돌아보며 다듬을 때 좋은 마무리를 이룰 수 있습니다.","positive":"경험을 되돌아보면 잘한 점과 고칠 점이 분명해져 좋은 마무리를 맺을 수 있습니다.","caution":"끝났다고 방심하며 돌아보는 과정을 건너뛰면 같은 실수가 되풀이됩니다.","advice":"마무리 단계에서 지금까지의 과정을 기록하고 평가해 보세요. 배운 점을 다음 일에 연결하는 것이 도움이 됩니다.","message":"돌아보는 마무리가 큰 결실입니다."}],"yong":null},"11":{"n":11,"name":"지천태","han":"地天泰","upper":"곤","lower":"건","upperHan":"坤","lowerHan":"乾","bits":[1,1,1,0,0,0],"binary":"111000","gua":{"text":"小往大來 吉亨","reading":"소왕대래 길형","modern":"작은 것이 가고 큰 것이 옵니다. 길하고 형통합니다.","symbol":"위에는 땅(坤), 아래에는 하늘(乾)이 있어, 아래의 맑은 기운은 올라가고 위의 무거운 기운은 내려와 서로 만나는 모습입니다. 위아래가 잘 통하는 평화의 괘입니다.","situation":"막혔던 일이 풀리고 서로의 뜻이 통하며 협력이 잘 이루어지는 국면입니다. 미뤄 둔 일을 실행하기에 좋은 흐름이지만, 평탄함이 영원히 이어지는 것은 아니므로 방심하기 쉬운 때이기도 합니다. 좋은 흐름을 구체적인 약속과 기반으로 바꿔 두는 것이 중요합니다.","positive":"소통과 화합이 이루어져 협력이 쉽고 일이 순조롭게 진행되기 쉽습니다.","caution":"순조로움에 취해 점검을 소홀히 하면 작은 틈이 나중에 큰 문제가 되기 쉽습니다.","direction":"좋은 흐름이 있을 때 미뤄 둔 제안과 계획을 실행하고, 합의 내용을 문서나 약속으로 정리해 두세요. 겸손을 유지하며 다음 단계의 준비와 여유 자원을 함께 챙기는 편이 도움이 됩니다.","message":"잘 통할 때가 기반을 다질 때입니다."},"yao":[{"guaN":11,"guaName":"지천태","pos":1,"label":"初九","yinyang":"yang","text":"拔茅茹 以其彙 征吉","reading":"발모여 이기휘 정길","modern":"띠풀을 뽑으니 뿌리가 얽혀 함께 뽑힙니다. 무리와 함께 나아가면 길합니다.","meaning":"좋은 흐름이 막 시작되는 단계에서 같은 뜻을 가진 사람들이 뿌리째 이어져 함께 움직이는 장면입니다. 혼자보다 뜻이 맞는 동료와 보조를 맞추면 힘이 커집니다.","positive":"비슷한 뜻을 가진 사람들과 함께 출발하면 추진력이 쉽게 붙습니다.","caution":"무리에 의존해 자신의 판단 없이 따라가기만 하면 방향을 잃기 쉽습니다.","advice":"함께할 사람들과 목표를 맞추고, 각자의 역할을 정한 뒤 작은 일부터 같이 시작해 보세요.","message":"뜻을 모아 함께 출발합니다."},{"guaN":11,"guaName":"지천태","pos":2,"label":"九二","yinyang":"yang","text":"包荒 用馮河 不遐遺 朋亡 得尙于中行","reading":"포황 용빙하 불하유 붕망 득상우중행","modern":"거친 것까지 품어 안고, 맨몸으로 강을 건널 만한 용기를 내며, 먼 곳도 버리지 않고, 사사로운 무리를 잊으면 중도의 길에서 존중을 얻습니다.","meaning":"아래 괘의 중심에서 넓은 아량으로 거친 사람과 일까지 받아들이고 결단하는 자리입니다. 가까운 사람만 챙기지 않고 치우침 없이 공평하게 대할 때 좋은 흐름이 이어집니다.","positive":"넓은 포용력과 용기로 다양한 사람의 협력을 이끌어 낼 수 있습니다.","caution":"편한 사람만 챙기거나 어려운 사람과 일을 피하면 흐름이 한쪽으로 기울기 쉽습니다.","advice":"껄끄러운 의견도 먼저 들어 보고, 친분보다 원칙과 공정함으로 결정하세요.","message":"넓게 품고 공정하게 대하세요."},{"guaN":11,"guaName":"지천태","pos":3,"label":"九三","yinyang":"yang","text":"无平不陂 无往不復 艱貞无咎 勿恤其孚 于食有福","reading":"무평불피 무왕불복 간정무구 물휼기부 우식유복","modern":"평평하기만 하고 기울지 않는 땅은 없고, 가기만 하고 돌아오지 않는 것은 없습니다. 어려움 속에서도 바르게 하면 허물이 없고, 그 믿음을 걱정하지 않아도 먹을 복이 있습니다.","meaning":"아래 괘의 끝으로 가장 좋은 때가 정점에 이르러 서서히 기울기 시작하는 전환기입니다. 좋음이 영원하지 않다는 이치를 알고 어려움에 대비하는 마음으로 바른 자세를 지키라는 장면입니다.","positive":"흐름의 변화를 미리 알아차리면 여유 있게 대비하고 복을 오래 지킬 수 있습니다.","caution":"지금의 평탄함이 계속될 것이라 믿고 방심하면 변화에 크게 흔들리기 쉽습니다.","advice":"좋을 때 여유 자원을 비축하고 점검하며, 흐름이 바뀌어도 흔들리지 않을 기본기를 정비하세요.","message":"좋을 때 변화를 대비하세요."},{"guaN":11,"guaName":"지천태","pos":4,"label":"六四","yinyang":"yin","text":"翩翩 不富以其鄰 不戒以孚","reading":"편편 불부이기린 불계이부","modern":"훨훨 내려옵니다. 부유하지 않으면서도 이웃과 함께하고, 경계하지 않아도 믿음으로 통합니다.","meaning":"위 괘의 시작에서 윗자리에 있는 이들이 위신을 내려놓고 아래로 가볍게 내려와 이웃과 어울리는 모습입니다. 서로 의심하지 않고 진심으로 통하는 소통의 순간입니다.","positive":"격식을 내려놓고 다가갈수록 서로의 신뢰가 쉽게 쌓입니다.","caution":"허물없음이 지나쳐 기본 예의나 역할의 경계를 잊지 않도록 살펴야 합니다.","advice":"먼저 다가가 편하게 말을 건네고, 진심이 전달될 수 있도록 솔직한 대화를 시도해 보세요.","message":"먼저 내려와 진심으로 통합니다."},{"guaN":11,"guaName":"지천태","pos":5,"label":"六五","yinyang":"yin","text":"帝乙歸妹 以祉 元吉","reading":"제을귀매 이지 원길","modern":"제을이 누이동생을 시집보내니 복이 있고 크게 길합니다.","meaning":"위 괘의 중심이자 핵심 자리에서 높은 사람이 자신을 낮추어 아래와 인연을 맺는 장면입니다. 지위를 앞세우기보다 겸손하게 연결할 때 서로에게 복이 되는 화합이 이루어집니다.","positive":"겸손한 연결이 양쪽 모두에게 이로운 협력과 복으로 이어질 수 있습니다.","caution":"지위나 조건만 앞세우면 형식적인 관계에 그치기 쉽습니다.","advice":"상대와 대등한 마음으로 약속을 맺고, 서로 이익이 되는 방향으로 조건을 조율해 보세요.","message":"낮추어 맺은 인연이 복이 됩니다."},{"guaN":11,"guaName":"지천태","pos":6,"label":"上六","yinyang":"yin","text":"城復于隍 勿用師 自邑告命 貞吝","reading":"성복우황 물용사 자읍고명 정린","modern":"성이 무너져 다시 해자로 돌아갑니다. 군대를 쓰지 말고, 자기 고을에서부터 명을 알려야 합니다. 바르더라도 아쉬움이 있습니다.","meaning":"끝자리에서 태평하던 흐름이 다하여 쌓아 올린 성이 무너져 내리는 모습입니다. 밖으로 힘을 쓰기보다 안쪽부터 다독이며 정리해야 하는 때입니다.","positive":"흐름이 바뀌는 신호를 알아차리면 피해를 줄이고 안쪽을 정비할 기회가 됩니다.","caution":"무너지는 흐름을 힘으로 되돌리려 하면 오히려 상처가 커지기 쉽습니다.","advice":"확장을 멈추고 가까운 사람들과 상황을 공유하며, 기본 질서부터 차분히 다시 세우세요.","message":"무리하지 말고 안쪽부터 다독이세요."}],"yong":null},"12":{"n":12,"name":"천지비","han":"天地否","upper":"건","lower":"곤","upperHan":"乾","lowerHan":"坤","bits":[0,0,0,1,1,1],"binary":"000111","gua":{"text":"否之匪人 不利君子貞 大往小來","reading":"비지비인 불리군자정 대왕소래","modern":"막힘이 사람의 도리가 아닌 것에서 비롯되니, 군자가 바름을 지키기에 이롭지 않습니다. 큰 것이 가고 작은 것이 옵니다.","symbol":"위에는 하늘(乾), 아래에는 땅(坤)이 있어, 하늘은 위로 올라가고 땅은 아래로 내려가 서로 만나지 못하는 모습입니다. 소통이 끊기고 뜻이 어긋나는 막힘의 괘입니다.","situation":"대화가 통하지 않고 노력이 인정받지 못하며 주변 환경이 불리하게 느껴지는 국면입니다. 이럴 때는 자신을 드러내기보다 안쪽을 단단히 하고 불필요한 충돌을 피하는 편이 도움이 됩니다. 막힘이 영원한 것은 아니므로 다음 흐름을 조용히 준비하는 시간으로 볼 수 있습니다.","positive":"겉으로 드러나는 성과가 적은 대신 내실과 원칙을 가다듬을 수 있는 시간이 됩니다.","caution":"막힌 상황을 억지로 뚫으려 하거나 원망에 매이면 힘만 빠지고 상황이 나빠지기 쉽습니다.","direction":"큰 확장과 결정은 미루고, 필요한 자원과 힘을 아끼며 현상 유지에 집중해 보세요. 뜻이 맞는 소수의 사람과 신뢰를 지키며 풀릴 때를 대비해 실력을 쌓아 두는 편이 좋습니다.","message":"막힐 때는 물러나 내실을 지킵니다."},"yao":[{"guaN":12,"guaName":"천지비","pos":1,"label":"初六","yinyang":"yin","text":"拔茅茹 以其彙 貞吉亨","reading":"발모여 이기휘 정길형","modern":"띠풀을 뽑으니 뿌리가 얽혀 함께 뽑힙니다. 무리와 함께 바름을 지키면 길하고 형통합니다.","meaning":"막힘이 막 시작되는 단계에서 뜻을 같이하는 사람들이 뿌리처럼 이어져 있는 장면입니다. 흐름에 휩쓸려 나아가기보다 함께 바른 자리를 지키는 것이 중요합니다.","positive":"뜻이 같은 사람들과 함께하면 막힌 상황에서도 버틸 힘이 생깁니다.","caution":"불리한 흐름에서 조급히 나서거나 이익을 좇아 무리를 따라가지 않도록 살펴야 합니다.","advice":"신뢰할 수 있는 사람들과 원칙을 공유하고, 지금은 나서기보다 바른 자리를 지키는 데 집중하세요.","message":"함께 바른 자리를 지킵니다."},{"guaN":12,"guaName":"천지비","pos":2,"label":"六二","yinyang":"yin","text":"包承 小人吉 大人否亨","reading":"포승 소인길 대인비형","modern":"윗사람을 받들며 감싸 안으니, 소인에게는 길하고 대인은 막힘 속에서도 형통합니다.","meaning":"아래 괘의 중심에서 윗사람의 뜻을 받들며 순응하는 자리입니다. 이익을 좇는 사람에게는 편한 길이지만, 원칙을 가진 사람은 막힌 상황 속에서도 자신의 중심을 잃지 않고 지킬 수 있습니다.","positive":"겸손히 받아들이는 자세로 불필요한 충돌을 피하면서 중심을 지킬 수 있습니다.","caution":"편한 길을 택하다 원칙을 슬그머니 굽히지 않도록 주의해야 합니다.","advice":"필요한 만큼은 예의 있게 따르되, 포기하지 말아야 할 기준을 스스로 분명히 해 두세요.","message":"순응하되 중심은 지킵니다."},{"guaN":12,"guaName":"천지비","pos":3,"label":"六三","yinyang":"yin","text":"包羞","reading":"포수","modern":"부끄러움을 품고 있습니다.","meaning":"아래 괘의 끝에서 자리가 맞지 않는데도 무리하게 이익이나 위치를 지키려다 부끄러운 일을 안게 되는 모습입니다. 전환기의 불안한 마음이 부끄러운 선택으로 이어지기 쉬운 자리입니다.","positive":"부끄러움을 느끼는 감각 자체가 방향을 바로잡을 계기가 될 수 있습니다.","caution":"불리한 흐름에서 체면이나 이득을 지키려다 정직하지 못한 선택을 하기 쉽습니다.","advice":"마음에 걸리는 일이 있다면 감추지 말고 스스로 인정하고, 늦기 전에 바로잡을 방법을 찾아보세요.","message":"부끄러운 선택은 일찍 바로잡으세요."},{"guaN":12,"guaName":"천지비","pos":4,"label":"九四","yinyang":"yang","text":"有命 无咎 疇離祉","reading":"유명 무구 주리지","modern":"명이 있으니 허물이 없고, 같은 무리가 복을 함께 누립니다.","meaning":"위 괘의 시작이자 윗자리 가까이에서 막힘이 풀리기 시작하는 경계입니다. 정당한 임무나 때를 따라 움직이면 허물이 없고, 함께하는 사람들도 복을 나눌 수 있습니다.","positive":"정당한 역할과 때에 맞춰 움직이면 막힘이 풀리는 첫 신호를 만들 수 있습니다.","caution":"때가 되기 전에 서두르거나 사사로운 이익으로 움직이면 흐름이 다시 막힙니다.","advice":"맡은 역할의 범위 안에서 정당하게 움직이고, 함께하는 사람들과 성과를 나눌 준비를 하세요.","message":"때와 역할에 맞게 움직입니다."},{"guaN":12,"guaName":"천지비","pos":5,"label":"九五","yinyang":"yang","text":"休否 大人吉 其亡其亡 繫于苞桑","reading":"휴비 대인길 기망기망 계우포상","modern":"막힘을 그치게 하니 대인에게 길합니다. 망할까 망할까 하며 조심하면 무성한 뽕나무 뿌리에 매어 두듯 튼튼합니다.","meaning":"위 괘의 중심이자 핵심 자리에서 막힘이 그쳐 가는 전환점입니다. 풀리기 시작해도 방심하지 않고 늘 위기를 의식하는 자세가 안정을 오래 지켜 줍니다.","positive":"경계하는 마음을 유지하면 풀린 흐름을 튼튼하게 다질 수 있습니다.","caution":"막힘이 풀렸다고 마음을 놓으면 같은 어려움이 되돌아오기 쉽습니다.","advice":"좋아지는 신호가 보여도 점검 항목과 대비책을 계속 챙기며, 기반을 단단히 묶어 두세요.","message":"풀려도 경계를 늦추지 않습니다."},{"guaN":12,"guaName":"천지비","pos":6,"label":"上九","yinyang":"yang","text":"傾否 先否後喜","reading":"경비 선비후희","modern":"막힘이 기울어 무너집니다. 먼저는 막히나 나중에는 기쁩니다.","meaning":"끝자리에서 오래 이어진 막힘이 마침내 기울어 풀리는 장면입니다. 어려웠던 시간 뒤에 흐름이 바뀌어 기쁨이 오는 모습이지만, 그 과정에서 변화도 따릅니다.","positive":"오랜 막힘이 풀리면서 새로운 소통과 기회가 열릴 가능성이 있습니다.","caution":"풀리는 순간의 들뜸으로 성급히 움직이면 새 흐름을 놓치기 쉽습니다.","advice":"그동안 쌓아 둔 준비를 점검하고, 달라진 분위기에 맞춰 차분히 한 걸음씩 나아가 보세요.","message":"막힘의 끝에서 기쁨이 열립니다."}],"yong":null},"13":{"n":13,"name":"천화동인","han":"天火同人","upper":"건","lower":"리","upperHan":"乾","lowerHan":"離","bits":[1,0,1,1,1,1],"binary":"101111","gua":{"text":"同人于野 亨 利涉大川 利君子貞","reading":"동인우야 형 리섭대천 리군자정","modern":"사람들과 들판에서 함께합니다. 형통합니다. 큰 내를 건너기에 이롭고, 군자가 바르게 지키는 데 이롭습니다.","symbol":"위에는 하늘(乾), 아래에는 불(離)이 있어, 높은 하늘 아래 불꽃이 환히 타오르는 모습입니다. 탁 트인 곳에서 뜻이 같은 사람들이 모여 함께하는 괘입니다.","situation":"혼자 하기 어려운 일을 여러 사람과 힘을 모아 해 나가는 국면입니다. 같은 목표를 향해 열린 마음으로 모일 때 큰일도 가능해지지만, 가까운 사람끼리만 뭉치거나 이익으로 묶이면 금방 흔들리기 쉽습니다. 누구에게나 공정한 기준이 모임의 힘이 됩니다.","positive":"공동의 목표가 분명하면 많은 사람의 힘이 모여 어려운 일도 함께 넘기기 쉽습니다.","caution":"친한 사람끼리만 뭉치거나 사사로운 이익이 앞서면 모임이 편 가르기로 흐르기 쉽습니다.","direction":"모임의 목적과 기준을 공개적으로 밝히고, 누구에게나 열려 있는 분위기를 만들어 보세요. 의견 차이는 숨기기보다 공통의 목표를 확인하며 조율하는 편이 도움이 됩니다.","message":"열린 마음으로 같은 뜻을 모읍니다."},"yao":[{"guaN":13,"guaName":"천화동인","pos":1,"label":"初九","yinyang":"yang","text":"同人于門 无咎","reading":"동인우문 무구","modern":"문 앞에서 사람들과 함께합니다. 허물이 없습니다.","meaning":"집 문을 나서서 막 사람들을 만나기 시작하는 단계입니다. 아직 특별한 편이 갈리기 전이라 누구와도 열린 마음으로 어울릴 수 있는 장면입니다.","positive":"처음부터 편견 없이 사람을 만나면 넓고 건강한 관계의 바탕이 쉽게 마련됩니다.","caution":"이 단계에서 이미 마음속으로 사람을 가려 두면 관계가 좁아지기 쉽습니다.","advice":"새로운 모임이나 협업의 첫 자리에서는 먼저 인사하고 서로의 목표를 가볍게 나눠 보세요. 특정 사람에게 기대기 전에 폭넓게 만나는 편이 좋습니다.","message":"문을 열고 누구와도 만납니다."},{"guaN":13,"guaName":"천화동인","pos":2,"label":"六二","yinyang":"yin","text":"同人于宗 吝","reading":"동인우종 린","modern":"같은 일가붙이끼리만 함께합니다. 아쉬움이 있습니다.","meaning":"중심에 있는 자리지만 같은 집안이나 같은 파벌 같은 가까운 울타리 안에서만 뭉치는 장면입니다. 편안하긴 해도 범위가 좁아 큰 뜻을 펼치기에는 아쉽습니다.","positive":"믿을 수 있는 가까운 사람들과의 유대는 안정감과 든든함을 줍니다.","caution":"끼리끼리 모이는 데 머물면 바깥 의견이 막히고 모임이 닫히기 쉽습니다.","advice":"익숙한 사람들과의 모임에 다른 배경의 사람이나 새 의견을 한 가지라도 들여 보세요. 가까운 이를 챙기되 기준은 모두에게 같게 두는 편이 좋습니다.","message":"익숙한 울타리 밖으로 문을 엽니다."},{"guaN":13,"guaName":"천화동인","pos":3,"label":"九三","yinyang":"yang","text":"伏戎于莽 升其高陵 三歲不興","reading":"복융우망 승기고릉 삼세불흥","modern":"병사를 풀숲에 숨겨 두고 높은 언덕에 올라 살핍니다. 삼 년이 지나도 일어나지 못합니다.","meaning":"아래 괘의 끝에서 서로 의심하고 경계하는 긴장이 높아진 장면입니다. 속마음을 숨기고 상대를 살피기만 하면 시간만 흘러 관계가 풀리지 않을 수 있습니다.","positive":"경계심은 무리한 충돌을 피하고 상황을 넓게 보도록 도와주기도 합니다.","caution":"의심이 오래 쌓이면 대화가 끊기고 협력할 기회를 놓치기 쉽습니다.","advice":"숨겨 둔 불만이나 의심을 혼자 키우기보다 믿을 만한 자리에서 솔직하게 확인해 보세요. 높은 곳에서 지켜보는 일을 적당한 선에서 멈추는 것도 필요합니다.","message":"의심을 쌓지 말고 대화로 풉니다."},{"guaN":13,"guaName":"천화동인","pos":4,"label":"九四","yinyang":"yang","text":"乘其墉 弗克攻 吉","reading":"승기용 불극공 길","modern":"담장 위에 올라가 있지만 공격하지 못합니다. 길합니다.","meaning":"위 괘의 시작에서 갈등의 담에 올라 맞서려다가 스스로 멈추는 장면입니다. 부딪칠 수 있는 자리에서 한 발 물러나 이치를 따지는 쪽을 택하는 모습입니다.","positive":"다툴 힘이 있어도 멈추면 관계가 깨지지 않고 다시 좋아질 여지가 남습니다.","caution":"멈추지 않고 밀어붙이면 이긴다 해도 신뢰를 잃기 쉽습니다.","advice":"의견이 부딪치는 순간에는 이기려는 마음을 내려놓고 상대가 왜 그렇게 생각하는지 먼저 물어보세요. 감정이 가라앉은 뒤 다시 이야기하는 편이 좋습니다.","message":"맞설 수 있어도 한 걸음 멈춥니다."},{"guaN":13,"guaName":"천화동인","pos":5,"label":"九五","yinyang":"yang","text":"同人 先號咷而後笑 大師克相遇","reading":"동인 선호도이후소 대사극상우","modern":"함께하려는 사람들이 먼저는 울부짖다가 나중에는 웃습니다. 큰 군대가 이겨서 서로 만납니다.","meaning":"핵심 자리에서 뜻이 같은 사람들이 가운데 장애물 때문에 한동안 떨어져 힘들어하다가, 끝내 이겨 내고 만나 웃게 되는 장면입니다. 이 과정에는 눈물과 큰 노력이 따른다는 점이 담겨 있습니다.","positive":"어려움을 함께 견딘 뒤의 만남은 신뢰가 깊어지기 쉽습니다.","caution":"방해 요소를 가볍게 보면 만남이 더 늦어지고 지치기 쉽습니다.","advice":"함께하는 길에 방해가 되는 요인을 숨기지 말고 인정하며, 함께 해결할 방법을 정하세요. 당장은 힘들어도 끈기 있게 이어 가는 편이 도움이 됩니다.","message":"눈물 뒤에 함께 웃는 날을 만듭니다."},{"guaN":13,"guaName":"천화동인","pos":6,"label":"上九","yinyang":"yang","text":"同人于郊 无悔","reading":"동인우교 무회","modern":"교외에서 사람들과 함께합니다. 후회가 없습니다.","meaning":"가장 바깥 자리에서 뜻이 같은 사람들과의 일이 한 단계 마무리되는 장면입니다. 도심의 중심에서 한 발 떨어진 곳이라 큰 성취보다는 담담한 어울림에 가깝습니다.","positive":"과한 욕심 없이 거리를 두고 함께하면 후회가 적은 관계가 되기 쉽습니다.","caution":"거리가 너무 멀어지면 모임의 큰 뜻을 이루는 힘은 약해질 수 있습니다.","advice":"이제는 모임의 중심을 차지하려 하기보다 한 걸음 물러나 필요한 만큼만 돕는 방식도 생각해 보세요. 성과보다 관계의 질을 챙기는 편이 좋습니다.","message":"한 걸음 물러서도 마음은 함께합니다."}],"yong":null},"14":{"n":14,"name":"화천대유","han":"火天大有","upper":"리","lower":"건","upperHan":"離","lowerHan":"乾","bits":[1,1,1,1,0,1],"binary":"111101","gua":{"text":"元亨","reading":"원형","modern":"크게 형통합니다.","symbol":"위에는 불·해(離), 아래에는 하늘(乾)이 있어, 높은 하늘 위에 해가 환히 떠서 만물을 비추는 모습입니다. 많은 것을 크게 소유하고 풍요를 누리는 괘입니다.","situation":"성과와 자원, 사람의 신뢰가 모이는 풍성한 국면입니다. 가진 것이 많을수록 어떻게 쓰고 나누는지가 더 중요해지며, 교만과 과시는 주변의 시기를 부르기 쉽습니다. 능력은 크지만 마음은 부드럽게 두는 태도가 좋은 흐름을 오래 이어 줍니다.","positive":"능력과 자원, 주변의 지지가 함께 모여 큰일을 이루기 쉬운 때입니다.","caution":"풍족함에 취해 과시하거나 독점하면 시기와 불화가 따르기 쉽습니다.","direction":"얻은 것을 바르게 쓰고 함께한 사람들에게 나누는 쪽으로 방향을 잡아 보세요. 관리 체계를 정비하고 겸손을 유지하면 풍요가 오래갈 가능성이 높아집니다.","message":"가진 것을 바르게 쓰고 나눕니다."},"yao":[{"guaN":14,"guaName":"화천대유","pos":1,"label":"初九","yinyang":"yang","text":"无交害 匪咎 艱則无咎","reading":"무교해 비구 간즉무구","modern":"해로운 것과 사귀지 않으면 허물이 아닙니다. 어려움을 알고 조심하면 허물이 없습니다.","meaning":"아직 가진 것이 많지 않은 시작 단계로, 풍요가 다가오기 전에 해가 될 만한 만남이나 유혹을 피하라는 장면입니다. 어려운 처지를 잊지 않으면 큰 문제가 생기기 어렵습니다.","positive":"아직 가진 것이 적을 때의 조심스러운 태도가 이후의 안정을 만들어 줍니다.","caution":"작은 성공에 들뜨거나 이해관계가 얽힌 만남에 휩쓸리기 쉽습니다.","advice":"얻은 것이 적을수록 함께하는 사람과 투자 대상을 신중히 고르세요. 처음의 어려웠던 마음가짐을 기록해 두면 도움이 됩니다.","message":"시작은 조심스럽게 시작합니다."},{"guaN":14,"guaName":"화천대유","pos":2,"label":"九二","yinyang":"yang","text":"大車以載 有攸往 无咎","reading":"대거이재 유유왕 무구","modern":"큰 수레에 짐을 싣습니다. 갈 곳이 있어도 허물이 없습니다.","meaning":"아래 괘의 가운데에서 많은 재물과 책임을 실을 만한 튼튼한 수레처럼 믿음직한 역량을 갖춘 장면입니다. 위의 부름에 응해 나서도 무리가 없는 때입니다.","positive":"맡은 몫을 감당할 능력이 갖춰져 있어 큰 역할도 안정적으로 해내기 쉽습니다.","caution":"실을 수 있는 한계를 넘겨 욕심껏 담으면 수레가 부서질 수 있습니다.","advice":"맡을 일의 양과 자원을 점검해 감당 가능한 범위 안에서 움직이세요. 필요하면 일을 나누어 맡기는 구조를 먼저 갖추는 편이 좋습니다.","message":"튼튼한 수레에 알맞게 싣습니다."},{"guaN":14,"guaName":"화천대유","pos":3,"label":"九三","yinyang":"yang","text":"公用亨于天子 小人弗克","reading":"공용향우천자 소인불극","modern":"제후가 천자에게 잔치를 바칩니다. 소인은 이를 해내지 못합니다.","meaning":"아래 괘의 끝에서 쌓은 것을 자기 것으로만 두지 않고 공적인 자리에 내놓는 장면입니다. 가진 것을 나눌 줄 아는 태도가 시험받는 전환기입니다.","positive":"성과를 더 큰 공동체를 위해 내놓으면 신뢰와 더 큰 기회가 따라오기 쉽습니다.","caution":"얻은 것을 사사로이 붙들면 작은 이익에 갇히기 쉽습니다.","advice":"얻은 성과의 일부를 조직이나 공동의 일에 쓰는 방식을 생각해 보세요. 나눔의 기준과 방법은 투명하게 정해 두는 편이 좋습니다.","message":"쌓은 것을 공적으로 씁니다."},{"guaN":14,"guaName":"화천대유","pos":4,"label":"九四","yinyang":"yang","text":"匪其彭 无咎","reading":"비기방 무구","modern":"너무 성대하게 하지 않습니다. 허물이 없습니다.","meaning":"위 괘의 시작이자 가장 높은 자리와 가까워, 세력이 너무 커 보이기 쉬운 경계의 자리입니다. 기세를 과하게 드러내지 않고 스스로 조절하는 장면입니다.","positive":"힘을 드러내지 않고 조절하면 윗사람과 주변의 의심을 피하기 쉽습니다.","caution":"가까운 윗자리를 의식해 과시하면 견제와 오해를 받기 쉽습니다.","advice":"실적과 영향력을 필요 이상 부풀리지 말고 담담히 보여 주세요. 윗사람과의 소통은 공개적이고 투명하게 이어 가는 편이 도움이 됩니다.","message":"성대함을 덜어 내고 절제합니다."},{"guaN":14,"guaName":"화천대유","pos":5,"label":"六五","yinyang":"yin","text":"厥孚交如 威如 吉","reading":"궐부교여 위여 길","modern":"그 믿음이 서로 통하고, 위엄도 있습니다. 길합니다.","meaning":"풍요의 중심에서 부드러운 마음으로 사람들과 믿음을 나누면서도 필요한 위엄을 잃지 않는 장면입니다. 신뢰와 단호함이 균형을 이룬 리더의 모습입니다.","positive":"믿음과 위엄이 함께 있어 사람들이 자연스럽게 따르고 일이 순조롭기 쉽습니다.","caution":"너무 부드럽기만 하면 기강이 풀리고, 너무 엄격하면 믿음이 식기 쉽습니다.","advice":"진심으로 소통하되 지켜야 할 약속과 기준은 분명하게 말하세요. 칭찬과 책임을 함께 나누는 방식이 도움이 됩니다.","message":"믿음으로 이끌고 위엄을 지킵니다."},{"guaN":14,"guaName":"화천대유","pos":6,"label":"上九","yinyang":"yang","text":"自天祐之 吉无不利","reading":"자천우지 길무불리","modern":"하늘로부터 도움을 받습니다. 길하며 이롭지 않은 것이 없습니다.","meaning":"큰 풍요의 끝에서도 겸손하게 덕을 지켜 온 덕분에 주변의 도움과 좋은 기운이 따르는 장면입니다. 가득 찬 자리에서 더 덜어 내고 낮추는 태도가 담겨 있습니다.","positive":"오래 쌓은 신뢰와 겸손이 뜻하지 않은 도움과 좋은 기회로 이어지기 쉽습니다.","caution":"정점에서 방심하면 자만이 싹터 쌓아 온 신뢰를 갉아먹을 수 있습니다.","advice":"가장 좋은 때일수록 받은 도움에 감사를 표하고 다음 세대와 주변에 기회를 돌려주세요. 정점에서의 겸손이 오래가는 길입니다.","message":"가득 찬 때일수록 낮춥니다."}],"yong":null},"15":{"n":15,"name":"지산겸","han":"地山謙","upper":"곤","lower":"간","upperHan":"坤","lowerHan":"艮","bits":[0,0,1,0,0,0],"binary":"001000","gua":{"text":"亨 君子有終","reading":"형 군자유종","modern":"형통합니다. 군자는 끝맺음이 있습니다.","symbol":"위에는 땅(坤), 아래에는 산(艮)이 있어, 높은 산이 땅 아래에 몸을 낮추고 있는 모습입니다. 실력이 있어도 스스로를 낮추는 겸손의 괘입니다.","situation":"능력이나 지위가 있으면서도 드러내지 않고 낮은 자세로 임하는 국면입니다. 이런 태도는 사람들의 신뢰를 얻고 일을 순조롭게 풀리게 하는 힘이 됩니다. 반대로 겸손을 핑계로 책임을 피하면 그 장점이 사라지므로 해야 할 일은 끝까지 해내는 것이 중요합니다.","positive":"낮은 자세는 갈등을 줄이고 주변의 도움과 호감을 얻는 데 큰 힘이 되기 쉽습니다.","caution":"겸손이 지나쳐 소극적이 되거나 책임을 미루는 핑계가 되지 않도록 살펴야 합니다.","direction":"성과를 말할 때 함께한 사람과 환경의 도움을 먼저 언급하고, 맡은 일은 묵묵히 끝까지 이어 가세요. 낮추되 필요한 말은 분명히 하는 편이 도움이 됩니다.","message":"낮추는 사람이 끝까지 갑니다."},"yao":[{"guaN":15,"guaName":"지산겸","pos":1,"label":"初六","yinyang":"yin","text":"謙謙君子 用涉大川 吉","reading":"겸겸군자 용섭대천 길","modern":"겸손하고 또 겸손한 군자는 큰 내를 건널 수 있습니다. 길합니다.","meaning":"가장 아래에서 시작하며 겸손을 몸에 익힌 단계로, 스스로를 거듭 낮추는 사람의 장면입니다. 그런 마음가짐이면 큰 일이나 모험 앞에서도 흔들림이 적습니다.","positive":"처음부터 낮은 자세로 임하면 새로운 도전에서도 주변의 도움을 받기 쉽습니다.","caution":"겸손이 지나쳐 시작 자체를 망설이면 기회가 지나갈 수 있습니다.","advice":"새로운 일을 시작할 때 아는 척하기보다 배우는 자세로 사람들에게 먼저 묻고 도움을 청해 보세요. 겸손한 태도로 한 걸음씩 나아가는 편이 좋습니다.","message":"낮은 곳에서 겸손으로 시작합니다."},{"guaN":15,"guaName":"지산겸","pos":2,"label":"六二","yinyang":"yin","text":"鳴謙 貞吉","reading":"명겸 정길","modern":"겸손함이 밖으로 울려 퍼집니다. 바르게 지키면 길합니다.","meaning":"아래 괘의 가운데에서 꾸며서가 아니라 마음에서 우러난 겸손이 자연스럽게 밖으로 알려지는 장면입니다. 사람들이 그 태도를 알아보고 호감을 갖게 됩니다.","positive":"진심에서 나온 겸손은 따로 알리지 않아도 주변의 신뢰로 이어지기 쉽습니다.","caution":"평판을 의식해 겸손을 연기하면 곧 드러나 오히려 신뢰를 잃기 쉽습니다.","advice":"인정받으려는 마음 없이 평소의 말과 행동을 일관되게 유지하세요. 칭찬을 받으면 담담히 받되 함께한 사람에게 공을 돌리는 편이 좋습니다.","message":"진심의 겸손은 저절로 알려집니다."},{"guaN":15,"guaName":"지산겸","pos":3,"label":"九三","yinyang":"yang","text":"勞謙 君子有終 吉","reading":"로겸 군자유종 길","modern":"수고하면서도 겸손합니다. 군자는 끝맺음이 있어 길합니다.","meaning":"아래 괘의 끝에서 애쓴 공이 크지만 자랑하지 않고 계속 낮은 자세로 일하는 장면입니다. 이 괘에서 유일한 양효로, 성과를 내는 사람의 겸손이 가장 빛나는 자리입니다.","positive":"공을 내세우지 않고 꾸준히 일하는 모습이 두터운 신뢰와 좋은 마무리를 만들기 쉽습니다.","caution":"고생이 쌓이면 서운함이 올라와 공을 내세우고 싶어질 수 있습니다.","advice":"맡은 일을 끝까지 해내되 성과는 함께한 사람들과 나누세요. 지칠 땐 혼자 떠안지 말고 도움을 요청하는 편이 좋습니다.","message":"수고하고도 자랑하지 않습니다."},{"guaN":15,"guaName":"지산겸","pos":4,"label":"六四","yinyang":"yin","text":"无不利 撝謙","reading":"무불리 휘겸","modern":"이롭지 않은 것이 없습니다. 겸손을 드러내 펼칩니다.","meaning":"위 괘의 시작이자 윗사람과 가까운 자리에서 겸손을 상황에 맞게 널리 펼쳐 쓰는 장면입니다. 위로는 존중하고 아래로는 배려하며 균형을 잡는 모습입니다.","positive":"겸손을 일관되게 실천하면 윗사람과 아랫사람 모두에게 신뢰를 얻기 쉽습니다.","caution":"가까운 윗자리를 의식해 지나치게 몸을 낮추면 줏대 없어 보일 수 있습니다.","advice":"주변 사람에게 존중을 표현하되 자신의 책임과 의견은 분명히 하세요. 윗사람에게는 정중하게, 아랫사람에게는 열린 마음으로 대하는 편이 좋습니다.","message":"겸손을 알맞게 두루 펼칩니다."},{"guaN":15,"guaName":"지산겸","pos":5,"label":"六五","yinyang":"yin","text":"不富以其鄰 利用侵伐 无不利","reading":"불부이기린 리용침벌 무불리","modern":"부유하지 않아도 이웃과 함께합니다. 정벌에 나서는 것이 이로우며 이롭지 않은 것이 없습니다.","meaning":"중심 자리에서 부드럽게 겸손하지만, 따르지 않는 쪽에는 필요할 때 단호하게 대처하는 장면입니다. 이웃과 나누는 마음이 있기에 그 단호함도 정당성을 얻습니다.","positive":"나눔과 겸손으로 얻은 신뢰가 있어 필요한 순간 단호하게 움직여도 지지를 받기 쉽습니다.","caution":"부드러움만 고집하면 부당한 일을 방치하고, 강경함이 앞서면 신뢰를 잃기 쉽습니다.","advice":"주변과 자원을 나누면서도 규칙을 어기는 일에는 분명히 선을 그으세요. 단호한 조치는 감정이 아닌 공정한 기준으로 진행하는 편이 좋습니다.","message":"나누는 마음에 단호함을 더합니다."},{"guaN":15,"guaName":"지산겸","pos":6,"label":"上六","yinyang":"yin","text":"鳴謙 利用行師 征邑國","reading":"명겸 리용행사 정읍국","modern":"겸손함이 밖으로 울려 퍼집니다. 군대를 움직여 자기 고을과 나라를 바로잡는 데 이롭습니다.","meaning":"끝자리에서 겸손함이 널리 알려졌지만 아직 마음먹은 대로 되지 않는 안쪽의 일을 스스로 정리해야 하는 장면입니다. 바깥 일보다 자기 영역의 문제를 바로잡는 쪽이 중심입니다.","positive":"쌓인 신망 덕분에 내부를 정돈하는 일을 비교적 순조롭게 추진하기 쉽습니다.","caution":"겸손을 이유로 미뤄 온 일이 쌓이면 오히려 문제가 커질 수 있습니다.","advice":"미뤄 둔 정리와 개선 작업을 이제 실행에 옮겨 보세요. 먼저 내 주변과 조직 안의 문제부터 차근차근 바로잡는 편이 좋습니다.","message":"겸손의 힘으로 내 안부터 바로잡습니다."}],"yong":null},"16":{"n":16,"name":"뇌지예","han":"雷地豫","upper":"진","lower":"곤","upperHan":"震","lowerHan":"坤","bits":[0,0,0,1,0,0],"binary":"000100","gua":{"text":"利建侯行師","reading":"리건후행사","modern":"제후를 세우고 군대를 움직이는 데 이롭습니다.","symbol":"위에는 우레(震), 아래에는 땅(坤)이 있어, 봄에 땅 위에서 우레가 울리며 만물이 깨어나는 모습입니다. 기쁨과 화합, 그리고 미리 준비한다는 뜻을 함께 지닌 괘입니다.","situation":"분위기가 좋고 사람들의 마음이 한데 모여 새로운 일을 추진하기 쉬운 국면입니다. 기쁨은 사람을 움직이는 힘이지만 지나치면 들뜸과 방심으로 이어지기 쉽습니다. 좋은 흐름을 타면서도 미리 준비하는 습관이 필요합니다.","positive":"사람들의 호응과 기대가 모여 일을 시작하고 추진하기에 좋은 분위기가 만들어지기 쉽습니다.","caution":"들뜬 기분에 취해 준비와 점검을 소홀히 하면 나중에 후회가 따르기 쉽습니다.","direction":"좋은 분위기를 활용해 계획을 세우고 협력을 구하되, 중요한 결정은 한 번 더 점검하세요. 즐거움과 준비를 함께 챙기는 편이 도움이 됩니다.","message":"기쁨을 타되 준비는 미리 합니다."},"yao":[{"guaN":16,"guaName":"뇌지예","pos":1,"label":"初六","yinyang":"yin","text":"鳴豫 凶","reading":"명예 흉","modern":"즐거움을 소리 내어 자랑합니다. 흉합니다.","meaning":"막 시작하는 단계에서 좋은 일이 생기자 들뜬 마음을 숨기지 못하고 자랑하는 장면입니다. 윗사람과 호응하는 자리를 믿고 뽐내다가 곤란해질 수 있습니다.","positive":"기쁜 일이 있다는 것은 의욕과 활기가 있다는 신호입니다.","caution":"아직 실력이 자리 잡기 전에 자랑하면 질투나 부담을 부르기 쉽습니다.","advice":"좋은 소식이나 후원이 있어도 조용히 받아들이고 실력을 먼저 쌓으세요. 자랑 대신 감사의 표현을 하는 편이 좋습니다.","message":"기쁨은 자랑보다 조용히 나눕니다."},{"guaN":16,"guaName":"뇌지예","pos":2,"label":"六二","yinyang":"yin","text":"介于石 不終日 貞吉","reading":"개우석 부종일 정길","modern":"돌처럼 굳건합니다. 하루가 다 가기 전에 판단합니다. 바르게 지키면 길합니다.","meaning":"아래 괘의 중심에서 모두가 들뜬 분위기 속에서도 돌처럼 흔들리지 않고, 질질 끌지 않고 곧 방향을 판단하는 장면입니다. 이 괘에서 가장 정신이 맑은 자리입니다.","positive":"분위기에 휩쓸리지 않고 기준을 지키면 빠르고 올바른 판단을 하기 쉽습니다.","caution":"혼자만 굳건하다 보면 주변과 어울리지 못하고 고립될 수 있습니다.","advice":"들뜬 분위기 속에서도 나만의 기준을 세워 두고, 아닌 일은 오래 끌지 말고 정리하세요. 주변과는 부드럽게 소통하는 편이 도움이 됩니다.","message":"들뜬 때일수록 기준을 지킵니다."},{"guaN":16,"guaName":"뇌지예","pos":3,"label":"六三","yinyang":"yin","text":"盱豫 悔 遲有悔","reading":"우예 회 지유회","modern":"윗사람을 쳐다보며 즐거워합니다. 후회가 있습니다. 늦게 고치면 후회가 있습니다.","meaning":"아래 괘의 끝에서 자기 판단 없이 윗자리의 눈치만 보며 기쁨을 얻으려는 장면입니다. 의존하다가 주저하며 고칠 때를 놓치면 후회가 깊어집니다.","positive":"윗사람의 인정을 구하는 마음은 성장의 동기가 되기도 합니다.","caution":"남의 평가에 기대어 즐거움을 찾으면 스스로 방향을 잃고 때를 놓치기 쉽습니다.","advice":"인정받는 데서 오는 기쁨과 내가 정말 원하는 것을 구분해 보세요. 어긋났다고 느끼면 미루지 말고 일찍 방향을 바로잡는 편이 좋습니다.","message":"눈치 대신 내 판단으로 움직입니다."},{"guaN":16,"guaName":"뇌지예","pos":4,"label":"九四","yinyang":"yang","text":"由豫 大有得 勿疑 朋盍簪","reading":"유예 대유득 물의 붕합잠","modern":"즐거움이 이 사람으로 말미암습니다. 크게 얻는 것이 있습니다. 의심하지 마세요. 벗들이 비녀로 머리를 모으듯 모여듭니다.","meaning":"위 괘의 시작이자 이 괘의 유일한 양효로, 사람들의 기쁨과 기대가 이 사람에게 모이는 중심 장면입니다. 자신을 믿고 나설 때 벗들이 비녀로 머리카락을 모으듯 모입니다.","positive":"사람들의 신뢰가 모여 큰 성과를 낼 수 있는 힘이 생기기 쉽습니다.","caution":"스스로를 의심하며 망설이면 모인 뜻이 흩어질 수 있습니다.","advice":"모인 사람들의 기대를 구체적인 계획과 역할 분담으로 연결해 보세요. 중심에 선다고 독점하지 말고 투명하게 소통하는 편이 좋습니다.","message":"믿음을 갖고 사람들을 모읍니다."},{"guaN":16,"guaName":"뇌지예","pos":5,"label":"六五","yinyang":"yin","text":"貞疾 恒不死","reading":"정질 항불사","modern":"바르게 지키지만 병이 듭니다. 오래도록 죽지는 않습니다.","meaning":"중심 자리에 있지만 가까운 강한 힘에 눌려 마음이 무겁고 답답한 장면입니다. 크게 무너지지는 않으나 지속적인 부담을 안고 가는 상태입니다.","positive":"어려움 속에서도 중심을 지키며 버티는 힘이 있어 큰 무너짐은 피하기 쉽습니다.","caution":"스트레스를 오래 방치하면 몸과 마음이 지치고 판단력이 흐려지기 쉽습니다.","advice":"부담이 되는 일과 사람을 점검하고 휴식과 도움 요청의 여유를 마련하세요. 몸이나 마음이 힘들다면 전문가와 상담하는 편이 좋습니다.","message":"눌린 마음을 돌보며 버팁니다."},{"guaN":16,"guaName":"뇌지예","pos":6,"label":"上六","yinyang":"yin","text":"冥豫 成有渝 无咎","reading":"명예 성유투 무구","modern":"즐거움에 눈이 어둡습니다. 이미 이루어진 일이라도 바꿀 수 있으면 허물이 없습니다.","meaning":"끝자리에서 즐거움에 빠져 판단이 흐려진 장면입니다. 이미 굳어진 습관도 마음먹고 바꾸면 허물을 피할 수 있다는 뜻이 담겨 있습니다.","positive":"스스로 잘못된 흐름을 알아차리고 바꾸면 다시 균형을 되찾기 쉽습니다.","caution":"즐거움에 계속 빠져 있으면 더 중요한 것을 놓칠 수 있습니다.","advice":"반복되는 즐거움이나 습관 중 나를 흐리게 하는 것이 있는지 돌아보세요. 작은 것부터 방식을 바꿔 보는 편이 도움이 됩니다.","message":"빠져 있던 즐거움에서 벗어납니다."}],"yong":null},"17":{"n":17,"name":"택뢰수","han":"澤雷隨","upper":"태","lower":"진","upperHan":"兌","lowerHan":"震","bits":[1,0,0,1,1,0],"binary":"100110","gua":{"text":"元亨利貞 无咎","reading":"원형이정 무구","modern":"크게 형통하고 바르게 하면 이로우며, 허물이 없습니다.","symbol":"위는 못(澤, 기쁨), 아래는 우레(雷, 움직임)입니다. 움직임이 있고 기쁨이 뒤따르듯, 때와 사람을 따라 유연하게 응하는 모습입니다.","situation":"새로운 흐름이나 믿을 만한 사람을 따라야 하는 국면입니다. 내 고집을 잠시 내려놓고 배우면 길이 열리기 쉽지만, 따르는 대상을 가리지 않으면 휩쓸리기 쉬운 때이기도 합니다.","positive":"유연하게 적응하면 사람의 마음을 얻고 일이 순조롭게 풀릴 가능성이 큽니다.","caution":"따르는 일 자체가 목적이 되면 원칙을 잃을 수 있으니, 무엇을 왜 따르는지 늘 살펴보세요.","direction":"먼저 내가 따를 만한 기준과 사람이 바른지 점검하세요. 그런 다음 때에 맞게 방식을 바꾸되, 바름이라는 중심은 지키는 편이 도움이 됩니다.","message":"바른 것을 따르면 길이 열립니다."},"yao":[{"guaN":17,"guaName":"택뢰수","pos":1,"label":"初九","yinyang":"yang","text":"官有渝 貞吉 出門交有功","reading":"관유투 정길 출문교유공","modern":"관직(맡은 자리)에 변화가 있으니, 바르게 하면 길합니다. 문을 나서 사람들과 사귀면 공이 있습니다.","meaning":"막 변화가 시작되는 첫 자리입니다. 환경이 바뀌는 때이니 집 안에만 머물지 말고 바깥으로 나가 사람을 만나 보라는 장면입니다.","positive":"새 환경에서 열린 마음으로 사람을 사귀면 뜻밖의 도움을 얻기 쉽습니다.","caution":"사귀는 사람이 누구든 좋다는 식이면 곤란하니, 바른 기준은 지켜야 합니다.","advice":"예전 방식을 고집하지 말고 새 모임이나 새 사람에게 먼저 다가가 보세요. 다만 가까워질 사람은 신중히 고르세요.","message":"문을 열고 나가 사귀세요."},{"guaN":17,"guaName":"택뢰수","pos":2,"label":"六二","yinyang":"yin","text":"係小子 失丈夫","reading":"계소자 실장부","modern":"어린 사람에게 매이면 어른 같은 사람을 잃습니다.","meaning":"가까이 있는 편한 사람이나 작은 이익에 마음이 붙들리는 자리입니다. 이쪽을 택하면 저쪽을 놓치기 쉬운 갈림길입니다.","positive":"가까운 관계를 소중히 여기는 마음은 안정감을 줄 수 있습니다.","caution":"편한 쪽만 따르다가 더 큰 가르침이나 기회를 놓칠 가능성이 있습니다.","advice":"지금 붙들고 있는 것이 정말 나를 키워 주는지 비교해 보세요. 눈앞의 편안함과 장기적 성장 중 무엇을 택할지 정리하는 것이 도움이 됩니다.","message":"가까운 것에 매이지 마세요."},{"guaN":17,"guaName":"택뢰수","pos":3,"label":"六三","yinyang":"yin","text":"係丈夫 失小子 隨有求得 利居貞","reading":"계장부 실소자 수유구득 리거정","modern":"어른 같은 사람을 따르면 어린 사람을 잃습니다. 따르면 구하는 것을 얻을 수 있으니, 바른 자리에 머무는 것이 이롭습니다.","meaning":"앞 단계와 반대로 더 큰 쪽을 택하는 전환기입니다. 얻는 것이 있는 대신 내려놓는 것도 생기는 때입니다.","positive":"더 나은 스승이나 흐름을 따르면 원하던 것을 얻을 가능성이 있습니다.","caution":"얻으려는 마음이 앞서 바른 자리를 벗어나면 오히려 흔들리기 쉽습니다.","advice":"무엇을 얻고 무엇을 놓을지 미리 인정하고 선택하세요. 욕심이 아니라 바른 자리를 지키는 데 중심을 두세요.","message":"큰 것을 택하되 바름을 지키세요."},{"guaN":17,"guaName":"택뢰수","pos":4,"label":"九四","yinyang":"yang","text":"隨有獲 貞凶 有孚在道 以明 何咎","reading":"수유획 정흉 유부재도 이명 하구","modern":"따라서 얻는 것이 있어도 고집하면 흉할 수 있습니다. 믿음이 도에 있고 밝게 처신하면 무슨 허물이 있겠습니까.","meaning":"윗사람 가까이에서 인정과 성과를 얻는 자리입니다. 가까운 만큼 공을 내세우거나 지위를 넘보는 오해를 사기 쉬운 경계선이기도 합니다.","positive":"성실하고 분명하게 처신하면 얻은 성과가 신뢰로 이어지기 쉽습니다.","caution":"성과에 집착하거나 윗자리를 의식해 과하게 행동하면 의심을 살 수 있습니다.","advice":"얻은 것을 내 몫으로만 두지 말고 투명하게 공유하세요. 의도가 바르고 분명하면 불필요한 오해를 줄일 수 있습니다.","message":"성과보다 믿음을 앞세우세요."},{"guaN":17,"guaName":"택뢰수","pos":5,"label":"九五","yinyang":"yang","text":"孚于嘉 吉","reading":"부우가 길","modern":"아름답고 선한 것에 믿음을 두니 길합니다.","meaning":"따름의 중심에 선 자리입니다. 좋은 것을 알아보고 믿어 주는 쪽이어서 사람들도 이 자리를 따르는 모습입니다.","positive":"선하고 좋은 것에 진심으로 마음을 두면 주변의 신뢰도 함께 쌓이기 쉽습니다.","caution":"좋아 보이는 것만 믿고 검증을 건너뛰면 판단이 흐려질 수 있습니다.","advice":"내가 믿는 대상이 정말 좋은지 한 번 더 확인하세요. 나 또한 믿을 만한 사람으로 행동하는 편이 도움이 됩니다.","message":"좋은 것에 진심을 두세요."},{"guaN":17,"guaName":"택뢰수","pos":6,"label":"上六","yinyang":"yin","text":"拘係之 乃從維之 王用亨于西山","reading":"구계지 내종유지 왕용향우서산","modern":"굳게 묶어 붙잡고 이어 맵니다. 왕이 서산에서 제사를 올립니다.","meaning":"따름이 가장 깊어진 끝자리입니다. 마음이 단단히 맺어진 모습이지만, 끝까지 가면 놓지 못하는 집착이 될 수도 있습니다.","positive":"깊은 신뢰와 헌신은 오래 이어지는 관계의 바탕이 됩니다.","caution":"너무 꽉 붙잡으면 서로를 얽매어 자유롭지 못하게 될 수 있습니다.","advice":"관계와 약속의 깊이는 소중히 하되, 숨 쉴 여유도 남겨 두세요. 마무리 단계에서는 감사의 마음을 표현해 보세요.","message":"깊이 맺되 얽매이지 마세요."}],"yong":null},"18":{"n":18,"name":"산풍고","han":"山風蠱","upper":"간","lower":"손","upperHan":"艮","lowerHan":"巽","bits":[0,1,1,0,0,1],"binary":"011001","gua":{"text":"元亨 利涉大川 先甲三日 後甲三日","reading":"원형 리섭대천 선갑삼일 후갑삼일","modern":"크게 형통합니다. 큰 내를 건너기에 이롭습니다. 갑일 사흘 전과 갑일 사흘 뒤를 살핍니다.","symbol":"위는 산(山, 멈춤), 아래는 바람(風, 스며듦)입니다. 산 아래 바람이 막혀 고여 썩듯, 오래 쌓인 문제를 바로잡아야 하는 모습입니다.","situation":"방치해 둔 문제나 오래된 습관, 관계의 묵은 앙금이 드러나는 국면입니다. 덮어 두면 더 곪기 쉽지만, 원인을 정리해 고치기 시작하면 새 출발의 계기가 될 가능성이 큽니다.","positive":"묵은 문제를 직시하고 손보기 시작하면 한동안 막혔던 일에 새 활력이 생길 수 있습니다.","caution":"과거를 탓하는 데 머물거나 준비 없이 서두르면 갈등만 커지기 쉽습니다.","direction":"고치기 전에 사흘 동안 계획하고, 고친 뒤에도 사흘 동안 점검하라는 말처럼 앞뒤로 신중하세요. 감정보다 원칙과 순서를 정해 단계적으로 개선해 가는 편이 도움이 됩니다.","message":"묵은 일을 정리하면 새 길이 열립니다."},"yao":[{"guaN":18,"guaName":"산풍고","pos":1,"label":"初六","yinyang":"yin","text":"幹父之蠱 有子 考无咎 厲終吉","reading":"간부지고 유자 고무구 려종길","modern":"아버지가 남긴 폐단을 바로잡습니다. 이런 자식이 있으면 돌아가신 아버지에게 허물이 없습니다. 위태로우나 끝내는 길합니다.","meaning":"앞 세대나 앞선 사람이 남긴 문제를 처음 맡아 수습하는 시작점입니다. 경험이 적어 조심스럽지만, 책임지려는 태도가 첫걸음입니다.","positive":"문제를 외면하지 않고 맡으려는 마음이 신뢰를 얻는 출발점이 됩니다.","caution":"의욕만 앞서면 위태로울 수 있으니 과거 사정을 충분히 알고 나서 움직여야 합니다.","advice":"먼저 무엇이 왜 문제가 되었는지 파악하세요. 전임자를 탓하기보다 이어받아 개선하는 자세가 도움이 됩니다.","message":"물려받은 짐을 차분히 정리하세요."},{"guaN":18,"guaName":"산풍고","pos":2,"label":"九二","yinyang":"yang","text":"幹母之蠱 不可貞","reading":"간모지고 불가정","modern":"어머니가 남긴 폐단을 바로잡을 때는 너무 곧게만 하려 해서는 안 됩니다.","meaning":"가까운 사람, 특히 정이 얽힌 관계의 문제를 다루는 자리입니다. 옳고 그름만 따지면 마음을 다치기 쉬운 상황입니다.","positive":"부드럽게 설득하고 감정을 존중하면 갈등을 덜 일으키고 고칠 수 있습니다.","caution":"원칙만 내세워 몰아붙이면 관계가 깨질 가능성이 있습니다.","advice":"가까운 사람과의 문제일수록 말투와 속도를 조절하세요. 고칠 점은 분명히 하되 상대가 받아들일 여지를 남기는 편이 좋습니다.","message":"강하게 말고 부드럽게 고치세요."},{"guaN":18,"guaName":"산풍고","pos":3,"label":"九三","yinyang":"yang","text":"幹父之蠱 小有悔 无大咎","reading":"간부지고 소유회 무대구","modern":"아버지가 남긴 폐단을 바로잡습니다. 작은 후회는 있으나 큰 허물은 없습니다.","meaning":"개혁의 의지가 강해지는 전환기입니다. 지나치게 몰아붙이다 작은 마찰이나 실수가 생길 수 있지만, 큰 틀에서는 바른 방향입니다.","positive":"적극적인 추진력으로 막혀 있던 일이 눈에 띄게 움직이기 쉽습니다.","caution":"속도가 지나치면 주변의 반발과 작은 후회가 따를 수 있습니다.","advice":"실수가 있어도 방향이 맞다면 수정하며 이어 가세요. 함께하는 사람들의 의견을 중간에 한 번 들어 보세요.","message":"작은 후회는 감수하며 나아가세요."},{"guaN":18,"guaName":"산풍고","pos":4,"label":"六四","yinyang":"yin","text":"裕父之蠱 往見吝","reading":"유부지고 왕견린","modern":"아버지가 남긴 폐단을 너그럽게 넘깁니다. 그대로 나아가면 아쉬움을 보게 됩니다.","meaning":"윗자리 가까이에 있으면서 문제를 알고도 느슨하게 넘기기 쉬운 자리입니다. 힘이 부족해 미루는 모습이기도 합니다.","positive":"무리하지 않고 상황을 조용히 살필 여유는 가질 수 있습니다.","caution":"문제를 그대로 두고 지나가면 결국 더 큰 부담이 되어 돌아올 가능성이 있습니다.","advice":"미루고 있는 문제가 있는지 솔직하게 돌아보세요. 혼자 힘이 부족하다면 도움받을 사람을 찾아 작게라도 시작하는 편이 좋습니다.","message":"미루지 말고 손을 대세요."},{"guaN":18,"guaName":"산풍고","pos":5,"label":"六五","yinyang":"yin","text":"幹父之蠱 用譽","reading":"간부지고 용예","modern":"아버지가 남긴 폐단을 바로잡아 명예를 얻습니다.","meaning":"중심 자리에서 아래 사람의 도움을 받아 문제를 정리하는 모습입니다. 혼자보다 좋은 인재와 함께할 때 성과가 드러납니다.","positive":"능력 있는 사람의 힘을 빌려 성과를 내고 좋은 평판을 얻기 쉽습니다.","caution":"공을 독차지하려 하거나 도움 준 사람을 소홀히 하면 평판이 흔들릴 수 있습니다.","advice":"믿을 만한 사람에게 권한을 나누어 주세요. 성과가 나면 함께한 사람들의 몫을 분명히 인정하세요.","message":"좋은 사람과 함께 바로잡으세요."},{"guaN":18,"guaName":"산풍고","pos":6,"label":"上九","yinyang":"yang","text":"不事王侯 高尙其事","reading":"불사왕후 고상기사","modern":"왕과 제후를 섬기지 않고, 자기 일을 높고 고상하게 여깁니다.","meaning":"큰 일을 정리한 뒤 물러나 자기 뜻을 지키는 끝자리입니다. 세속의 이익에서 한 걸음 떨어져 가치를 추구하는 모습입니다.","positive":"세속의 이해에서 벗어나 자신의 가치를 지키며 마음의 여유를 얻을 수 있습니다.","caution":"지나치게 물러나면 세상과 단절되고 고립되기 쉽습니다.","advice":"일을 마무리한 뒤에는 잠시 쉬며 내가 진짜 소중히 여기는 일이 무엇인지 정리해 보세요. 다만 사람들과의 연결은 완전히 끊지 않는 편이 좋습니다.","message":"마무리 뒤엔 나의 뜻을 돌아보세요."}],"yong":null},"19":{"n":19,"name":"지택림","han":"地澤臨","upper":"곤","lower":"태","upperHan":"坤","lowerHan":"兌","bits":[1,1,0,0,0,0],"binary":"110000","gua":{"text":"元亨利貞 至于八月有凶","reading":"원형이정 지우팔월유흉","modern":"크게 형통하고 바르게 하면 이롭습니다. 팔월에 이르면 흉함이 있을 수 있습니다.","symbol":"위는 땅(地), 아래는 못(澤)입니다. 땅이 못을 내려다보듯 위에서 아래로 다가가 살피고 이끄는 모습이며, 양의 기운이 아래에서 자라나는 때입니다.","situation":"영향력과 기회, 사람이 점점 늘어나는 성장기입니다. 가까이서 돌보고 이끄는 자세가 효과를 내기 쉬운 반면, 기세가 오를 때 이미 변화의 조짐이 있음을 기억해야 하는 국면입니다.","positive":"기반이 자라나는 시기라 사람과 기회가 모이고 일이 커지기 쉽습니다.","caution":"성장세만 믿고 방심하면 시간이 지나 기세가 꺾일 때 대비가 부족해질 수 있습니다.","direction":"가까이 다가가 듣고 돕는 자세로 사람을 키우세요. 좋을 때일수록 기반과 규칙을 다지고, 흐름이 바뀔 때를 위한 준비도 함께 해 두는 편이 도움이 됩니다.","message":"다가가 이끌되, 성할 때 준비하세요."},"yao":[{"guaN":19,"guaName":"지택림","pos":1,"label":"初九","yinyang":"yang","text":"咸臨 貞吉","reading":"함림 정길","modern":"함께 느끼며 다가갑니다. 바르게 하면 길합니다.","meaning":"막 성장이 시작되는 자리입니다. 위의 사람과 마음이 통해 같이 움직이는 모습이라, 뜻을 함께하는 이들이 생기는 단계입니다.","positive":"마음이 통하는 사람이 생겨 시작이 든든해지기 쉽습니다.","caution":"작은 기세에 들떠 바른 방향을 놓치지 않도록 주의해야 합니다.","advice":"함께할 사람과 목표를 먼저 나누고 바른 뜻으로 시작하세요. 서두르기보다 마음을 맞추는 데 시간을 쓰는 편이 좋습니다.","message":"마음을 모아 바르게 시작하세요."},{"guaN":19,"guaName":"지택림","pos":2,"label":"九二","yinyang":"yang","text":"咸臨 吉 无不利","reading":"함림 길 무불리","modern":"함께 느끼며 다가가니 길하고 이롭지 않은 것이 없습니다.","meaning":"아래 괘의 중심에서 강한 힘을 지니고, 위의 사람들과도 호응하는 자리입니다. 뜻이 통하고 영향력이 가장 힘 있게 퍼지는 때입니다.","positive":"능력과 신뢰가 함께 받쳐 주어 주변의 협조를 얻기 쉽습니다.","caution":"순조로움에 기대어 윗사람의 뜻을 무작정 따르거나 자만하지 않도록 살펴야 합니다.","advice":"자신 있게 이끌되, 판단의 근거는 상황을 살피며 스스로 세우세요. 도움 주는 사람에게 감사를 표현하면 흐름이 더 오래 갑니다.","message":"힘 있게 이끌되 스스로 판단하세요."},{"guaN":19,"guaName":"지택림","pos":3,"label":"六三","yinyang":"yin","text":"甘臨 无攸利 旣憂之 无咎","reading":"감림 무유리 기우지 무구","modern":"달콤하게 다가가면 이로운 바가 없습니다. 이미 걱정하여 고치면 허물이 없습니다.","meaning":"아래 괘의 끝이자 전환기이며, 힘이 커질수록 달콤한 말과 편한 태도로 사람을 대하기 쉬운 자리입니다. 알아차리고 고치면 문제는 작아집니다.","positive":"잘못된 태도를 스스로 알아채고 바꾸면 신뢰를 회복하기 쉽습니다.","caution":"듣기 좋은 말과 편한 관계에 안주하면 진짜 도움을 주지 못하게 됩니다.","advice":"칭찬이나 호의가 습관이 되어 있지 않은지 점검하세요. 필요한 말은 정중하게 전하는 쪽이 오래 가는 관계를 만듭니다.","message":"달콤함보다 진심을 택하세요."},{"guaN":19,"guaName":"지택림","pos":4,"label":"六四","yinyang":"yin","text":"至臨 无咎","reading":"지림 무구","modern":"지극하게 다가가니 허물이 없습니다.","meaning":"위 괘의 시작으로, 아래 사람들과 가장 가까이 마주하는 자리입니다. 있는 자리에서 성실하게 살피고 곁에서 돕는 모습입니다.","positive":"현장을 직접 챙기고 정성을 다하면 신뢰가 깊어지기 쉽습니다.","caution":"세세한 일에 너무 매이거나 자기 자리를 벗어난 간섭을 하지 않도록 주의하세요.","advice":"맡은 역할 안에서 사람을 직접 만나 필요를 확인하세요. 정성은 다하되 선을 넘지 않는 균형이 도움이 됩니다.","message":"정성껏 곁에서 살피세요."},{"guaN":19,"guaName":"지택림","pos":5,"label":"六五","yinyang":"yin","text":"知臨 大君之宜 吉","reading":"지림 대군지의 길","modern":"지혜로 다가갑니다. 큰 임금다운 마땅한 방식이니 길합니다.","meaning":"위 괘의 중심이자 핵심 자리입니다. 모든 것을 직접 하지 않고 지혜로운 사람에게 맡겨 큰 판을 움직이는 모습입니다.","positive":"사람을 알아보고 알맞게 맡기면 일이 크게 안정되기 쉽습니다.","caution":"자리의 권위에 기대어 사람 보는 눈을 소홀히 하면 판단이 흐려질 수 있습니다.","advice":"직접 나서기보다 믿을 만한 사람을 세우고 방향을 정해 주는 데 집중하세요. 결과를 점검하는 시간을 꾸준히 가지세요.","message":"지혜로 사람을 쓰세요."},{"guaN":19,"guaName":"지택림","pos":6,"label":"上六","yinyang":"yin","text":"敦臨 吉 无咎","reading":"돈림 길 무구","modern":"돈독하게 다가가니 길하고 허물이 없습니다.","meaning":"성장의 끝자리에서 두텁고 너그러운 마음으로 사람을 대하는 모습입니다. 높은 자리에 있지만 아래를 아끼며 마무리합니다.","positive":"후덕하게 베풀면 오래도록 이어지는 신뢰와 좋은 평판을 얻을 수 있습니다.","caution":"성과에 만족해 마음이 느슨해지면 앞서 언급한 쇠함의 조짐을 놓칠 수 있습니다.","advice":"쌓은 것을 나누고 후배와 동료를 아끼세요. 다음 국면을 위한 준비도 차분히 해 두는 편이 좋습니다.","message":"너그럽게 베풀며 마무리하세요."}],"yong":null},"20":{"n":20,"name":"풍지관","han":"風地觀","upper":"손","lower":"곤","upperHan":"巽","lowerHan":"坤","bits":[0,0,0,0,1,1],"binary":"000011","gua":{"text":"盥而不薦 有孚顒若","reading":"관이불천 유부옹약","modern":"손을 씻고 아직 제물을 올리지 않았을 때, 믿음이 있어 우러러보는 모습입니다.","symbol":"위는 바람(風), 아래는 땅(地)입니다. 바람이 땅 위를 두루 지나가듯 넓게 살피고, 또 사람들이 우러러보도록 모범을 보이는 모습입니다.","situation":"서둘러 행동하기보다 상황을 관찰하고 나를 돌아보아야 하는 국면입니다. 내 태도가 남에게 어떻게 보이는지도 중요해지는 때여서, 경건하고 진지한 마음가짐이 신뢰의 바탕이 됩니다.","positive":"차분히 살피고 정돈된 태도를 보이면 주변의 믿음을 얻기 쉽습니다.","caution":"보는 일에만 머물거나 남의 시선만 의식하면 정작 필요한 결정을 미루게 될 수 있습니다.","direction":"당장 결론내리기보다 정보를 모으고 여러 관점에서 살펴보세요. 말과 행동을 일치시키며 내가 어떤 모습으로 보이는지도 점검하는 편이 도움이 됩니다.","message":"먼저 살피고, 나를 돌아보세요."},"yao":[{"guaN":20,"guaName":"풍지관","pos":1,"label":"初六","yinyang":"yin","text":"童觀 小人无咎 君子吝","reading":"동관 소인무구 군자린","modern":"어린아이처럼 봅니다. 보통 사람에게는 허물이 없으나 군자에게는 아쉬움이 있습니다.","meaning":"막 관찰을 시작한 자리로, 아직 눈이 얕아 겉만 보는 단계입니다. 배우는 입장이라면 괜찮지만 큰 책임을 질 사람이라면 부족한 시야입니다.","positive":"순수한 호기심으로 보는 것은 배움의 첫걸음이 될 수 있습니다.","caution":"겉모습만 보고 판단하면 깊은 맥락을 놓치기 쉽습니다.","advice":"보이는 것 뒤의 이유와 사정을 한 번 더 물어보세요. 아직 잘 모르는 부분은 아는 사람에게 배우는 자세가 좋습니다.","message":"겉만 보지 말고 더 깊이 보세요."},{"guaN":20,"guaName":"풍지관","pos":2,"label":"六二","yinyang":"yin","text":"闚觀 利女貞","reading":"규관 리녀정","modern":"문틈으로 엿보듯 봅니다. 여인이 바르게 지키는 데는 이롭습니다.","meaning":"좁은 틈으로 바깥을 내다보는 자리입니다. 시야가 제한되어 있지만 자신의 자리를 조심스럽게 지키는 모습이기도 합니다.","positive":"무리하지 않고 안전한 위치에서 상황을 차분히 파악할 수 있습니다.","caution":"좁은 시야에 갇혀 전체 흐름을 놓칠 가능성이 있습니다.","advice":"한 가지 창으로만 보고 있지 않은지 점검하세요. 더 넓은 정보를 구하되, 서두르지 않고 자기 자리를 지키는 것도 방법입니다.","message":"좁은 틈 밖으로 시야를 넓히세요."},{"guaN":20,"guaName":"풍지관","pos":3,"label":"六三","yinyang":"yin","text":"觀我生 進退","reading":"관아생 진퇴","modern":"나의 삶을 돌아보고 나아갈지 물러날지를 정합니다.","meaning":"아래 괘의 끝에서 위로 나아갈 기로에 선 전환기입니다. 남을 보던 눈을 나 자신에게 돌려 행동의 방향을 정하는 자리입니다.","positive":"스스로를 돌아보며 나아갈 때와 물러설 때를 알맞게 고를 수 있습니다.","caution":"결정을 미루며 갈팡질팡하면 기회도 정리의 시점도 놓치기 쉽습니다.","advice":"내가 지금까지 한 선택과 결과를 적어 보고 다음 걸음이 맞는지 점검하세요. 확신이 서지 않으면 작게 시험해 보세요.","message":"나를 돌아보고 걸음을 정하세요."},{"guaN":20,"guaName":"풍지관","pos":4,"label":"六四","yinyang":"yin","text":"觀國之光 利用賓于王","reading":"관국지광 리용빈우왕","modern":"나라의 빛나는 모습을 봅니다. 왕의 손님이 되어 쓰이는 데 이롭습니다.","meaning":"위 괘의 시작이자 높은 자리와 가까운 경계입니다. 좋은 모범과 큰 흐름을 가까이서 보고 배우며 인정받을 수 있는 위치입니다.","positive":"훌륭한 사람이나 조직을 가까이서 보고 배우면 기회로 이어지기 쉽습니다.","caution":"가까이 있다고 우쭐하거나 윗사람 눈치만 보면 배움을 놓칠 수 있습니다.","advice":"큰 조직이나 선배의 좋은 점을 구체적으로 관찰해 내 것으로 만드세요. 기회가 오면 겸손하게 능력을 보여 주세요.","message":"좋은 본보기를 곁에서 배우세요."},{"guaN":20,"guaName":"풍지관","pos":5,"label":"九五","yinyang":"yang","text":"觀我生 君子无咎","reading":"관아생 군자무구","modern":"나의 삶을 돌아봅니다. 군자라면 허물이 없습니다.","meaning":"중심 자리에서 남에게 모범이 되는 모습입니다. 내 행동이 곧 주변이 보는 기준이 되므로, 스스로를 살피는 일이 중요합니다.","positive":"자신의 말과 행동을 점검하면 주변도 자연스럽게 믿고 따르기 쉽습니다.","caution":"책임이 큰 자리라 작은 흐트러짐도 크게 비칠 수 있습니다.","advice":"내가 하는 말과 실제 행동이 일치하는지 점검하세요. 주변 사람들의 모습을 통해 내 영향이 어떤지도 살펴보는 편이 좋습니다.","message":"내 모습이 곧 본보기입니다."},{"guaN":20,"guaName":"풍지관","pos":6,"label":"上九","yinyang":"yang","text":"觀其生 君子无咎","reading":"관기생 군자무구","modern":"그 삶을 바라봅니다. 군자라면 허물이 없습니다.","meaning":"끝자리에서 한 걸음 물러나 자신과 주변의 모습을 넓게 되돌아봅니다. 세속의 이해를 떠나 전체를 바라보는 관조의 단계입니다.","positive":"높은 곳에서 전체를 보며 마음의 중심과 균형을 잡기 쉽습니다.","caution":"관찰자의 자리에만 머물면 실제 행동으로 옮길 기회를 놓칠 수 있습니다.","advice":"돌아본 것을 정리해 다음 행동에 반영하세요. 한 걸음 떨어져 보되, 필요한 때에는 다시 현장으로 돌아오는 것이 도움이 됩니다.","message":"멀리서 보고 배운 것을 행하세요."}],"yong":null},"21":{"n":21,"name":"화뢰서합","han":"火雷噬嗑","upper":"리","lower":"진","upperHan":"離","lowerHan":"震","bits":[1,0,0,1,0,1],"binary":"100101","gua":{"text":"亨 利用獄","reading":"형 리용옥","modern":"형통합니다. 옥사를 다스리는 데 이롭습니다.","symbol":"위는 불(밝음), 아래는 우레(움직임)입니다. 입 안에 걸린 것을 씹어 없애야 입이 다물리듯, 막힌 것을 가려 처리하는 괘입니다.","situation":"소통과 진행을 가로막는 방해물이나 잘못이 분명히 드러난 국면입니다. 덮어 두기보다 기준과 사실에 따라 하나씩 가려내 해결해야 일이 다시 풀리기 쉽습니다. 다만 밝게 살피는 일과 거세게 몰아붙이는 일은 다르다는 점을 함께 떠올려 보세요.","positive":"문제의 원인을 분명히 가려내면 막혔던 일이 풀리고 관계의 신뢰도 되살아나기 쉽습니다.","caution":"엄정함이 지나쳐 가혹해지면 해결보다 반발을 부를 수 있으니 처분의 강도를 살펴보세요.","direction":"감정이 아니라 기준과 증거를 바탕으로 단계적으로 처리하는 편이 도움이 됩니다. 작은 잘못은 일찍 바로잡고, 처리한 뒤에는 재발을 막을 규칙을 남겨 보세요.","message":"막힌 것은 분명히 가리되 가혹하지 않게"},"yao":[{"guaN":21,"guaName":"화뢰서합","pos":1,"label":"初九","yinyang":"yang","text":"屨校滅趾 无咎","reading":"구교멸지 무구","modern":"발에 형틀을 채워 발끝이 가려집니다. 허물이 없습니다.","meaning":"막 시작하는 자리에서 잘못에 가벼운 제재를 받는 장면입니다. 작은 잘못 때문에 걸음이 멈추게 되지만 크게 번지기 전에 제동이 걸린 셈입니다.","positive":"작은 단계에서 멈추게 되어 큰 잘못으로 이어질 길이 막힙니다.","caution":"가벼운 제재라고 대수롭지 않게 넘기면 같은 일이 되풀이되기 쉽습니다.","advice":"지적을 받았다면 변명보다 원인을 확인하고 바로 고쳐 보세요. 초기에 바로잡는 것이 가장 비용이 적게 듭니다.","message":"작은 잘못은 초기에 바로잡기"},{"guaN":21,"guaName":"화뢰서합","pos":2,"label":"六二","yinyang":"yin","text":"噬膚滅鼻 无咎","reading":"서부멸비 무구","modern":"부드러운 살을 씹다가 코가 파묻힙니다. 허물이 없습니다.","meaning":"아래 괘의 중심에서 바른 자리를 지키며 문제를 처리하는 모습입니다. 연한 살이라 쉽게 씹히지만 너무 깊이 파고들어 코까지 묻힌다는 말은 처리에 힘이 들어간 상태를 보여 줍니다.","positive":"원칙에 맞게 처리하니 순조롭게 진행되고 비난을 받을 일이 적습니다.","caution":"쉬운 일이라 여겨 지나치게 파고들면 상대에게 부담을 줄 수 있습니다.","advice":"해결이 수월해 보일수록 필요한 만큼만 처리하고 선을 지켜 보세요. 상대의 입장을 한 번 헤아려 보는 것도 도움이 됩니다.","message":"쉬울 때일수록 필요한 만큼만"},{"guaN":21,"guaName":"화뢰서합","pos":3,"label":"六三","yinyang":"yin","text":"噬腊肉 遇毒 小吝 无咎","reading":"서석육 우독 소린 무구","modern":"말린 고기를 씹다가 독을 만납니다. 조금 아쉬우나 허물은 없습니다.","meaning":"아래 괘의 끝에서 자리가 알맞지 않은 채 오래 묵은 문제를 다루려는 모습입니다. 오래된 일은 얽힌 사정이 많아 뜻하지 않은 반발이나 불쾌한 일을 만나기 쉽습니다.","positive":"탈이 나더라도 큰 허물로 이어지지 않고 정리할 여지가 남아 있습니다.","caution":"내 힘과 명분이 충분하지 않은 상태로 묵은 문제를 건드리면 반감을 사기 쉽습니다.","advice":"묵은 문제일수록 근거와 협조자를 먼저 확보한 뒤 접근해 보세요. 뜻밖의 저항이 나와도 감정적으로 맞서지 않는 편이 낫습니다.","message":"묵은 문제는 준비하고 접근하기"},{"guaN":21,"guaName":"화뢰서합","pos":4,"label":"九四","yinyang":"yang","text":"噬乾胏 得金矢 利艱貞 吉","reading":"서건자 득금시 리간정 길","modern":"뼈 붙은 말린 고기를 씹다가 쇠 화살촉을 얻습니다. 어려움 속에서 바르게 지키면 이롭고 길합니다.","meaning":"위 괘의 시작으로, 윗사람과 가까이서 단단하고 까다로운 문제를 맡는 자리입니다. 쇠 화살촉은 곧고 단단함을 상징하며, 힘든 일 속에서도 원칙을 굳게 지키라는 뜻으로 읽을 수 있습니다.","positive":"까다로운 문제도 곧은 원칙을 지키면 끝내 해결의 실마리를 얻기 쉽습니다.","caution":"어렵다고 원칙을 느슨하게 하거나 반대로 힘만 앞세우면 결과가 흐려질 수 있습니다.","advice":"어렵고 불편한 일일수록 기준을 분명히 세우고 끈기 있게 이어 가 보세요. 주변의 압박이 있어도 같은 기준을 일관되게 적용하는 것이 중요합니다.","message":"어려운 일도 곧은 기준으로"},{"guaN":21,"guaName":"화뢰서합","pos":5,"label":"六五","yinyang":"yin","text":"噬乾肉 得黃金 貞厲 无咎","reading":"서건육 득황금 정려 무구","modern":"말린 고기를 씹다가 누런 쇠를 얻습니다. 바르게 하되 위태로움을 늘 생각하면 허물이 없습니다.","meaning":"위 괘의 중심, 결정권을 가진 자리입니다. 황금은 중용과 공정함을 뜻하는 듯 읽히며, 판단을 내리는 입장일수록 신중해야 한다는 점이 함께 드러납니다.","positive":"공정하고 적절한 판단으로 문제를 매듭지을 수 있어 신뢰를 얻기 쉽습니다.","caution":"결정권이 있다는 이유로 방심하거나 혼자 판단하면 위태로워질 수 있습니다.","advice":"판단을 내리는 입장이라면 결정이 옳은지 한 번 더 점검하고 근거를 공개해 보세요. 단호함에 신중함을 함께 더하는 편이 좋습니다.","message":"공정하게 판단하고 늘 신중하게"},{"guaN":21,"guaName":"화뢰서합","pos":6,"label":"上九","yinyang":"yang","text":"何校滅耳 凶","reading":"하교멸이 흉","modern":"목에 형틀을 메어 귀가 가려집니다. 흉합니다.","meaning":"끝에 이른 자리로, 잘못이 쌓이고 쌓인 데다 남의 말도 듣지 않아 큰 제재를 받는 모습입니다. 귀가 가려진다는 것은 충고를 듣지 못하는 상태를 비유한 표현입니다.","positive":"스스로 상황을 돌아보고 방식을 바꿀 마지막 계기가 될 수 있습니다.","caution":"경고를 거듭 흘려보내면 감당하기 어려운 어려움이 따를 수 있습니다.","advice":"주변의 충고와 반복되는 지적을 이제라도 열린 마음으로 들어 보세요. 쌓아 온 잘못이 있다면 더 커지기 전에 정리하는 방법을 찾는 편이 좋습니다.","message":"충고를 들을 때 비로소 길이 열립니다"}],"yong":null},"22":{"n":22,"name":"산화비","han":"山火賁","upper":"간","lower":"리","upperHan":"艮","lowerHan":"離","bits":[1,0,1,0,0,1],"binary":"101001","gua":{"text":"亨 小利有攸往","reading":"형 소리유유왕","modern":"형통합니다. 가는 바가 있으면 조금 이롭습니다.","symbol":"위는 산(멈춤), 아래는 불(밝음)입니다. 산 아래에서 불빛이 비추어 산을 아름답게 물들이듯, 꾸밈과 무늬를 말하는 괘입니다.","situation":"이미지와 형식, 첫인상이 중요하게 작용하는 시기입니다. 겉을 가다듬으면 일이 부드럽게 풀리지만, 큰일을 꾸밈에만 기대어 밀고 나가기에는 부족할 수 있습니다. 알맹이가 충실한지 함께 살펴보세요.","positive":"형식과 표현을 정돈하면 좋은 인상을 주고 작은 일은 순조롭게 진행되기 쉽습니다.","caution":"겉모습에 마음이 쏠리면 본질이 비어 있는 것을 놓칠 수 있습니다.","direction":"전달 방식과 모양새는 다듬되 중요한 결정은 내용과 실질적인 조건을 기준으로 해 보세요. 가장 좋은 꾸밈은 소박하고 진실한 바탕에서 나온다는 점을 기억하면 좋겠습니다.","message":"꾸밈은 바탕이 단단할 때 빛납니다"},"yao":[{"guaN":22,"guaName":"산화비","pos":1,"label":"初九","yinyang":"yang","text":"賁其趾 舍車而徒","reading":"비기지 사거이도","modern":"그 발을 꾸밉니다. 수레를 버리고 걸어갑니다.","meaning":"막 시작하는 낮은 자리에서 편한 수레보다 자기 발로 걷는 길을 택하는 장면입니다. 겉치레로 올라서기보다 정직하게 한 걸음씩 가는 태도를 꾸밈으로 삼는 모습입니다.","positive":"분수에 맞게 직접 걷는 길은 처음부터 기반을 단단하게 만들어 줍니다.","caution":"남의 도움이나 겉으로 편한 방법에 기대면 떳떳함이 흐려질 수 있습니다.","advice":"시작 단계라면 남의 눈에 좋아 보이는 방법보다 내 힘으로 해낼 수 있는 방식을 골라 보세요. 조금 느려도 내가 한 일이라는 근거가 남습니다.","message":"직접 걷는 길이 가장 떳떳합니다"},{"guaN":22,"guaName":"산화비","pos":2,"label":"六二","yinyang":"yin","text":"賁其須","reading":"비기수","modern":"그 수염을 꾸밉니다.","meaning":"아래 괘의 중심에서 수염이 턱을 따라 움직이듯 가까운 윗사람과 호흡을 맞추며 꾸미는 모습입니다. 수염은 스스로 움직이는 것이 아니라 얼굴을 따라 움직이므로, 독자적이기보다 함께하는 아름다움을 말합니다.","positive":"믿을 만한 상대와 호흡을 맞추면 서로의 장점이 함께 돋보이기 쉽습니다.","caution":"상대에게 지나치게 맞추다 보면 내 판단과 주관이 약해질 수 있습니다.","advice":"협력할 사람과 역할을 나눠 서로를 돋보이게 하되 내 기준도 분명히 해 보세요. 함께하는 일에서는 함께 가는 속도가 중요합니다.","message":"좋은 호흡이 서로를 빛나게 합니다"},{"guaN":22,"guaName":"산화비","pos":3,"label":"九三","yinyang":"yang","text":"賁如濡如 永貞吉","reading":"비여유여 영정길","modern":"꾸민 듯 윤기가 흐르는 듯합니다. 오래도록 바르게 하면 길합니다.","meaning":"아래 괘의 끝에서 이웃한 효들과 어울려 한껏 윤택하고 아름다운 상태입니다. 좋은 분위기에 취하면 흐르기 쉬우니, 바름을 오래 지키라는 당부가 붙어 있습니다.","positive":"주변의 호의와 좋은 분위기 속에서 일이 부드럽게 흘러가기 쉽습니다.","caution":"달콤한 분위기에 젖어 경계를 풀면 중심을 잃을 수 있습니다.","advice":"분위기가 좋을수록 지켜야 할 원칙과 한도를 먼저 정해 두어 보세요. 오래 가는 관계와 성과는 꾸준한 바름에서 나옵니다.","message":"좋은 때일수록 중심을 오래 지키기"},{"guaN":22,"guaName":"산화비","pos":4,"label":"六四","yinyang":"yin","text":"賁如皤如 白馬翰如 匪寇婚媾","reading":"비여파여 백마한여 비구혼구","modern":"꾸민 듯 희고 소박한 듯합니다. 흰 말이 나는 듯 달려옵니다. 도적이 아니라 혼인을 청하는 사람입니다.","meaning":"위 괘의 시작으로 꾸밈과 소박함 사이에서 망설이는 자리입니다. 가까운 곳에 다가오는 존재가 해를 끼치려는 이가 아니라 뜻이 맞는 상대일 수 있다는 점이 눈에 띕니다.","positive":"겉으로 낯선 만남이 알고 보면 서로를 이해하는 좋은 인연이 될 수 있습니다.","caution":"의심이 지나치면 다가오는 좋은 기회와 사람을 밀어낼 수 있습니다.","advice":"낯선 제안이나 사람에 대해 성급히 경계하거나 반기기보다 의도를 차분히 살펴보세요. 겉모습을 걷어 내고 진심을 확인하는 것이 먼저입니다.","message":"겉모습 너머의 진심을 살펴보세요"},{"guaN":22,"guaName":"산화비","pos":5,"label":"六五","yinyang":"yin","text":"賁于丘園 束帛戔戔 吝 終吉","reading":"비우구원 속백전전 린 종길","modern":"언덕의 동산을 꾸밉니다. 묶은 비단 예물이 보잘것없습니다. 아쉬우나 끝내는 길합니다.","meaning":"위 괘의 중심에서 화려한 곳이 아닌 소박한 동산에 마음을 쓰는 모습입니다. 예물은 적어 아쉽지만 정성이 담겨 있어 끝에는 좋은 결과로 이어진다는 뜻으로 읽을 수 있습니다.","positive":"소박해도 정성을 다하면 신뢰와 좋은 결과를 얻을 수 있습니다.","caution":"넉넉하지 못한 형편을 체면 때문에 부끄러워하면 마음의 정성까지 가릴 수 있습니다.","advice":"비용이나 규모보다 진심이 전해지는 방식을 택해 보세요. 부족해 보이는 것을 억지로 채우기보다 정성을 더하는 쪽이 도움이 됩니다.","message":"소박한 정성이 끝내 빛납니다"},{"guaN":22,"guaName":"산화비","pos":6,"label":"上九","yinyang":"yang","text":"白賁 无咎","reading":"백비 무구","modern":"흰 빛으로 꾸밉니다. 허물이 없습니다.","meaning":"끝에 이른 자리로 온갖 꾸밈을 지나 아무 색도 더하지 않은 본바탕으로 돌아오는 모습입니다. 가장 높은 단계의 아름다움은 꾸밈이 없는 소박함이라는 뜻으로 읽힙니다.","positive":"꾸밈을 덜어 낸 담백함이 오히려 깊은 신뢰와 편안함을 줍니다.","caution":"보여 주는 데 익숙해진 습관을 놓지 못하면 진짜 가치를 가릴 수 있습니다.","advice":"치장과 과시를 덜어 내고 본질에 시간을 써 보세요. 있는 그대로를 드러내도 괜찮은지 스스로 점검해 보는 것도 좋습니다.","message":"덜어 낸 자리에서 진짜가 보입니다"}],"yong":null},"23":{"n":23,"name":"산지박","han":"山地剝","upper":"간","lower":"곤","upperHan":"艮","lowerHan":"坤","bits":[0,0,0,0,0,1],"binary":"000001","gua":{"text":"不利有攸往","reading":"불리유유왕","modern":"가는 바가 있으면 이롭지 않습니다.","symbol":"위는 산, 아래는 땅입니다. 높은 산이 땅 위에서 조금씩 깎여 내려앉듯, 다섯 음이 아래서부터 올라와 맨 위 하나의 양을 벗겨 내는 모습입니다.","situation":"자원이나 지위, 관계가 조금씩 깎여 나가고 형세가 불리하게 기운 국면입니다. 이럴 때 무리하게 나서면 소모가 커지기 쉬워, 지킬 것을 정하고 기반을 보존하는 쪽이 도움이 됩니다. 아직 맨 위에 양이 하나 남아 있다는 점이 희망의 실마리입니다.","positive":"물러나 기반을 지키는 동안 다음을 위한 씨앗과 실력을 조용히 보존할 수 있습니다.","caution":"불리한 때에 맞서 반격하거나 확장에 나서면 남은 것까지 잃을 수 있습니다.","direction":"새로 벌이기보다 멈추고 지킬 것과 내려놓을 것을 구분해 보세요. 때의 흐름에 순응하며 버티는 힘을 기르는 것이 회복의 바탕이 됩니다.","message":"멈추고 지키는 것도 전략입니다"},"yao":[{"guaN":23,"guaName":"산지박","pos":1,"label":"初六","yinyang":"yin","text":"剝牀以足 蔑貞 凶","reading":"박상이족 멸정 흉","modern":"침상을 깎되 다리부터 시작합니다. 바름이 업신여겨지니 흉합니다.","meaning":"막 시작되는 자리에서 가장 아래, 기반이 되는 부분이 먼저 허물어지는 모습입니다. 눈에 잘 띄지 않는 곳에서 시작된 균열이라 처음에는 가볍게 보기 쉽습니다.","positive":"초기에 징후를 알아차리면 피해가 번지기 전에 대비할 수 있습니다.","caution":"작은 균열을 대수롭지 않게 넘기면 바른 원칙까지 흔들리기 쉽습니다.","advice":"기반이 되는 부분부터 점검하고 허술한 곳을 먼저 보강해 보세요. 불리한 흐름이 보이면 무리한 진행을 잠시 멈추는 편이 좋습니다.","message":"기반의 작은 균열을 먼저 살피기"},{"guaN":23,"guaName":"산지박","pos":2,"label":"六二","yinyang":"yin","text":"剝牀以辨 蔑貞 凶","reading":"박상이변 멸정 흉","modern":"침상을 깎되 다리와 몸체가 만나는 곳까지 이릅니다. 바름이 업신여겨지니 흉합니다.","meaning":"아래 괘의 중심 자리로 침상의 다리와 몸체의 경계까지 깎여 올라온 상태입니다. 위에서 도와주는 이도 없어 점차 안정감이 무너지는 느낌이 커집니다.","positive":"무엇이 흔들리는지 구체적으로 보이는 만큼 대응할 지점을 찾기 쉽습니다.","caution":"혼자 버틸 수 있다고 여기고 도움을 구하지 않으면 부담이 커질 수 있습니다.","advice":"홀로 감당하려 하지 말고 믿을 만한 사람과 상황을 나누어 보세요. 지금은 반격보다 지킬 영역을 줄여 선명하게 하는 편이 도움이 됩니다.","message":"혼자 버티기보다 함께 지키기"},{"guaN":23,"guaName":"산지박","pos":3,"label":"六三","yinyang":"yin","text":"剝之 无咎","reading":"박지 무구","modern":"깎이는 가운데 있으나 허물은 없습니다.","meaning":"아래 괘의 끝에서 여러 음 속에 홀로 위의 양과 호응하는 자리입니다. 어지러운 무리와 어울리는 대신 방향을 달리하니 깎이는 흐름 속에서도 허물을 면하는 모습입니다.","positive":"흐름에 휩쓸리지 않고 중심을 지키면 비난을 피할 여지가 생깁니다.","caution":"주변 분위기에 맞서다 고립되거나 반대로 휩쓸려 따라가지 않도록 살펴야 합니다.","advice":"무리와 결을 달리하더라도 대립하기보다 조용히 신뢰할 수 있는 쪽과 관계를 유지해 보세요. 어디에 서 있을지 스스로 분명히 정하는 일이 중요합니다.","message":"흐름에 휩쓸리지 않는 선택"},{"guaN":23,"guaName":"산지박","pos":4,"label":"六四","yinyang":"yin","text":"剝牀以膚 凶","reading":"박상이부 흉","modern":"침상을 깎아 살갗에까지 이릅니다. 흉합니다.","meaning":"위 괘의 시작으로, 깎이는 흐름이 이제 사람의 몸에 닿을 만큼 가까워진 단계입니다. 더는 남의 일이 아니라 내 자리와 직접 맞닿은 문제가 되었다는 뜻으로 읽을 수 있습니다.","positive":"위기가 눈앞에 닿은 만큼 더는 미룰 수 없는 정리와 결단의 기회가 됩니다.","caution":"피해가 직접 닿았는데도 상황이 나아지기를 기다리기만 하면 손실이 커질 수 있습니다.","advice":"건강과 재정, 핵심 관계처럼 정말 지켜야 할 것을 우선순위로 올리고 나머지는 과감히 줄여 보세요. 중대한 일은 전문가의 도움도 함께 받는 편이 안전합니다.","message":"지켜야 할 것부터 우선 챙기기"},{"guaN":23,"guaName":"산지박","pos":5,"label":"六五","yinyang":"yin","text":"貫魚 以宮人寵 无不利","reading":"관어 이궁인총 무불리","modern":"물고기를 꿰듯 궁인들을 이끌어 총애를 받게 합니다. 이롭지 않은 것이 없습니다.","meaning":"위 괘의 중심에서 가장 영향력이 큰 자리입니다. 깎아내리려는 무리를 물고기 꿰미처럼 질서 있게 이끌어 위의 양에게 순종하게 하니, 형세가 반전되는 모습입니다.","positive":"대립하던 무리를 하나의 질서로 이끌면 불리한 흐름이 부드럽게 정리될 수 있습니다.","caution":"힘을 앞세워 누르면 오히려 반발이 커지니 질서를 세우는 방식에 유의해야 합니다.","advice":"갈등하는 사람들을 배제하기보다 역할과 질서를 주어 한 방향으로 모아 보세요. 중심에 선 사람일수록 포용과 일관된 기준이 도움이 됩니다.","message":"흩어진 힘을 질서로 모으기"},{"guaN":23,"guaName":"산지박","pos":6,"label":"上九","yinyang":"yang","text":"碩果不食 君子得輿 小人剝廬","reading":"석과불식 군자득여 소인박려","modern":"큰 과일은 먹히지 않고 남아 있습니다. 군자는 수레를 얻고 소인은 지붕을 벗겨 냅니다.","meaning":"끝에 이른 자리로, 깎이다 깎인 끝에 큰 과일 하나가 남은 모습입니다. 이 과일은 씨앗이 되어 다시 싹을 틔울 수 있는 희망이며, 남은 것을 지키는 이는 힘을 얻고 파괴에만 몰두하는 이는 제 집까지 잃는다는 대비가 보입니다.","positive":"남은 핵심을 지켜 내면 다시 일어설 바탕이 마련될 수 있습니다.","caution":"남은 것까지 소진하거나 파괴적인 방식으로 대응하면 스스로의 터전을 잃을 수 있습니다.","advice":"마지막으로 남은 핵심 실력과 신뢰, 관계를 씨앗처럼 아껴 보세요. 이 시기를 정리하며 다음 시작에 필요한 것을 조용히 준비하면 좋습니다.","message":"남은 씨앗이 다음을 엽니다"}],"yong":null},"24":{"n":24,"name":"지뢰복","han":"地雷復","upper":"곤","lower":"진","upperHan":"坤","lowerHan":"震","bits":[1,0,0,0,0,0],"binary":"100000","gua":{"text":"亨 出入无疾 朋來无咎 反復其道 七日來復 利有攸往","reading":"형 출입무질 붕래무구 반복기도 칠일래복 리유유왕","modern":"형통합니다. 나가고 들어옴에 병이 없고 벗이 와도 허물이 없습니다. 그 도를 되풀이하여 이레 만에 돌아오니, 가는 바가 있으면 이롭습니다.","symbol":"위는 땅, 아래는 우레입니다. 가장 아래에서 하나의 양이 다시 생겨나 움직이기 시작하는 모습으로, 돌아옴과 회복을 뜻하는 괘입니다.","situation":"막혔던 일이나 흐트러진 리듬이 서서히 제자리로 돌아오기 시작하는 국면입니다. 아직 기운이 작고 여린 때이므로 큰 도약보다 바른 방향으로의 복귀가 우선입니다. 다시 시작하는 것 자체가 의미 있는 첫걸음입니다.","positive":"다시 시작할 계기가 생기고 멀어졌던 일과 관계를 회복할 가능성이 열립니다.","caution":"회복 초기에 서두르거나 예전 방식을 그대로 반복하면 흐름이 다시 꺾이기 쉽습니다.","direction":"완벽한 재출발보다 지킬 수 있는 작은 기본부터 회복해 보세요. 속도보다 꾸준함을 기준으로 삼고 지난 실패의 원인은 기록해 반복을 줄이면 좋습니다.","message":"다시 돌아온 첫걸음을 소중히"},"yao":[{"guaN":24,"guaName":"지뢰복","pos":1,"label":"初九","yinyang":"yang","text":"不遠復 无祗悔 元吉","reading":"불원복 무지회 원길","modern":"멀리 가지 않아 돌아옵니다. 크게 후회할 일이 없으니 크게 길합니다.","meaning":"막 시작하는 자리로, 잘못된 길로 오래 가기 전에 일찍 돌아선 모습입니다. 이 괘에서 하나뿐인 양으로서 회복의 출발점에 해당합니다.","positive":"방향을 일찍 바로잡으니 후회가 크지 않고 이후의 회복도 수월해집니다.","caution":"작은 어긋남을 두고 보다가 돌아설 시기를 놓치지 않도록 해야 합니다.","advice":"어긋났다는 느낌이 들면 바로 멈추고 처음 목표와 기본으로 돌아가 보세요. 늦지 않았다고 스스로 인정하는 것도 도움이 됩니다.","message":"일찍 돌아서면 후회가 줄어듭니다"},{"guaN":24,"guaName":"지뢰복","pos":2,"label":"六二","yinyang":"yin","text":"休復 吉","reading":"휴복 길","modern":"아름답게 돌아옵니다. 길합니다.","meaning":"아래 괘의 중심에서 가까이 있는 초효의 회복을 따르며 함께 기쁘게 돌아오는 모습입니다. 좋은 본보기를 곁에서 보고 따르니 복귀가 자연스럽고 편안합니다.","positive":"믿을 만한 사람을 본받아 따르니 회복이 안정적이고 즐겁게 이루어지기 쉽습니다.","caution":"남을 따르기만 하고 스스로 이해하지 못하면 회복이 오래가지 못할 수 있습니다.","advice":"좋은 본보기가 되는 사람이나 방식을 곁에 두고 배워 보세요. 따라 하는 데서 그치지 말고 나에게 맞는 방식으로 소화해 보면 좋습니다.","message":"좋은 본보기를 곁에 두고 배우기"},{"guaN":24,"guaName":"지뢰복","pos":3,"label":"六三","yinyang":"yin","text":"頻復 厲 无咎","reading":"빈복 려 무구","modern":"자주 돌아옵니다. 위태로우나 허물은 없습니다.","meaning":"아래 괘의 끝으로 자리가 알맞지 않아 돌아오기를 되풀이하는 모습입니다. 여러 번 흔들리는 것은 불안하지만 그때마다 다시 돌아오려는 마음 덕분에 큰 허물은 되지 않습니다.","positive":"넘어져도 다시 돌아오려는 시도가 이어지면 결국 습관을 바로잡을 수 있습니다.","caution":"흔들림이 반복되면 스스로를 탓하다가 의욕을 잃기 쉽습니다.","advice":"반복되는 흔들림을 실패로만 보지 말고 흔들리는 이유를 기록해 보세요. 돌아오는 횟수보다 돌아온다는 사실을 의미 있게 여기는 편이 좋습니다.","message":"흔들려도 다시 돌아오면 됩니다"},{"guaN":24,"guaName":"지뢰복","pos":4,"label":"六四","yinyang":"yin","text":"中行獨復","reading":"중행독복","modern":"중간에서 가다가 홀로 돌아옵니다.","meaning":"위 괘의 시작으로 여러 음 가운데 서 있으면서 홀로 아래의 초효를 향해 돌아오는 모습입니다. 주위가 모두 다른 길로 가도 옳은 쪽을 알아보고 혼자 방향을 트는 자리입니다.","positive":"주변의 흐름과 달라도 옳은 방향을 선택하는 판단력이 돋보입니다.","caution":"외로움이나 주변의 시선 때문에 선택이 흔들릴 수 있습니다.","advice":"혼자 방향을 틀어야 하는 상황이라면 이유를 스스로 분명히 정리해 두세요. 뜻이 통하는 한두 사람과 가볍게라도 연결을 유지하면 힘이 됩니다.","message":"홀로라도 옳은 방향을 택하기"},{"guaN":24,"guaName":"지뢰복","pos":5,"label":"六五","yinyang":"yin","text":"敦復 无悔","reading":"돈복 무회","modern":"돈독하게 돌아옵니다. 후회가 없습니다.","meaning":"위 괘의 중심에서 두텁고 너그러운 마음으로 돌아오는 모습입니다. 돌아오는 일을 서두르지 않고 성실하게 쌓아 가니 뒤에 후회할 일이 적습니다.","positive":"성실하고 진중한 태도 덕분에 회복이 단단히 자리 잡을 수 있습니다.","caution":"느긋함이 지나치면 실행이 느슨해져 흐지부지될 수 있습니다.","advice":"돌아온 뒤에도 기본을 성실하게 이어 가며 작은 약속을 지켜 보세요. 쌓인 신뢰가 회복의 든든한 밑받침이 됩니다.","message":"성실한 복귀는 후회가 적습니다"},{"guaN":24,"guaName":"지뢰복","pos":6,"label":"上六","yinyang":"yin","text":"迷復 凶 有災眚 用行師 終有大敗 以其國 君 凶 至于十年 不克征","reading":"미복 흉 유재생 용행사 종유대패 이기국 군 흉 지우십년 불극정","modern":"돌아오는 길에 미혹합니다. 흉하여 재앙과 허물이 있습니다. 군대를 일으키면 끝내 크게 패하고, 그 나라의 임금에게까지 흉하여 십 년이 되어도 정벌에 나설 수 없습니다.","meaning":"끝에 이른 자리로 돌아오는 길을 잃고 헤매는 모습입니다. 이미 극에 이르러 방향을 되돌릴 기회를 놓치고 무리하게 밀어붙이면 손실이 오래 이어질 수 있다고 경고하는 효입니다.","positive":"길을 잃었음을 알아차리는 것이 방향을 바로잡는 출발점이 됩니다.","caution":"방향이 틀린 채 힘으로 밀어붙이면 손실이 크고 회복에 오랜 시간이 걸릴 수 있습니다.","advice":"일을 더 키우기 전에 멈추고 처음 방향이 맞았는지 차분히 되짚어 보세요. 큰 결정은 서두르지 말고 주변의 조언과 충분한 검토를 거치는 편이 안전합니다.","message":"길을 잃었다면 멈추고 되짚기"}],"yong":null},"25":{"n":25,"name":"천뢰무망","han":"天雷无妄","upper":"건","lower":"진","upperHan":"乾","lowerHan":"震","bits":[1,0,0,1,1,1],"binary":"100111","gua":{"text":"元亨利貞 其匪正有眚 不利有攸往","reading":"원형이정 기비정유생 불리유유왕","modern":"크게 형통하고 바르게 하는 것이 이롭습니다. 바르지 않으면 재앙이 있으니, 나아가는 일에 이롭지 않습니다.","symbol":"위에는 하늘, 아래에는 우레가 있어 하늘의 뜻을 따라 자연스럽게 움직이는 모습입니다. 꾸밈이나 속셈 없이 있는 그대로 행동하는 순수함을 말합니다.","situation":"계산하고 꾸미는 것보다 진심과 정직함이 힘을 얻는 국면입니다. 다만 마음에 바르지 못한 속셈이 섞이면 예상하지 못한 문제가 생기기 쉽습니다. 뜻밖의 일이 닥쳐도 억울해하기보다 내 도리를 지키는 데 집중하면 도움이 됩니다.","positive":"숨김없는 태도가 신뢰를 얻고, 자연스러운 흐름을 타면 일이 순조롭게 풀릴 가능성이 있습니다.","caution":"요행을 바라거나 속셈을 품고 움직이면 뜻밖의 손실이 생기기 쉬우니 동기를 먼저 살펴보세요.","direction":"결과를 미리 계산하기보다 지금 해야 할 일을 정직하게 하는 쪽으로 방향을 잡으세요. 새로운 일을 크게 벌이기보다 바른 마음을 점검하며 차분히 나아가는 편이 좋습니다.","message":"꾸밈없는 진심이 가장 든든한 길입니다."},"yao":[{"guaN":25,"guaName":"천뢰무망","pos":1,"label":"初九","yinyang":"yang","text":"无妄往 吉","reading":"무망왕 길","modern":"헛된 욕심 없이 나아가면 길합니다.","meaning":"막 첫걸음을 떼는 단계에서, 순수한 마음 그대로 움직이는 때입니다. 아직 아무 계산이 섞이지 않았기에 출발이 가볍고 바릅니다.","positive":"순수한 동기로 시작하면 주변의 신뢰를 얻기 쉽습니다.","caution":"처음의 순수함이 성과를 보며 욕심으로 바뀌지 않는지 살펴야 합니다.","advice":"시작하는 이유를 한 줄로 적어 보고, 그 마음 그대로 한 걸음 내딛어 보세요. 과정에서 얻는 것을 먼저 따지지 않는 편이 도움이 됩니다.","message":"처음 마음 그대로 나아가세요."},{"guaN":25,"guaName":"천뢰무망","pos":2,"label":"六二","yinyang":"yin","text":"不耕穫 不菑畬 則利有攸往","reading":"불경확 불치여 즉리유유왕","modern":"밭을 갈지 않아도 거두고, 개간하지 않아도 좋은 밭을 얻는다면, 나아가는 것이 이롭습니다.","meaning":"아래 괘의 가운데 자리로, 결과에 집착하지 않고 맡은 때의 일을 자연스럽게 하는 모습입니다. 밭을 갈 때는 거둘 생각 없이 갈고, 거둘 때는 그 일에 충실한 태도를 비유합니다.","positive":"성과에 매달리지 않고 할 일을 하면 마음이 편하고 흐름이 자연스럽습니다.","caution":"이 말은 노력 없이 얻으라는 뜻이 아니라, 대가를 계산하며 일하지 말라는 뜻임을 기억하세요.","advice":"지금 하는 일의 보상을 미리 따지기보다 단계마다 충실히 해 보세요. 결과는 그 뒤에 자연스럽게 따라오는지 살펴보면 됩니다.","message":"대가를 따지지 않고 제 일을 합니다."},{"guaN":25,"guaName":"천뢰무망","pos":3,"label":"六三","yinyang":"yin","text":"无妄之災 或繫之牛 行人之得 邑人之災","reading":"무망지재 혹계지우 행인지득 읍인지재","modern":"바르게 살아도 뜻밖의 재앙이 있습니다. 누군가 소를 매어 두었는데, 지나가던 사람이 끌고 가면 마을 사람이 손해를 입는 것과 같습니다.","meaning":"아래 괘의 끝자리로 전환기에 해당하며, 내 잘못이 없는데도 뜻밖의 손해나 오해가 생길 수 있는 장면입니다. 소를 잃은 마을 사람처럼 이유 없이 피해를 보는 느낌이 들 수 있습니다.","positive":"잘못이 없다는 사실이 시간이 지나면 정리되는 힘이 될 수 있습니다.","caution":"억울함에 분노하여 무리하게 대응하면 상황이 더 꼬이기 쉽습니다.","advice":"일어난 일을 사실대로 정리하고, 필요한 도움을 받아 담담하게 수습해 보세요. 손해를 줄이는 현실적인 조치가 우선입니다.","message":"뜻밖의 일은 담담히 수습하세요."},{"guaN":25,"guaName":"천뢰무망","pos":4,"label":"九四","yinyang":"yang","text":"可貞 无咎","reading":"가정 무구","modern":"바름을 지킬 수 있으며, 허물이 없습니다.","meaning":"위 괘로 올라와 윗자리와 가까워지는 경계의 자리입니다. 강한 성격이지만 겸손한 자리에 있어, 꾸미지 않는 본래의 바름을 지키기만 하면 되는 때입니다.","positive":"자리가 달라져도 본래의 마음을 지키면 허물을 피할 수 있습니다.","caution":"새로운 환경에 맞추려고 이것저것 덧붙이다가 본모습을 잃지 않도록 하세요.","advice":"달라진 자리에서도 내가 지켜 온 기본 원칙이 무엇인지 확인해 보세요. 더 보태기보다 지키는 쪽을 택하는 편이 안정적입니다.","message":"바름을 지키면 허물이 없습니다."},{"guaN":25,"guaName":"천뢰무망","pos":5,"label":"九五","yinyang":"yang","text":"无妄之疾 勿藥有喜","reading":"무망지질 물약유희","modern":"뜻밖의 병이 생겨도 약을 쓰지 않으면 기쁜 일이 있습니다.","meaning":"위 괘의 가운데로 핵심 자리에 있고 바름도 갖춘 상태입니다. 내 잘못 없이 생긴 어려움은 서둘러 손대기보다 스스로 회복되도록 지켜보는 지혜를 말합니다.","positive":"바른 중심이 있으면 작은 문제는 시간이 지나며 저절로 가라앉기도 합니다.","caution":"불안한 마음에 불필요한 대응을 서두르면 오히려 일을 키울 수 있습니다.","advice":"원인이 내게 없다면 상황을 지켜보며 평소의 생활과 원칙을 유지해 보세요. 다만 실제 건강 문제는 이 해석에 기대지 말고 전문가와 상의하세요.","message":"조급한 손길보다 지켜봄이 낫습니다."},{"guaN":25,"guaName":"천뢰무망","pos":6,"label":"上九","yinyang":"yang","text":"无妄行有眚 无攸利","reading":"무망행유생 무유리","modern":"순수함만 믿고 나아가면 재앙이 있고, 이로운 바가 없습니다.","meaning":"끝에 다다른 자리에서 더 나아가려 하면 때에 맞지 않게 됩니다. 순수함도 때를 살피지 않고 밀어붙이면 문제를 부를 수 있다는 경고입니다.","positive":"멈출 때를 알면 지금까지 쌓은 바름을 지킬 수 있습니다.","caution":"옳다는 확신으로 상황을 살피지 않고 계속 밀어붙이는 것은 피하세요.","advice":"이미 마무리 단계라면 새로 무엇을 벌이기보다 정리하고 쉬어 가세요. 내 방식이 지금 상황에 맞는지 한 번 더 점검하는 편이 도움이 됩니다.","message":"때를 살피지 않는 순수함은 위태롭습니다."}],"yong":null},"26":{"n":26,"name":"산천대축","han":"山天大畜","upper":"간","lower":"건","upperHan":"艮","lowerHan":"乾","bits":[1,1,1,0,0,1],"binary":"111001","gua":{"text":"利貞 不家食吉 利涉大川","reading":"이정 불가식길 이섭대천","modern":"바르게 하는 것이 이롭습니다. 집에서 먹지 않아도 길합니다. 큰 내를 건너는 것이 이롭습니다.","symbol":"위에는 산(艮), 아래에는 하늘(乾)이 있어, 큰 산이 하늘의 힘찬 기운을 품고 쌓아 두는 모습입니다. 실력과 덕을 크게 모으고 기르는 괘입니다.","situation":"힘이 모자란 때가 아니라 오히려 힘이 충분히 쌓여 가는 국면입니다. 다만 지금은 쌓은 것을 한꺼번에 쏟기보다 다듬고 붙들어 두는 시간이 필요합니다. 준비가 무르익으면 집 안에 머무르지 않고 바깥에서 쓰일 기회가 다가오기 쉽습니다.","positive":"배움과 경험, 자원이 차곡차곡 쌓여 큰 도전을 감당할 바탕이 됩니다. 쌓은 실력이 신뢰로 이어질 수 있습니다.","caution":"많이 갖췄다는 생각에 서두르거나 쌓기만 하고 쓰임을 미루면 기회를 놓치기 쉽습니다. 방향이 바른지 계속 점검하세요.","direction":"멈추고 쌓는 힘과 나아가는 힘의 균형을 잡아 보세요. 지금은 기본기와 원칙을 다지고, 때가 되었다고 느껴지면 큰 일에 도전해 보는 편이 도움이 됩니다.","message":"충분히 쌓은 힘을 바르게 쓸 때입니다."},"yao":[{"guaN":26,"guaName":"산천대축","pos":1,"label":"初九","yinyang":"yang","text":"有厲 利已","reading":"유려 이이","modern":"위태로움이 있으니 멈추는 것이 이롭습니다.","meaning":"막 힘을 쓰려는 처음 단계인데, 바로 위의 음효가 앞길을 막아 서 있는 장면입니다. 의욕은 넘치지만 지금 나서면 부딪히기 쉬우니 한 걸음 멈추라는 뜻입니다.","positive":"멈추는 선택을 하면 불필요한 충돌과 소모를 줄이고 힘을 아낄 수 있습니다.","caution":"준비가 덜 된 상태에서 의욕만 앞세워 밀어붙이면 위태로워지기 쉽습니다.","advice":"당장 나서고 싶은 마음을 잠시 눌러 두고, 막혀 있는 이유와 내 준비 상태를 먼저 살펴보세요.","message":"서두르지 말고 먼저 멈추어 보세요."},{"guaN":26,"guaName":"산천대축","pos":2,"label":"九二","yinyang":"yang","text":"輿說輹","reading":"여탈복","modern":"수레에서 바퀴 축을 풀어 놓습니다.","meaning":"아래 괘의 중심에서 힘이 넘치지만, 스스로 수레의 바퀴를 풀어 앞으로 가지 않는 장면입니다. 가운데를 지키는 자리라 무리하게 나아가지 않고 때를 기다릴 줄 압니다.","positive":"스스로 속도를 조절하는 절제 덕분에 안정감과 신뢰를 지킬 수 있습니다.","caution":"기다림이 길어질 때 조급해져 억지로 바퀴를 다시 끼우면 흐름이 어긋나기 쉽습니다.","advice":"지금은 앞으로 가는 대신 장비와 실력을 점검하는 시간으로 쓰세요. 스스로 멈춘 이유를 분명히 해 두면 마음이 편해집니다.","message":"스스로 멈추는 것도 힘입니다."},{"guaN":26,"guaName":"산천대축","pos":3,"label":"九三","yinyang":"yang","text":"良馬逐 利艱貞 曰閑輿衛 利有攸往","reading":"양마축 이간정 왈한여위 이유유왕","modern":"좋은 말이 달려 쫓아갑니다. 어려움을 알고 바르게 지키는 것이 이롭습니다. 날마다 수레 모는 법과 호위하는 법을 익히면 나아가는 것이 이롭습니다.","meaning":"아래 괘의 끝에서 위쪽의 상구와 같은 뜻을 가진 효가 만나, 막힘이 풀리고 함께 달리게 되는 전환기입니다. 속도가 붙는 때일수록 방향과 준비를 다지라는 조언이 담겨 있습니다.","positive":"길이 열리고 뜻이 맞는 사람과 함께 힘차게 나아갈 수 있는 흐름입니다.","caution":"달리는 기세에 취해 기본 훈련과 안전 점검을 건너뛰면 탈이 나기 쉽습니다.","advice":"달리기 전후로 연습과 점검을 일과처럼 이어 가세요. 어려움이 있을 수 있음을 염두에 두고 원칙을 지키며 나아가면 좋습니다.","message":"속도를 낼수록 기본기를 챙기세요."},{"guaN":26,"guaName":"산천대축","pos":4,"label":"六四","yinyang":"yin","text":"童牛之牿 元吉","reading":"동우지곡 원길","modern":"어린 소의 뿔에 가로나무를 대어 줍니다. 크게 길합니다.","meaning":"위 괘의 시작에서 아래의 강한 기운을 미리 달래고 막아 주는 장면입니다. 뿔이 자라기 전에 대어 주듯, 문제가 커지기 전에 살짝 다잡는 지혜를 말합니다.","positive":"일이 커지기 전에 미리 단속해 힘을 덜 들이고도 안정을 얻을 수 있습니다.","caution":"때를 놓쳐 이미 자란 뒤에 막으려 하면 훨씬 많은 힘이 듭니다.","advice":"작은 징후일 때 규칙을 정하고 부드럽게 방향을 잡아 주세요. 강하게 누르기보다 미리 약속하는 쪽이 낫습니다.","message":"일이 커지기 전에 미리 다잡으세요."},{"guaN":26,"guaName":"산천대축","pos":5,"label":"六五","yinyang":"yin","text":"豶豕之牙 吉","reading":"분시지아 길","modern":"거세한 돼지의 어금니입니다. 길합니다.","meaning":"위 괘의 중심에서 거칠게 날뛰는 힘을 뿌리부터 가라앉히는 장면입니다. 어금니를 막기보다 돼지의 성질 자체를 누그러뜨리듯 근본을 다스리면 저절로 안정됩니다.","positive":"강하게 맞서지 않고도 근본을 살펴 부드럽게 문제를 풀어낼 수 있습니다.","caution":"겉으로 드러난 행동만 억누르면 불만이 다른 곳으로 새어 나오기 쉽습니다.","advice":"눈에 보이는 문제 행동보다 그 밑에 있는 원인을 먼저 찾아보세요. 힘으로 누르는 대신 방향을 바꿔 주는 것이 도움이 됩니다.","message":"겉이 아닌 뿌리를 다스리세요."},{"guaN":26,"guaName":"산천대축","pos":6,"label":"上九","yinyang":"yang","text":"何天之衢 亨","reading":"하천지구 형","modern":"하늘의 네거리가 어찌 이리 넓은가. 형통합니다.","meaning":"오래 쌓아 온 힘이 막힘없이 터져 나와 사방으로 길이 열리는 끝자리입니다. 쌓기만 하던 단계가 지나 이제 쌓은 것을 세상에 쓰는 때가 되었다는 뜻입니다.","positive":"쌓아 온 실력이 드러나 선택지가 넓어지고 활동 무대가 커질 수 있습니다.","caution":"길이 너무 많아 보여 방향을 못 잡거나, 쌓은 것을 자랑에만 쓰지 않도록 조심하세요.","advice":"넓어진 길 가운데 내가 바라는 방향을 한 가지 골라 시작해 보세요. 쌓은 힘을 나누고 베푸는 데 쓰면 더 오래갑니다.","message":"이제 쌓은 힘을 세상에 쓰세요."}],"yong":null},"27":{"n":27,"name":"산뢰이","han":"山雷頤","upper":"간","lower":"진","upperHan":"艮","lowerHan":"震","bits":[1,0,0,0,0,1],"binary":"100001","gua":{"text":"貞吉 觀頤 自求口實","reading":"정길 관이 자구구실","modern":"바르면 길합니다. 턱을 살펴보고 스스로 입에 채울 것을 구합니다.","symbol":"위에는 산(艮), 아래에는 우레(震)가 있어, 위아래가 단단하고 가운데가 빈 입과 턱의 모습입니다. 먹고 말하며 스스로를 기르고 남을 기르는 괘입니다.","situation":"무엇을 먹고 무슨 말을 하며 누구를 돌보는지가 삶의 방향을 보여 주는 국면입니다. 건강과 생활 습관, 말버릇, 사람을 키우는 일이 중요해지기 쉽습니다. 남이 주는 것에만 기대지 않고 스스로 채우는 태도도 살펴볼 때입니다.","positive":"생활 습관과 말씨를 가다듬으면 몸과 마음이 건강해지고 주변과의 관계도 좋아질 수 있습니다.","caution":"무엇을 받아들이는지 가리지 않고 먹고 말하다 보면 몸도 마음도 흐트러지기 쉽습니다.","direction":"내가 받아들이는 것과 내보내는 것을 하나씩 점검해 보세요. 말은 줄이고 섭취는 절제하며, 내가 기르는 사람이나 일에 어떤 영양을 주고 있는지도 돌아보면 좋습니다.","message":"무엇을 먹고 말하는지가 나를 기릅니다."},"yao":[{"guaN":27,"guaName":"산뢰이","pos":1,"label":"初九","yinyang":"yang","text":"舍爾靈龜 觀我朶頤 凶","reading":"사이영귀 관아타이 흉","modern":"그대의 신령한 거북을 버려 두고 나의 늘어진 턱을 바라보니 흉합니다.","meaning":"스스로 기를 힘이 있는 처음 단계인데, 자기 것을 버려 두고 남이 먹는 것을 부러워하며 입을 벌리는 장면입니다. 위쪽 응하는 자리의 도움에 마음이 쏠리기 쉬운 자리입니다.","positive":"스스로 갖춘 힘이 이미 있음을 알아차리면 방향을 되돌릴 수 있습니다.","caution":"남의 것을 부러워하며 내 장점을 잊으면 마음이 흔들리고 어려움이 따르기 쉽습니다.","advice":"비교하는 마음이 올라오면 내가 이미 가진 것을 세 가지 적어 보세요. 스스로 기를 수 있는 것부터 시작하는 편이 좋습니다.","message":"내 안의 힘을 두고 남을 부러워 마세요."},{"guaN":27,"guaName":"산뢰이","pos":2,"label":"六二","yinyang":"yin","text":"顛頤 拂經于丘頤 征凶","reading":"전이 불경우구이 정흉","modern":"거꾸로 기름을 받고, 떳떳한 이치를 어기고 언덕에서 기름을 구하니, 나아가면 흉합니다.","meaning":"아래 괘의 중심이지만 스스로 서지 못하고 아랫사람의 몸으로 윗사람에게 기대어 얻으려는 장면입니다. 정상적인 순서를 거스르고 높은 곳에서 얻으려 하면 무리가 따릅니다.","positive":"도움을 받아야 할 때를 알아차리는 것만으로도 방향을 점검할 기회가 됩니다.","caution":"순서를 건너뛰고 이득부터 얻으려 하면 오히려 더 큰 어려움이 따르기 쉽습니다.","advice":"도움을 구할 때도 원칙과 순서를 지키고 있는지 살펴보세요. 먼 곳에서 쉽게 얻으려 하기보다 가까운 곳에서 정직하게 구하세요.","message":"순서를 건너뛴 도움은 오래가지 않습니다."},{"guaN":27,"guaName":"산뢰이","pos":3,"label":"六三","yinyang":"yin","text":"拂頤 貞凶 十年勿用 无攸利","reading":"불이 정흉 십년물용 무유리","modern":"기름의 도리를 어기니, 고집하면 흉합니다. 십 년 동안 쓰지 못하고 이로울 바가 없습니다.","meaning":"아래 괘의 끝에서 지나치게 즐기고 탐하는 쪽으로 기울어 기르는 도리를 거스르는 장면입니다. 바른 길과 반대로 가면서 계속 밀어붙이는 때의 위험을 말합니다.","positive":"방향이 어긋났다고 인정하는 순간이 오히려 바른 길로 돌아가는 출발점이 됩니다.","caution":"쾌락이나 이익에 끌려 계속 버티면 오랫동안 쓰이지 못하고 손해가 길어질 수 있습니다.","advice":"지금 끌리는 습관이나 관계가 나를 기르는지 소모시키는지 따져 보세요. 오래 가는 선택이 무엇인지 기준을 세워 보는 편이 도움이 됩니다.","message":"끌리는 대로 가기 전에 멈추어 보세요."},{"guaN":27,"guaName":"산뢰이","pos":4,"label":"六四","yinyang":"yin","text":"顛頤 吉 虎視眈眈 其欲逐逐 无咎","reading":"전이 길 호시탐탐 기욕축축 무구","modern":"거꾸로 기르는 것이나 길합니다. 호랑이처럼 노려보고 그 바람이 끊이지 않으니 허물이 없습니다.","meaning":"위 괘의 시작에서 윗자리의 힘을 받아 아래를 기르는 장면입니다. 아래의 도움을 청하는 모습이 겉으로는 거꾸로 같지만, 크게 베풀기 위해 진지하게 구하니 허물이 되지 않습니다.","positive":"자신을 낮추고 필요한 도움을 구하면 그 힘으로 더 많은 사람을 기를 수 있습니다.","caution":"구하는 마음이 개인의 욕심으로 흐르면 같은 행동이 전혀 다르게 읽힐 수 있습니다.","advice":"도움을 구하는 목적이 나만을 위한 것인지 함께 나누기 위한 것인지 되묻고, 진지하고 끈기 있게 필요한 사람을 찾아가 보세요.","message":"낮추어 구하되 베푸는 데 쓰세요."},{"guaN":27,"guaName":"산뢰이","pos":5,"label":"六五","yinyang":"yin","text":"拂經 居貞吉 不可涉大川","reading":"불경 거정길 불가섭대천","modern":"떳떳한 이치를 어기나, 가만히 바르게 있으면 길합니다. 큰 내를 건너서는 안 됩니다.","meaning":"위 괘의 중심에 있으면서 스스로는 힘이 부족해 아래 상구의 도움을 받는 장면입니다. 큰 일을 직접 벌이기보다 믿을 만한 사람에게 기대어 조용히 지키는 편이 맞는 자리입니다.","positive":"겸손히 조언을 받아들이면 안정적으로 많은 사람을 돌볼 수 있습니다.","caution":"무리하게 큰 모험이나 변화를 벌이면 감당하기 어려워질 수 있습니다.","advice":"큰 결정은 서두르지 말고 믿을 수 있는 조언자의 의견을 구하세요. 지금은 현재 자리를 지키며 차분히 기르는 것이 좋습니다.","message":"큰 모험보다 차분히 지키세요."},{"guaN":27,"guaName":"산뢰이","pos":6,"label":"上九","yinyang":"yang","text":"由頤 厲吉 利涉大川","reading":"유이 려길 이섭대천","modern":"말미암아 기르게 됩니다. 위태롭게 여기면 길합니다. 큰 내를 건너는 것이 이롭습니다.","meaning":"마지막 자리에서 많은 사람이 이 사람을 통해 길러지는 장면입니다. 책임이 무거우니 늘 조심스러운 마음을 지키면 큰 일도 해낼 수 있습니다.","positive":"남을 기르는 책임을 맡아 큰 도전도 함께 건널 수 있는 힘이 있습니다.","caution":"책임이 크다는 사실을 잊고 가볍게 여기면 위험이 커지기 쉽습니다.","advice":"내가 돌보는 사람들을 떠올리며 늘 신중하게 결정하세요. 조심하는 마음이 있다면 큰 일에 도전해도 좋은 때입니다.","message":"무거운 책임일수록 조심스럽게 나아가세요."}],"yong":null},"28":{"n":28,"name":"택풍대과","han":"澤風大過","upper":"태","lower":"손","upperHan":"兌","lowerHan":"巽","bits":[0,1,1,1,1,0],"binary":"011110","gua":{"text":"棟橈 利有攸往 亨","reading":"동요 이유유왕 형","modern":"마룻대가 휩니다. 나아갈 곳이 있으면 이롭고 형통합니다.","symbol":"위에는 연못(澤), 아래에는 바람(巽, 나무)이 있어, 못물이 나무를 덮어 대들보가 휘어지는 모습입니다. 가운데는 강한데 양 끝이 약해 무게를 버티기 어려운 괘입니다.","situation":"책임이나 업무, 감정의 짐이 평소 감당하던 수준을 넘어선 국면입니다. 이대로 버티면 한계에 이르기 쉽지만, 평소와 다른 결단과 방식의 전환으로 길을 찾을 수도 있습니다. 비상한 때에는 비상한 대응이 필요합니다.","positive":"한계에 다다른 만큼 낡은 방식을 바꾸고 과감하게 움직일 명분이 생깁니다. 방향을 잡으면 오히려 크게 풀릴 수 있습니다.","caution":"혼자 모든 짐을 지려 하거나 무리하게 버티면 어느 순간 한꺼번에 무너지기 쉽습니다.","direction":"짐을 나누고 받쳐 줄 기둥을 보강하는 쪽으로 방향을 잡아 보세요. 도움을 요청하고 구조를 바꾸되, 무리한 한 방보다 균형을 회복하는 선택이 도움이 됩니다.","message":"무거울 때는 방식부터 바꾸세요."},"yao":[{"guaN":28,"guaName":"택풍대과","pos":1,"label":"初六","yinyang":"yin","text":"藉用白茅 无咎","reading":"자용백모 무구","modern":"흰 띠풀을 깔고 물건을 놓으니 허물이 없습니다.","meaning":"짐이 쌓이기 시작하는 처음 단계에서 흰 풀을 깔아 놓고 조심스럽게 물건을 두는 장면입니다. 낮은 자리에서 한 겹 더 정성을 들이는 신중함이 허물을 막아 줍니다.","positive":"처음부터 조심스럽게 준비하면 큰 짐도 안전하게 다룰 수 있습니다.","caution":"신중함이 지나쳐 시작 자체를 미루거나 소심해지지 않도록 하세요.","advice":"큰 일을 시작하기 전에 완충 장치와 안전망을 한 겹씩 만들어 두세요. 작은 정성이 뒤의 큰 부담을 줄여 줍니다.","message":"시작부터 한 겹 더 조심하세요."},{"guaN":28,"guaName":"택풍대과","pos":2,"label":"九二","yinyang":"yang","text":"枯楊生稊 老夫得其女妻 无不利","reading":"고양생제 노부득기녀처 무불리","modern":"마른 버드나무에 새싹이 돋습니다. 늙은 남자가 젊은 아내를 얻으니 이롭지 않은 것이 없습니다.","meaning":"아래 괘의 중심에서 단단한 힘이 가장 약한 처음 효와 만나 생기를 얻는 장면입니다. 시든 줄기에 새싹이 돋듯, 오래된 것에 새로운 활력이 들어오는 때입니다.","positive":"새로운 사람이나 아이디어가 정체된 상황에 생기를 불어넣을 수 있습니다.","caution":"새로운 활력에 기대 현실의 한계를 잊거나 균형을 놓치지 않도록 하세요.","advice":"오래된 방식에 새 관점을 한 가지 들여와 보세요. 낮은 자리의 의견에도 귀를 열면 도움이 됩니다.","message":"낡은 곳에 새 싹이 돋습니다."},{"guaN":28,"guaName":"택풍대과","pos":3,"label":"九三","yinyang":"yang","text":"棟橈 凶","reading":"동요 흉","modern":"마룻대가 휘니 흉합니다.","meaning":"아래 괘의 끝자리에서 강한 힘이 강한 자리에 놓여 너무 무겁고 고집스러워진 장면입니다. 누구의 도움도 받아들이지 않다 보니 버티는 힘이 한계에 이릅니다.","positive":"한계를 정직하게 인식하면 구조를 바꿀 마지막 기회를 잡을 수 있습니다.","caution":"남의 조언을 막고 혼자 버티면 어려움이 한꺼번에 커지기 쉽습니다.","advice":"버티는 것이 곧 강함은 아닙니다. 지금 짊어진 일을 목록으로 적고 나눌 수 있는 것부터 다른 사람에게 부탁해 보세요.","message":"혼자 버티는 것은 한계가 있습니다."},{"guaN":28,"guaName":"택풍대과","pos":4,"label":"九四","yinyang":"yang","text":"棟隆 吉 有它吝","reading":"동륭 길 유타린","modern":"마룻대가 높이 솟으니 길합니다. 다른 마음이 있으면 아쉬움이 따릅니다.","meaning":"위 괘의 시작에서 휘지 않고 튼튼하게 받치는 장면입니다. 아래의 도움을 받아 중심이 곧게 서지만, 다른 곳에 마음을 쓰면 균형이 흔들릴 수 있습니다.","positive":"주변에서 받쳐 주는 힘 덕분에 부담을 이겨 내고 안정감을 되찾을 수 있습니다.","caution":"믿을 만한 기둥이 있는데도 다른 쪽에 마음을 기웃거리면 아쉬운 일이 생기기 쉽습니다.","advice":"지금 나를 받쳐 주는 사람이나 방식에 집중하고 신뢰를 지키세요. 곁눈질하기보다 맡은 자리를 단단히 하는 편이 낫습니다.","message":"받쳐 주는 힘에 집중하세요."},{"guaN":28,"guaName":"택풍대과","pos":5,"label":"九五","yinyang":"yang","text":"枯楊生華 老婦得其士夫 无咎无譽","reading":"고양생화 노부득기사부 무구무예","modern":"마른 버드나무에 꽃이 핍니다. 늙은 부인이 젊은 남편을 얻으니 허물도 없고 칭찬도 없습니다.","meaning":"위 괘의 중심이지만 이미 위에 짐이 쌓여 뿌리 없이 꽃만 피는 장면입니다. 반짝 활기는 있으나 오래 이어질 새 힘으로 이어지기는 어렵습니다.","positive":"일시적으로 기분 전환이나 작은 성과를 얻어 숨통을 틔울 수 있습니다.","caution":"꽃이 핀 것을 큰 성공으로 착각하고 뿌리를 돌보지 않으면 오래가지 않습니다.","advice":"눈에 띄는 성과에 들뜨기보다 뿌리가 되는 기반을 다시 점검하세요. 칭찬이 없어도 꾸준히 내실을 다지는 것이 좋습니다.","message":"꽃보다 뿌리를 돌보세요."},{"guaN":28,"guaName":"택풍대과","pos":6,"label":"上六","yinyang":"yin","text":"過涉滅頂 凶 无咎","reading":"과섭멸정 흉 무구","modern":"지나치게 물을 건너 이마까지 잠기니 흉하나, 허물은 없습니다.","meaning":"끝자리에서 너무 깊이 들어가 물이 정수리를 덮는 장면입니다. 위험을 무릅쓰고 한 일의 결과이므로 형편은 어렵지만, 뜻을 다하려 한 일이라 탓하기는 어렵습니다.","positive":"스스로 한계를 넘어서려 한 용기와 헌신은 의미 있는 경험으로 남습니다.","caution":"무리한 도전이 지나치면 몸과 마음이 크게 지칠 수 있으니 안전을 먼저 살피세요.","advice":"이미 깊이 들어갔다면 더 가려 하지 말고 한 발 물러날 길을 찾으세요. 자신을 탓하기보다 다음에는 어디까지가 적당한지 기준을 세우세요.","message":"용기도 한계를 알아야 빛납니다."}],"yong":null},"29":{"n":29,"name":"감위수","han":"坎爲水","upper":"감","lower":"감","upperHan":"坎","lowerHan":"坎","bits":[0,1,0,0,1,0],"binary":"010010","gua":{"text":"習坎 有孚 維心亨 行有尙","reading":"습감 유부 유심형 행유상","modern":"거듭된 구덩이입니다. 믿음이 있으니 오직 마음이 통하고, 나아가면 높이 평가받습니다.","symbol":"위아래 모두 물(坎)이 겹쳐 있어, 구덩이와 험한 곳이 거듭되는 모습입니다. 그래도 물은 낮은 곳을 채우며 멈추지 않고 흘러가는 괘입니다.","situation":"어려움이 한 번으로 끝나지 않고 연이어 닥치는 듯한 국면입니다. 요령보다 정직과 꾸준함이 필요한 때이고, 피하려 하기보다 어려움 속에서 배우며 나아가는 태도가 중요합니다. 침착함을 잃지 않으면 길이 보이기 쉽습니다.","positive":"시련을 겪으며 마음이 단단해지고, 진심으로 대하는 태도가 주변의 신뢰를 얻을 수 있습니다.","caution":"당황해서 꾀를 부리거나 구덩이 안에 익숙해져 주저앉으면 더 깊이 빠지기 쉽습니다.","direction":"물이 낮은 곳을 채우며 흐르듯 눈앞의 한 걸음부터 차분히 나아가 보세요. 진실한 마음을 지키고, 혼자 버티기 어려우면 도움을 청하는 것도 방법입니다.","message":"물처럼 정직하게 한 걸음씩 흐르세요."},"yao":[{"guaN":29,"guaName":"감위수","pos":1,"label":"初六","yinyang":"yin","text":"習坎 入于坎窞 凶","reading":"습감 입우감담 흉","modern":"거듭된 구덩이에서 구덩이 속 깊은 곳으로 들어가니 흉합니다.","meaning":"어려움의 처음 단계에서 음이 낮은 자리에 있어 힘이 약하고, 구덩이에 익숙해져 더 깊이 빠지는 장면입니다. 시작부터 길을 잃으면 빠져나오기가 힘들어집니다.","positive":"처음 단계에서 깊이를 인정하면 빠져나올 방법을 일찍 찾을 수 있습니다.","caution":"어려움에 익숙해져 체념하거나 작은 위기를 가볍게 보면 더 깊어지기 쉽습니다.","advice":"무엇이 나를 구덩이로 이끄는지 한 가지씩 적어 보고, 가장 작은 것부터 벗어나는 행동을 시작해 보세요.","message":"빠졌다면 더 깊이 들어가지 마세요."},{"guaN":29,"guaName":"감위수","pos":2,"label":"九二","yinyang":"yang","text":"坎有險 求小得","reading":"감유험 구소득","modern":"구덩이 속에 험난함이 있으니, 작은 것부터 구하여 얻습니다.","meaning":"아래 괘의 중심에서 강한 힘으로 버티지만 사방이 막힌 장면입니다. 당장 벗어나기는 어려우니 큰 목표 대신 작은 것부터 얻어 가는 것이 현실적입니다.","positive":"작은 성과를 하나씩 얻으며 숨통을 트고 다음 걸음을 준비할 수 있습니다.","caution":"한 번에 모든 것을 해결하려는 욕심이 오히려 더 큰 위험을 부를 수 있습니다.","advice":"지금은 큰 탈출보다 오늘 해결할 수 있는 작은 일에 집중하세요. 작은 성공들이 모여 길을 만듭니다.","message":"큰 탈출보다 작은 한 걸음이 먼저입니다."},{"guaN":29,"guaName":"감위수","pos":3,"label":"六三","yinyang":"yin","text":"來之坎坎 險且枕 入于坎窞 勿用","reading":"래지감감 험차침 입우감담 물용","modern":"오고 가는 곳마다 구덩이이고 험한 데다 기대어 있으니, 구덩이 깊은 곳에 들어갑니다. 쓰지 마십시오.","meaning":"아래 괘의 끝자리에서 앞뒤가 모두 험해 나아가도 물러나도 구덩이인 장면입니다. 무리하게 움직이면 오히려 더 깊이 빠지는 때입니다.","positive":"움직임을 멈추고 상황을 정확히 읽을 시간을 얻을 수 있습니다.","caution":"답답한 마음에 되는 대로 움직이면 앞뒤 모두 막힌 상황이 더 나빠지기 쉽습니다.","advice":"결정을 서두르지 말고 쉬면서 정보를 모으세요. 선택지가 다 어려워 보일 때는 일단 멈추는 것이 안전한 선택일 수 있습니다.","message":"앞뒤가 막히면 먼저 멈추세요."},{"guaN":29,"guaName":"감위수","pos":4,"label":"六四","yinyang":"yin","text":"樽酒簋貳 用缶 納約自牖 終无咎","reading":"준주궤이 용부 납약자유 종무구","modern":"술 한 통과 밥 두 그릇을 질그릇에 담아, 창문으로 약속을 들이니 끝내 허물이 없습니다.","meaning":"위 괘의 시작에서 임금 가까운 자리에 놓여, 화려한 예물 없이 소박한 마음으로 믿음을 전하는 장면입니다. 어려운 때에는 격식보다 진심과 열린 틈이 길을 만듭니다.","positive":"꾸밈없는 정성이 어려운 관계를 풀고 믿음을 이어 줍니다.","caution":"형식이나 체면에 얽매여 마음을 전할 통로를 스스로 막지 않도록 하세요.","advice":"화려한 방법보다 솔직하고 소박한 대화를 택해 보세요. 정면이 막혀 있다면 다른 통로로 진심을 전할 방법을 찾아보세요.","message":"진심은 소박해도 통합니다."},{"guaN":29,"guaName":"감위수","pos":5,"label":"九五","yinyang":"yang","text":"坎不盈 祗旣平 无咎","reading":"감불영 지기평 무구","modern":"구덩이가 가득 차지는 않았으나 이미 평평해지니 허물이 없습니다.","meaning":"위 괘의 중심에서 물이 구덩이를 채우며 평평해지는 장면입니다. 아직 넘치지는 않지만 어려움이 가라앉기 시작하고, 지나치게 채우려 하지 않는 절제가 허물을 막습니다.","positive":"어려움이 차츰 가라앉아 안정을 되찾는 흐름을 느낄 수 있습니다.","caution":"조금 나아졌다고 서둘러 가득 채우려 하거나 넘치도록 욕심내지 않도록 하세요.","advice":"회복되는 속도에 맞추어 천천히 균형을 잡아 가세요. 지금은 넘치게 채우기보다 적당한 선에서 멈추는 편이 좋습니다.","message":"넘치기 전에 평평해지면 충분합니다."},{"guaN":29,"guaName":"감위수","pos":6,"label":"上六","yinyang":"yin","text":"係用徽纆 寘于叢棘 三歲不得 凶","reading":"계용휘묵 치우총극 삼세부득 흉","modern":"굵은 밧줄로 묶어 가시덤불에 가두니 삼 년이 지나도 풀려나지 못하여 흉합니다.","meaning":"어려움의 마지막 자리에서 음이 약한 채 길을 잃고 스스로 갇힌 듯한 장면입니다. 오래 걸리고 풀리지 않는 듯 느껴지는 시기를 말하며, 거기서 어떻게 마음을 정리하는지가 중요합니다.","positive":"오랜 시련 끝에 같은 일을 되풀이하지 않을 교훈을 얻을 수 있습니다.","caution":"스스로를 가두는 생각에 오래 머물면 풀려날 기회마저 놓치기 쉽습니다.","advice":"묶여 있다고 느끼는 원인을 구체적으로 적어 보고, 혼자 풀기 어렵다면 믿을 만한 사람이나 전문가의 도움을 청해 보세요.","message":"스스로 가두는 생각을 풀어 보세요."}],"yong":null},"30":{"n":30,"name":"리위화","han":"離爲火","upper":"리","lower":"리","upperHan":"離","lowerHan":"離","bits":[1,0,1,1,0,1],"binary":"101101","gua":{"text":"利貞 亨 畜牝牛 吉","reading":"이정 형 휵빈우 길","modern":"바르게 하는 것이 이롭고 형통합니다. 암소를 기르듯 하면 길합니다.","symbol":"위아래 모두 불(離)이 겹쳐 있어, 불이 땔감에 붙어 타오르며 밝게 비추는 모습입니다. 밝음과 서로 의지함을 뜻하는 괘입니다.","situation":"이해와 통찰, 드러남과 평가가 두드러지는 국면입니다. 불이 땔감에 붙어야 타오르듯 무엇에 의지하는지에 따라 밝음이 오래갈 수도, 금방 소진될 수도 있습니다. 내가 기대는 기반이 바른지 살펴볼 때입니다.","positive":"상황이 환히 보이고 사람들에게 내 가치를 알릴 기회가 생길 수 있습니다. 순하고 부드러운 태도가 도움이 됩니다.","caution":"드러나는 데만 마음을 쓰면 기운이 빨리 소진되고, 의지할 대상을 잘못 고르면 함께 흔들리기 쉽습니다.","direction":"화려하게 빛나는 것보다 바른 것에 의지하고 부드럽게 유지하는 쪽을 택해 보세요. 밝음이 기울 때를 받아들일 준비도 함께 하면 좋습니다.","message":"바른 것에 붙어 오래 밝히세요."},"yao":[{"guaN":30,"guaName":"리위화","pos":1,"label":"初九","yinyang":"yang","text":"履錯然 敬之 无咎","reading":"이착연 경지 무구","modern":"발걸음이 어지럽게 엇갈리나 공경하는 마음으로 대하면 허물이 없습니다.","meaning":"밝음이 막 피어나는 처음 단계에서 이것저것 마음이 어수선하게 얽히는 장면입니다. 아직 중심이 없으니 서두르지 말고 정중하고 신중한 태도로 시작하라는 뜻입니다.","positive":"처음의 어수선함을 신중함으로 다잡으면 이후 흐름이 훨씬 안정됩니다.","caution":"이것저것 손대며 마음이 분산되면 아무것도 제대로 시작하지 못할 수 있습니다.","advice":"하루를 시작할 때 오늘 집중할 일 한두 가지를 정하고, 그 일을 정성스럽게 대해 보세요.","message":"어수선한 시작은 정성으로 가라앉히세요."},{"guaN":30,"guaName":"리위화","pos":2,"label":"六二","yinyang":"yin","text":"黃離 元吉","reading":"황리 원길","modern":"누런빛의 밝음입니다. 크게 길합니다.","meaning":"아래 괘의 중심에서 음이 음의 자리에 놓여 부드럽고 바르게 빛나는 장면입니다. 누런색은 가운데를 뜻하는 빛깔로, 치우치지 않고 조화롭게 밝히는 상태를 말합니다.","positive":"치우치지 않은 태도가 주변의 신뢰와 조화를 얻고 안정된 성과로 이어집니다.","caution":"좋은 상태라는 생각에 안주해 점검을 게을리하면 균형이 조금씩 기울 수 있습니다.","advice":"지금의 균형 잡힌 태도와 루틴을 소중히 지키세요. 한쪽으로 쏠린다고 느낄 때 가운데로 돌아오는 습관을 가지면 좋습니다.","message":"가운데를 지키는 밝음이 가장 오래갑니다."},{"guaN":30,"guaName":"리위화","pos":3,"label":"九三","yinyang":"yang","text":"日昃之離 不鼓缶而歌 則大耋之嗟 凶","reading":"일측지리 불고부이가 즉대질지차 흉","modern":"해가 기울어 가는 때의 밝음입니다. 질그릇을 치며 노래하지 않으면 늙음을 탄식하게 되니 흉합니다.","meaning":"아래 괘의 끝에서 한 시기의 밝음이 저물고 다음으로 넘어가는 전환기입니다. 해 질 녘을 즐기며 받아들이지 못하고 늙음만 한탄하면 힘들어지는 때를 말합니다.","positive":"끝을 받아들이면 지금까지의 시간을 소중히 되돌아보며 다음 단계를 준비할 수 있습니다.","caution":"지나간 전성기에만 매달려 한탄하면 마음이 더 가라앉기 쉽습니다.","advice":"이미 지나가는 것을 인정하고 지금 즐길 수 있는 소소한 즐거움을 찾아보세요. 다음 세대나 다음 단계로 넘겨줄 것도 생각해 보세요.","message":"저무는 때도 노래하며 받아들이세요."},{"guaN":30,"guaName":"리위화","pos":4,"label":"九四","yinyang":"yang","text":"突如其來如 焚如 死如 棄如","reading":"돌여기래여 분여 사여 기여","modern":"갑자기 닥쳐와 불타고 죽고 버려지는 듯합니다.","meaning":"위 괘의 시작에서 아래의 불길이 갑자기 치고 올라와 자리를 위협하는 장면입니다. 밝음을 이으려는 급한 기세가 오히려 스스로를 태우고 모두에게서 멀어지게 만드는 모습입니다.","positive":"급격한 소진을 겪은 뒤에 무엇이 중요한지 선명하게 깨달을 수 있습니다.","caution":"성급한 기세와 격한 감정으로 치고 나가면 관계와 기반을 한꺼번에 잃기 쉽습니다.","advice":"화가 오르거나 마음이 급해질 때 바로 행동하지 말고 하루 이틀 시간을 두세요. 불길을 키우기보다 다스리는 쪽을 택해 보세요.","message":"급한 불길은 먼저 나를 태웁니다."},{"guaN":30,"guaName":"리위화","pos":5,"label":"六五","yinyang":"yin","text":"出涕沱若 戚嗟若 吉","reading":"출체타약 척차약 길","modern":"눈물이 비 오듯 흐르고 근심하며 탄식하니 길합니다.","meaning":"위 괘의 중심에서 가장 높은 자리에 있지만 두 강한 효 사이에 끼어 걱정이 깊은 장면입니다. 근심하고 슬퍼하는 마음이 오히려 겸손과 신중함이 되어 길로 이어집니다.","positive":"스스로의 부족함을 알고 아파하는 마음이 사람들의 공감을 얻고 균형을 잡아 줍니다.","caution":"걱정에만 머물러 아무 행동도 하지 않으면 슬픔이 길어질 수 있습니다.","advice":"마음이 아플 때는 감정을 참지 말고 털어놓으세요. 그 마음을 바탕으로 주변을 돌보고 조심스럽게 정리해 보세요.","message":"근심하는 마음이 나를 바로 세웁니다."},{"guaN":30,"guaName":"리위화","pos":6,"label":"上九","yinyang":"yang","text":"王用出征 有嘉折首 獲匪其醜 无咎","reading":"왕용출정 유가절수 획비기추 무구","modern":"왕이 출정하여 아름다운 공으로 우두머리를 꺾고, 그 무리를 사로잡지는 않으니 허물이 없습니다.","meaning":"밝음이 끝에 이른 자리에서 과감하게 문제의 핵심만 정리하는 장면입니다. 우두머리만 꺾고 따르는 무리는 해치지 않는 절도로 허물이 없습니다.","positive":"핵심 문제를 분명히 가려내 과감하게 정리하면 불필요한 피해를 줄일 수 있습니다.","caution":"결단이 지나쳐 관련 없는 사람이나 부분까지 정리하려 들면 새로운 갈등이 생깁니다.","advice":"문제의 뿌리와 곁가지를 구분하고 뿌리에만 단호하게 대응해 보세요. 나머지에는 너그러움을 남겨 두면 좋습니다.","message":"핵심만 단호하게, 나머지는 너그럽게."}],"yong":null},"31":{"n":31,"name":"택산함","han":"澤山咸","upper":"태","lower":"간","upperHan":"兌","lowerHan":"艮","bits":[0,0,1,1,1,0],"binary":"001110","gua":{"text":"亨 利貞 取女吉","reading":"형 이정 취녀길","modern":"형통합니다. 바르게 하는 것이 이롭습니다. 여자를 맞이하면 길합니다.","symbol":"위에는 연못(澤), 아래에는 산(艮)이 있어, 산이 낮은 곳의 못을 받아들이고 못이 산을 적시며 서로 기운을 주고받는 모습입니다. 마음이 서로 느껴 통하는 괘입니다.","situation":"새로운 인연이나 교감, 공감이 중요해지는 국면입니다. 계산보다 열린 마음과 진정성이 상대에게 전달되어 관계가 시작되기 쉽습니다. 다만 느낌이 곧 깊이는 아니므로, 감응이 어디까지 이르렀는지 살필 필요도 있습니다.","positive":"마음을 열면 사람과 일에서 자연스러운 공감과 호응을 얻을 수 있습니다.","caution":"겉으로 드러난 끌림이나 분위기에만 이끌리면 마음이 금세 흔들릴 수 있습니다.","direction":"진심을 천천히 확인하며 열린 마음으로 다가가 보세요. 느낌이 얕은 단계에서 확신하기보다 바른 마음과 관계의 깊이를 함께 키우는 편이 좋습니다.","message":"열린 마음이 서로를 움직입니다."},"yao":[{"guaN":31,"guaName":"택산함","pos":1,"label":"初六","yinyang":"yin","text":"咸其拇","reading":"함기무","modern":"엄지발가락에서 느낍니다.","meaning":"감응이 막 시작되는 맨 아래 단계로, 발끝이 살짝 움직이는 정도의 아주 작은 느낌입니다. 마음은 일었지만 아직 행동으로 드러나지 않은 상태입니다.","positive":"작은 호감과 호기심이 새로운 인연의 출발점이 될 수 있습니다.","caution":"아직 미미한 느낌을 과대하게 해석하면 앞서 나가기 쉽습니다.","advice":"느낌이 생겼다면 서두르지 말고 시간을 두고 지켜보세요. 작은 신호를 천천히 확인해 가면 좋습니다.","message":"작은 느낌은 천천히 지켜보세요."},{"guaN":31,"guaName":"택산함","pos":2,"label":"六二","yinyang":"yin","text":"咸其腓 凶 居吉","reading":"함기비 흉 거길","modern":"장딴지에서 느낍니다. 나아가면 흉하고 머무르면 길합니다.","meaning":"아래 괘의 중심으로, 감응이 장딴지까지 올라와 몸이 먼저 움직이려는 장면입니다. 느낌이 앞서 서둘러 가려 하면 어려움이 따르니 자리를 지키며 기다리는 쪽이 맞습니다.","positive":"차분히 머무르며 때를 기다리면 감정이 자연스럽게 가라앉고 방향이 보입니다.","caution":"끌리는 대로 급히 움직이면 상대와 속도가 맞지 않아 어긋나기 쉽습니다.","advice":"마음이 급해질 때 한 박자 쉬어 가세요. 지금은 먼저 다가가기보다 내 자리에서 신뢰를 쌓는 편이 도움이 됩니다.","message":"움직이고 싶을 때 한 박자 쉬세요."},{"guaN":31,"guaName":"택산함","pos":3,"label":"九三","yinyang":"yang","text":"咸其股 執其隨 往吝","reading":"함기고 집기수 왕린","modern":"허벅지에서 느끼고 그 따르는 것을 붙잡으니, 나아가면 아쉬움이 따릅니다.","meaning":"아래 괘의 끝에서 감응이 허벅지까지 올라와 남을 따라가려는 마음이 강해지는 장면입니다. 스스로 중심을 잡지 못하고 남의 움직임에 끌려가기 쉬운 전환기입니다.","positive":"남에게 마음이 열려 있어 협력이 쉬워지는 면이 있습니다.","caution":"주체성 없이 상대나 분위기를 따라가다 보면 후회나 아쉬움이 남기 쉽습니다.","advice":"누구를 따르고 싶은 마음이 들면 그것이 내 판단인지 분위기인지 먼저 구분해 보세요. 내 기준을 한 가지 정하고 움직이면 좋습니다.","message":"따라가기 전에 내 기준을 세우세요."},{"guaN":31,"guaName":"택산함","pos":4,"label":"九四","yinyang":"yang","text":"貞吉 悔亡 憧憧往來 朋從爾思","reading":"정길 회망 동동왕래 붕종이사","modern":"바르면 길하고 후회가 없어집니다. 마음이 갈팡질팡 오가면 벗이 그대의 생각만 따를 것입니다.","meaning":"위 괘의 시작이자 마음에 해당하는 자리로, 진심으로 감응하려는 장면입니다. 바른 마음을 지키면 후회가 사라지지만 이런저런 계산으로 오가면 영향이 좁은 범위에 그칩니다.","positive":"바른 마음을 지키면 후회가 줄고 더 넓은 공감과 신뢰를 얻을 수 있습니다.","caution":"이해득실을 따지며 마음이 오락가락하면 진심이 전해지지 않고 몇 사람에게만 머뭅니다.","advice":"계산을 앞세우기보다 내 마음이 가려는 바른 방향을 정하고 일관되게 대하세요. 진심이 있는 곳에 사람이 모입니다.","message":"계산을 줄이고 진심을 지키세요."},{"guaN":31,"guaName":"택산함","pos":5,"label":"九五","yinyang":"yang","text":"咸其脢 无悔","reading":"함기매 무회","modern":"등살에서 느끼니 후회가 없습니다.","meaning":"위 괘의 중심에서 감응이 등까지 이르렀지만 마음을 움직이는 데까지는 가지 않은 장면입니다. 깊이 있게 흔들리지 않고 꾸준히 자리를 지키는 모습으로 후회가 없습니다.","positive":"외부의 자극에 쉽게 휩쓸리지 않는 안정감이 신뢰를 줍니다.","caution":"흔들리지 않는 만큼 적극적인 교감이 부족해 보일 수 있으니 필요할 때는 마음을 표현하세요.","advice":"서두르지 않는 태도는 유지하되 상대가 알 수 있도록 작은 관심을 말로 전해 보세요.","message":"흔들리지 않되 마음은 표현하세요."},{"guaN":31,"guaName":"택산함","pos":6,"label":"上六","yinyang":"yin","text":"咸其輔頰舌","reading":"함기보협설","modern":"광대뼈와 뺨과 혀에서 느낍니다.","meaning":"마지막 자리에서 감응이 말로만 나타나는 장면입니다. 마음이 담기지 않은 채 입으로만 감동을 주고받으면 겉치레가 되기 쉽습니다.","positive":"말로 마음을 표현하고 소통하는 것 자체는 관계에 활력을 줄 수 있습니다.","caution":"말만 앞서고 행동과 진심이 따르지 않으면 신뢰가 가벼워질 수 있습니다.","advice":"말한 만큼 행동으로 옮기고 있는지 돌아보세요. 화려한 표현보다 작은 실천을 하나 더하는 것이 좋습니다.","message":"말보다 진심과 행동이 오래갑니다."}],"yong":null},"32":{"n":32,"name":"뇌풍항","han":"雷風恒","upper":"진","lower":"손","upperHan":"震","lowerHan":"巽","bits":[0,1,1,1,0,0],"binary":"011100","gua":{"text":"亨 无咎 利貞 利有攸往","reading":"형 무구 이정 이유유왕","modern":"형통하고 허물이 없습니다. 바르게 하는 것이 이롭고, 나아갈 곳이 있는 것도 이롭습니다.","symbol":"위에는 우레(震), 아래에는 바람(巽)이 있어, 우레와 바람이 서로 도우며 오래 이어지는 모습입니다. 꾸준함과 변치 않는 도리를 뜻하는 괘입니다.","situation":"장기적인 일과 관계, 습관을 다져야 하는 국면입니다. 단기 성과보다 지속 가능한 방식을 정하고 꾸준히 이어 가는 것이 중요합니다. 변치 않음은 굳어 있음이 아니라 변화 속에서도 근본을 지키는 것입니다.","positive":"일관된 태도와 꾸준한 노력이 쌓여 신뢰와 안정으로 이어질 수 있습니다.","caution":"처음부터 지나치게 깊이 파고들거나 고집만 지키면 오히려 막히기 쉽습니다.","direction":"오래 할 수 있는 속도와 방식을 정하고 근본은 지키되 상황에 맞춰 유연하게 조정해 보세요. 눈에 보이는 성과보다 꾸준히 이어 가는 힘에 마음을 두면 좋습니다.","message":"근본은 지키고 방식은 유연하게."},"yao":[{"guaN":32,"guaName":"뇌풍항","pos":1,"label":"初六","yinyang":"yin","text":"浚恒 貞凶 无攸利","reading":"준항 정흉 무유리","modern":"깊이 파서 항상함을 구하니, 고집하면 흉하고 이로울 바가 없습니다.","meaning":"이제 막 시작하는 단계에서 너무 깊이, 너무 빨리 변치 않는 결과를 바라는 장면입니다. 아직 바탕이 쌓이지 않았는데 처음부터 큰 성과와 깊은 관계를 요구하면 무리가 따릅니다.","positive":"처음의 열정은 오래 이어 갈 에너지가 되어 줄 수 있습니다.","caution":"시작하자마자 깊은 결과를 요구하면 서로 부담을 느끼고 지치기 쉽습니다.","advice":"처음에는 작은 단위의 약속과 습관부터 시작하세요. 시간이 쌓이며 깊어지는 속도를 인정해 주는 편이 좋습니다.","message":"처음부터 깊이 파지 마세요."},{"guaN":32,"guaName":"뇌풍항","pos":2,"label":"九二","yinyang":"yang","text":"悔亡","reading":"회망","modern":"후회가 사라집니다.","meaning":"아래 괘의 중심에서 강한 힘이 짝수 자리에 있어 스스로 지나침을 알고 절제하는 장면입니다. 중심을 지키니 처음의 아쉬움이 자연스럽게 가라앉습니다.","positive":"자리에 맞게 힘을 조절하여 후회를 줄이고 안정을 되찾을 수 있습니다.","caution":"잘 풀리고 있다고 해서 절제하는 습관을 놓으면 다시 어긋나기 쉽습니다.","advice":"지금의 균형을 만든 습관이 무엇인지 확인하고 계속 이어 가세요. 과해지려는 순간 한 걸음 덜어내는 연습을 해 보세요.","message":"중심을 지키면 후회가 줄어듭니다."},{"guaN":32,"guaName":"뇌풍항","pos":3,"label":"九三","yinyang":"yang","text":"不恒其德 或承之羞 貞吝","reading":"불항기덕 혹승지수 정린","modern":"그 덕을 변함없이 지니지 못하니 혹 부끄러움을 받게 됩니다. 고집하면 아쉬움이 따릅니다.","meaning":"아래 괘의 끝에서 위로 나아가려는 마음이 급해 태도가 자꾸 흔들리는 전환기입니다. 일관성 없이 이랬다저랬다 하면 신뢰를 잃어 스스로 부끄러운 일을 겪기 쉽습니다.","positive":"흔들림을 알아차리면 원칙을 다시 정해 일관성을 회복할 기회가 됩니다.","caution":"상황에 따라 말과 태도가 달라지면 주변의 신뢰를 잃기 쉽습니다.","advice":"내가 지키려는 원칙을 한두 문장으로 적어 두고 흔들릴 때마다 확인하세요. 약속은 지킬 수 있는 만큼만 하는 편이 도움이 됩니다.","message":"자주 바뀌면 신뢰가 흔들립니다."},{"guaN":32,"guaName":"뇌풍항","pos":4,"label":"九四","yinyang":"yang","text":"田无禽","reading":"전무금","modern":"사냥을 해도 잡을 짐승이 없습니다.","meaning":"위 괘의 시작에서 자리에 맞지 않는 곳에서 애써 사냥을 하는 장면입니다. 방법이나 장소가 맞지 않아 오래 노력해도 얻는 것이 적은 때입니다.","positive":"결과가 없는 경험을 통해 방식을 바꿔야 한다는 중요한 신호를 얻을 수 있습니다.","caution":"맞지 않는 방식을 꾸준함이라는 이름으로 계속하면 힘만 소모하기 쉽습니다.","advice":"오래 해도 성과가 없다면 노력의 양이 아니라 방향과 장소가 맞는지 점검해 보세요. 꾸준함은 알맞은 곳에서 빛납니다.","message":"꾸준함에도 알맞은 자리가 필요합니다."},{"guaN":32,"guaName":"뇌풍항","pos":5,"label":"六五","yinyang":"yin","text":"恒其德 貞 婦人吉 夫子凶","reading":"항기덕 정 부인길 부자흉","modern":"그 덕을 변함없이 지니니 곧습니다. 부인에게는 길하고 남편에게는 흉합니다.","meaning":"위 괘의 중심에서 부드러운 힘이 한결같이 따르는 덕을 지키는 장면입니다. 따르고 순응하는 자세는 잘 어울리지만, 결단하고 이끌어야 할 때는 그것만으로는 부족할 수 있습니다.","positive":"한결같이 순하게 지키는 태도가 안정과 신뢰를 줍니다.","caution":"상황이 변하는데도 같은 태도만 유지하면 결단이 필요한 때를 놓칠 수 있습니다.","advice":"지금의 자리에서 요구되는 역할이 지키는 것인지 이끄는 것인지 구분해 보세요. 한결같음과 필요한 결단을 함께 가져가면 좋습니다.","message":"한결같음에 때맞는 판단을 더하세요."},{"guaN":32,"guaName":"뇌풍항","pos":6,"label":"上六","yinyang":"yin","text":"振恒 凶","reading":"진항 흉","modern":"항상함을 흔들어 놓으니 흉합니다.","meaning":"마지막 자리에서 위로 올라 가만히 있지 못하고 계속 움직이며 흔드는 장면입니다. 오래 이어져야 할 것을 쉬지 않고 흔들면 안정이 깨지고 지치게 됩니다.","positive":"움직임이 많다는 것은 에너지가 충분하다는 뜻이기도 합니다.","caution":"끊임없이 새 것을 추구하며 흔들면 쌓은 것이 무너지고 지치기 쉽습니다.","advice":"변화를 주려 할 때 지켜야 할 것과 바꿀 것을 구분해 보세요. 가만히 두어야 자라는 것도 있으니 잠시 쉬어 보는 것도 좋습니다.","message":"흔들기보다 가만히 지켜보세요."}],"yong":null},"33":{"n":33,"name":"천산둔","han":"天山遯","upper":"건","lower":"간","upperHan":"乾","lowerHan":"艮","bits":[0,0,1,1,1,1],"binary":"001111","gua":{"text":"亨 小利貞","reading":"형 소리정","modern":"형통합니다. 작은 일에서는 곧고 바르게 하는 것이 이롭습니다.","symbol":"위에는 하늘(乾), 아래에는 산(艮)이 있어, 하늘 아래 산이 우뚝 서 있지만 하늘은 그 위로 멀어져 가는 모습입니다. 물러나 몸을 피하는 것, 곧 때에 맞게 물러서는 지혜를 뜻합니다.","situation":"상황이 불리하게 흘러가거나 내 힘이 한계에 이르러, 맞서기보다 한 걸음 물러나는 편이 나은 국면입니다. 도망이 아니라 힘을 아끼고 다음을 준비하기 위한 후퇴입니다. 다만 물러나는 때를 놓치면 부담이 커지기 쉽습니다.","positive":"무리하게 부딪치지 않고 물러남으로써 손실을 줄이고 기회를 다시 볼 여유를 얻을 수 있습니다.","caution":"미련이나 체면 때문에 물러날 때를 놓치면 소모가 커지기 쉽고, 지나치게 도망치듯 떠나면 관계가 상할 수 있습니다.","direction":"물러날 일과 지킬 일을 구분하고, 정리할 것은 차분히 정리하세요. 큰 것은 못 바꿔도 작은 영역에서 바르게 지키는 데 집중하는 편이 도움이 됩니다.","message":"물러남은 패배가 아니라 다음을 위한 선택입니다."},"yao":[{"guaN":33,"guaName":"천산둔","pos":1,"label":"初六","yinyang":"yin","text":"遯尾 厲 勿用有攸往","reading":"둔미 려 물용유유왕","modern":"물러나는 행렬의 꼬리에 있으니 위태롭습니다. 나아가 일을 벌이지 마십시오.","meaning":"물러나는 흐름에서 가장 뒤처진 자리입니다. 시작 단계에서 이미 때를 놓쳐 위험이 가까이 있는 상황입니다.","positive":"무리하지 않고 가만히 있으면 피해를 키우지 않을 수 있습니다.","caution":"뒤늦게 뭔가를 만회하려고 나서면 오히려 위태로워지기 쉽습니다.","advice":"새 일을 벌이기보다 지금 하던 것을 조용히 줄이고 안전을 먼저 살펴보세요.","message":"뒤늦은 때는 움직이지 않는 것이 낫습니다."},{"guaN":33,"guaName":"천산둔","pos":2,"label":"六二","yinyang":"yin","text":"執之用黃牛之革 莫之勝說","reading":"집지용황우지혁 막지승탈","modern":"누런 소의 가죽으로 단단히 붙들어 매니, 아무도 풀어낼 수 없습니다.","meaning":"중심을 잡은 자리에서 뜻을 굳게 지키는 모습입니다. 물러나는 상황 속에서도 사람이나 원칙과의 끈을 단단히 붙들고 있습니다.","positive":"믿을 만한 원칙과 관계를 굳게 지켜 흔들림이 적습니다.","caution":"너무 단단히 붙들면 융통성을 잃고 변화에 늦게 반응할 수 있습니다.","advice":"지킬 약속과 원칙을 분명히 하되, 상황이 바뀌면 방식은 조정할 여지를 남겨 두세요.","message":"굳은 마음이 중심을 지켜 줍니다."},{"guaN":33,"guaName":"천산둔","pos":3,"label":"九三","yinyang":"yang","text":"係遯 有疾厲 畜臣妾吉","reading":"계둔 유질려 축신첩길","modern":"얽매여 물러나니 병이 생기듯 위태롭습니다. 하인과 첩을 거두어 기르는 정도의 일에는 길합니다.","meaning":"미련과 인연에 발목이 잡혀 선뜻 물러나지 못하는 자리입니다. 큰 결단은 어렵지만 가까운 사람을 돌보는 일 정도는 무난합니다.","positive":"가까운 사람을 챙기고 일상을 돌보는 일은 안정적으로 해낼 수 있습니다.","caution":"미련 때문에 결정을 미루면 몸과 마음이 지치기 쉽고 큰일을 맡기엔 부담이 큽니다.","advice":"무엇이 나를 붙잡고 있는지 점검하고, 큰 도전은 미루고 작은 책임 위주로 정리하세요.","message":"붙잡는 것이 무엇인지 먼저 살펴보세요."},{"guaN":33,"guaName":"천산둔","pos":4,"label":"九四","yinyang":"yang","text":"好遯 君子吉 小人否","reading":"호둔 군자길 소인비","modern":"좋아하는 마음으로도 물러납니다. 군자는 길하고 소인은 그렇지 못합니다.","meaning":"마음에 아쉬움이 남지만 스스로 정해 깔끔히 물러나는 자리입니다. 의지가 강하면 잘 정리하지만 미련에 끌려가면 어려워집니다.","positive":"좋아하는 것을 내려놓고 단호히 정리하는 힘이 좋은 결과로 이어질 수 있습니다.","caution":"감정에 이끌려 마지못해 물러나면 정리가 흐지부지되고 미련만 남기 쉽습니다.","advice":"아쉬움은 인정하되 기준을 정해 놓고 물러나세요. 정리한 뒤의 계획까지 함께 세워 두면 도움이 됩니다.","message":"아쉬워도 스스로 정해 물러나세요."},{"guaN":33,"guaName":"천산둔","pos":5,"label":"九五","yinyang":"yang","text":"嘉遯 貞吉","reading":"가둔 정길","modern":"아름답게 물러납니다. 바르게 하면 길합니다.","meaning":"가장 중심 자리에서 때와 도리에 맞게 아름답게 물러나는 모습입니다. 주변과 마찰 없이 마무리하는 성숙함이 돋보입니다.","positive":"시기와 명분이 맞아 서로 부담 없이 물러나고 좋은 인상을 남길 수 있습니다.","caution":"겉으로만 아름다운 퇴장에 그치지 않도록 속마음과 실제 정리 상태를 확인할 필요가 있습니다.","advice":"인수인계와 감사 인사 등 마무리를 바르게 챙기세요. 물러나는 이유를 투명하게 나누는 편이 좋습니다.","message":"때에 맞는 물러남이 품격을 남깁니다."},{"guaN":33,"guaName":"천산둔","pos":6,"label":"上九","yinyang":"yang","text":"肥遯 无不利","reading":"비둔 무불리","modern":"넉넉하게 물러납니다. 이롭지 않은 것이 없습니다.","meaning":"이미 끝자리에서 아무 걸림 없이 여유롭게 물러나는 모습입니다. 가장 홀가분한 퇴장으로, 마음의 여유가 있는 상태입니다.","positive":"미련과 의심 없이 물러나 자유롭고 마음이 편안해지기 쉽습니다.","caution":"너무 멀리 떠나 필요한 관계나 책임까지 놓지 않았는지 살펴볼 필요가 있습니다.","advice":"여유를 가지고 정리하되 지켜야 할 연락과 마무리 책임은 챙기세요. 쉬는 시간도 다음 준비에 쓰면 좋습니다.","message":"여유로운 물러남은 자유를 줍니다."}],"yong":null},"34":{"n":34,"name":"뇌천대장","han":"雷天大壯","upper":"진","lower":"건","upperHan":"震","lowerHan":"乾","bits":[1,1,1,1,0,0],"binary":"111100","gua":{"text":"利貞","reading":"이정","modern":"곧고 바르게 하는 것이 이롭습니다.","symbol":"위에는 우레(震), 아래에는 하늘(乾)이 있어, 하늘 위에서 천둥이 울리는 듯 강한 기운이 힘차게 오르는 모습입니다. 크고 강한 힘이 성한 상태를 뜻합니다.","situation":"힘과 기세가 크게 오른 국면으로 밀어붙이고 싶은 마음이 커지기 쉽습니다. 다만 힘이 강할수록 바르게 쓰는 것이 중요하고, 힘만 앞세우면 반발이나 실수가 생기기 쉽습니다.","positive":"추진력과 자원이 충분해 오래 미뤄 온 일을 힘 있게 진행하기 좋은 때입니다.","caution":"자신의 힘을 과신해 주변을 압박하거나 무리하게 나서면 부딪힘과 손실이 생기기 쉽습니다.","direction":"힘을 쓰되 명분과 절제를 함께 갖추세요. 속도를 낼 부분과 힘을 아낄 부분을 구분하면 오래 가는 성과로 이어집니다.","message":"강할 때일수록 바름이 힘을 지켜 줍니다."},"yao":[{"guaN":34,"guaName":"뇌천대장","pos":1,"label":"初九","yinyang":"yang","text":"壯于趾 征凶 有孚","reading":"장우지 정흉 유부","modern":"발가락에만 힘이 올라 있습니다. 나아가면 흉하며, 믿음이 있어도 그렇습니다.","meaning":"기운은 넘치지만 아직 준비가 덜 된 시작 단계입니다. 발끝에만 힘이 들어간 것처럼 의욕이 앞서 있습니다.","positive":"의욕과 열정이 높아 시작할 동력은 충분합니다.","caution":"준비 없이 먼저 나서면 어려움이 따르기 쉽고 중간에 쉽게 꺾일 수 있습니다.","advice":"당장 나서기보다 기초와 계획을 점검하세요. 작은 시험부터 해 보는 편이 도움이 됩니다.","message":"의욕보다 준비를 먼저 갖추세요."},{"guaN":34,"guaName":"뇌천대장","pos":2,"label":"九二","yinyang":"yang","text":"貞吉","reading":"정길","modern":"곧고 바르게 하면 길합니다.","meaning":"아래 괘의 중심에서 힘이 알맞게 조절된 자리입니다. 강하지만 과하지 않게 중용을 지키는 모습입니다.","positive":"힘을 적절히 조절하여 안정적으로 신뢰를 쌓기 좋습니다.","caution":"편안함에 안주하면 정작 필요한 때에 힘을 쓰지 못할 수 있습니다.","advice":"지금의 균형 잡힌 방식을 유지하며 꾸준히 해 나가세요. 바른 기준을 지키는 편이 힘이 됩니다.","message":"알맞게 쓰는 힘이 오래 갑니다."},{"guaN":34,"guaName":"뇌천대장","pos":3,"label":"九三","yinyang":"yang","text":"小人用壯 君子用罔 貞厲 羝羊觸藩 羸其角","reading":"소인용장 군자용망 정려 저양촉번 리기각","modern":"소인은 힘을 쓰고 군자는 힘을 쓰지 않습니다. 고집하면 위태롭습니다. 숫양이 울타리를 들이받다 뿔이 걸리는 것과 같습니다.","meaning":"아래 괘의 끝에서 기세가 가장 거칠어지기 쉬운 자리입니다. 힘을 과시하다 스스로 곤경에 걸리기 쉽습니다.","positive":"과한 힘을 의식하고 조절한다면 위기를 일찍 알아차릴 수 있습니다.","caution":"힘으로 밀어붙이면 장애물에 걸려 오히려 움직이지 못하게 될 수 있습니다.","advice":"자존심을 내세우기보다 한 템포 쉬며 방법을 바꿔 보세요. 정면 돌파가 아닌 다른 길도 살펴보면 좋습니다.","message":"힘자랑은 스스로를 가두기 쉽습니다."},{"guaN":34,"guaName":"뇌천대장","pos":4,"label":"九四","yinyang":"yang","text":"貞吉 悔亡 藩決不羸 壯于大輿之輹","reading":"정길 회망 번결불리 장우대여지복","modern":"곧고 바르게 하면 길하고 후회가 사라집니다. 울타리가 트여 뿔이 걸리지 않고, 큰 수레의 바퀴통처럼 튼튼합니다.","meaning":"위 괘의 첫 자리에서 막혀 있던 길이 열리는 모습입니다. 힘이 있으면서도 부드러운 환경을 만나 앞으로 나아가기 쉽습니다.","positive":"장애가 풀리고 힘을 실을 기반이 단단해 전진하기 좋습니다.","caution":"길이 열렸다고 속도를 지나치게 올리면 다시 부딪힐 수 있습니다.","advice":"열린 길에서 바른 방향을 확인하며 속도를 조절하세요. 지원과 자원이 받쳐 주는지 함께 살피면 좋습니다.","message":"길이 열리면 방향을 먼저 확인하세요."},{"guaN":34,"guaName":"뇌천대장","pos":5,"label":"六五","yinyang":"yin","text":"喪羊于易 无悔","reading":"상양우이 무회","modern":"들판의 경계에서 양을 잃습니다. 후회가 없습니다.","meaning":"중심 자리에서 강한 기세를 부드럽게 내려놓는 모습입니다. 고집을 놓는 순간 오히려 평안이 찾아옵니다.","positive":"힘을 쓰려는 마음을 내려놓아 불필요한 충돌을 피할 수 있습니다.","caution":"너무 쉽게 놓아 버리면 소중한 것까지 잃을 수 있으니 무엇을 놓는지 확인이 필요합니다.","advice":"버려도 되는 고집과 지켜야 할 핵심을 구분하세요. 부드러운 태도로 협의하는 편이 도움이 됩니다.","message":"놓을 줄 아는 것도 힘입니다."},{"guaN":34,"guaName":"뇌천대장","pos":6,"label":"上六","yinyang":"yin","text":"羝羊觸藩 不能退 不能遂 无攸利 艱則吉","reading":"저양촉번 불능퇴 불능수 무유리 간즉길","modern":"숫양이 울타리를 들이받아 물러나지도 나아가지도 못합니다. 이로운 바가 없으나 어려움을 견디면 길합니다.","meaning":"기세가 극에 이르러 오도 가도 못하는 상태입니다. 무리하게 키운 힘이 오히려 족쇄가 된 모습입니다.","positive":"어려움을 받아들이고 천천히 풀어 가면 돌파구가 보일 수 있습니다.","caution":"밀어붙이기를 계속하면 소모만 커지고 상황이 더 꼬이기 쉽습니다.","advice":"멈추어 상황을 다시 보고, 어려움을 인정하며 하나씩 풀어 가세요. 도움을 청하는 것도 방법입니다.","message":"막힌 때는 힘보다 인내입니다."}],"yong":null},"35":{"n":35,"name":"화지진","han":"火地晉","upper":"리","lower":"곤","upperHan":"離","lowerHan":"坤","bits":[0,0,0,1,0,1],"binary":"000101","gua":{"text":"康侯用錫馬蕃庶 晝日三接","reading":"강후용석마번서 주일삼접","modern":"나라를 편안케 한 제후에게 말을 많이 내리고, 하루에 세 번 접견합니다.","symbol":"위에는 불(離)이 밝게 빛나고 아래에는 땅(坤)이 있어, 해가 땅 위로 떠오르는 모습입니다. 밝음이 나아가 인정받고 오르는 괘입니다.","situation":"노력이 눈에 띄고 인정받으며 위로 올라갈 기회가 열리는 국면입니다. 밝은 흐름을 타고 나아가기 좋지만, 드러나는 만큼 시선과 기대도 커지므로 태도를 가다듬는 것이 중요합니다.","positive":"실력과 성과가 주목받아 신뢰와 기회를 얻기 쉬운 때입니다.","caution":"인정받는 일에 들떠 욕심이 앞서거나 질투와 견제를 얕보면 흔들릴 수 있습니다.","direction":"밝은 흐름을 타고 성실히 나아가되 성과를 나누고 겸손을 지키세요. 결과를 서두르기보다 신뢰를 쌓는 데 힘쓰는 편이 도움이 됩니다.","message":"밝게 오를수록 겸손이 길을 지켜 줍니다."},"yao":[{"guaN":35,"guaName":"화지진","pos":1,"label":"初六","yinyang":"yin","text":"晉如摧如 貞吉 罔孚 裕 无咎","reading":"진여최여 정길 망부 유 무구","modern":"나아가려 하나 꺾입니다. 바르게 하면 길합니다. 믿음을 얻지 못해도 여유를 가지면 허물이 없습니다.","meaning":"막 나아가기 시작했지만 아직 알아주는 이가 없고 막히기 쉬운 자리입니다. 시작 단계의 좌절을 겪는 모습입니다.","positive":"초조해하지 않고 바르게 지키면 시간이 지나 인정받을 바탕이 됩니다.","caution":"인정받지 못한다고 조급해하면 흔들려 쉽게 포기하거나 잘못된 길로 갈 수 있습니다.","advice":"당장의 평가에 연연하지 말고 여유를 가지고 꾸준히 실력을 쌓으세요.","message":"인정은 늦어도 바르게 이어 가세요."},{"guaN":35,"guaName":"화지진","pos":2,"label":"六二","yinyang":"yin","text":"晉如愁如 貞吉 受茲介福于其王母","reading":"진여수여 정길 수자개복우기왕모","modern":"나아가려 하나 근심이 있습니다. 바르게 하면 길하여, 이 큰 복을 왕모에게서 받습니다.","meaning":"중심 자리지만 위에서 이끌어 줄 후원이 아직 닿지 않아 근심이 있는 때입니다. 꾸준히 바름을 지키면 따뜻한 지지를 받는 모습입니다.","positive":"바르게 지키는 태도가 윗사람이나 후원자의 호의로 이어지기 쉽습니다.","caution":"근심이 크면 주저하거나 도움을 청하는 시기를 놓칠 수 있습니다.","advice":"걱정을 혼자 안고 있기보다 신뢰할 만한 사람에게 상황을 알리고 조언을 구해 보세요.","message":"바른 걸음은 따뜻한 지지로 돌아옵니다."},{"guaN":35,"guaName":"화지진","pos":3,"label":"六三","yinyang":"yin","text":"衆允 悔亡","reading":"중윤 회망","modern":"여러 사람이 믿고 따릅니다. 후회가 사라집니다.","meaning":"아래 괘의 끝에서 위의 밝음으로 올라가려는 전환점입니다. 주변의 신뢰가 한목소리로 모여 앞길을 밀어 줍니다.","positive":"주변의 지지와 협력으로 망설임이 줄고 후회할 일도 풀립니다.","caution":"사람들의 지지에 기대어 책임을 흐리면 신뢰가 흔들릴 수 있습니다.","advice":"도움 준 사람들에게 감사를 표하고 함께 방향을 정하세요. 내가 맡을 몫을 분명히 하면 좋습니다.","message":"함께하는 믿음이 길을 열어 줍니다."},{"guaN":35,"guaName":"화지진","pos":4,"label":"九四","yinyang":"yang","text":"晉如鼫鼠 貞厲","reading":"진여석서 정려","modern":"나아가는 모습이 다람쥐 같습니다. 고집하면 위태롭습니다.","meaning":"위 괘의 첫 자리로 높은 자리에 가까워졌지만 자리에 맞지 않는 힘으로 불안하게 올라 있는 모습입니다. 챙기기만 하고 쓸 곳은 모르는 쥐에 빗댄 표현입니다.","positive":"자신의 부족함을 점검하면 자리에 맞는 실력을 갖출 기회가 됩니다.","caution":"욕심과 불안으로 자리를 지키려 하면 신뢰를 잃고 위태로워지기 쉽습니다.","advice":"가진 것을 움켜쥐기보다 나누고 책임을 다하는 쪽으로 방향을 바꿔 보세요.","message":"자리에 맞는 실력과 태도를 먼저 갖추세요."},{"guaN":35,"guaName":"화지진","pos":5,"label":"六五","yinyang":"yin","text":"悔亡 失得勿恤 往吉 无不利","reading":"회망 실득물휼 왕길 무불리","modern":"후회가 사라집니다. 잃고 얻음을 걱정하지 마십시오. 나아가면 길하고 이롭지 않은 것이 없습니다.","meaning":"밝음의 중심 자리로 여유 있게 이끄는 위치입니다. 작은 손익에 매이지 않고 큰 흐름을 보면 일이 풀리기 쉽습니다.","positive":"작은 득실에 흔들리지 않아 큰 흐름을 보며 일을 이끌기 좋습니다.","caution":"여유가 지나쳐 필요한 점검을 놓치면 허점이 생길 수 있습니다.","advice":"손익에 연연하기보다 목표와 방향을 보고 나아가세요. 필요한 곳에는 신뢰할 사람에게 권한을 나누는 것이 도움이 됩니다.","message":"작은 득실보다 큰 방향을 보세요."},{"guaN":35,"guaName":"화지진","pos":6,"label":"上九","yinyang":"yang","text":"晉其角 維用伐邑 厲吉 无咎 貞吝","reading":"진기각 유용벌읍 려길 무구 정린","modern":"뿔 끝까지 나아갑니다. 오직 자기 영지를 바로잡는 데 쓴다면 위태로우나 길하고 허물이 없습니다. 그러나 고집하면 아쉽습니다.","meaning":"가장 높은 끝자리로 더 나아갈 곳이 없는 상태입니다. 앞으로 나아가려는 힘이 자기 안을 정돈하는 데 쓰여야 하는 때입니다.","positive":"밖으로 확장하기보다 내부를 정리하는 데 힘을 쓰면 안정을 찾을 수 있습니다.","caution":"끝까지 밀어붙이는 태도는 주변과 마찰을 빚고 아쉬움을 남기기 쉽습니다.","advice":"외부 확장보다는 내 영역의 문제를 바로잡고 마무리하세요. 강경한 태도는 줄이는 편이 좋습니다.","message":"끝에 이르면 밖보다 안을 다스리세요."}],"yong":null},"36":{"n":36,"name":"지화명이","han":"地火明夷","upper":"곤","lower":"리","upperHan":"坤","lowerHan":"離","bits":[1,0,1,0,0,0],"binary":"101000","gua":{"text":"利艱貞","reading":"리간정","modern":"어려울 때 곧고 바르게 지키는 것이 이롭습니다.","symbol":"위에는 땅(坤), 아래에는 불(離)이 있어 밝은 해가 땅속으로 들어간 모습입니다. 밝음이 가려지고 상처받는 어두운 시기를 뜻합니다.","situation":"능력이나 뜻이 인정받지 못하고 어둡고 억눌린 환경에 놓인 국면입니다. 이럴 때 드러내고 맞서기보다 속으로 밝음을 지키며 때를 기다리는 지혜가 필요합니다.","positive":"속의 밝음을 지키며 조용히 내실을 다지는 힘을 기를 수 있는 때입니다.","caution":"어려움에 맞서 정면충돌하거나 반대로 마음의 밝음마저 잃으면 상처가 깊어질 수 있습니다.","direction":"겉으로는 낮추고 속으로는 원칙을 지키세요. 중요한 판단은 신중히 하고, 믿을 수 있는 사람과 의지하며 버티는 편이 도움이 됩니다.","message":"어둠 속에서도 안의 빛을 지키세요."},"yao":[{"guaN":36,"guaName":"지화명이","pos":1,"label":"初九","yinyang":"yang","text":"明夷于飛 垂其翼 君子于行 三日不食 有攸往 主人有言","reading":"명이우비 수기익 군자우행 삼일불식 유유왕 주인유언","modern":"밝음이 상하여 날아가는데 날개를 늘어뜨립니다. 군자가 길을 나서 사흘을 먹지 못하며, 가는 곳의 주인이 말을 합니다.","meaning":"어둠이 막 시작될 때 일찍 위험을 알아채고 조용히 떠나는 모습입니다. 대가가 따르지만 몸을 지키는 선택입니다.","positive":"위험의 조짐을 일찍 알아차리고 피하는 판단력이 있습니다.","caution":"떠나는 과정에서 곤란이 따르고 주변의 말이 있을 수 있습니다.","advice":"상황이 나빠지기 전에 거리를 두고 필요한 최소한의 준비를 하세요. 주변 말에 흔들리지 않는 편이 좋습니다.","message":"조짐을 일찍 알아차려 몸을 지키세요."},{"guaN":36,"guaName":"지화명이","pos":2,"label":"六二","yinyang":"yin","text":"明夷 夷于左股 用拯馬壯 吉","reading":"명이 이우좌고 용증마장 길","modern":"밝음이 상하여 왼쪽 다리를 다쳤습니다. 건장한 말로 구제하니 길합니다.","meaning":"어두운 상황에서 다치지만 중심을 잡고 온건히 대처하는 자리입니다. 부상은 있지만 치명적이지 않아 방법을 찾을 수 있습니다.","positive":"피해가 크지 않을 때 빠르게 수습하면 회복하기 좋습니다.","caution":"작은 상처를 방치하면 이동과 대응에 지장을 줄 수 있습니다.","advice":"문제를 알아차렸다면 도움이 될 자원과 사람을 서둘러 확보하세요. 무리하지 않고 회복에 집중하는 것이 좋습니다.","message":"작은 상처는 빨리 돌보세요."},{"guaN":36,"guaName":"지화명이","pos":3,"label":"九三","yinyang":"yang","text":"明夷于南狩 得其大首 不可疾貞","reading":"명이우남수 득기대수 불가질정","modern":"밝음이 상한 때에 남쪽으로 사냥을 가서 우두머리를 잡습니다. 서둘러 바로잡으려 해서는 안 됩니다.","meaning":"아래 괘의 끝에서 어둠의 원인을 마주하고 해결할 기회를 얻는 때입니다. 그러나 오래된 문제는 급히 고치려 하면 탈이 납니다.","positive":"문제의 핵심에 접근할 힘과 기회가 있습니다.","caution":"한꺼번에 바로잡으려 서두르면 반발이 생기고 오히려 어긋날 수 있습니다.","advice":"문제의 핵심을 파악하되 단계를 나누어 차근차근 접근하세요. 시간을 두고 신뢰를 쌓는 편이 도움이 됩니다.","message":"큰 문제는 서두르지 말고 단계로 푸세요."},{"guaN":36,"guaName":"지화명이","pos":4,"label":"六四","yinyang":"yin","text":"入于左腹 獲明夷之心 于出門庭","reading":"입우좌복 획명이지심 우출문정","modern":"왼쪽 배로 들어가 밝음이 상한 마음을 알아냅니다. 그리하여 문밖 뜰을 나섭니다.","meaning":"어둠의 중심부 가까이서 내부의 사정을 알게 되고 떠날 때를 짐작하는 자리입니다. 상황의 본질을 이해한 만큼 거리를 둘 수 있습니다.","positive":"내부 사정을 이해하여 대응과 탈출의 방향을 판단할 수 있습니다.","caution":"알게 된 사실을 함부로 드러내면 위험해질 수 있습니다.","advice":"알게 된 정보는 신중하게 다루고, 떠날 시기와 방식을 미리 구상해 두세요.","message":"알았다면 조용히 때를 보세요."},{"guaN":36,"guaName":"지화명이","pos":5,"label":"六五","yinyang":"yin","text":"箕子之明夷 利貞","reading":"기자지명이 리정","modern":"기자가 밝음을 감추었듯 합니다. 곧고 바르게 지키는 것이 이롭습니다.","meaning":"가장 가까이서 어둠을 마주하지만 겉으로는 어리석은 듯 숨기며 속의 밝음을 지키는 자리입니다. 은인자중하며 뜻을 지키는 모습입니다.","positive":"겉으로는 낮추고 속으로는 원칙을 굳게 지켜 위기에서 자신을 보존할 수 있습니다.","caution":"감추기만 하다 마음이 위축되거나 옳은 일마저 외면할 수 있습니다.","advice":"위험한 곳에서는 드러내지 않되 마음속 기준은 놓지 마세요. 가까운 사람과 조용히 뜻을 나누는 것도 도움이 됩니다.","message":"겉은 낮추고 속은 지키세요."},{"guaN":36,"guaName":"지화명이","pos":6,"label":"上六","yinyang":"yin","text":"不明晦 初登于天 後入于地","reading":"불명회 초등우천 후입우지","modern":"밝지 못하고 어둡습니다. 처음에는 하늘에 올랐다가 나중에는 땅속으로 들어갑니다.","meaning":"어둠이 극에 이른 끝자리로 높이 올랐던 것이 내려와 어두워진 모습입니다. 극한에 이르면 변화가 가까워진다는 신호이기도 합니다.","positive":"바닥을 확인하면 다시 올라갈 방향을 새로 정하기 쉽습니다.","caution":"과거의 영광이나 자존심에 매이면 하락이 더 길어질 수 있습니다.","advice":"지금의 어둠이 어디서 왔는지 돌아보고 인정하세요. 새롭게 시작할 작은 단계를 정하는 것이 도움이 됩니다.","message":"끝에 이르면 새 시작을 준비하세요."}],"yong":null},"37":{"n":37,"name":"풍화가인","han":"風火家人","upper":"손","lower":"리","upperHan":"巽","lowerHan":"離","bits":[1,0,1,0,1,1],"binary":"101011","gua":{"text":"利女貞","reading":"리녀정","modern":"여자가 곧고 바르게 하는 것이 이롭습니다.","symbol":"위에는 바람(巽), 아래에는 불(離)이 있어, 안에서 피어오른 불의 온기가 바람을 타고 밖으로 퍼지는 모습입니다. 집안을 바르게 이루는 질서를 뜻합니다.","situation":"가정이나 가까운 조직 안의 질서와 역할을 돌아보는 국면입니다. 밖의 일보다 안을 먼저 다져야 할 때이며, 각자의 자리에서 책임을 다하는 것이 안정의 바탕이 됩니다.","positive":"가까운 사람과 신뢰와 역할 분담이 잘 이루어지면 안정과 화목을 얻기 쉽습니다.","caution":"너무 엄격하거나 반대로 지나치게 느슨하면 갈등과 무너짐이 생기기 쉽습니다.","direction":"가까운 사람과의 대화와 약속, 역할을 정리하세요. 바깥일보다 안의 기반을 먼저 챙기는 편이 도움이 됩니다.","message":"가까운 곳의 질서가 모든 일의 바탕입니다."},"yao":[{"guaN":37,"guaName":"풍화가인","pos":1,"label":"初九","yinyang":"yang","text":"閑有家 悔亡","reading":"한유가 회망","modern":"집안에 처음부터 울타리를 둡니다. 후회가 사라집니다.","meaning":"가정이나 모임이 시작되는 때 미리 규칙과 경계를 세우는 자리입니다. 처음에 기준을 세우면 뒤의 후회가 줄어듭니다.","positive":"초기에 기준을 분명히 하여 이후의 혼란을 줄일 수 있습니다.","caution":"규칙을 일방적으로 정하면 반발이 생기고 후회가 남을 수 있습니다.","advice":"함께하는 사람들과 기본 규칙과 역할을 미리 나누어 정하세요. 작은 약속부터 지키는 습관이 중요합니다.","message":"시작할 때 기준을 세우세요."},{"guaN":37,"guaName":"풍화가인","pos":2,"label":"六二","yinyang":"yin","text":"无攸遂 在中饋 貞吉","reading":"무유수 재중궤 정길","modern":"제멋대로 이루려 하지 않고 집안에서 음식 준비를 맡습니다. 바르게 하면 길합니다.","meaning":"가운데 자리에서 자신의 자리를 지키며 집안의 일상을 돌보는 모습입니다. 눈에 띄는 큰일보다 꾸준히 안을 챙기는 역할이 중요합니다.","positive":"일상과 기본을 성실히 돌보면 모두에게 안정감을 줍니다.","caution":"자신의 몫에만 갇혀 의견을 내지 못하면 답답함이 쌓일 수 있습니다.","advice":"돌봄이나 일상의 일을 가볍게 여기지 말고 필요한 부분은 편하게 말하세요. 서로의 수고를 알아주는 말이 도움이 됩니다.","message":"일상을 돌보는 일이 중심입니다."},{"guaN":37,"guaName":"풍화가인","pos":3,"label":"九三","yinyang":"yang","text":"家人嗃嗃 悔厲吉 婦子嘻嘻 終吝","reading":"가인학학 회려길 부자희희 종린","modern":"집안사람을 엄하게 다스립니다. 후회와 위태로움이 있으나 길합니다. 부인과 아이가 희희낙락하면 끝내 아쉽습니다.","meaning":"아래 괘의 끝에서 지나친 엄격함과 지나친 느슨함 사이에서 균형을 찾아야 하는 자리입니다. 엄격함은 힘들어도 풀어짐보다는 낫지만 한쪽에 치우치면 곤란합니다.","positive":"기준을 분명히 세우면 큰 혼란을 막는 데 도움이 됩니다.","caution":"지나친 엄격함은 갈등을, 지나친 방임은 기강이 풀어지는 문제를 부를 수 있습니다.","advice":"기준은 단단히 하되 대화와 배려를 곁들이세요. 한쪽으로 치우쳤다면 중간으로 조금씩 조절해 보세요.","message":"엄함과 느슨함의 균형을 찾으세요."},{"guaN":37,"guaName":"풍화가인","pos":4,"label":"六四","yinyang":"yin","text":"富家 大吉","reading":"부가 대길","modern":"집안을 풍요롭게 합니다. 크게 길합니다.","meaning":"위 괘의 첫 자리에서 부드럽게 살림과 자원을 불리는 모습입니다. 자리와 성품이 잘 맞아 안정과 풍요를 이룹니다.","positive":"자원을 알뜰하게 모으고 관리하여 안정과 여유를 얻기 쉽습니다.","caution":"재물과 이익에만 신경 쓰면 가까운 사람과의 마음이 멀어질 수 있습니다.","advice":"수입과 지출, 역할 분담을 정리해 두세요. 모은 것의 일부는 가까운 사람과 나누는 편이 좋습니다.","message":"알뜰히 챙겨 안을 풍요롭게 하세요."},{"guaN":37,"guaName":"풍화가인","pos":5,"label":"九五","yinyang":"yang","text":"王假有家 勿恤 吉","reading":"왕격유가 물휼 길","modern":"왕이 집안에 이르러 자애롭게 합니다. 걱정하지 마십시오. 길합니다.","meaning":"가장 중심 자리에서 위엄과 사랑으로 집안을 이끄는 모습입니다. 주변이 믿고 따르며 서로 아끼는 분위기가 만들어집니다.","positive":"중심에 선 사람이 솔선하고 아끼면 신뢰와 화목이 자연스레 퍼집니다.","caution":"자리에 취해 가까운 이의 이야기를 듣지 않으면 균형이 흔들릴 수 있습니다.","advice":"가까운 사람의 이야기를 먼저 듣고 따뜻한 마음을 표현하세요. 책임을 나누면 부담이 줄어듭니다.","message":"사랑과 위엄을 함께 갖추세요."},{"guaN":37,"guaName":"풍화가인","pos":6,"label":"上九","yinyang":"yang","text":"有孚威如 終吉","reading":"유부위여 종길","modern":"믿음과 위엄이 있습니다. 끝내 길합니다.","meaning":"집안일의 끝자리에서 쌓은 신뢰와 몸가짐이 위엄이 되는 모습입니다. 오래 이어 온 바른 태도가 마무리를 안정시킵니다.","positive":"진실한 태도로 쌓은 신뢰가 오랜 시간 안정을 만듭니다.","caution":"위엄만 앞세우면 거리감이 생기고 따뜻함이 사라질 수 있습니다.","advice":"진심을 바탕으로 한 일관된 태도를 유지하세요. 엄격함과 따뜻함의 균형을 잊지 않는 것이 좋습니다.","message":"믿음이 위엄을 만듭니다."}],"yong":null},"38":{"n":38,"name":"화택규","han":"火澤睽","upper":"리","lower":"태","upperHan":"離","lowerHan":"兌","bits":[1,1,0,1,0,1],"binary":"110101","gua":{"text":"小事吉","reading":"소사길","modern":"작은 일에는 길합니다.","symbol":"위에는 불(離)이 위로 타오르고, 아래에는 못(兌)이 아래로 스며들어, 서로 반대 방향으로 갈라서는 모습입니다. 어긋나고 등지는 상황을 뜻합니다.","situation":"뜻이 맞지 않고 서로 어긋나기 쉬운 국면입니다. 큰 계획을 함께 추진하기는 어렵지만, 차이를 인정하고 작은 일부터 조율하면 풀릴 여지가 있습니다.","positive":"차이를 인정하면 서로의 장점을 보완하는 새로운 관점을 얻을 수 있습니다.","caution":"의견 차이를 감정으로 번지게 하거나 큰일을 서둘러 합의하려 하면 틈이 더 벌어지기 쉽습니다.","direction":"큰 합의보다 작은 일부터 맞춰 보세요. 오해를 풀고 공통점을 찾는 대화에 시간을 들이는 편이 도움이 됩니다.","message":"다름을 인정하는 데서 조율이 시작됩니다."},"yao":[{"guaN":38,"guaName":"화택규","pos":1,"label":"初九","yinyang":"yang","text":"悔亡 喪馬勿逐 自復 見惡人 无咎","reading":"회망 상마물축 자복 견악인 무구","modern":"후회가 사라집니다. 말을 잃어도 쫓지 마십시오. 저절로 돌아옵니다. 나쁜 사람을 만나도 허물이 없습니다.","meaning":"어긋남이 시작되는 때에 억지로 붙잡지 않고 기다리는 자리입니다. 떠나는 것을 쫓지 않아도 때가 되면 돌아오기도 합니다.","positive":"집착을 내려놓으면 오히려 관계가 회복될 여지가 생깁니다.","caution":"불편한 사람을 피하기만 하면 오해를 풀 기회를 잃을 수 있습니다.","advice":"떠난 것을 붙잡으려 하지 말고 거리를 두고 지켜보세요. 불편한 상대와도 예의를 지키며 대화를 이어 가면 좋습니다.","message":"붙잡지 않아도 돌아올 것은 돌아옵니다."},{"guaN":38,"guaName":"화택규","pos":2,"label":"九二","yinyang":"yang","text":"遇主于巷 无咎","reading":"우주우항 무구","modern":"주인을 골목에서 우연히 만납니다. 허물이 없습니다.","meaning":"공식적인 자리가 아닌 골목에서 편하게 만나 오해를 푸는 모습입니다. 격식보다 자연스러운 만남이 길을 엽니다.","positive":"형식을 내려놓은 편안한 만남으로 서로의 마음을 열 수 있습니다.","caution":"자리가 편하다고 본론을 흐리면 오해가 풀리지 않을 수 있습니다.","advice":"공식 자리 대신 가벼운 식사나 산책처럼 부담 없는 자리를 만들어 보세요. 핵심 이야기는 분명히 전하는 것이 좋습니다.","message":"가까운 만남이 틈을 메웁니다."},{"guaN":38,"guaName":"화택규","pos":3,"label":"六三","yinyang":"yin","text":"見輿曳 其牛掣 其人天且劓 无初有終","reading":"견여예 기우체 기인천차의 무초유종","modern":"수레가 끌리고 소가 가로막히며, 사람은 머리를 깎이고 코를 베이는 일을 당합니다. 처음은 없으나 끝은 있습니다.","meaning":"아래 괘의 끝에서 앞뒤가 막혀 크게 고생하는 모습입니다. 처음에는 오해와 시련이 있지만 끝까지 가면 풀릴 수 있다는 뜻입니다.","positive":"고난 속에서도 꾸준히 이어 가면 결국 마무리를 할 수 있습니다.","caution":"처음의 막힘 때문에 쉽게 의심하고 포기하면 풀릴 길을 놓칠 수 있습니다.","advice":"중간에 고비가 와도 목표를 다시 확인하며 천천히 가세요. 상황이 풀릴 때까지 끈기를 유지하는 것이 도움이 됩니다.","message":"처음은 어려워도 끝을 보세요."},{"guaN":38,"guaName":"화택규","pos":4,"label":"九四","yinyang":"yang","text":"睽孤 遇元夫 交孚 厲无咎","reading":"규고 우원부 교부 려무구","modern":"어긋나 외롭지만 으뜸가는 사람을 만나 서로 믿음을 나눕니다. 위태로우나 허물이 없습니다.","meaning":"위 괘의 첫 자리에서 고립감을 느끼다가 뜻이 통하는 사람을 만나는 모습입니다. 믿을 만한 동반자를 만나면 위기를 넘기기 쉽습니다.","positive":"뜻이 통하는 사람을 만나 신뢰를 나누며 외로움을 덜 수 있습니다.","caution":"외로움에 빠져 기회를 놓치거나 의심을 거두지 못하면 관계가 멀어질 수 있습니다.","advice":"외로울 때 먼저 신뢰할 만한 사람에게 마음을 열어 보세요. 서로 진심으로 대하는 것이 중요합니다.","message":"진심이 통하는 한 사람이 큰 힘이 됩니다."},{"guaN":38,"guaName":"화택규","pos":5,"label":"六五","yinyang":"yin","text":"悔亡 厥宗噬膚 往何咎","reading":"회망 궐종서부 왕하구","modern":"후회가 사라집니다. 그 일가가 부드러운 살을 씹듯 쉽게 어울립니다. 나아가면 무슨 허물이 있겠습니까.","meaning":"중심 자리에서 가까운 사람의 도움으로 막혔던 마음이 풀리는 모습입니다. 부드럽게 다가가면 쉽게 뜻이 통합니다.","positive":"가까운 사람과 쉽게 통하여 이전의 후회가 풀리기 쉽습니다.","caution":"너무 쉽게 풀렸다고 방심하면 다시 어긋날 수 있습니다.","advice":"도움을 주는 사람에게 감사를 전하고 다시 오해가 쌓이지 않게 자주 소통하세요.","message":"풀린 뒤에도 소통을 이어 가세요."},{"guaN":38,"guaName":"화택규","pos":6,"label":"上九","yinyang":"yang","text":"睽孤 見豕負塗 載鬼一車 先張之弧 後說之弧 匪寇婚媾 往遇雨則吉","reading":"규고 견시부도 재귀일거 선장지호 후탈지호 비구혼구 왕우우즉길","modern":"어긋나 외롭습니다. 돼지가 진흙을 뒤집어쓴 것과 귀신이 수레 하나 가득 실린 것을 봅니다. 먼저 활을 당겼다가 나중에 놓으니, 도적이 아니라 혼인할 짝입니다. 가다가 비를 만나면 길합니다.","meaning":"어긋남의 끝자리에서 의심이 커져 헛것까지 보이는 모습입니다. 의심을 풀고 보니 적이 아니라 오히려 가까워질 상대였다는 뜻입니다.","positive":"의심을 거두고 상대를 다시 보면 오해가 풀려 화해할 길이 열립니다.","caution":"의심이 지나치면 상대를 적으로 단정하고 관계를 해칠 수 있습니다.","advice":"의심이 들 때는 확인할 수 있는 사실부터 살펴보고 직접 대화로 풀어 보세요. 경계를 내려놓는 용기가 도움이 됩니다.","message":"의심을 풀면 적이 벗이 됩니다."}],"yong":null},"39":{"n":39,"name":"수산건","han":"水山蹇","upper":"감","lower":"간","upperHan":"坎","lowerHan":"艮","bits":[0,0,1,0,1,0],"binary":"001010","gua":{"text":"利西南 不利東北 利見大人 貞吉","reading":"리서남 불리동북 리견대인 정길","modern":"서남쪽은 이롭고 동북쪽은 이롭지 않습니다. 덕 있는 사람을 만나는 것이 이롭고, 바르게 지키면 길합니다.","symbol":"위에는 물(감), 아래에는 산(간)이 있습니다. 산 앞을 물이 가로막아 걸음을 멈추고 절뚝이게 되는 모습으로, 앞길이 험해 나아가기 어려운 상황을 나타냅니다.","situation":"일이 뜻대로 풀리지 않고 앞이 막힌 듯한 국면입니다. 힘으로 밀어붙이면 더 지치기 쉬워서, 평탄한 쪽으로 방향을 돌리고 도와줄 사람을 찾는 편이 도움이 됩니다. 어려움 속에서 자신을 돌아볼 시간이 되기도 합니다.","positive":"막힌 때에 속도를 늦추고 원인을 점검하면 오히려 단단해질 수 있습니다. 믿을 만한 조언자와 동료가 큰 힘이 됩니다.","caution":"험한 쪽으로 무리하게 나아가거나 막힌 이유를 남 탓으로만 돌리면 상황이 더 꼬이기 쉽습니다.","direction":"험한 길은 돌아가고, 평탄한 방향을 찾아 움직이세요. 혼자 버티기보다 경험 있는 사람에게 도움을 청하고, 바른 태도를 꾸준히 지키는 것이 좋습니다.","message":"막혔을 때는 멈추어 돌아보고 도움을 구하세요."},"yao":[{"guaN":39,"guaName":"수산건","pos":1,"label":"初六","yinyang":"yin","text":"往蹇 來譽","reading":"왕건 래예","modern":"나아가면 어렵고, 물러나 돌아오면 칭찬을 받습니다.","meaning":"막 시작하는 자리에서 앞에는 험한 길이 놓여 있습니다. 서두르기보다 잠시 멈추어 준비하는 것이 지혜로운 때입니다.","positive":"물러나 준비하는 태도가 주변의 신뢰와 좋은 평가로 이어질 수 있습니다.","caution":"아직 힘이 약한데 서둘러 나서면 어려움만 크게 느끼기 쉽습니다.","advice":"지금은 앞서 나가기보다 정보를 모으고 기초를 다지세요. 물러서는 것이 약함이 아니라 준비임을 기억하는 편이 좋습니다.","message":"서두르지 말고 준비하며 기다리세요."},{"guaN":39,"guaName":"수산건","pos":2,"label":"六二","yinyang":"yin","text":"王臣蹇蹇 匪躬之故","reading":"왕신건건 비궁지고","modern":"왕의 신하가 어렵고 또 어려운 길을 가는 것은 자기 자신 때문이 아닙니다.","meaning":"아래 괘의 중심에서 맡은 책임을 지고 험한 길을 헤쳐 가는 모습입니다. 어려움이 계속되어도 자신의 이익이 아니라 맡은 일이나 윗사람을 위해 애쓰는 장면입니다.","positive":"사심 없이 애쓰는 모습이 신뢰와 존경을 얻는 바탕이 됩니다.","caution":"혼자 모든 짐을 지려 하면 지치기 쉬우니 한계를 살피세요.","advice":"힘들더라도 공동의 목표를 기준으로 판단하세요. 지칠 때는 역할을 나누고 도움을 청하는 것이 오래 가는 방법입니다.","message":"나를 위해서가 아닌 맡은 일을 위해 걸으세요."},{"guaN":39,"guaName":"수산건","pos":3,"label":"九三","yinyang":"yang","text":"往蹇 來反","reading":"왕건 래반","modern":"나아가면 어렵고, 돌아오면 반기는 이가 있습니다.","meaning":"아래 괘의 끝에서 앞의 험한 길과 마주한 전환점입니다. 계속 나아가기보다 돌아서서 가까운 사람들 곁으로 돌아오는 선택이 힘이 됩니다.","positive":"가까운 이들이 기쁘게 맞아 주며 안정과 지지를 얻을 수 있습니다.","caution":"의욕이 앞서 앞길의 험함을 가볍게 보면 힘을 소진하기 쉽습니다.","advice":"무리한 전진을 멈추고 가족, 동료 같은 기반을 먼저 챙기세요. 안정된 자리에서 다시 계획을 세우는 편이 도움이 됩니다.","message":"물러나 가까운 사람들과 힘을 모으세요."},{"guaN":39,"guaName":"수산건","pos":4,"label":"六四","yinyang":"yin","text":"往蹇 來連","reading":"왕건 래련","modern":"나아가면 어렵고, 돌아오면 함께 이어집니다.","meaning":"위 괘의 시작으로 윗자리에 가까워졌지만 아직 홀로 험한 길을 가기엔 힘이 부족합니다. 아래의 동료들과 손을 잡을 때 길이 열립니다.","positive":"주변 사람들과 연결되면 혼자서는 어렵던 일을 함께 풀어낼 수 있습니다.","caution":"혼자 해결하려 하면 한계에 부딪히기 쉽고 협력의 기회를 놓칠 수 있습니다.","advice":"함께할 사람들을 모아 역할을 나누세요. 앞으로 가기 전에 팀의 호흡을 맞추는 일에 시간을 쓰는 것이 좋습니다.","message":"혼자 가지 말고 이어져 함께 가세요."},{"guaN":39,"guaName":"수산건","pos":5,"label":"九五","yinyang":"yang","text":"大蹇 朋來","reading":"대건 붕래","modern":"크게 어려운 때에 벗이 찾아옵니다.","meaning":"위 괘의 중심이자 가장 큰 어려움을 마주한 자리입니다. 책임이 무거운 만큼 힘든 상황이지만, 뜻을 함께하는 벗이 모여드는 때이기도 합니다.","positive":"어려움이 클수록 뜻이 맞는 사람들의 도움이 드러나기 쉽습니다.","caution":"스스로 감당하려 고집하면 곁에 온 도움을 놓칠 수 있습니다.","advice":"중심을 잡고 바른 뜻을 분명히 밝히세요. 도와주려는 사람에게 구체적으로 부탁하고 함께 풀어 가는 편이 좋습니다.","message":"큰 어려움 속에서 벗의 손을 잡으세요."},{"guaN":39,"guaName":"수산건","pos":6,"label":"上六","yinyang":"yin","text":"往蹇 來碩 吉 利見大人","reading":"왕건 래석 길 리견대인","modern":"나아가면 어렵지만 돌아오면 큰 성과가 있고 길합니다. 덕 있는 사람을 만나는 것이 이롭습니다.","meaning":"어려움의 끝자리로, 더 가려 하기보다 돌아와 안을 충실히 하면 큰 열매를 얻는 때입니다. 지혜로운 사람의 안내가 길을 밝혀 줍니다.","positive":"그동안의 고생이 성숙과 큰 성과로 이어질 가능성이 있습니다.","caution":"끝났다고 느슨해지거나 다시 무리하게 바깥으로 나서면 얻은 것을 잃기 쉽습니다.","advice":"지금까지의 경험을 정리하고 조언해 줄 어른이나 멘토를 찾아보세요. 얻은 배움을 다음 단계의 토대로 삼는 것이 좋습니다.","message":"돌아와 배움을 쌓으면 큰 결실이 됩니다."}],"yong":null},"40":{"n":40,"name":"뇌수해","han":"雷水解","upper":"진","lower":"감","upperHan":"震","lowerHan":"坎","bits":[0,1,0,1,0,0],"binary":"010100","gua":{"text":"利西南 无所往 其來復吉 有攸往 夙吉","reading":"리서남 무소왕 기래복길 유유왕 숙길","modern":"서남쪽이 이롭습니다. 갈 곳이 없으면 돌아와 제자리를 회복하는 것이 길하고, 갈 곳이 있다면 서두르는 것이 길합니다.","symbol":"위에는 우레(진), 아래에는 물(감)이 있습니다. 우레와 비가 일어나 답답한 기운이 풀리듯, 얽히고 막힌 것이 풀려 나가는 모습입니다.","situation":"오래 막히고 얽혔던 문제가 풀릴 실마리가 보이는 국면입니다. 긴장이 풀리는 때일수록 처리할 일은 빨리 마무리하고, 남은 감정과 뒷정리를 챙겨야 다시 꼬이지 않습니다. 새로 할 일이 없다면 일상을 회복하는 것이 우선입니다.","positive":"답답하던 일이 풀리고 숨통이 트이는 때라 해결과 화해의 기회가 열려 있습니다.","caution":"풀렸다고 방심하거나 질질 끌면 같은 문제가 되풀이되기 쉽고, 정리를 미루면 감정의 앙금이 남을 수 있습니다.","direction":"해결할 수 있는 일은 서둘러 처리하고, 해결할 일이 없다면 평소의 자리로 돌아가 안정을 되찾으세요. 상대의 허물은 너그럽게 풀어 주되 재발 방지를 위한 간단한 정리는 해 두는 것이 좋습니다.","message":"풀릴 때는 미루지 말고 빠르게 매듭지으세요."},"yao":[{"guaN":40,"guaName":"뇌수해","pos":1,"label":"初六","yinyang":"yin","text":"无咎","reading":"무구","modern":"허물이 없습니다.","meaning":"막 어려움에서 벗어나기 시작하는 자리입니다. 약한 자리이지만 위의 강한 효와 호응하여 크게 힘쓰지 않아도 무난히 넘어갈 수 있는 때입니다.","positive":"큰 탈 없이 안정적으로 새 국면을 시작할 수 있습니다.","caution":"별일 없다고 해서 긴장을 완전히 놓으면 작은 문제를 놓치기 쉽습니다.","advice":"지금은 무리하게 움직이지 말고 한숨 돌리며 상황을 차분히 살피세요. 몸과 마음을 추스르는 것이 다음 걸음의 바탕이 됩니다.","message":"서두르지 말고 숨을 고르세요."},{"guaN":40,"guaName":"뇌수해","pos":2,"label":"九二","yinyang":"yang","text":"田獲三狐 得黃矢 貞吉","reading":"전획삼호 득황시 정길","modern":"사냥하여 여우 세 마리를 잡고 누런 화살을 얻으니, 바르게 지키면 길합니다.","meaning":"아래 괘의 중심에서 강한 힘으로 간사한 방해 요소를 가려내 없애는 장면입니다. 누런 화살은 곧고 중용을 지키는 태도를 비유한 것으로 볼 수 있습니다.","positive":"문제의 원인을 정확히 가려내 정리하면 상황이 크게 개선될 수 있습니다.","caution":"정의감이 지나쳐 사람을 공격하거나 수단이 거칠어지지 않도록 살펴야 합니다.","advice":"해묵은 문제의 원인을 하나씩 찾아 바르게 제거하세요. 공정함과 중심을 잃지 않는 것이 중요합니다.","message":"곧고 바르게 문제의 뿌리를 정리하세요."},{"guaN":40,"guaName":"뇌수해","pos":3,"label":"六三","yinyang":"yin","text":"負且乘 致寇至 貞吝","reading":"부차승 치구지 정린","modern":"짐을 지고서 수레를 타니 도둑을 불러들입니다. 그대로 고집하면 아쉬운 일이 생깁니다.","meaning":"아래 괘의 끝에서 자신의 분수에 맞지 않는 자리나 몫을 누리려 하는 모습입니다. 풀린 때를 틈타 과한 욕심을 내면 비난과 손해를 부르기 쉽습니다.","positive":"스스로를 돌아보고 분수에 맞게 고치면 문제를 줄일 수 있습니다.","caution":"능력이나 자격보다 과한 자리를 차지하려 하면 구설과 시비를 부르기 쉽습니다.","advice":"지금 내가 누리는 것이 내 힘과 노력에 맞는지 점검하세요. 욕심을 덜고 겸손하게 자세를 낮추는 편이 도움이 됩니다.","message":"분수에 맞게 처신하세요."},{"guaN":40,"guaName":"뇌수해","pos":4,"label":"九四","yinyang":"yang","text":"解而拇 朋至斯孚","reading":"해이무 붕지사부","modern":"엄지발가락을 풀어 놓으면 벗이 와서 믿음으로 함께합니다.","meaning":"위 괘의 시작에서 가까이 있는 하찮고 거추장스러운 인연이나 습관을 정리해야 하는 자리입니다. 그것을 풀어 놓아야 참된 동지와 신뢰가 이어집니다.","positive":"불필요한 관계를 정리하면 진짜 뜻이 맞는 사람과 만날 가능성이 커집니다.","caution":"미련 때문에 잘못된 관계나 습관에 매여 있으면 좋은 인연이 들어오기 어렵습니다.","advice":"발목을 잡는 사소한 인연이나 습관이 있는지 살펴보고 정리하세요. 믿을 만한 사람과의 관계에 마음을 쓰는 편이 좋습니다.","message":"묶인 것을 풀면 참된 벗이 옵니다."},{"guaN":40,"guaName":"뇌수해","pos":5,"label":"六五","yinyang":"yin","text":"君子維有解 吉 有孚于小人","reading":"군자유유해 길 유부우소인","modern":"군자가 풀어낼 수 있으면 길하고, 소인에게도 믿음이 드러납니다.","meaning":"위 괘의 중심으로 얽힌 문제를 풀어내는 핵심 자리입니다. 지도자가 스스로 풀어내는 모습을 보이면, 반대편에 있던 사람들도 그 진심을 알아보고 물러나게 됩니다.","positive":"솔직하고 단호하게 매듭을 풀면 갈등하던 사람들과도 신뢰를 회복할 수 있습니다.","caution":"속마음을 감추거나 애매하게 넘기면 믿음이 쌓이지 않고 갈등이 남을 수 있습니다.","advice":"책임 있는 자리에서 먼저 매듭을 풀겠다는 태도를 보이세요. 상대의 결과보다 진심이 전해지는 방식을 선택하는 것이 좋습니다.","message":"먼저 진심으로 풀면 믿음이 돌아옵니다."},{"guaN":40,"guaName":"뇌수해","pos":6,"label":"上六","yinyang":"yin","text":"公用射隼于高墉之上 獲之 无不利","reading":"공용석준우고용지상 획지 무불리","modern":"공이 높은 담 위의 매를 쏘아 잡으니 이롭지 않은 것이 없습니다.","meaning":"풀림의 마지막 자리로, 높은 곳에 버티고 있는 근본 장애를 때를 보아 해소하는 장면입니다. 충분히 준비가 되었을 때 움직이면 마무리가 깔끔해질 수 있습니다.","positive":"오래 남은 근본 문제를 정리하면 이후의 흐름이 매우 편안해질 가능성이 큽니다.","caution":"준비 없이 서둘러 나서면 놓칠 수 있으니 시기와 방법을 살펴야 합니다.","advice":"마지막까지 남은 핵심 장애를 침착하게 겨냥하세요. 해결한 뒤에는 다시 같은 일이 생기지 않도록 원칙을 정해 두는 편이 좋습니다.","message":"때를 살펴 근본 장애를 해소하세요."}],"yong":null},"41":{"n":41,"name":"산택손","han":"山澤損","upper":"간","lower":"태","upperHan":"艮","lowerHan":"兌","bits":[1,1,0,0,0,1],"binary":"110001","gua":{"text":"有孚 元吉 无咎 可貞 利有攸往 曷之用 二簋可用享","reading":"유부 원길 무구 가정 리유유왕 갈지용 이궤가용향","modern":"진실한 믿음이 있으면 크게 좋고 허물이 없으며, 바르게 지켜 나갈 수 있고 나아가는 일에 이롭습니다. 무엇을 쓸까요? 두 그릇의 소박한 제물로도 제사를 올릴 수 있습니다.","symbol":"위의 산(간)이 아래의 연못(태)을 내려다보는 모습으로, 아래의 것을 덜어 위를 보탠다는 뜻입니다. 줄이고 덜어내는 일이 어떻게 오히려 이로움이 되는지를 말하는 괘입니다.","situation":"지출, 일정, 감정, 관계에서 넘치는 부분을 줄여야 하는 국면입니다. 덜어내는 것이 손해처럼 느껴지기 쉽지만, 진심만 남는다면 소박해도 충분하다고 이 괘는 말합니다. 무엇을 덜고 무엇을 지킬지 가려내는 것이 핵심입니다.","positive":"군더더기를 정리하면 정말 중요한 것이 또렷해지고, 적은 것으로도 정성과 신뢰를 보여 줄 수 있는 때입니다.","caution":"덜어냄이 지나치면 정작 필요한 것까지 잃을 수 있고, 형식만 줄이고 마음까지 식으면 의미가 없어집니다.","direction":"먼저 줄여도 삶에 큰 지장이 없는 것부터 정리해 보세요. 그렇게 생긴 여유를 사람과 일의 본질에 돌리는 방향으로 선택하면 도움이 됩니다.","message":"덜어낸 자리에 진심을 남기세요."},"yao":[{"guaN":41,"guaName":"산택손","pos":1,"label":"初九","yinyang":"yang","text":"已事遄往 无咎 酌損之","reading":"이사천왕 무구 작손지","modern":"하던 일을 마치고 서둘러 달려가면 허물이 없습니다. 덜어 주되 정도를 헤아려 덜어야 합니다.","meaning":"막 시작하는 자리에서 윗사람이나 이웃을 돕는 일에 기꺼이 나서는 장면입니다. 다만 내 몫을 얼마나 덜어 줄지는 형편을 헤아려 조절해야 합니다.","positive":"자기 일을 마무리한 뒤 곧바로 도우러 가는 신속함이 좋은 인상을 줍니다.","caution":"마음이 앞서 내 여력 이상으로 내어 주면 오래 이어가기 어렵습니다.","advice":"도울 때는 내 일을 먼저 정리하고, 줄 수 있는 만큼의 범위를 미리 정해 두세요. 부담 없는 크기로 시작하는 편이 좋습니다.","message":"서두르되 헤아려서 덜어 주세요."},{"guaN":41,"guaName":"산택손","pos":2,"label":"九二","yinyang":"yang","text":"利貞 征凶 弗損益之","reading":"리정 정흉 불손익지","modern":"바르게 지키는 것이 이롭고, 나서서 나아가면 어려움이 따릅니다. 덜지 않고도 보탬이 될 수 있습니다.","meaning":"아래 괘의 중심에서 자기 중심을 지키는 자리입니다. 윗사람에게 잘 보이려고 자신을 깎아 가며 나서기보다, 제자리를 지키는 것이 오히려 도움이 되는 장면입니다.","positive":"스스로를 낮추거나 무리하지 않아도 중심을 지키는 것만으로 신뢰를 얻을 수 있습니다.","caution":"상대를 위한다며 무리하게 나서면 오히려 어려움을 부르기 쉽습니다.","advice":"인정받으려고 나를 소모하는 선택은 잠시 멈추고, 내 원칙과 속도를 지키세요. 도움은 꼭 희생이 아니어도 됩니다.","message":"나를 깎지 않고 중심을 지키세요."},{"guaN":41,"guaName":"산택손","pos":3,"label":"六三","yinyang":"yin","text":"三人行 則損一人 一人行 則得其友","reading":"삼인행 즉손일인 일인행 즉득기우","modern":"세 사람이 길을 가면 한 사람이 덜려 나가고, 한 사람이 길을 가면 벗을 얻게 됩니다.","meaning":"아래 괘의 끝에서 위 괘로 넘어가는 전환기입니다. 셋이 되면 균형이 깨지고 하나는 밀려나기 쉬우니, 둘의 짝이 맞는 구조로 정리하게 되는 때입니다.","positive":"관계의 숫자와 구조를 단순하게 하면 오히려 진짜 동료를 만나기 쉽습니다.","caution":"셋이 얽힌 관계에서는 소외되는 사람이 생겨 갈등이 되기 쉽습니다.","advice":"관계나 팀이 복잡해졌다면 역할을 둘씩 짝지어 나누는 방법을 살펴보세요. 혼자 나서는 것이 도리어 좋은 만남으로 이어질 수 있습니다.","message":"단순해지면 짝이 보입니다."},{"guaN":41,"guaName":"산택손","pos":4,"label":"六四","yinyang":"yin","text":"損其疾 使遄有喜 无咎","reading":"손기질 사천유희 무구","modern":"그 병을 덜어내 빨리 낫게 하면 기쁨이 있고 허물이 없습니다.","meaning":"위 괘의 시작에서 자신의 결점과 병폐를 인정하고 덜어내는 장면입니다. 좋은 짝(아래 초효)의 도움을 받아 빠르게 고쳐 나가는 모습입니다.","positive":"문제를 일찍 인정하고 손보면 회복이 빠르고 주변에 기쁨이 돌아옵니다.","caution":"고칠 점을 알면서 미루면 작은 흠이 큰 부담으로 커질 수 있습니다.","advice":"고치고 싶은 습관이나 오래된 문제 하나를 정해 믿을 만한 사람에게 도움을 청해 보세요. 빠르게 손보는 쪽이 부담이 적습니다.","message":"병폐는 일찍 덜수록 가볍습니다."},{"guaN":41,"guaName":"산택손","pos":5,"label":"六五","yinyang":"yin","text":"或益之 十朋之龜 弗克違 元吉","reading":"혹익지 십붕지귀 불극위 원길","modern":"누군가 보태 주는데, 값비싼 큰 거북이 같은 귀한 것이라 거절하기 어렵습니다. 크게 좋습니다.","meaning":"위 괘의 중심에서 겸허하게 자신을 비운 덕에 사방에서 뜻밖의 이로움이 모여드는 장면입니다. 귀한 도움이 거절할 수 없을 만큼 자연스럽게 찾아옵니다.","positive":"스스로를 낮추고 덜어낸 태도가 주변의 큰 호의와 지원으로 돌아올 수 있습니다.","caution":"받은 도움을 당연하게 여기면 그 인연이 오래 가지 못합니다.","advice":"좋은 제안이나 도움이 오면 고맙게 받되, 사양할 이유가 없는지 한 번 살피고 감사를 표현하세요. 받은 것을 다시 나누는 방법도 생각해 보세요.","message":"비운 자리에 귀한 것이 찾아옵니다."},{"guaN":41,"guaName":"산택손","pos":6,"label":"上九","yinyang":"yang","text":"弗損益之 无咎 貞吉 利有攸往 得臣无家","reading":"불손익지 무구 정길 리유유왕 득신무가","modern":"덜지 않고도 보탤 수 있어 허물이 없고, 바르게 지키면 좋으며 나아가는 일에 이롭습니다. 뜻을 같이하는 사람을 얻는데, 사사로운 집을 따로 두지 않습니다.","meaning":"덜어냄의 끝에 이르러 이제는 자신을 덜지 않고도 남에게 보탬이 되는 단계입니다. 개인의 이익보다 공동의 뜻을 앞세울 때 많은 사람이 함께합니다.","positive":"나눌 줄 아는 사람에게는 사심 없는 동료가 모이고 일의 범위도 넓어집니다.","caution":"이로움을 받는 위치에 오래 있으면 처음의 겸손이 흐려질 수 있습니다.","advice":"지금까지 쌓은 것을 내 안에만 두지 말고, 공동의 목적을 위해 쓰는 방법을 찾아보세요. 사적인 이득과 공적인 일의 경계를 분명히 하면 도움이 됩니다.","message":"내 것을 넘어 함께의 일로 키우세요."}],"yong":null},"42":{"n":42,"name":"풍뢰익","han":"風雷益","upper":"손","lower":"진","upperHan":"巽","lowerHan":"震","bits":[1,0,0,0,1,1],"binary":"100011","gua":{"text":"利有攸往 利涉大川","reading":"리유유왕 리섭대천","modern":"나아가는 바가 있으면 이롭습니다. 큰 내를 건너는 것도 이롭습니다.","symbol":"위에는 바람(巽), 아래에는 우레(震)가 있어 바람과 천둥이 서로 힘을 북돋는 모습입니다. 위에서 덜어 아래를 보태 주는, 더함과 이로움의 괘입니다.","situation":"도움과 기회가 흘러들어 와 무언가를 시작하거나 키우기에 좋은 국면입니다. 이런 때는 큰일에 도전해도 지원을 받기 쉽습니다. 다만 받은 이로움을 혼자만의 것으로 두면 흐름이 오래가기 어렵습니다.","positive":"주변의 지원과 호의를 얻기 쉬워 새로운 도전과 성장에 힘이 붙기 쉽습니다.","caution":"받는 데 익숙해져 스스로 노력하거나 나누는 일을 소홀히 하면 흐름이 약해질 수 있습니다.","direction":"기회가 보일 때 미루지 말고 구체적인 계획으로 옮겨 보세요. 배울 점은 바로 따르고 고칠 점은 일찍 고치며, 얻은 것을 주변과 나누는 편이 흐름을 이어 가는 데 도움이 됩니다.","message":"받은 이로움은 나눌 때 오래갑니다."},"yao":[{"guaN":42,"guaName":"풍뢰익","pos":1,"label":"初九","yinyang":"yang","text":"利用爲大作 元吉 无咎","reading":"리용위대작 원길 무구","modern":"큰일을 일으키는 데 쓰면 이롭습니다. 크게 길하고 허물이 없습니다.","meaning":"윗사람의 지원을 처음 받아 큰일을 시작해 볼 수 있는 단계입니다. 아직 낮은 자리라 부담이 클 수 있어, 받은 도움에 걸맞은 일을 해내는지가 관건입니다.","positive":"지원이 막 닿아 새 일을 힘 있게 시작하기 좋은 때입니다.","caution":"받은 도움에 걸맞지 않은 작은 성과에 머물면 기회가 아깝게 지나갈 수 있습니다.","advice":"목표를 한 단계 크게 잡고 준비를 꼼꼼히 하세요. 도움 준 사람에게 진행 상황을 알리는 편이 신뢰에 도움이 됩니다.","message":"도움을 받았다면 큰일에 쓰세요."},{"guaN":42,"guaName":"풍뢰익","pos":2,"label":"六二","yinyang":"yin","text":"或益之十朋之龜 弗克違 永貞吉 王用享于帝 吉","reading":"혹익지십붕지귀 불극위 영정길 왕용향우제 길","modern":"누군가 큰 값어치의 거북 점패(십붕)를 더해 주니 거스를 수 없습니다. 오래도록 바르게 지키면 길합니다. 왕이 상제께 제사를 올려도 길합니다.","meaning":"아래 괘의 중심에서 사양하기 어려울 만큼 큰 이로움이 찾아오는 장면입니다. 내가 겸손하고 바르게 서 있으니 사람들이 자연스럽게 도움을 보태 줍니다.","positive":"겸손하고 바른 태도 덕분에 여러 곳에서 도움이 모이기 쉽습니다.","caution":"좋은 평가에 들떠 원칙을 느슨하게 하면 얻은 신뢰가 흔들릴 수 있습니다.","advice":"주어진 도움은 감사히 받되 꾸준한 태도를 유지하세요. 이 이로움을 어디에 쓸지 공적인 목적과 함께 생각해 보세요.","message":"바르게 서 있으면 도움이 모입니다."},{"guaN":42,"guaName":"풍뢰익","pos":3,"label":"六三","yinyang":"yin","text":"益之用凶事 无咎 有孚中行 告公用圭","reading":"익지용흉사 무구 유부중행 고공용규","modern":"어려운 일에 쓰도록 더해 주니 허물이 없습니다. 믿음을 두고 중도로 행하며, 공께 알릴 때 규(홀)를 갖춥니다.","meaning":"아래 괘의 끝에서 위기나 어려운 일을 수습하는 데 이로움이 쓰이는 장면입니다. 급한 상황에서 받은 지원이므로 정직하게 쓰고 투명하게 보고하는 것이 중요합니다.","positive":"어려운 일을 수습할 자원과 도움을 얻어 위기를 넘기기 쉽습니다.","caution":"위급하다는 이유로 과정을 숨기거나 무리하면 오해를 살 수 있습니다.","advice":"받은 지원의 사용처를 기록하고 윗사람이나 관계자에게 성실히 알리세요. 치우치지 않는 선에서 차분하게 대응하는 편이 도움이 됩니다.","message":"어려울 때 받은 도움일수록 투명하게 쓰세요."},{"guaN":42,"guaName":"풍뢰익","pos":4,"label":"六四","yinyang":"yin","text":"中行 告公從 利用爲依遷國","reading":"중행 고공종 리용위의천국","modern":"중도로 행하여 공께 알리면 따르십니다. 의지하여 나라를 옮기는 일에 쓰면 이롭습니다.","meaning":"아래의 이로움을 받들어 위로 전달하는 가까운 윗자리에 있는 장면입니다. 중간에서 의견을 바르게 전하면 큰 결정도 받아들여지기 쉽습니다.","positive":"중간에서 신뢰를 얻어 큰 변화나 이전 같은 일을 설득하기 좋습니다.","caution":"자기 이익을 앞세워 말을 전하면 신뢰가 한꺼번에 약해질 수 있습니다.","advice":"의견을 전할 때 치우치지 말고 사실과 공익을 중심에 두세요. 큰 변화를 제안한다면 근거와 순서를 갖추는 편이 좋습니다.","message":"공정한 전달이 큰 결정을 이끕니다."},{"guaN":42,"guaName":"풍뢰익","pos":5,"label":"九五","yinyang":"yang","text":"有孚惠心 勿問元吉 有孚惠我德","reading":"유부혜심 물문원길 유부혜아덕","modern":"믿음을 두고 은혜로운 마음을 가지면 묻지 않아도 크게 길합니다. 믿음을 두고 나의 덕을 은혜로 여겨 따릅니다.","meaning":"위 괘의 중심에서 진심으로 베푸는 자리입니다. 결과를 따지지 않고 베푸는 마음이 사람들의 믿음과 호응으로 돌아오는 장면입니다.","positive":"진심 어린 배려가 신뢰와 호응으로 이어지기 쉬운 때입니다.","caution":"보답을 기대하며 베풀면 마음이 어긋나 오히려 서운함이 쌓일 수 있습니다.","advice":"내가 가진 것 중 나눌 수 있는 것을 정해 부담 없이 베풀어 보세요. 결과를 지나치게 계산하지 않는 편이 도움이 됩니다.","message":"계산 없는 베풂이 신뢰가 됩니다."},{"guaN":42,"guaName":"풍뢰익","pos":6,"label":"上九","yinyang":"yang","text":"莫益之 或擊之 立心勿恒 凶","reading":"막익지 혹격지 입심물항 흉","modern":"더해 주는 사람이 없고 혹 공격하는 사람도 있습니다. 마음을 세우는 데 꾸준함이 없으니 흉합니다.","meaning":"더함의 끝에서 이득만 구하다 도움의 흐름이 끊기고 주변의 비판을 받는 장면입니다. 베풀지 않고 얻기만 하면 사람들이 등을 돌리기 쉽습니다.","positive":"이 시점에 자신의 태도를 돌아보면 관계를 되돌릴 기회가 될 수 있습니다.","caution":"욕심이 앞서고 마음이 자주 흔들리면 주변의 도움이 끊기고 비난을 받기 쉽습니다.","advice":"얻으려는 마음을 잠시 내려놓고 주변에 먼저 보탤 것이 있는지 살펴보세요. 한번 정한 마음을 꾸준히 지키는 일부터 시작해 보세요.","message":"얻기만 하면 도움이 끊기기 쉽습니다."}],"yong":null},"43":{"n":43,"name":"택천쾌","han":"澤天夬","upper":"태","lower":"건","upperHan":"兌","lowerHan":"乾","bits":[1,1,1,1,1,0],"binary":"111110","gua":{"text":"揚于王庭 孚號有厲 告自邑 不利卽戎 利有攸往","reading":"양우왕정 부호유려 고자읍 불리즉융 리유유왕","modern":"왕의 뜰에서 드러내어 밝힙니다. 진실로 외치되 위태로움이 있습니다. 자기 고을에 먼저 알리고, 곧바로 무력에 나서는 것은 이롭지 않습니다. 나아가는 바가 있으면 이롭습니다.","symbol":"위에는 연못(兌), 아래에는 하늘(乾)이 있어 연못물이 하늘 높이 차올라 터지려는 모습입니다. 쌓인 문제를 결단해 풀어내는 괘입니다.","situation":"오래 미뤄 온 문제를 이제는 분명히 정리해야 하는 국면입니다. 공개적이고 정당한 절차로 밝히면 힘을 얻지만, 감정이나 힘으로 밀어붙이면 반발이 커지기 쉽습니다.","positive":"미뤄 온 일을 매듭짓고 흐름을 새롭게 열 수 있는 결단의 시기입니다.","caution":"성급함이나 감정적 대응은 작은 문제를 큰 갈등으로 키울 수 있습니다.","direction":"결단하기 전에 사실과 근거를 정리하고, 관련된 사람들에게 이유를 먼저 설명하세요. 단호하되 절차를 지키고 마무리 이후의 관계까지 함께 생각하는 편이 도움이 됩니다.","message":"단호하되 절차는 지키세요."},"yao":[{"guaN":43,"guaName":"택천쾌","pos":1,"label":"初九","yinyang":"yang","text":"壯于前趾 往不勝爲咎","reading":"장우전지 왕불승위구","modern":"앞발가락에 힘이 넘칩니다. 나아가 이기지 못하면 허물이 됩니다.","meaning":"막 시작하는 자리에서 의욕만 앞서 달려 나가려는 장면입니다. 준비가 덜 된 채 앞서 나가면 힘이 모자라 오히려 낭패를 볼 수 있습니다.","positive":"의욕과 추진력이 충분해 일을 시작할 에너지가 있습니다.","caution":"준비 없이 먼저 나서면 승산이 낮아 부담과 비난을 안기 쉽습니다.","advice":"행동하기 전에 이길 수 있는 조건이 갖춰졌는지 점검하세요. 하나씩 준비를 채운 뒤 움직이는 편이 안전합니다.","message":"의욕보다 준비가 먼저입니다."},{"guaN":43,"guaName":"택천쾌","pos":2,"label":"九二","yinyang":"yang","text":"惕號 莫夜有戎 勿恤","reading":"척호 모야유융 물휼","modern":"두려워하며 외칩니다. 늦은 밤에 적이 있어도 근심하지 마십시오.","meaning":"아래 괘의 중심에서 경계심을 유지하며 주변에 알리고 대비하는 장면입니다. 미리 조심하고 알려 두었으므로 갑작스러운 일이 생겨도 크게 흔들리지 않습니다.","positive":"경계하고 준비한 덕분에 갑작스러운 일에도 침착하게 대응하기 쉽습니다.","caution":"지나친 걱정에 사로잡히면 오히려 판단이 흐려질 수 있습니다.","advice":"위험 요소를 주변과 공유하고 대응 순서를 정해 두세요. 준비를 마쳤다면 막연한 불안은 내려놓는 편이 좋습니다.","message":"미리 대비하면 걱정이 줄어듭니다."},{"guaN":43,"guaName":"택천쾌","pos":3,"label":"九三","yinyang":"yang","text":"壯于頄 有凶 君子夬夬 獨行遇雨 若濡有慍 无咎","reading":"장우규 유흉 군자쾌쾌 독행우우 약유유온 무구","modern":"광대뼈에 힘이 드러나니 흉함이 있습니다. 군자는 결단하고 또 결단하여 홀로 가다 비를 만나 옷이 젖어 불쾌해도 허물은 없습니다.","meaning":"아래 괘의 끝에서 결의가 얼굴에 드러날 만큼 강해진 전환기입니다. 감정을 드러내면 반발을 사지만, 결단을 지키면서 오해를 감수하면 허물은 피할 수 있습니다.","positive":"오해를 감수하더라도 뜻을 굽히지 않는 결단력이 있습니다.","caution":"분노나 결의를 겉으로 크게 드러내면 주변의 불편과 반발을 키울 수 있습니다.","advice":"감정은 가라앉히고 결정의 이유를 차분히 설명하세요. 외로운 길일 수 있으니 이해해 줄 사람과 대화하는 편이 도움이 됩니다.","message":"결단은 단단히, 표정은 차분히."},{"guaN":43,"guaName":"택천쾌","pos":4,"label":"九四","yinyang":"yang","text":"臀无膚 其行次且 牽羊悔亡 聞言不信","reading":"둔무부 기행자저 견양회망 문언불신","modern":"엉덩이에 살갗이 없어 걸음이 머뭇거립니다. 양을 끌듯 따라가면 후회가 사라집니다. 그러나 말을 들어도 믿지 않습니다.","meaning":"위 괘의 시작에서 불안하고 앉아 있기도 힘든 상태로 머뭇거리는 장면입니다. 앞장서기보다 무리를 따라 순하게 나아가면 후회를 줄일 수 있지만, 조언을 받아들이지 않으면 어려움이 이어집니다.","positive":"앞서기보다 흐름을 따르면 후회를 줄일 수 있는 자리입니다.","caution":"좋은 조언도 믿지 않고 고집하면 제자리에서 계속 불편함을 겪기 쉽습니다.","advice":"혼자 결정하기 어려우면 믿을 만한 사람의 의견을 따라 한 걸음 옮겨 보세요. 듣는 태도를 열어 두는 편이 도움이 됩니다.","message":"머뭇거릴 때는 조언을 열어 두세요."},{"guaN":43,"guaName":"택천쾌","pos":5,"label":"九五","yinyang":"yang","text":"莧陸夬夬 中行无咎","reading":"현륙쾌쾌 중행무구","modern":"비름풀을 단호히 뽑듯 결단하고 또 결단하되, 중도로 행하면 허물이 없습니다.","meaning":"위 괘의 중심에서 마지막 걸림돌을 제거하는 핵심 자리입니다. 뿌리가 질긴 풀처럼 미련이 남기 쉬워, 단호함과 균형을 함께 지켜야 하는 장면입니다.","positive":"핵심 문제를 정리할 위치와 힘이 있어 마무리하기에 좋습니다.","caution":"미련이나 지나친 강경함 중 어느 한쪽으로 치우치면 일이 깔끔하게 끝나지 않을 수 있습니다.","advice":"끝내야 할 일을 분명히 정하되 절차와 균형은 지키세요. 정리한 뒤에 남은 감정은 스스로 돌아보는 편이 좋습니다.","message":"단호함과 균형을 함께 지키세요."},{"guaN":43,"guaName":"택천쾌","pos":6,"label":"上六","yinyang":"yin","text":"无號 終有凶","reading":"무호 종유흉","modern":"호소할 곳이 없습니다. 끝내는 흉함이 있습니다.","meaning":"마지막 자리에서 주변이 모두 돌아선 듯 외쳐도 도움을 구하기 어려운 장면입니다. 방심하면 정리된 줄 알았던 문제가 다시 불거질 수 있습니다.","positive":"끝에 이르렀으니 마무리를 점검해 남은 위험을 줄일 기회가 있습니다.","caution":"다 끝났다고 방심하면 남은 문제가 뒤늦게 크게 번질 수 있습니다.","advice":"마무리 단계에서도 점검 목록을 만들어 빠진 것이 없는지 확인하세요. 도움이 필요하면 미리 주변에 알리는 편이 좋습니다.","message":"끝났다고 느낄 때 한 번 더 점검하세요."}],"yong":null},"44":{"n":44,"name":"천풍구","han":"天風姤","upper":"건","lower":"손","upperHan":"乾","lowerHan":"巽","bits":[0,1,1,1,1,1],"binary":"011111","gua":{"text":"女壯 勿用取女","reading":"녀장 물용취녀","modern":"여자가 건장합니다. 이런 여자를 아내로 맞아들이지 마십시오.","symbol":"위에는 하늘(乾), 아래에는 바람(巽)이 있어 하늘 아래 바람이 불며 뜻밖에 만나는 모습입니다. 다섯 양 아래에 음 하나가 처음 들어오는 괘입니다.","situation":"뜻하지 않은 만남이나 제안, 유혹이 갑자기 찾아오는 국면입니다. 처음에는 작고 반가워 보이지만 점점 영향력이 커질 수 있어, 초기에 기준을 세워 두는 일이 중요합니다.","positive":"새로운 인연과 기회를 만나 시야가 넓어질 수 있는 시기입니다.","caution":"작은 호의나 유혹에 쉽게 마음을 열면 어느새 주도권을 잃기 쉽습니다.","direction":"새로 생긴 만남이나 제안은 서둘러 결론을 내리지 말고 시간을 두고 살펴보세요. 내 기준과 경계를 먼저 분명히 하면 좋은 인연과 그렇지 않은 인연을 구별하기 쉽습니다.","message":"뜻밖의 만남은 기준을 세우고 맞이하세요."},"yao":[{"guaN":44,"guaName":"천풍구","pos":1,"label":"初六","yinyang":"yin","text":"繫于金柅 貞吉 有攸往 見凶 羸豕孚蹢躅","reading":"계우금니 정길 유유왕 견흉 리시부척촉","modern":"쇠로 만든 수레 멈춤대에 묶어 두니 바르게 지키면 길합니다. 나아가는 바가 있으면 흉함을 만납니다. 야윈 돼지도 진실로 뛰어다니려 합니다.","meaning":"작은 기운이 막 자라나기 시작하는 단계로, 약해 보여도 곧 움직이려는 힘이 있습니다. 이때 단단히 묶어 두듯 초기에 선을 그어야 뒤탈이 적습니다.","positive":"초기에 분명히 제어하면 큰 문제로 커지는 일을 막기 쉽습니다.","caution":"작다고 가볍게 보고 풀어 두면 나중에 감당하기 어려워질 수 있습니다.","advice":"마음이 흔들리는 일에는 기한이나 규칙을 먼저 정해 두세요. 작은 습관과 관계에서 경계를 분명히 하는 편이 좋습니다.","message":"작을 때 선을 그으세요."},{"guaN":44,"guaName":"천풍구","pos":2,"label":"九二","yinyang":"yang","text":"包有魚 无咎 不利賓","reading":"포유어 무구 불리빈","modern":"꾸러미에 물고기가 있으니 허물이 없습니다. 손님에게는 이롭지 않습니다.","meaning":"아래 괘의 중심에서 다가온 인연을 내가 맡아 품고 관리하는 장면입니다. 내가 먼저 책임지고 감싸면 문제가 번지지 않지만, 다른 사람에게까지 나누면 혼란이 생길 수 있습니다.","positive":"내가 책임지고 관리하면 새로운 관계를 안정적으로 이어 가기 쉽습니다.","caution":"내가 감당할 일을 널리 퍼뜨리면 관계가 복잡해지고 오해가 생길 수 있습니다.","advice":"새로 얻은 것은 내가 직접 관리할 범위 안에서 정리하세요. 외부에 알리거나 나눌 때는 신중하게 판단하는 편이 좋습니다.","message":"내가 맡은 인연은 내가 책임지세요."},{"guaN":44,"guaName":"천풍구","pos":3,"label":"九三","yinyang":"yang","text":"臀无膚 其行次且 厲 无大咎","reading":"둔무부 기행자저 려 무대구","modern":"엉덩이에 살갗이 없어 걸음이 머뭇거립니다. 위태롭지만 큰 허물은 없습니다.","meaning":"아래 괘의 끝에서 만남에 마음이 끌리지만 아무도 받아 주지 않아 불안하게 머뭇거리는 장면입니다. 서두르지 않고 머뭇거린 덕에 큰 잘못은 피할 수 있습니다.","positive":"머뭇거리는 신중함 덕에 큰 실수를 피할 수 있습니다.","caution":"불안과 답답함 때문에 억지로 나아가면 위태로운 선택으로 이어질 수 있습니다.","advice":"결정을 서두르지 말고 지금 불편한 마음의 이유를 적어 보세요. 확신이 설 때까지 한 걸음 물러서 지켜보는 편이 좋습니다.","message":"답답해도 서둘지 않으면 큰 허물은 없습니다."},{"guaN":44,"guaName":"천풍구","pos":4,"label":"九四","yinyang":"yang","text":"包无魚 起凶","reading":"포무어 기흉","modern":"꾸러미에 물고기가 없습니다. 일어나면 흉합니다.","meaning":"위 괘의 시작에서 가까워야 할 상대를 놓쳐 곁에 아무도 남지 않은 장면입니다. 그 상태에서 무리하게 나서면 주변과 더 멀어져 어려움을 부를 수 있습니다.","positive":"잃은 관계를 돌아볼 계기가 되어 앞으로의 태도를 고칠 수 있습니다.","caution":"사람을 소홀히 대한 상태에서 강하게 밀어붙이면 고립이 깊어질 수 있습니다.","advice":"먼저 소홀했던 사람에게 연락하거나 사과할 일이 있는지 살펴보세요. 큰 행동은 관계를 회복한 뒤로 미루는 편이 좋습니다.","message":"사람을 놓친 뒤에는 서두르지 마세요."},{"guaN":44,"guaName":"천풍구","pos":5,"label":"九五","yinyang":"yang","text":"以杞包瓜 含章 有隕自天","reading":"이기포과 함장 유운자천","modern":"버드나무 가지로 오이를 감쌉니다. 아름다움을 속에 품으니 하늘에서 떨어지는 것이 있습니다.","meaning":"위 괘의 중심에서 높은 자리에 있으면서도 낮은 사람을 큰 나무가 오이를 감싸듯 품는 장면입니다. 덕을 안에 품고 기다리면 뜻밖의 좋은 기회가 찾아올 가능성이 있습니다.","positive":"덕을 쌓고 품어 안는 태도가 뜻밖의 좋은 소식으로 이어질 수 있습니다.","caution":"기다림이 길어지면 조급해져 스스로 드러내려 하다 흐름을 놓칠 수 있습니다.","advice":"드러내기보다 내실을 쌓고 사람을 품는 데 힘쓰세요. 기회는 준비된 사람에게 오기 쉬우니 차분히 기다려 보세요.","message":"속을 채우며 기다리면 기회가 옵니다."},{"guaN":44,"guaName":"천풍구","pos":6,"label":"上九","yinyang":"yang","text":"姤其角 吝 无咎","reading":"구기각 린 무구","modern":"뿔에서 만납니다. 아쉬움이 있으나 허물은 없습니다.","meaning":"맨 위에서 너무 높고 뻣뻣해 다가오는 사람이 없는 장면입니다. 고립되어 아쉬움은 있지만 스스로 중심을 지키니 큰 잘못은 아닙니다.","positive":"자기 원칙을 지키며 지나친 어울림에 휩쓸리지 않은 점이 장점입니다.","caution":"너무 높고 뻣뻣하게 굴면 사람들이 다가오기 어려워 외로워질 수 있습니다.","advice":"원칙은 지키되 먼저 말을 건네는 여유를 가져 보세요. 거리를 조금 좁히는 일이 아쉬움을 줄이는 데 도움이 됩니다.","message":"원칙은 지키되 문은 열어 두세요."}],"yong":null},"45":{"n":45,"name":"택지췌","han":"澤地萃","upper":"태","lower":"곤","upperHan":"兌","lowerHan":"坤","bits":[0,0,0,1,1,0],"binary":"000110","gua":{"text":"亨 王假有廟 利見大人 亨 利貞 用大牲吉 利有攸往","reading":"형 왕격유묘 리견대인 형 리정 용대생길 리유유왕","modern":"형통합니다. 왕이 사당에 이르러 정성을 다합니다. 대인을 만나면 이롭고 형통하며, 바르게 하는 것이 이롭습니다. 큰 희생을 써서 제사를 올리면 길합니다. 나아가는 바가 있으면 이롭습니다.","symbol":"위에는 연못(兌), 아래에는 땅(坤)이 있어 연못에 물이 모이듯 사람과 힘이 한곳에 모이는 모습입니다. 모임과 결집의 괘입니다.","situation":"사람, 자원, 관심이 한곳으로 모여드는 국면입니다. 기회가 커지는 만큼 중심이 되는 뜻과 질서가 필요하며, 모임이 클수록 뜻밖의 일에 대한 대비도 함께 요구됩니다.","positive":"사람과 자원이 모여 큰일을 함께 도모하기 좋은 시기입니다.","caution":"중심과 규칙이 없으면 모일수록 혼란과 갈등이 커지기 쉽습니다.","direction":"모임의 목적과 기준을 먼저 분명히 하고, 중심이 될 사람과 역할을 정하세요. 많은 사람이 모이는 일일수록 위험 요소를 미리 점검해 두는 편이 도움이 됩니다.","message":"모일수록 중심과 대비가 필요합니다."},"yao":[{"guaN":45,"guaName":"택지췌","pos":1,"label":"初六","yinyang":"yin","text":"有孚不終 乃亂乃萃 若號 一握爲笑 勿恤 往无咎","reading":"유부불종 내란내췌 약호 일악위소 물휼 왕무구","modern":"믿음이 있으나 끝까지 이어지지 못하니 마음이 어지럽고 이리저리 모입니다. 외쳐 부르면 한 번 손을 잡고 웃게 됩니다. 근심하지 말고 나아가면 허물이 없습니다.","meaning":"모임이 막 시작되는 자리에서 믿음이 흔들려 어느 무리에 들어갈지 갈피를 잡지 못하는 장면입니다. 함께할 사람에게 마음을 열어 손을 내밀면 불안이 풀릴 수 있습니다.","positive":"마음을 열고 손을 내밀면 뜻이 맞는 사람을 만날 가능성이 큽니다.","caution":"주변의 말에 흔들려 이곳저곳 기웃거리면 중심을 잃기 쉽습니다.","advice":"함께할 사람과 이유를 한 번 정리해 보고, 믿을 만한 사람에게 먼저 도움을 청해 보세요. 남의 시선에 크게 걱정하지 않아도 좋습니다.","message":"흔들릴 때는 믿을 사람 곁으로 가세요."},{"guaN":45,"guaName":"택지췌","pos":2,"label":"六二","yinyang":"yin","text":"引吉 无咎 孚乃利用禴","reading":"인길 무구 부내리용약","modern":"이끌려 모이니 길하고 허물이 없습니다. 믿음이 있으면 간소한 제사(약제)를 올려도 이롭습니다.","meaning":"아래 괘의 중심에서 윗사람과 뜻이 통해 자연스럽게 이끌려 모이는 장면입니다. 형식을 크게 갖추지 않아도 진심이 통하면 관계가 이어집니다.","positive":"진심만으로 좋은 사람들과 자연스럽게 연결될 수 있습니다.","caution":"스스로 길을 만들지 않고 끌려가기만 하면 주도성을 잃을 수 있습니다.","advice":"끌리는 방향이 나의 뜻과 맞는지 점검한 뒤 함께하세요. 형식보다 정성 어린 태도에 무게를 두는 편이 좋습니다.","message":"진심이 통하면 형식은 간소해도 됩니다."},{"guaN":45,"guaName":"택지췌","pos":3,"label":"六三","yinyang":"yin","text":"萃如嗟如 无攸利 往无咎 小吝","reading":"췌여차여 무유리 왕무구 소린","modern":"모이고자 하나 탄식합니다. 이로운 바가 없습니다. 가면 허물은 없으나 조금 아쉬움이 있습니다.","meaning":"아래 괘의 끝에서 어울리고 싶은데 마땅히 받아 주는 곳이 없어 한숨짓는 전환기입니다. 위쪽의 가까운 사람을 향해 나아가면 크게 어긋나지는 않지만 약간의 아쉬움은 남을 수 있습니다.","positive":"고립을 벗어나려는 시도를 해 볼 수 있는 때입니다.","caution":"혼자 한탄만 하며 머물면 상황이 더 나아지기 어렵습니다.","advice":"도움을 구할 만한 사람에게 먼저 다가가 보세요. 작은 아쉬움은 감수하고 시도해 보는 편이 도움이 됩니다.","message":"한탄보다 한 걸음 다가가세요."},{"guaN":45,"guaName":"택지췌","pos":4,"label":"九四","yinyang":"yang","text":"大吉 无咎","reading":"대길 무구","modern":"크게 길합니다. 허물이 없습니다.","meaning":"위 괘의 시작에서 윗사람과 아랫사람 사이를 잇는 자리에 서 있는 장면입니다. 자리가 완전히 맞지 않아 부담이 있으나, 사사로움 없이 사람을 모으면 허물이 없습니다.","positive":"사람들을 잇는 역할을 잘 해내면 좋은 평가를 얻기 쉽습니다.","caution":"모은 사람과 성과를 내 것으로 여기면 곧 신뢰를 잃을 수 있습니다.","advice":"공적인 목적을 앞세워 사람들을 연결하고, 성과는 함께 나누세요. 내 자리의 부담을 인정하고 겸손하게 임하는 편이 좋습니다.","message":"사사로움 없이 모으면 허물이 없습니다."},{"guaN":45,"guaName":"택지췌","pos":5,"label":"九五","yinyang":"yang","text":"萃有位 无咎 匪孚 元永貞 悔亡","reading":"췌유위 무구 비부 원영정 회망","modern":"모임에서 자리를 갖습니다. 허물이 없습니다. 아직 믿음을 얻지 못한 이들이 있다면 처음부터 오래도록 바름을 지키면 후회가 사라집니다.","meaning":"위 괘의 중심에서 모임의 중심 자리에 앉아 있는 장면입니다. 자리가 있다고 모두가 믿어 주는 것은 아니므로 꾸준하고 바른 태도로 신뢰를 쌓아야 합니다.","positive":"중심 자리에서 사람들을 이끌 수 있는 영향력이 있습니다.","caution":"자리의 권위에만 기대면 아직 믿지 않는 사람들이 멀어질 수 있습니다.","advice":"자리보다 태도로 신뢰를 얻는다는 마음으로 꾸준히 임하세요. 아직 믿지 않는 사람에게는 서두르지 말고 시간을 두고 보여 주세요.","message":"신뢰는 자리보다 태도에서 나옵니다."},{"guaN":45,"guaName":"택지췌","pos":6,"label":"上六","yinyang":"yin","text":"齎咨涕洟 无咎","reading":"재자체이 무구","modern":"탄식하며 눈물과 콧물을 흘립니다. 허물은 없습니다.","meaning":"맨 위에서 모임에 끼지 못하고 외로이 탄식하는 장면입니다. 스스로 부족함을 깨닫고 마음을 다해 슬퍼하니 큰 허물은 되지 않습니다.","positive":"솔직하게 마음을 드러내는 일이 변화의 계기가 될 수 있습니다.","caution":"자존심 때문에 고립을 계속 이어 가면 외로움이 깊어질 수 있습니다.","advice":"마음속의 아쉬움을 가까운 사람에게 솔직히 이야기해 보세요. 자세를 낮추고 다시 다가가는 편이 도움이 됩니다.","message":"솔직한 마음이 다시 사람을 이어 줍니다."}],"yong":null},"46":{"n":46,"name":"지풍승","han":"地風升","upper":"곤","lower":"손","upperHan":"坤","lowerHan":"巽","bits":[0,1,1,0,0,0],"binary":"011000","gua":{"text":"元亨 用見大人 勿恤 南征吉","reading":"원형 용견대인 물휼 남정길","modern":"크게 형통합니다. 대인을 만나 뵈되 근심하지 마십시오. 남쪽으로 나아가면 길합니다.","symbol":"위에는 땅(坤), 아래에는 바람 또는 나무(巽)가 있어 땅속에서 나무가 자라 올라오는 모습입니다. 순리대로 차근차근 오르는 괘입니다.","situation":"성장과 상승의 흐름이 있는 국면으로, 겸손하고 성실하게 쌓아 온 것이 힘이 됩니다. 급하게 뛰어오르기보다 단계를 밟을 때 안정적으로 올라갈 수 있습니다.","positive":"순조로운 성장과 윗사람의 도움을 얻어 한 단계 올라서기 좋은 시기입니다.","caution":"오르는 속도에 취해 기본을 소홀히 하면 중간에 흔들릴 수 있습니다.","direction":"목표를 단계로 나누고 한 걸음씩 실천하세요. 이끌어 줄 사람을 찾아 정중하게 도움을 청하고, 올라갈수록 기본기를 다지는 편이 도움이 됩니다.","message":"한 계단씩 오르는 것이 가장 빠릅니다."},"yao":[{"guaN":46,"guaName":"지풍승","pos":1,"label":"初六","yinyang":"yin","text":"允升 大吉","reading":"윤승 대길","modern":"믿고 따라 오릅니다. 크게 길합니다.","meaning":"막 시작하는 자리에서 위의 뜻과 어우러져 함께 올라가는 장면입니다. 낮은 자리에서 순하게 따르니 윗사람의 신뢰를 얻기 쉽습니다.","positive":"윗사람이나 선배의 이끎을 받아 순조롭게 출발할 수 있습니다.","caution":"스스로 판단하지 않고 따르기만 하면 성장의 폭이 제한될 수 있습니다.","advice":"신뢰할 만한 선배나 멘토의 방식을 먼저 따라 해 보세요. 배우면서 나만의 생각도 조금씩 키워 가는 편이 좋습니다.","message":"믿을 만한 길을 따라 오르세요."},{"guaN":46,"guaName":"지풍승","pos":2,"label":"九二","yinyang":"yang","text":"孚乃利用禴 无咎","reading":"부내리용약 무구","modern":"믿음이 있으면 간소한 제사(약제)를 올려도 이롭습니다. 허물이 없습니다.","meaning":"아래 괘의 중심에서 강한 힘을 가졌으나 겸손하게 위의 부름에 응하는 장면입니다. 꾸밈없는 진심이 윗사람에게 닿으면 소박한 모습으로도 인정받을 수 있습니다.","positive":"진정성이 있으면 화려한 포장이 없어도 신뢰를 얻기 쉽습니다.","caution":"소박함을 핑계로 준비를 소홀히 하면 진심이 제대로 전해지지 않을 수 있습니다.","advice":"형식보다 마음을 담아 성실히 준비하세요. 과장하지 않고 있는 그대로를 보여 주는 편이 도움이 됩니다.","message":"꾸밈없는 진심이 길을 엽니다."},{"guaN":46,"guaName":"지풍승","pos":3,"label":"九三","yinyang":"yang","text":"升虛邑","reading":"승허읍","modern":"빈 고을에 오릅니다.","meaning":"아래 괘의 끝에서 막힘없이 올라가는 길이 열려 거침없이 나아가는 장면입니다. 방해가 없어 편하지만 비어 있는 고을처럼 의지할 기반이 부족하다는 점을 생각해 볼 만합니다.","positive":"장애가 적어 속도를 내어 나아가기 좋은 시기입니다.","caution":"거침없이 올라가다 보면 기반과 준비가 따라오지 못할 수 있습니다.","advice":"순조로울 때 내가 이룬 기반이 단단한지 점검해 보세요. 속도를 내되 중간중간 쉬며 점검하는 편이 좋습니다.","message":"순조로울수록 기반을 점검하세요."},{"guaN":46,"guaName":"지풍승","pos":4,"label":"六四","yinyang":"yin","text":"王用亨于岐山 吉 无咎","reading":"왕용향우기산 길 무구","modern":"왕이 기산에서 제사를 올립니다. 길하고 허물이 없습니다.","meaning":"위 괘의 시작에서 높은 곳을 향해 정성을 다하며 자신의 자리를 순하게 지키는 장면입니다. 앞서 나서기보다 맡은 일을 공손히 해내면 허물이 없습니다.","positive":"맡은 역할을 정성껏 하면 신뢰를 얻으며 안정적으로 자리 잡을 수 있습니다.","caution":"더 높은 자리를 욕심내 선을 넘으면 균형이 흔들릴 수 있습니다.","advice":"내가 맡은 몫을 성실히 하고 의견은 공손히 올리세요. 내 자리의 경계를 존중하는 편이 오래가는 길입니다.","message":"맡은 자리에서 정성을 다하세요."},{"guaN":46,"guaName":"지풍승","pos":5,"label":"六五","yinyang":"yin","text":"貞吉 升階","reading":"정길 승계","modern":"바르게 지키면 길합니다. 계단을 밟아 오릅니다.","meaning":"위 괘의 중심에서 계단을 하나씩 밟아 올라 중심 자리에 이르는 장면입니다. 바르고 꾸준하게 쌓아 온 과정이 인정받는 때입니다.","positive":"차근차근 쌓아 온 성과가 인정받아 자리를 얻기 쉽습니다.","caution":"높은 자리에 올랐다고 순서와 과정을 건너뛰면 신뢰가 흔들릴 수 있습니다.","advice":"지금까지의 원칙을 유지하며 한 단계씩 책임을 넓혀 가세요. 주변의 도움에 대한 감사를 표하는 편이 좋습니다.","message":"바른 계단이 가장 안전한 길입니다."},{"guaN":46,"guaName":"지풍승","pos":6,"label":"上六","yinyang":"yin","text":"冥升 利于不息之貞","reading":"명승 리우불식지정","modern":"어두운 가운데도 계속 오릅니다. 쉬지 않는 바름을 지키는 데 이롭습니다.","meaning":"맨 위에서 이미 높이 올랐는데도 멈추지 않고 눈이 어두운 채 계속 오르려는 장면입니다. 오르기만 계속하면 지치기 쉬우니 목적을 바르게 하는 쪽으로 힘을 돌릴 필요가 있습니다.","positive":"그 열정을 바른 방향으로 쓰면 오랫동안 의미 있는 성과를 이어 갈 수 있습니다.","caution":"더 높이만 바라보다 지치고 시야가 좁아질 수 있습니다.","advice":"더 오르는 것보다 지금의 위치에서 바른 일을 꾸준히 하는 데 힘을 두세요. 목표가 나에게 정말 필요한지 돌아보는 편이 도움이 됩니다.","message":"더 높이보다 바른 방향을 살피세요."}],"yong":null},"47":{"n":47,"name":"택수곤","han":"澤水困","upper":"태","lower":"감","upperHan":"兌","lowerHan":"坎","bits":[0,1,0,1,1,0],"binary":"010110","gua":{"text":"亨 貞 大人吉 无咎 有言不信","reading":"형 정 대인길 무구 유언불신","modern":"형통합니다. 바르게 지키면 대인은 길하고 허물이 없습니다. 말을 해도 믿어 주지 않습니다.","symbol":"위에는 연못(兌), 아래에는 물(坎)이 있어 연못의 물이 아래로 새어 말라 가는 모습입니다. 자원과 여건이 막힌 곤궁의 괘입니다.","situation":"노력해도 결과가 잘 나오지 않고 말을 해도 받아들여지지 않는 답답한 국면입니다. 이런 때는 변명보다 자신의 중심을 지키는 태도가 더 중요해집니다.","positive":"어려움 속에서 자신의 중심과 원칙을 단단히 확인할 수 있는 시기입니다.","caution":"말로 해명하려 애쓸수록 오히려 오해가 커질 수 있습니다.","direction":"지금은 말을 줄이고 해야 할 일을 묵묵히 이어 가세요. 믿을 만한 소수의 사람과 상황을 나누며 버틸 수 있는 여력을 아끼는 편이 도움이 됩니다.","message":"곤궁할 때는 말보다 중심을 지키세요."},"yao":[{"guaN":47,"guaName":"택수곤","pos":1,"label":"初六","yinyang":"yin","text":"臀困于株木 入于幽谷 三歲不覿","reading":"둔곤우주목 입우유곡 삼세부적","modern":"엉덩이가 나무 그루터기에 걸려 곤란합니다. 깊숙한 골짜기에 들어가 삼 년 동안 보이지 않습니다.","meaning":"곤궁이 막 시작되는 맨 아래에서 앉을 곳조차 불편하고 어두운 곳으로 들어가는 장면입니다. 어려움이 길게 느껴지는 시기이므로 조급하게 움직이기보다 버틸 준비가 필요합니다.","positive":"물러나 힘을 아끼며 내면을 돌아볼 시간이 생깁니다.","caution":"답답함에 무리하게 움직이면 더 깊은 곤란에 빠질 수 있습니다.","advice":"당장 결과를 내려 하지 말고 생활과 지출을 정리해 버틸 기반을 마련하세요. 오래 걸릴 수 있다고 마음의 준비를 하는 편이 좋습니다.","message":"어려움이 길 수 있으니 힘을 아끼세요."},{"guaN":47,"guaName":"택수곤","pos":2,"label":"九二","yinyang":"yang","text":"困于酒食 朱紱方來 利用享祀 征凶 无咎","reading":"곤우주식 주불방래 리용향사 정흉 무구","modern":"술과 음식에 곤란을 겪습니다. 붉은 예복(주불)을 입은 이가 막 옵니다. 제사를 올리는 데 쓰면 이롭습니다. 나아가면 흉하나 허물은 없습니다.","meaning":"아래 괘의 중심에서 먹고사는 일은 풀렸지만 마음은 여전히 채워지지 않는 장면입니다. 높은 사람이 찾아오는 기회가 있으나 서두르면 어렵고, 정성을 다해 기다리는 편이 낫습니다.","positive":"윗사람이나 후원자를 만날 기회가 열릴 수 있습니다.","caution":"기회가 보여 무리하게 나서면 어려움이 따를 수 있습니다.","advice":"찾아오는 기회에 성의껏 응하되 먼저 나서서 밀어붙이지는 마세요. 내 마음을 다잡는 시간을 가져 보는 편이 도움이 됩니다.","message":"기회에는 정성으로 응하고 서두르지 마세요."},{"guaN":47,"guaName":"택수곤","pos":3,"label":"六三","yinyang":"yin","text":"困于石 據于蒺藜 入于其宮 不見其妻 凶","reading":"곤우석 거우질려 입우기궁 불견기처 흉","modern":"바위에 막히고 가시덤불에 의지하게 됩니다. 집에 들어가도 아내를 보지 못하니 흉합니다.","meaning":"아래 괘의 끝에서 앞은 바위, 뒤는 가시로 막혀 진퇴양난에 빠진 장면입니다. 무리하게 밀어붙이는 자리에서 의지할 곳마저 잃어 가장 힘든 순간입니다.","positive":"스스로 한계를 인정하면 무엇을 바꿔야 할지 선명해질 수 있습니다.","caution":"무리한 선택이나 고집은 가까운 사람까지 멀어지게 할 수 있습니다.","advice":"지금은 앞으로 밀어붙이기보다 멈추고 가까운 사람과 상황을 솔직히 나누세요. 필요하다면 전문가나 주변의 도움을 받아 보세요.","message":"막다른 곳에서는 멈추고 도움을 구하세요."},{"guaN":47,"guaName":"택수곤","pos":4,"label":"九四","yinyang":"yang","text":"來徐徐 困于金車 吝 有終","reading":"래서서 곤우금거 린 유종","modern":"오는 것이 느릿느릿합니다. 쇠로 된 수레에 막혀 곤란합니다. 아쉬움이 있으나 끝은 있습니다.","meaning":"위 괘의 시작에서 도우려는 이가 있지만 큰 수레(권세) 때문에 느리게 오는 장면입니다. 도움이 더디고 아쉽지만 결국 닿는 때가 있습니다.","positive":"느리더라도 도움이 닿는 길이 열려 있어 마무리까지 갈 수 있습니다.","caution":"더딘 속도에 조급해하면 오히려 관계가 틀어질 수 있습니다.","advice":"도움이 늦어지는 이유를 이해하고 기다리는 마음으로 소통하세요. 필요한 연락은 꾸준히 이어 가는 편이 좋습니다.","message":"더딘 도움도 끝은 있습니다."},{"guaN":47,"guaName":"택수곤","pos":5,"label":"九五","yinyang":"yang","text":"劓刖 困于赤紱 乃徐有說 利用祭祀","reading":"의월 곤우적불 내서유열 리용제사","modern":"코와 발이 베이는 형벌을 받듯 아랫사람의 도움도 끊기고 붉은 예복(적불)을 입은 이에게도 곤란을 겪습니다. 천천히 기쁨이 찾아오니 제사를 올리는 것이 이롭습니다.","meaning":"위 괘의 중심에서 높은 자리에 있어도 아래의 도움을 잃고 위아래로 막힌 장면입니다. 정성을 다해 바르게 하면 시간이 지나 점차 풀리며 기쁨을 얻을 수 있습니다.","positive":"정성과 바른 태도로 시간이 지나면서 막힌 곳이 풀릴 가능성이 있습니다.","caution":"높은 자리라고 혼자 해결하려 하면 더 고립될 수 있습니다.","advice":"마음을 다해 진심을 보이고 시간이 필요한 일은 기다려 주세요. 아래 사람의 목소리도 다시 들어 보는 편이 도움이 됩니다.","message":"정성으로 기다리면 서서히 풀립니다."},{"guaN":47,"guaName":"택수곤","pos":6,"label":"上六","yinyang":"yin","text":"困于葛藟 于臲卼 曰動悔 有悔 征吉","reading":"곤우갈류 우얼올 왈동회 유회 정길","modern":"칡덩굴에 얽히고 위태로운 곳에 있습니다. 움직이면 후회한다고 말합니다. 후회를 안고 나아가면 길합니다.","meaning":"곤궁의 끝에서 얽매인 것이 많아 움직일 때마다 후회가 앞서는 장면입니다. 이제 후회하는 마음을 인정하고 한 걸음 나아가면 막힌 곤경에서 빠져나올 수 있습니다.","positive":"어려움의 끝에서 결단하면 곤궁에서 빠져나올 기회가 있습니다.","caution":"후회에 사로잡혀 아무것도 하지 않으면 얽힌 상태가 이어질 수 있습니다.","advice":"후회되는 일을 적고, 그중 지금 바꿀 수 있는 하나를 골라 실행해 보세요. 작은 변화를 시작하는 편이 도움이 됩니다.","message":"후회를 안고 한 걸음 나아가세요."}],"yong":null},"48":{"n":48,"name":"수풍정","han":"水風井","upper":"감","lower":"손","upperHan":"坎","lowerHan":"巽","bits":[0,1,1,0,1,0],"binary":"011010","gua":{"text":"改邑不改井 无喪无得 往來井井 汔至 亦未繘井 羸其瓶 凶","reading":"개읍불개정 무상무득 왕래정정 흘지 역미율정 리기병 흉","modern":"고을은 바꿔도 우물은 바꾸지 못합니다. 잃음도 얻음도 없습니다. 오가는 사람마다 우물을 이용합니다. 거의 다 이르렀는데 두레박줄이 우물에 닿지 못하거나 두레박을 깨뜨리면 흉합니다.","symbol":"위에는 물(坎), 아래에는 바람 또는 나무(巽)가 있어 나무 두레박이 물을 길어 올리는 우물의 모습입니다. 변치 않는 근원과 그것을 길어 쓰는 일을 뜻하는 괘입니다.","situation":"겉은 변해도 바뀌지 않는 근본을 가꾸고 나눠야 하는 국면입니다. 우물처럼 꾸준히 채우고 정비하며 사람들에게 쓰임이 되도록 하는 일이 중요합니다.","positive":"꾸준히 쌓은 실력과 기반을 사람들에게 나눠 쓸모 있게 할 수 있는 시기입니다.","caution":"끝에서 방심하거나 도구를 소홀히 하면 지금까지의 노력이 헛될 수 있습니다.","direction":"나의 근본이 되는 역량과 자원을 정리하고 꾸준히 보수하세요. 끝맺음 직전에 마지막 점검과 도구 점검을 거치는 편이 도움이 됩니다.","message":"근본을 가꾸고 나누는 것이 힘입니다."},"yao":[{"guaN":48,"guaName":"수풍정","pos":1,"label":"初六","yinyang":"yin","text":"井泥不食 舊井无禽","reading":"정니불식 구정무금","modern":"우물이 진흙투성이라 먹지 못합니다. 오래된 우물에는 새도 찾아오지 않습니다.","meaning":"맨 아래 바닥 단계에서 진흙이 쌓여 쓸 수 없는 우물과 같은 장면입니다. 기반이 오래 방치되어 사람들이 찾지 않는 상태이니 먼저 가꾸는 일이 필요합니다.","positive":"문제가 바닥에서 드러나 어디부터 손봐야 할지 알기 쉽습니다.","caution":"방치된 상태로 두면 기회가 와도 활용하지 못할 수 있습니다.","advice":"묵은 습관이나 오래된 방식 중 정리할 것을 하나씩 걷어 내세요. 기본기를 다시 다지는 데 시간을 쓰는 편이 도움이 됩니다.","message":"먼저 바닥의 진흙부터 걷어 내세요."},{"guaN":48,"guaName":"수풍정","pos":2,"label":"九二","yinyang":"yang","text":"井谷射鮒 甕敝漏","reading":"정곡사부 옹폐루","modern":"우물 바닥의 물이 붕어에게나 쏟아집니다. 물동이가 낡아 샙니다.","meaning":"아래 괘의 중심에서 물은 있으나 위로 길어 올리지 못하고 아래로만 흘려보내는 장면입니다. 가진 힘이 큰 곳에 쓰이지 못하고 도구가 낡아 새어 나가고 있습니다.","positive":"쓸 만한 실력이나 자원은 이미 가지고 있습니다.","caution":"도구와 방법이 낡으면 가진 힘이 제대로 쓰이지 못하고 새어 나갈 수 있습니다.","advice":"내 능력을 더 큰 곳에 쓸 방법과 낡은 도구의 교체 여부를 살펴보세요. 쓰임을 넓혀 줄 사람을 찾아보는 편이 좋습니다.","message":"가진 힘이 새지 않게 도구를 고치세요."},{"guaN":48,"guaName":"수풍정","pos":3,"label":"九三","yinyang":"yang","text":"井渫不食 爲我心惻 可用汲 王明 並受其福","reading":"정설불식 위아심측 가용급 왕명 병수기복","modern":"우물을 치웠는데도 마시지 않습니다. 내 마음이 안타깝습니다. 길어 쓸 수 있으니 왕이 밝으면 함께 그 복을 받습니다.","meaning":"아래 괘의 끝에서 깨끗이 정비했는데도 알아주는 이가 없어 쓰이지 못하는 전환기입니다. 인정받지 못해 안타까우나 알아보는 사람을 만나면 함께 이로움을 누릴 수 있습니다.","positive":"준비를 갖춰 두었으니 알아보는 사람을 만나면 바로 쓰임이 될 수 있습니다.","caution":"알아주지 않는다고 낙담하면 준비한 것을 스스로 놓아 버릴 수 있습니다.","advice":"내 실력과 성과를 알릴 수 있는 방법을 찾아보세요. 알아봐 줄 사람에게 보일 기회를 만드는 편이 도움이 됩니다.","message":"준비된 실력은 알릴 때 쓰임이 됩니다."},{"guaN":48,"guaName":"수풍정","pos":4,"label":"六四","yinyang":"yin","text":"井甃 无咎","reading":"정추 무구","modern":"우물에 벽돌을 쌓아 수리합니다. 허물이 없습니다.","meaning":"위 괘의 시작에서 우물 안쪽을 벽돌로 단단히 쌓아 보수하는 장면입니다. 당장 눈에 띄는 성과보다 기반을 보수하는 일이 앞으로의 안정을 만듭니다.","positive":"기반을 보수하면 이후의 안정과 쓰임이 한결 수월해질 수 있습니다.","caution":"지금 당장의 성과가 없다고 보수를 건너뛰면 나중에 더 큰 수리가 필요해질 수 있습니다.","advice":"급하지 않아도 중요한 점검과 정비 일정을 정해 실천하세요. 눈에 띄지 않는 준비의 가치를 스스로 인정해 주는 편이 좋습니다.","message":"보수하는 시간도 성과의 일부입니다."},{"guaN":48,"guaName":"수풍정","pos":5,"label":"九五","yinyang":"yang","text":"井洌 寒泉食","reading":"정렬 한천식","modern":"우물물이 맑고 차가워 시원한 샘물을 마십니다.","meaning":"위 괘의 중심에서 맑고 차가운 물이 사람들에게 실제로 쓰이는 장면입니다. 꾸준히 가꾼 결과가 열매를 맺어 많은 사람에게 도움이 되는 때입니다.","positive":"오랜 노력이 인정받고 사람들에게 도움이 되는 결실을 얻기 쉽습니다.","caution":"인정받는 시기에 관리를 늦추면 맑음이 흐려질 수 있습니다.","advice":"지금의 수준을 유지하는 점검 습관을 이어 가세요. 얻은 것을 주변과 기꺼이 나누는 편이 도움이 됩니다.","message":"맑게 가꾼 것은 나눌 때 빛납니다."},{"guaN":48,"guaName":"수풍정","pos":6,"label":"上六","yinyang":"yin","text":"井收勿幕 有孚元吉","reading":"정수물막 유부원길","modern":"우물물을 길어 올리되 덮개를 덮지 마십시오. 믿음이 있으면 크게 길합니다.","meaning":"마지막 단계에서 우물이 가득 차 누구나 마음껏 길어 쓸 수 있도록 열어 두는 장면입니다. 쌓아 온 것을 독점하지 않고 널리 열어 둘 때 신뢰가 커집니다.","positive":"쌓은 것을 열어 나누면 신뢰와 보람이 오래 이어지기 쉽습니다.","caution":"얻은 것을 닫아 두고 혼자만 쓰면 쌓은 가치가 빛을 잃을 수 있습니다.","advice":"내가 쌓은 지식이나 경험을 나눌 방법을 정해 실행해 보세요. 사람들이 쉽게 쓸 수 있도록 열어 두는 편이 도움이 됩니다.","message":"덮지 말고 열어 두면 오래갑니다."}],"yong":null},"49":{"n":49,"name":"택화혁","han":"澤火革","upper":"태","lower":"리","upperHan":"兌","lowerHan":"離","bits":[1,0,1,1,1,0],"binary":"101110","gua":{"text":"已日乃孚 元亨利貞 悔亡","reading":"이일내부 원형리정 회망","modern":"때가 지난 뒤에야 믿음을 얻습니다. 크게 형통하고 바르게 하면 이롭습니다. 후회할 일이 사라집니다.","symbol":"위는 연못(태), 아래는 불(리)입니다. 물과 불이 맞닿아 서로를 바꾸려 하듯, 낡은 틀을 고쳐 새롭게 만드는 변화를 나타냅니다.","situation":"지금까지의 방식이 한계에 이르러 어떤 식으로든 바꿔야 한다는 목소리가 커지는 국면입니다. 다만 변화는 주변의 믿음과 때가 갖춰져야 받아들여지기 쉽습니다. 서둘러 뒤집기보다 충분히 설명하고 기다린 뒤 움직이는 편이 도움이 됩니다.","positive":"명분이 바르고 사람들의 신뢰를 얻은 변화는 후회가 줄고 오래 갈 가능성이 큽니다.","caution":"준비 없이 바꾸거나 나만 옳다고 밀어붙이면 반발이 커지고 변화의 뜻이 흐려질 수 있습니다.","direction":"먼저 왜 바꾸어야 하는지를 분명히 하고, 관련된 사람들에게 충분히 설명해 이해를 얻으세요. 그다음 때가 무르익었을 때 단계적으로 실행하는 쪽이 안정적입니다.","message":"믿음이 쌓인 때에 바르게 바꾸세요"},"yao":[{"guaN":49,"guaName":"택화혁","pos":1,"label":"初九","yinyang":"yang","text":"鞏用黃牛之革","reading":"공용황우지혁","modern":"누런 소가죽으로 단단히 묶습니다.","meaning":"변화가 막 떠오르는 첫 단계입니다. 아직 힘도 위치도 약하니 섣불리 나서지 말고 질긴 가죽으로 묶어 두듯 자신을 단단히 붙들어 두는 장면입니다.","positive":"성급히 움직이지 않으면 준비할 시간과 기반을 얻을 수 있습니다.","caution":"변화하고 싶은 마음만 앞서 나서면 아직 약한 힘이 쉽게 꺾일 수 있습니다.","advice":"지금은 변화를 외치기보다 생각을 정리하고 필요한 근거와 동료를 모으세요. 때를 기다리는 것도 실천의 하나입니다.","message":"아직은 단단히 준비할 때입니다"},{"guaN":49,"guaName":"택화혁","pos":2,"label":"六二","yinyang":"yin","text":"已日乃革之 征吉 无咎","reading":"이일내혁지 정길 무구","modern":"때가 다 찬 뒤에야 바꿉니다. 나아가면 길하고 허물이 없습니다.","meaning":"아래 괘의 중심에서 바른 자리에 있고, 위의 강한 중심과 호응하는 위치입니다. 준비가 갖춰져 이제 실제로 바꿔도 되는 시기가 되었음을 보여 줍니다.","positive":"때와 위치, 지지하는 사람이 어우러져 변화를 시작하기에 좋은 여건입니다.","caution":"여건이 좋다고 해서 방심하거나 독단으로 하면 얻은 믿음을 잃을 수 있습니다.","advice":"충분히 준비했다면 이제 계획을 실행에 옮기세요. 다만 도와줄 윗사람이나 동료와 보조를 맞추며 나아가는 편이 좋습니다.","message":"무르익었다면 이제 움직이세요"},{"guaN":49,"guaName":"택화혁","pos":3,"label":"九三","yinyang":"yang","text":"征凶 貞厲 革言三就 有孚","reading":"정흉 정려 혁언삼취 유부","modern":"나아가면 흉하고, 고집하면 위태롭습니다. 바꾸자는 말이 세 번 충분히 오가면 믿음이 생깁니다.","meaning":"아래 괘의 끝에서 의욕이 지나치게 커지기 쉬운 자리입니다. 급하게 밀어붙이면 어려움이 생기므로 의견을 여러 차례 나누어 공감을 얻어야 하는 장면입니다.","positive":"충분히 논의하고 검토하면 처음의 조급함이 신뢰로 바뀔 수 있습니다.","caution":"속도를 내는 데만 집중하면 반대와 오해가 쌓여 일이 위태로워지기 쉽습니다.","advice":"변화안을 여러 번 공유하고 의견을 들어 고치세요. 충분히 합의가 되었다고 느낄 때 실행해도 늦지 않습니다.","message":"서두르지 말고 충분히 논의하세요"},{"guaN":49,"guaName":"택화혁","pos":4,"label":"九四","yinyang":"yang","text":"悔亡 有孚改命 吉","reading":"회망 유부개명 길","modern":"후회가 사라집니다. 믿음이 있어 명을 고치니 길합니다.","meaning":"아래 불에서 위 연못으로 넘어와 변화의 문턱을 지나는 자리입니다. 사람들의 믿음을 바탕으로 방향과 질서를 새로 정해도 되는 단계를 나타냅니다.","positive":"신뢰가 바탕이 되어 있어 새 방향을 정해도 후회가 적은 편입니다.","caution":"믿음을 얻었다는 이유로 처음의 뜻과 달리 사사로운 이익으로 흐를 수 있습니다.","advice":"새 방침이나 규칙을 정할 때는 처음의 명분에 맞는지 거듭 확인하세요. 달라진 점을 투명하게 알리면 도움이 됩니다.","message":"믿음 위에 새 방향을 세우세요"},{"guaN":49,"guaName":"택화혁","pos":5,"label":"九五","yinyang":"yang","text":"大人虎變 未占有孚","reading":"대인호변 미점유부","modern":"대인이 호랑이처럼 선명하게 바꿉니다. 점을 치지 않아도 믿음이 있습니다.","meaning":"위 괘의 중심이자 변화를 이끄는 핵심 자리입니다. 호랑이 무늬가 분명하듯 뜻이 뚜렷하고 공정한 변화는 설명하지 않아도 사람들이 따르기 쉬운 장면입니다.","positive":"방향이 분명하고 공정하면 많은 사람이 자연스럽게 변화에 동참합니다.","caution":"내 확신만 믿고 이유를 설명하지 않으면 믿음은 금방 흔들릴 수 있습니다.","advice":"변화의 목적과 기준을 선명하게 드러내고 결과로 보여 주세요. 말보다 일관된 행동이 믿음을 쌓습니다.","message":"뜻을 분명히 하면 사람이 따릅니다"},{"guaN":49,"guaName":"택화혁","pos":6,"label":"上六","yinyang":"yin","text":"君子豹變 小人革面 征凶 居貞吉","reading":"군자표변 소인혁면 정흉 거정길","modern":"군자는 표범처럼 무늬가 달라지고, 소인은 얼굴빛만 바뀝니다. 더 나아가면 흉하고, 머물러 바르게 지키면 길합니다.","meaning":"변화가 거의 완성된 끝자리입니다. 바뀐 모습이 자리 잡는 때이므로 더 큰 개혁을 이어 가기보다 이루어진 변화를 지키고 다듬는 장면입니다.","positive":"변화가 자리 잡아 안정되면 새 방식이 일상이 되며 편안해집니다.","caution":"변화를 멈추지 않고 더 몰아치면 피로와 반발이 생길 수 있습니다.","advice":"이제는 새 방식이 뿌리내리도록 점검하고 정착시키는 데 힘쓰세요. 겉만 바뀐 부분이 없는지도 살펴보세요.","message":"이룬 변화는 지키고 다듬으세요"}],"yong":null},"50":{"n":50,"name":"화풍정","han":"火風鼎","upper":"리","lower":"손","upperHan":"離","lowerHan":"巽","bits":[0,1,1,1,0,1],"binary":"011101","gua":{"text":"元吉 亨","reading":"원길 형","modern":"크게 좋고 형통합니다.","symbol":"위는 불(리), 아래는 바람·나무(손)입니다. 나무에 불을 지펴 솥에 음식을 익히듯, 재료를 쓸모 있게 바꾸어 사람을 길러 내는 모습입니다.","situation":"낡은 것을 바꾼 뒤 새 질서를 세우고 안정시키는 국면입니다. 솥이 세 발로 서듯 능력과 사람, 환경의 균형이 중요합니다. 지금 가진 재료를 더 쓸모 있게 가꾸는 일과 잘 맞는 시기입니다.","positive":"있는 재료를 잘 다듬고 인재를 키우면 모두에게 도움이 되는 성과로 이어지기 쉽습니다.","caution":"감당할 수 없는 일을 떠맡으면 솥발이 부러지듯 균형을 잃고 낭패를 볼 수 있습니다.","direction":"지금 가진 자원으로 무엇을 어떻게 익혀 낼지 정하고, 능력에 맞는 범위부터 차근차근 키우세요. 사람과 역할의 균형을 살피는 것이 핵심입니다.","message":"균형 있게 담고 알맞게 익히세요"},"yao":[{"guaN":50,"guaName":"화풍정","pos":1,"label":"初六","yinyang":"yin","text":"鼎顚趾 利出否 得妾以其子 无咎","reading":"정전지 리출비 득첩이기자 무구","modern":"솥의 발이 뒤집혔습니다. 안의 나쁜 것을 쏟아 내기에는 이롭습니다. 첩을 얻어 그 아들까지 얻으니 허물이 없습니다.","meaning":"막 시작하는 자리에서 솥을 엎어 묵은 찌꺼기를 비우는 장면입니다. 처음에는 흐트러져 보여도 비워야 새것을 담을 수 있다는 뜻으로 볼 수 있습니다.","positive":"낡고 쓸모없는 것을 비우면 새로 시작할 공간이 마련됩니다.","caution":"뒤집힌 모습에만 마음을 쓰면 비우는 일의 의미를 놓칠 수 있습니다.","advice":"익숙하지만 더는 도움이 안 되는 습관이나 방식을 정리하세요. 낮은 자리의 사람이라도 쓸모를 찾아 주면 도움이 됩니다.","message":"비워야 새것을 담을 수 있습니다"},{"guaN":50,"guaName":"화풍정","pos":2,"label":"九二","yinyang":"yang","text":"鼎有實 我仇有疾 不我能卽 吉","reading":"정유실 아구유질 불아능즉 길","modern":"솥 안에 음식이 가득합니다. 나의 짝(원수)에게 병이 있어 나에게 가까이 오지 못하니 길합니다.","meaning":"아래 괘의 중심에서 실속이 가득한 자리입니다. 알찬 내실이 있으면 방해하려는 이가 있어도 가까이 오지 못하는 장면으로 읽을 수 있습니다.","positive":"내용이 충실하면 질투나 방해에도 흔들리지 않고 중심을 지킬 수 있습니다.","caution":"가득 찬 것에 만족해 스스로를 점검하지 않으면 허점이 생길 수 있습니다.","advice":"내실을 쌓는 데 집중하고 가까이 오려는 유혹이나 시비에는 흔들리지 마세요. 지키는 것이 곧 힘입니다.","message":"내실이 가득하면 흔들리지 않습니다"},{"guaN":50,"guaName":"화풍정","pos":3,"label":"九三","yinyang":"yang","text":"鼎耳革 其行塞 雉膏不食 方雨虧悔 終吉","reading":"정이혁 기행색 치고불식 방우휴회 종길","modern":"솥귀가 바뀌어 솥을 옮기지 못합니다. 꿩기름 같은 좋은 음식을 먹지 못합니다. 비가 내려 후회가 줄어들면 끝내 길합니다.","meaning":"아래 괘의 끝에서 좋은 것이 준비되어 있어도 손잡이가 막혀 전해지지 못하는 장면입니다. 쓰임이 막힌 답답함 속에서 인내하는 때입니다.","positive":"막힌 시간을 지나며 마음을 가다듬으면 결국 좋은 방향으로 풀릴 수 있습니다.","caution":"인정받지 못한다는 답답함에 성급히 행동하면 후회가 늘 수 있습니다.","advice":"알아주지 않아도 실력을 가꾸며 기다리세요. 소통이 막혔다면 전달하는 방식을 점검해 보는 것도 도움이 됩니다.","message":"막힘은 잠시, 때를 기다리세요"},{"guaN":50,"guaName":"화풍정","pos":4,"label":"九四","yinyang":"yang","text":"鼎折足 覆公餗 其形渥 凶","reading":"정절족 복공속 기형악 흉","modern":"솥의 발이 부러져 공(公)의 음식을 엎었습니다. 그 모습이 흠뻑 젖어 흉합니다.","meaning":"위 괘의 시작에서 윗자리와 가까워 큰일을 맡았으나 감당하지 못하는 장면입니다. 능력에 비해 무거운 책임을 졌을 때의 부끄러움을 뜻합니다.","positive":"실패를 인정하고 점검하면 맡을 일의 크기를 바로잡는 계기가 됩니다.","caution":"내 역량과 도울 사람을 헤아리지 않고 큰 책임을 맡으면 낭패가 따르기 쉽습니다.","advice":"맡은 일이 버겁다면 일찍 도움을 청하고 범위를 조정하세요. 믿고 맡긴 사람에게 정직하게 알리는 것이 먼저입니다.","message":"감당할 만큼만 맡으세요"},{"guaN":50,"guaName":"화풍정","pos":5,"label":"六五","yinyang":"yin","text":"鼎黃耳金鉉 利貞","reading":"정황이금현 리정","modern":"솥에 누런 귀와 쇠고리가 있습니다. 바르게 하면 이롭습니다.","meaning":"위 괘의 중심이자 핵심 자리로, 부드럽게 중심을 지키며 든든한 협력자를 만나 솥을 잘 들어 올리는 모습입니다. 겸손함과 단단한 도움이 어우러진 장면입니다.","positive":"유연한 태도로 중심을 지키면 단단한 협력을 얻어 일이 안정되기 쉽습니다.","caution":"좋은 자리에 있다고 해서 협력자의 조언을 흘려들으면 균형이 깨질 수 있습니다.","advice":"중심에서 열린 마음으로 사람들의 말을 듣고 바른 원칙을 지키세요. 믿을 만한 조력자와 역할을 나누면 좋습니다.","message":"열린 중심이 단단한 협력을 부릅니다"},{"guaN":50,"guaName":"화풍정","pos":6,"label":"上九","yinyang":"yang","text":"鼎玉鉉 大吉 无不利","reading":"정옥현 대길 무불리","modern":"솥에 옥고리가 달려 있습니다. 크게 길하고 이롭지 않은 것이 없습니다.","meaning":"끝자리에서 강함과 부드러움이 알맞게 어우러져 옥처럼 온화해진 모습입니다. 오랜 정비가 마무리되어 쓰임이 잘 이루어지는 장면입니다.","positive":"단단함과 온화함이 균형을 이루어 쓰는 사람도 받는 사람도 편안한 상태입니다.","caution":"잘 갖춰진 상태에서 안주하면 다음 변화에 둔해질 수 있습니다.","advice":"이룬 것을 부드럽게 나누고 다음 세대나 동료에게 전해 주세요. 쓰임이 오래가도록 관리하는 습관이 도움이 됩니다.","message":"단단함에 온화함을 더해 나누세요"}],"yong":null},"51":{"n":51,"name":"진위뢰","han":"震爲雷","upper":"진","lower":"진","upperHan":"震","lowerHan":"震","bits":[1,0,0,1,0,0],"binary":"100100","gua":{"text":"亨 震來虩虩 笑言啞啞 震驚百里 不喪匕鬯","reading":"형 진래혁혁 소언액액 진경백리 불상비창","modern":"형통합니다. 우레가 칠 때 두려워 조심하다가 나중에는 웃고 말합니다. 우레가 백 리를 놀라게 해도 제사의 숟가락과 향주를 놓치지 않습니다.","symbol":"위아래 모두 우레(진)로, 우레가 거듭 울리는 모습입니다. 갑작스러운 충격과 놀람, 그리고 그 속에서 깨어나는 움직임을 나타냅니다.","situation":"예상하지 못한 사건이나 큰 변화로 마음이 크게 흔들리는 국면입니다. 놀라는 것은 자연스러운 일이며 오히려 조심하는 계기가 됩니다. 소란 속에서도 해야 할 기본을 놓치지 않으면 지나고 나서 웃을 수 있는 경우가 많습니다.","positive":"놀람을 계기로 스스로를 점검하고 신중해지면 성장의 기회가 될 수 있습니다.","caution":"놀란 나머지 허둥대거나 기본을 잊으면 작은 일이 큰 혼란으로 번질 수 있습니다.","direction":"충격이 왔을 때는 먼저 숨을 고르고 지금 지켜야 할 핵심이 무엇인지 확인하세요. 소동이 가라앉은 뒤에는 무엇을 배웠는지 정리해 두는 것이 좋습니다.","message":"놀라도 중심은 놓치지 마세요"},"yao":[{"guaN":51,"guaName":"진위뢰","pos":1,"label":"初九","yinyang":"yang","text":"震來虩虩 後笑言啞啞 吉","reading":"진래혁혁 후소언액액 길","modern":"우레가 칠 때 두려워 조심하다가, 나중에는 웃고 말합니다. 길합니다.","meaning":"충격의 첫 순간을 맞는 자리로, 처음에는 놀라고 두렵지만 그 두려움을 삼가는 마음으로 바꿀 수 있는 장면입니다. 시작 단계의 조심이 훗날의 여유가 됩니다.","positive":"처음에 신중하게 대처하면 일이 지나간 뒤 편안히 웃을 수 있습니다.","caution":"두려움에 얼어붙어 아무것도 하지 않으면 대응할 시기를 놓칠 수 있습니다.","advice":"놀란 마음을 인정하되 할 수 있는 작은 일부터 차분히 시작하세요. 조심하는 태도를 잃지 않으면 됩니다.","message":"두려움은 조심으로 바꾸세요"},{"guaN":51,"guaName":"진위뢰","pos":2,"label":"六二","yinyang":"yin","text":"震來厲 億喪貝 躋于九陵 勿逐 七日得","reading":"진래려 억상패 제우구릉 물축 칠일득","modern":"우레가 오니 위태롭습니다. 큰 재물을 잃을 듯하니 높은 언덕에 올라갑니다. 쫓아가지 않으면 이레 만에 되찾습니다.","meaning":"아래 괘의 중심에서 충격으로 손해를 입을 수 있는 장면입니다. 서둘러 따라가기보다 안전한 높은 곳으로 물러나 때를 기다리면 잃은 것이 돌아올 수도 있습니다.","positive":"잠시 물러나 기다리면 잃었다고 여긴 것을 되찾을 여지가 생깁니다.","caution":"손실을 당장 만회하려고 쫓아가면 더 큰 손해로 이어질 수 있습니다.","advice":"급한 마음에 무리하게 회복하려 하지 말고 안전한 자리로 물러나 상황을 지켜보세요. 시간이 해결해 주는 부분도 있습니다.","message":"쫓지 말고 물러나 기다리세요"},{"guaN":51,"guaName":"진위뢰","pos":3,"label":"六三","yinyang":"yin","text":"震蘇蘇 震行无眚","reading":"진소소 진행무생","modern":"우레에 정신이 얼떨떨합니다. 놀라서 움직이면 재앙이 없습니다.","meaning":"아래 괘의 끝에서 놀람이 극에 달해 멍해지는 전환의 자리입니다. 그래도 정신을 차려 움직이면 큰 잘못은 피할 수 있다는 장면입니다.","positive":"혼란 속에서도 한 걸음 내딛는 행동이 상황을 바꾸는 계기가 됩니다.","caution":"멍한 상태에서 판단하거나 제자리에 오래 머물면 문제가 길어질 수 있습니다.","advice":"생각이 정리되지 않을 때는 우선 몸을 움직여 환경을 바꿔 보세요. 믿을 만한 사람에게 상황을 이야기하는 것도 도움이 됩니다.","message":"멍할 땐 먼저 한 걸음 움직이세요"},{"guaN":51,"guaName":"진위뢰","pos":4,"label":"九四","yinyang":"yang","text":"震遂泥","reading":"진수니","modern":"우레가 쳐서 진흙에 빠집니다.","meaning":"위 괘의 시작이지만 강한 힘이 두 음 사이에 끼여 움직이기 어려운 자리입니다. 충격에 빠져 힘을 쓰지 못하고 진흙 속에 갇힌 듯한 장면입니다.","positive":"가만히 멈추어 가라앉은 시간을 보내며 다음 방향을 생각해 볼 수 있습니다.","caution":"빠져나오려 애쓸수록 더 깊이 빠질 수 있고 판단이 흐려질 수 있습니다.","advice":"지금은 힘을 빼고 무엇이 나를 붙잡고 있는지 살펴보세요. 믿을 만한 도움을 구하고 작은 발판부터 마련하는 편이 좋습니다.","message":"서둘러 빠져나오기보다 발판을 찾으세요"},{"guaN":51,"guaName":"진위뢰","pos":5,"label":"六五","yinyang":"yin","text":"震往來厲 億无喪有事","reading":"진왕래려 억무상유사","modern":"우레가 오가며 위태롭습니다. 크게 잃지는 않으나 일은 있습니다.","meaning":"위 괘의 중심 자리로 충격이 거듭 오가는 상황입니다. 위태롭지만 중심을 지키며 맡은 일을 놓지 않으면 큰 손실은 피할 수 있는 장면입니다.","positive":"자기 자리와 맡은 일에 충실하면 거듭된 충격에도 큰 잃음은 피하기 쉽습니다.","caution":"연이은 변화에 지쳐 중심을 놓으면 맡은 책임이 흔들릴 수 있습니다.","advice":"여러 가지 소란 속에서도 가장 중요한 일 한두 가지를 정해 지키세요. 쉬어 가며 판단의 균형을 유지하는 것이 좋습니다.","message":"핵심 한 가지를 지키며 버티세요"},{"guaN":51,"guaName":"진위뢰","pos":6,"label":"上六","yinyang":"yin","text":"震索索 視矍矍 征凶 震不于其躬 于其鄰 无咎 婚媾有言","reading":"진삭삭 시확확 정흉 진불우기궁 우기린 무구 혼구유언","modern":"우레에 오들오들 떨고 두리번거립니다. 나아가면 흉합니다. 우레가 내 몸이 아니라 이웃에 닿았을 때 대비하면 허물이 없습니다. 혼인 맺은 사이에는 말이 있습니다.","meaning":"끝자리에서 두려움이 지나쳐 안절부절못하는 장면입니다. 충격이 내게 닿기 전에 이웃의 일을 보고 미리 대비하면 되고, 가까운 관계에서는 오해로 말이 오갈 수 있습니다.","positive":"남의 일을 거울삼아 미리 대비하면 큰 어려움을 피할 수 있습니다.","caution":"두려움에 휩쓸려 무리하게 움직이면 어려움이 커지고 가까운 사이에서도 말다툼이 생길 수 있습니다.","advice":"불안할수록 큰 결정은 미루고 주변 사례를 통해 미리 점검하세요. 가까운 사람과는 오해가 없도록 차분히 이야기하는 편이 좋습니다.","message":"이웃의 일을 보고 미리 대비하세요"}],"yong":null},"52":{"n":52,"name":"간위산","han":"艮爲山","upper":"간","lower":"간","upperHan":"艮","lowerHan":"艮","bits":[0,0,1,0,0,1],"binary":"001001","gua":{"text":"艮其背 不獲其身 行其庭 不見其人 无咎","reading":"간기배 불획기신 행기정 불견기인 무구","modern":"등에서 멈추면 자기 몸을 의식하지 않고, 뜰에서 걸어도 사람을 보지 않습니다. 허물이 없습니다.","symbol":"위아래 모두 산(간)으로, 산이 거듭 우뚝 서 있는 모습입니다. 멈춤과 고요함, 그리고 그칠 곳에서 그치는 지혜를 나타냅니다.","situation":"욕심이나 걱정이 앞서 마음이 분주한 때, 일부러 멈추고 가라앉힐 것을 권하는 국면입니다. 눈앞의 이익과 남의 시선에서 한 걸음 물러나면 오히려 방향이 선명해집니다. 멈춤은 포기가 아니라 다음 걸음을 위한 정돈입니다.","positive":"잡념과 욕심을 내려놓으면 마음이 고요해지고 판단이 맑아질 수 있습니다.","caution":"멈춤이 지나쳐 굳어 버리거나 아예 마음을 닫아 버리면 소통이 끊길 수 있습니다.","direction":"그칠 때와 움직일 때를 구분하는 것이 핵심입니다. 지금은 무리한 일을 줄이고 마음을 가라앉힌 뒤, 때가 되면 다시 움직일 기준을 정해 두세요.","message":"멈출 곳에서 멈추면 길이 보입니다"},"yao":[{"guaN":52,"guaName":"간위산","pos":1,"label":"初六","yinyang":"yin","text":"艮其趾 无咎 利永貞","reading":"간기지 무구 리영정","modern":"발에서 멈춥니다. 허물이 없고 오래도록 바르게 하면 이롭습니다.","meaning":"막 움직이려는 발 단계에서 멈추는 장면입니다. 행동으로 옮기기 전에 멈추면 실수를 줄일 수 있고, 그 마음을 오래 이어 가야 한다는 뜻입니다.","positive":"첫걸음 전에 멈추어 생각하면 잘못 들어서는 일을 막을 수 있습니다.","caution":"한 번 멈춘 뒤 곧 흐지부지되면 같은 실수가 반복될 수 있습니다.","advice":"시작하기 전에 이 일이 정말 필요한지 한 번 더 확인하세요. 바른 원칙을 꾸준히 지키는 것이 중요합니다.","message":"움직이기 전에 먼저 멈추세요"},{"guaN":52,"guaName":"간위산","pos":2,"label":"六二","yinyang":"yin","text":"艮其腓 不拯其隨 其心不快","reading":"간기비 불증기수 기심불쾌","modern":"장딴지에서 멈춥니다. 따르는 윗사람을 구하지 못하니 마음이 즐겁지 않습니다.","meaning":"아래 괘의 중심 자리지만 위의 강한 자리가 멈춰 있어 내 의지대로 움직이기 어려운 장면입니다. 따르는 입장이라 옳다고 여겨도 말리지 못해 마음이 불편합니다.","positive":"내 한계를 알고 받아들이면 무리한 충돌을 피할 수 있습니다.","caution":"불편한 마음을 억누르기만 하면 불만이 쌓여 관계가 어색해질 수 있습니다.","advice":"내 힘으로 바꿀 수 없는 일은 정중하게 의견만 전하고 내려놓는 연습을 하세요. 마음이 무거우면 믿을 만한 사람과 이야기해 보세요.","message":"바꿀 수 없는 일은 내려놓으세요"},{"guaN":52,"guaName":"간위산","pos":3,"label":"九三","yinyang":"yang","text":"艮其限 列其夤 厲薰心","reading":"간기한 렬기인 려훈심","modern":"허리에서 멈춥니다. 등뼈 살이 찢어집니다. 위태로움이 마음을 태웁니다.","meaning":"아래 괘의 끝에서 억지로 멈추려다 몸과 마음이 갈라지는 장면입니다. 과열된 상황에서 무리하게 틀어막으면 오히려 마음이 타들어 갈 수 있습니다.","positive":"무리한 억제가 위험하다는 점을 알아차리면 방식을 바꿀 기회가 됩니다.","caution":"참기만 하다 몸이 굳고 마음이 타서 갈등이 커질 수 있습니다.","advice":"억지로 누르기보다 쉬는 시간과 해소할 통로를 마련하세요. 몸과 마음이 힘들면 휴식을 우선하는 편이 좋습니다.","message":"억지로 누르지 말고 풀어 주세요"},{"guaN":52,"guaName":"간위산","pos":4,"label":"六四","yinyang":"yin","text":"艮其身 无咎","reading":"간기신 무구","modern":"몸에서 멈춥니다. 허물이 없습니다.","meaning":"위 괘의 시작이자 윗자리와 가까운 자리로, 몸가짐 전체를 바르게 가다듬어 멈추는 장면입니다. 큰일을 하기보다 자신을 단속하는 데서 허물을 피합니다.","positive":"자신의 태도와 습관을 정돈하면 불필요한 잘못을 막을 수 있습니다.","caution":"나를 다스리는 데만 머물면 주변과의 협력이 소홀해질 수 있습니다.","advice":"말과 행동을 가볍게 하지 말고 한 템포 느리게 하세요. 맡은 역할 안에서 꾸준히 몸가짐을 바르게 하는 것이 도움이 됩니다.","message":"먼저 내 몸가짐을 바로잡으세요"},{"guaN":52,"guaName":"간위산","pos":5,"label":"六五","yinyang":"yin","text":"艮其輔 言有序 悔亡","reading":"간기보 언유서 회망","modern":"턱에서 멈춥니다. 말에 순서가 있으니 후회가 사라집니다.","meaning":"위 괘의 중심 자리로, 말을 멈추고 가려 하는 장면입니다. 중심에 있는 사람이 할 말과 안 할 말을 구분하고 차례를 지키면 후회가 줄어듭니다.","positive":"말을 아끼고 순서를 지키면 신뢰가 쌓이고 후회할 일이 줄어듭니다.","caution":"감정이 앞선 말이나 불필요한 말이 오해와 갈등을 부를 수 있습니다.","advice":"중요한 이야기를 하기 전에 요점을 정리하고 차례를 정해 두세요. 화가 날 때는 답을 잠시 미루는 습관이 도움이 됩니다.","message":"말은 아끼고 차례를 지키세요"},{"guaN":52,"guaName":"간위산","pos":6,"label":"上九","yinyang":"yang","text":"敦艮 吉","reading":"돈간 길","modern":"두텁게 멈춥니다. 길합니다.","meaning":"멈춤의 끝자리로, 흔들림 없이 후하게 그침을 이룬 상태입니다. 이미 단단히 자리 잡은 안정으로 멈춤이 깊은 덕이 된 장면입니다.","positive":"오래 쌓은 절제와 차분함이 안정과 신뢰로 열매를 맺습니다.","caution":"멈춤에 익숙해져 필요한 때에도 움직이지 않으면 기회를 놓칠 수 있습니다.","advice":"지금의 안정을 지키되 움직일 때가 오면 가볍게 나설 준비도 해 두세요. 두터운 마음으로 주변을 돌보는 일도 좋습니다.","message":"두터운 멈춤이 안정을 지킵니다"}],"yong":null},"53":{"n":53,"name":"풍산점","han":"風山漸","upper":"손","lower":"간","upperHan":"巽","lowerHan":"艮","bits":[0,0,1,0,1,1],"binary":"001011","gua":{"text":"女歸吉 利貞","reading":"녀귀길 리정","modern":"여자가 시집가는 일은 길합니다. 바르게 하는 것이 이롭습니다.","symbol":"산 위에 바람(나무)이 있는 모습으로, 산 위의 나무가 오랜 시간에 걸쳐 조금씩 자라듯 한 단계씩 나아가는 괘입니다. 혼인의 순서처럼 절차를 밟는 전진을 뜻합니다.","situation":"일이나 관계가 서서히, 순서대로 진행되는 국면입니다. 빨리 결과를 내고 싶은 마음이 들어도 단계를 건너뛰면 오히려 탈이 나기 쉽습니다. 차분히 절차를 지키는 쪽이 안정적인 결과로 이어질 가능성이 큽니다.","positive":"기초를 다지며 천천히 나아가기 때문에 한번 쌓은 신뢰와 성과가 오래 유지되기 쉽습니다.","caution":"속도가 느리다고 조급해져 순서를 건너뛰거나 형식만 갖추려 하면 힘이 빠질 수 있습니다.","direction":"큰 도약보다 한 계단씩 오르는 방식이 어울립니다. 지금 어느 단계에 있는지 확인하고, 다음 단계의 준비를 차근차근 하는 편이 도움이 됩니다.","message":"서두르지 않고 순서대로 가면 길이 열립니다."},"yao":[{"guaN":53,"guaName":"풍산점","pos":1,"label":"初六","yinyang":"yin","text":"鴻漸于干 小子厲 有言 无咎","reading":"홍점우간 소자려 유언 무구","modern":"기러기가 물가로 점점 나아갑니다. 어린아이는 위태롭고 말이 있겠으나 허물은 없습니다.","meaning":"첫걸음을 막 뗀 때입니다. 아직 기반이 약해 주변에서 걱정이나 비판의 말이 나오기 쉽습니다.","positive":"처음의 조심스러운 태도 덕분에 큰 실수 없이 출발할 수 있습니다.","caution":"주변의 말에 흔들려 시작도 전에 포기하거나, 반대로 무시하고 서두를 수 있습니다.","advice":"걱정하는 말은 점검의 기회로 삼으세요. 작게 시작해 기초를 먼저 다지는 편이 좋습니다.","message":"시작의 걱정은 준비의 신호입니다."},{"guaN":53,"guaName":"풍산점","pos":2,"label":"六二","yinyang":"yin","text":"鴻漸于磐 飮食衎衎 吉","reading":"홍점우반 음식간간 길","modern":"기러기가 큰 바위로 점점 나아갑니다. 먹고 마심이 즐거우니 길합니다.","meaning":"안정된 자리를 얻어 여유를 누리는 단계입니다. 아래 괘의 중심이라 균형이 잡히고 위의 지원도 기대할 수 있습니다.","positive":"든든한 터전 위에서 여유와 어울림을 누릴 수 있습니다.","caution":"편안함에 머물러 나눔 없이 즐기기만 하면 다음 걸음이 늦어질 수 있습니다.","advice":"얻은 안정을 주변과 나누고, 함께하는 사람들과 신뢰를 쌓는 데 쓰세요.","message":"안정은 나눌 때 더 단단해집니다."},{"guaN":53,"guaName":"풍산점","pos":3,"label":"九三","yinyang":"yang","text":"鴻漸于陸 夫征不復 婦孕不育 凶 利禦寇","reading":"홍점우륙 부정불복 부잉불육 흉 리어구","modern":"기러기가 뭍으로 점점 나아갑니다. 남편이 떠나 돌아오지 못하고 아내는 잉태해도 기르지 못하니 흉합니다. 도적을 막는 데는 이롭습니다.","meaning":"아래 괘의 끝에서 너무 앞서 나가려는 때입니다. 물이 없는 뭍은 기러기에게 맞지 않는 곳이라 무리하면 어려움이 따르기 쉽습니다.","positive":"방어와 지키는 일에는 힘을 쓸 수 있는 때입니다.","caution":"주변의 사정과 맞지 않게 혼자 앞서가면 기반을 잃고 어려움을 겪을 수 있습니다.","advice":"새로운 확장보다 지키는 일에 집중하세요. 무리한 도전은 한 번 멈추고 상황을 살피는 편이 도움이 됩니다.","message":"앞서기보다 지키는 데 힘을 쓰세요."},{"guaN":53,"guaName":"풍산점","pos":4,"label":"六四","yinyang":"yin","text":"鴻漸于木 或得其桷 无咎","reading":"홍점우목 혹득기각 무구","modern":"기러기가 나무로 점점 나아갑니다. 어쩌면 평평한 가지를 얻으니 허물이 없습니다.","meaning":"위 괘의 시작으로, 불안정한 높은 곳에 올라선 단계입니다. 부드러운 자세로 알맞은 자리를 찾으면 안정을 얻을 수 있습니다.","positive":"겸손하게 순응하면 머물 만한 자리를 찾을 가능성이 있습니다.","caution":"발이 물갈퀴인 새가 나무 위에 오르듯, 어울리지 않는 자리에서 무리하면 불안해집니다.","advice":"지금 자리가 자신에게 맞는지 살피고, 맞지 않으면 작은 발판부터 찾아보세요.","message":"내게 맞는 가지를 찾는 때입니다."},{"guaN":53,"guaName":"풍산점","pos":5,"label":"九五","yinyang":"yang","text":"鴻漸于陵 婦三歲不孕 終莫之勝 吉","reading":"홍점우릉 부삼세불잉 종막지승 길","modern":"기러기가 언덕으로 점점 나아갑니다. 아내가 삼 년 동안 잉태하지 못하나 끝내 이를 이길 것이 없으니 길합니다.","meaning":"중심 자리에 올라 가장 높은 곳에 이르렀으나, 뜻이 맞는 이와 만나기까지 시간이 걸리는 단계입니다. 방해가 있어도 끝내는 풀리기 쉽습니다.","positive":"오해와 장애가 있어도 시간이 지나면 제자리를 찾을 가능성이 있습니다.","caution":"기다림이 길어지면 지치거나 다른 길로 새고 싶어질 수 있습니다.","advice":"당장의 성과가 보이지 않아도 바른 방식을 유지하며 인내하세요. 조급한 해결은 피하는 편이 좋습니다.","message":"기다림 끝에 맞는 인연이 닿습니다."},{"guaN":53,"guaName":"풍산점","pos":6,"label":"上九","yinyang":"yang","text":"鴻漸于陸 其羽可用爲儀 吉","reading":"홍점우륙 기우가용위의 길","modern":"기러기가 높은 곳으로 점점 나아갑니다. 그 깃털은 의식의 장식으로 쓸 만하니 길합니다.","meaning":"긴 여정을 마치고 높이 오른 마무리 단계입니다. 앞서 쌓은 모습이 다른 이들의 본보기가 될 수 있습니다.","positive":"과정에서 쌓은 품격이 다른 사람에게 좋은 모범이 될 수 있습니다.","caution":"높은 자리에 올랐다는 이유로 자만하면 쌓은 신뢰가 흔들릴 수 있습니다.","advice":"배운 것을 정리하고 후배나 주변에 나누세요. 처음의 태도를 잃지 않는 것이 중요합니다.","message":"끝에서도 처음처럼 단정하세요."}],"yong":null},"54":{"n":54,"name":"뇌택귀매","han":"雷澤歸妹","upper":"진","lower":"태","upperHan":"震","lowerHan":"兌","bits":[1,1,0,1,0,0],"binary":"110100","gua":{"text":"征凶 无攸利","reading":"정흉 무유리","modern":"나아가면 흉하고 이로울 바가 없습니다.","symbol":"위에 우레, 아래에 연못이 있는 모습으로, 기쁨(연못)을 따라 움직임(우레)이 일어나는 괘입니다. 젊은 여성이 시집가는 혼인을 상징합니다.","situation":"감정이나 기쁨에 이끌려 서둘러 관계나 계약을 맺기 쉬운 때입니다. 자리와 조건이 분명하지 않은 채 나아가면 어긋남이 생길 가능성이 있습니다. 시작의 기쁨보다 끝까지 이어갈 수 있는지를 먼저 살펴볼 필요가 있습니다.","positive":"관계를 맺고 새로운 결합을 시작하는 에너지가 풍부해 인연이 만들어지기 쉽습니다.","caution":"기분과 분위기에 휩쓸려 조건과 책임을 확인하지 않으면 나중에 갈등이 생길 수 있습니다.","direction":"당장 나아가기보다 관계의 위치와 책임을 분명히 하세요. 불리한 자리라도 맡은 몫을 성실히 하면 서서히 균형이 잡힐 수 있습니다.","message":"기쁨에 앞서 자리와 조건을 먼저 살피세요."},"yao":[{"guaN":54,"guaName":"뇌택귀매","pos":1,"label":"初九","yinyang":"yang","text":"歸妹以娣 跛能履 征吉","reading":"귀매이제 파능리 정길","modern":"누이를 시집보낼 때 동생을 함께 딸려 보냅니다. 절름발이가 능히 걷듯 나아가면 길합니다.","meaning":"주된 자리가 아니라 곁에서 돕는 위치에서 시작하는 단계입니다. 부족해 보여도 맡은 몫을 하면 길이 열립니다.","positive":"드러나지 않는 보조 역할에서도 꾸준히 하면 인정받을 수 있습니다.","caution":"스스로의 한계가 크다고 느껴 시작을 망설이거나, 주 역할을 넘보면 어긋날 수 있습니다.","advice":"작은 몫이라도 성실히 해 보세요. 한계를 인정하면서 할 수 있는 만큼 나아가는 편이 도움이 됩니다.","message":"곁에서도 제 몫을 하면 길이 열립니다."},{"guaN":54,"guaName":"뇌택귀매","pos":2,"label":"九二","yinyang":"yang","text":"眇能視 利幽人之貞","reading":"묘능시 리유인지정","modern":"애꾸눈이 능히 보듯 합니다. 조용히 지내는 사람의 바름이 이롭습니다.","meaning":"아래 괘의 중심에서 능력은 있으나 짝의 협조가 충분하지 않은 상황입니다. 시야가 제한적이어도 지킬 것을 지키는 태도가 중요합니다.","positive":"소란스럽지 않은 절개와 안정된 태도가 신뢰를 줍니다.","caution":"충분히 보이지 않는다고 불안해하거나 홀로 외롭게 고립될 수 있습니다.","advice":"화려한 변화보다 조용히 원칙을 지키세요. 나서기 전에 상대의 상황과 입장을 충분히 살피는 편이 좋습니다.","message":"조용히 원칙을 지키는 것이 힘입니다."},{"guaN":54,"guaName":"뇌택귀매","pos":3,"label":"六三","yinyang":"yin","text":"歸妹以須 反歸以娣","reading":"귀매이수 반귀이제","modern":"시집가는 데 기다림이 필요하여 돌아왔다가 동생처럼 낮은 자리로 다시 갑니다.","meaning":"자리에 맞지 않게 앞서 나가다 막힌 상태입니다. 아래 괘의 끝에서 마음은 급하지만 조건이 맞지 않아 물러나게 됩니다.","positive":"한 걸음 물러서서 조건을 다시 조정할 기회가 생깁니다.","caution":"기다리지 못하고 급히 나서면 체면이 상하거나 같은 실수를 반복할 수 있습니다.","advice":"당장 인정받으려는 욕심을 줄이고, 낮은 자리에서 다시 시작할 마음을 가져 보세요.","message":"물러남은 다시 설 준비입니다."},{"guaN":54,"guaName":"뇌택귀매","pos":4,"label":"九四","yinyang":"yang","text":"歸妹愆期 遲歸有時","reading":"귀매건기 지귀유시","modern":"시집가는 시기를 놓쳤지만 늦게 가더라도 때가 있습니다.","meaning":"기회가 지연되어 마음이 조급할 수 있는 시기입니다. 하지만 서둘러 아무 곳이나 가기보다 맞는 때를 기다리는 편이 어울립니다.","positive":"기다림 속에서 더 좋은 조건과 인연을 만날 가능성이 열려 있습니다.","caution":"지연이 길어지면 불안해져 맞지 않는 선택을 하기 쉽습니다.","advice":"기준을 낮추어 서두르기보다 기준을 지키며 기다리세요. 그동안 스스로를 준비하는 시간으로 쓰면 좋습니다.","message":"늦어도 맞는 때가 있습니다."},{"guaN":54,"guaName":"뇌택귀매","pos":5,"label":"六五","yinyang":"yin","text":"帝乙歸妹 其君之袂 不如其娣之袂良 月幾望 吉","reading":"제을귀매 기군지몌 불여기제지몌량 월기망 길","modern":"제을이 누이를 시집보내니, 정실의 소매가 동생의 소매만큼 곱지 않습니다. 달이 보름에 가까우니 길합니다.","meaning":"높은 자리에 있으면서도 겉치레보다 소박함과 겸손을 앞세우는 모습입니다. 가득 차기 직전의 달처럼 절제가 미덕이 됩니다.","positive":"화려함보다 덕과 겸손으로 존중받을 수 있습니다.","caution":"가득 찬 듯한 시기에 지나치게 드러내면 균형이 깨질 수 있습니다.","advice":"겉모양에 힘을 빼고 속을 채우세요. 가진 것의 일부를 내려놓는 여유가 관계를 편안하게 합니다.","message":"보름 전의 달처럼 절제하세요."},{"guaN":54,"guaName":"뇌택귀매","pos":6,"label":"上六","yinyang":"yin","text":"女承筐无實 士刲羊无血 无攸利","reading":"녀승광무실 사규양무혈 무유리","modern":"여자가 광주리를 받들었으나 담긴 것이 없고, 남자가 양을 잡았으나 피가 나지 않으니 이로울 바가 없습니다.","meaning":"겉으로는 의식을 치르지만 실질이 없는 결말입니다. 약속이나 형식이 이어지지 못하고 허무함이 남을 수 있습니다.","positive":"허울을 되돌아보고 관계나 일의 실질을 새로 점검할 계기가 됩니다.","caution":"형식과 말뿐인 약속에 기대면 결과가 공허해지기 쉽습니다.","advice":"정리해야 할 관계나 계약은 솔직하게 점검하세요. 실제로 이행할 수 있는 약속만 남기는 편이 좋습니다.","message":"실질이 없는 약속은 내려놓으세요."}],"yong":null},"55":{"n":55,"name":"뇌화풍","han":"雷火豐","upper":"진","lower":"리","upperHan":"震","lowerHan":"離","bits":[1,0,1,1,0,0],"binary":"101100","gua":{"text":"亨 王假之 勿憂 宜日中","reading":"형 왕격지 물우 의일중","modern":"형통합니다. 왕이 이에 이르렀으니 근심하지 마십시오. 해가 중천에 있을 때처럼 하는 것이 알맞습니다.","symbol":"위에 우레, 아래에 불(번개)이 있는 모습으로, 밝음과 움직임이 함께하는 풍성한 때를 뜻합니다. 성대함의 정점을 상징합니다.","situation":"성과와 규모, 주목도가 크게 오른 전성기의 국면입니다. 해가 중천에 오르면 기울기 시작하듯, 가장 좋을 때 다음 단계를 준비하는 지혜가 필요합니다. 풍성함 속에서 균형과 공정함을 잃지 않는 것이 과제입니다.","positive":"밝은 판단력과 추진력이 갖춰져 큰 일을 이루고 성과를 널리 펼치기 좋은 때입니다.","caution":"정점에서는 가려진 부분이 생기기 쉽고, 지나친 자신감이 판단을 흐릴 수 있습니다.","direction":"성과를 투명하게 나누고 한결같이 밝은 판단을 유지하세요. 지금의 풍요를 영원하다고 여기기보다 다음 변화에 대비하는 편이 도움이 됩니다.","message":"가장 풍성할 때 기울 때를 대비하세요."},"yao":[{"guaN":55,"guaName":"뇌화풍","pos":1,"label":"初九","yinyang":"yang","text":"遇其配主 雖旬无咎 往有尙","reading":"우기배주 수순무구 왕유상","modern":"짝이 되는 주인을 만났습니다. 열흘 동안은 허물이 없으며 나아가면 높이 평가받습니다.","meaning":"풍성함이 시작되는 때에 뜻이 맞는 사람을 만나는 장면입니다. 서로 힘을 보태면 좋은 출발이 됩니다.","positive":"좋은 협력자를 만나 일의 방향이 분명해질 수 있습니다.","caution":"기간이 지나치게 길어지면 서로의 균형이 흔들릴 수 있습니다.","advice":"믿을 만한 동료와 역할을 나누고 일정을 적절히 조절하세요. 지나친 의존은 피하는 편이 좋습니다.","message":"맞는 짝을 만나면 힘이 배가 됩니다."},{"guaN":55,"guaName":"뇌화풍","pos":2,"label":"六二","yinyang":"yin","text":"豐其蔀 日中見斗 往得疑疾 有孚發若 吉","reading":"풍기부 일중견두 왕득의질 유부발약 길","modern":"풍성하지만 큰 가림막으로 가려져 한낮에 북두성이 보입니다. 나아가면 의심과 시기를 받으나, 믿음으로 마음을 열면 길합니다.","meaning":"밝은 자리에 있으나 윗사람이 어두워 뜻이 전달되지 않는 상황입니다. 의심을 받더라도 정성으로 신뢰를 보일 필요가 있습니다.","positive":"진심 있는 태도가 닫힌 마음을 서서히 열어 줄 가능성이 있습니다.","caution":"의심에 맞서 다투거나 서둘러 설득하면 오히려 불신이 깊어질 수 있습니다.","advice":"설득보다 꾸준한 신뢰를 쌓는 데 집중하세요. 오해가 풀릴 때까지 성실한 태도를 이어 가는 편이 좋습니다.","message":"신뢰는 설득보다 진심으로 쌓입니다."},{"guaN":55,"guaName":"뇌화풍","pos":3,"label":"九三","yinyang":"yang","text":"豐其沛 日中見沫 折其右肱 无咎","reading":"풍기패 일중견매 절기우굉 무구","modern":"풍성하지만 장막이 짙어 한낮에 작은 별이 보입니다. 오른팔이 부러지나 허물은 없습니다.","meaning":"아래 괘의 끝에서 어둠이 짙어져 큰일을 하기 어려운 상황입니다. 중요한 도구나 역할이 막히는 일을 겪을 수 있습니다.","positive":"뜻대로 되지 않는 경험이 스스로의 방식을 돌아볼 기회가 됩니다.","caution":"능력이 있어도 상황이 가려져 있어 크게 움직이면 손해를 볼 수 있습니다.","advice":"지금은 큰일을 벌이기보다 정리하고 물러나 있는 편이 낫습니다. 책임을 남에게 돌리지 않는 자세가 도움이 됩니다.","message":"막힐 때는 잠시 물러서 정비하세요."},{"guaN":55,"guaName":"뇌화풍","pos":4,"label":"九四","yinyang":"yang","text":"豐其蔀 日中見斗 遇其夷主 吉","reading":"풍기부 일중견두 우기이주 길","modern":"풍성하지만 큰 가림막으로 가려져 한낮에 북두성이 보입니다. 대등한 주인을 만나니 길합니다.","meaning":"위 괘의 시작에서 어두운 상황이 이어지지만, 뜻이 맞는 동료나 상대를 만나 길이 열리는 장면입니다.","positive":"함께할 사람을 만나면 막혔던 일이 풀릴 가능성이 있습니다.","caution":"자기 판단만 믿고 혼자 움직이면 가려진 부분을 놓치기 쉽습니다.","advice":"도움이 될 만한 동료와 의견을 나누세요. 지위보다 마음이 통하는 사람을 찾는 편이 좋습니다.","message":"같은 뜻의 동료가 어둠을 걷어 줍니다."},{"guaN":55,"guaName":"뇌화풍","pos":5,"label":"六五","yinyang":"yin","text":"來章 有慶譽 吉","reading":"래장 유경예 길","modern":"빛나는 재능을 불러오니 경사와 명예가 있어 길합니다.","meaning":"중심 자리에서 겸손하게 사람들의 좋은 재능과 의견을 받아들이는 모습입니다. 그 덕분에 좋은 평판이 따라올 수 있습니다.","positive":"열린 태도로 인재와 의견을 모으면 조직에 경사가 생길 수 있습니다.","caution":"자기 판단에만 의지하면 좋은 기회를 놓칠 수 있습니다.","advice":"주변의 좋은 제안을 열린 마음으로 받아들이세요. 공을 나누는 태도가 신뢰를 키워 줍니다.","message":"열린 마음이 명예를 부릅니다."},{"guaN":55,"guaName":"뇌화풍","pos":6,"label":"上六","yinyang":"yin","text":"豐其屋 蔀其家 闚其戶 闃其无人 三歲不覿 凶","reading":"풍기옥 부기가 규기호 격기무인 삼세부적 흉","modern":"집을 크게 짓고 그 집을 가렸습니다. 문틈으로 엿보니 고요하여 사람이 없고, 삼 년이 지나도 보이지 않으니 흉합니다.","meaning":"풍성함이 지나쳐 스스로를 고립시킨 끝에 이른 상태입니다. 겉은 크지만 안은 비어 사람과 단절될 수 있습니다.","positive":"과한 풍요가 남긴 공허함을 돌아보고 관계를 회복할 기회가 됩니다.","caution":"높이만 추구하다 주변과 단절되면 외로움과 어려움이 길어질 수 있습니다.","advice":"자신을 가리던 벽을 낮추고 사람들에게 먼저 다가가 보세요. 규모보다 관계를 돌보는 편이 도움이 됩니다.","message":"화려함 뒤의 고립을 살피세요."}],"yong":null},"56":{"n":56,"name":"화산려","han":"火山旅","upper":"리","lower":"간","upperHan":"離","lowerHan":"艮","bits":[0,0,1,1,0,1],"binary":"001101","gua":{"text":"小亨 旅貞吉","reading":"소형 려정길","modern":"조금 형통합니다. 나그네가 바르게 하면 길합니다.","symbol":"산 위에 불이 있는 모습으로, 불이 한곳에 머물지 않고 옮겨 가는 나그네의 처지를 뜻합니다. 낯선 곳에서의 처신을 가르치는 괘입니다.","situation":"이사, 이직, 새로운 조직 등으로 낯선 환경에서 기반이 약한 국면입니다. 크게 뜻을 펼치기보다 작게 적응하며 신뢰를 쌓는 것이 중요합니다. 겸손하고 신중하게 행동하면 어려움을 줄일 수 있습니다.","positive":"작은 일을 바르게 해 나가면 조금씩 길이 열리고 새로운 경험이 쌓입니다.","caution":"지나친 자만이나 경솔한 행동이 낯선 곳에서 쉽게 마찰과 손실을 부를 수 있습니다.","direction":"그곳의 규칙과 분위기를 먼저 파악하고 낮은 자세로 신뢰를 쌓으세요. 불필요한 분쟁은 피하고 큰 결정은 서두르지 않는 편이 좋습니다.","message":"낯선 곳에서는 낮게, 바르게 처신하세요."},"yao":[{"guaN":56,"guaName":"화산려","pos":1,"label":"初六","yinyang":"yin","text":"旅瑣瑣 斯其所取災","reading":"려쇄쇄 사기소취재","modern":"나그네가 쩨쩨하고 좀스럽게 구니 이것이 스스로 재앙을 부르는 일입니다.","meaning":"낯선 곳에서 막 시작하는 단계로, 불안해서 사소한 일에 집착하기 쉽습니다. 그런 태도가 스스로 어려움을 만드는 원인이 될 수 있습니다.","positive":"처음의 불안을 알아차리면 태도를 바로잡을 여지가 있습니다.","caution":"작은 이익이나 체면에 매달리면 신뢰를 잃고 불필요한 갈등이 생길 수 있습니다.","advice":"사소한 일에 얽매이지 말고 여유 있게 행동하세요. 먼저 환경에 익숙해지는 데 집중하는 편이 좋습니다.","message":"좀스러움은 스스로 어려움을 부릅니다."},{"guaN":56,"guaName":"화산려","pos":2,"label":"六二","yinyang":"yin","text":"旅卽次 懷其資 得童僕貞","reading":"려즉차 회기자 득동복정","modern":"나그네가 숙소에 이르러 재물을 품고 있으며 충직한 시종을 얻습니다.","meaning":"아래 괘의 중심에서 안정된 거처와 자원, 믿을 만한 조력자를 얻는 장면입니다. 낯선 곳에서 가장 안정적인 때입니다.","positive":"머물 곳과 필요한 자원, 신뢰할 사람을 갖추어 든든합니다.","caution":"안정을 얻었다고 방심하면 지킨 것을 잃을 수 있습니다.","advice":"가진 것을 아껴 쓰고 곁의 사람에게 믿음으로 대하세요. 베푼 신뢰가 안정으로 돌아오는 편입니다.","message":"머물 곳과 사람이 있어 든든합니다."},{"guaN":56,"guaName":"화산려","pos":3,"label":"九三","yinyang":"yang","text":"旅焚其次 喪其童僕 貞厲","reading":"려분기차 상기동복 정려","modern":"나그네가 머물던 숙소를 불태우고 시종도 잃으니 바르게 해도 위태롭습니다.","meaning":"아래 괘의 끝에서 지나치게 강하게 굴다 거처와 조력자를 잃는 장면입니다. 낯선 곳에서 고압적인 태도는 위험을 키웁니다.","positive":"위기를 겪으며 태도를 돌아보고 바로잡을 계기가 됩니다.","caution":"자리가 불안한데 사람을 함부로 대하거나 급하게 밀어붙이면 기반을 잃을 수 있습니다.","advice":"강하게 주장하기보다 낮은 자세로 사람을 대하세요. 떠난 관계는 성실하게 정리하는 편이 도움이 됩니다.","message":"지나친 강함이 의지할 곳을 잃게 합니다."},{"guaN":56,"guaName":"화산려","pos":4,"label":"九四","yinyang":"yang","text":"旅于處 得其資斧 我心不快","reading":"려우처 득기자부 아심불쾌","modern":"나그네가 머물 곳을 얻고 재물과 도끼를 얻었으나 내 마음은 즐겁지 않습니다.","meaning":"위 괘의 시작에서 자리와 도구는 얻었으나 아직 진짜 내 집이 아니라 마음이 편하지 않은 단계입니다.","positive":"자립할 수단과 최소한의 터전을 마련할 수 있는 때입니다.","caution":"겉의 조건이 갖춰져도 불안한 마음을 방치하면 자신감이 흔들릴 수 있습니다.","advice":"스스로를 지킬 준비를 하되 한 번에 크게 벌이지 마세요. 불편한 마음의 이유를 차분히 살펴보면 좋습니다.","message":"자리를 얻어도 마음은 아직 객입니다."},{"guaN":56,"guaName":"화산려","pos":5,"label":"六五","yinyang":"yin","text":"射雉 一矢亡 終以譽命","reading":"사치 일시망 종이예명","modern":"꿩을 쏘는데 화살 하나를 잃었으나 끝내 명예와 지위를 얻습니다.","meaning":"중심 자리에서 작은 손실을 감수하고 큰 신뢰를 얻는 장면입니다. 낯선 곳에서도 부드럽게 위와 아래의 인정을 받을 수 있습니다.","positive":"작은 손해를 감수한 덕에 좋은 평판과 인정을 얻을 가능성이 있습니다.","caution":"작은 이득을 아까워하면 더 큰 신뢰를 놓칠 수 있습니다.","advice":"눈앞의 손해에 연연하지 말고 장기적인 신뢰를 택하세요. 능력을 드러내되 겸손하게 하는 편이 좋습니다.","message":"작은 손해가 큰 신뢰를 남깁니다."},{"guaN":56,"guaName":"화산려","pos":6,"label":"上九","yinyang":"yang","text":"鳥焚其巢 旅人先笑後號咷 喪牛于易 凶","reading":"조분기소 려인선소후호도 상우우이 흉","modern":"새가 그 둥지를 불태웠습니다. 나그네가 먼저는 웃다가 나중에는 울부짖으며, 소를 쉽게 잃으니 흉합니다.","meaning":"높은 자리에서 자만하여 의지할 터전을 스스로 잃는 끝 단계입니다. 처음의 기쁨이 방심으로 이어져 슬픔이 될 수 있습니다.","positive":"뒤늦게라도 지나친 자만을 돌아보고 태도를 바꿀 계기가 됩니다.","caution":"성공에 취해 경계를 풀면 쌓아 온 기반이 한순간에 흔들릴 수 있습니다.","advice":"높은 자리일수록 낮은 자세를 유지하고 주변을 경계하세요. 잃은 것은 책임을 인정하고 차근차근 되찾는 편이 좋습니다.","message":"자만은 둥지를 태웁니다."}],"yong":null},"57":{"n":57,"name":"손위풍","han":"巽爲風","upper":"손","lower":"손","upperHan":"巽","lowerHan":"巽","bits":[0,1,1,0,1,1],"binary":"011011","gua":{"text":"小亨 利有攸往 利見大人","reading":"소형 리유유왕 리견대인","modern":"조금 형통합니다. 나아갈 바가 있으면 이롭고, 대인을 만나보는 것이 이롭습니다.","symbol":"바람(巽)이 위아래로 거듭 불어 어디든 스며드는 모습입니다. 부드럽게 파고들고 겸손히 따르는 태도를 뜻하는 괘입니다.","situation":"강하게 밀어붙이기보다 설득과 조율로 영향을 넓혀 가는 국면입니다. 한 번에 큰 성과가 나기보다 작게 통하며 차츰 퍼져 가기 쉽습니다. 이럴 때는 경험과 안목이 있는 사람의 조언을 구하면 방향을 잡는 데 도움이 됩니다.","positive":"부드럽고 꾸준한 소통으로 상대의 마음에 자연스럽게 스며들 수 있는 때입니다. 겸손한 태도가 신뢰를 쌓아 줍니다.","caution":"지나치게 맞추다 보면 망설임과 우유부단으로 흐르기 쉽습니다. 따르는 일과 스스로 정하는 일을 구분해 두세요.","direction":"같은 뜻을 거듭 차분히 전하되, 핵심 원칙은 분명히 세우는 방향이 좋습니다. 조언을 구할 사람을 찾고, 결정이 필요한 때에는 기한을 정해 선택하는 편이 도움이 됩니다.","message":"바람처럼 부드럽게, 그러나 중심은 잃지 마세요."},"yao":[{"guaN":57,"guaName":"손위풍","pos":1,"label":"初六","yinyang":"yin","text":"進退 利武人之貞","reading":"진퇴 리무인지정","modern":"나아갔다 물러났다 합니다. 무인처럼 곧게 지키는 것이 이롭습니다.","meaning":"막 시작하는 자리에서 부드러움이 지나쳐 앞으로 갈지 물러설지 망설이는 모습입니다. 이럴 때는 군인이 명령을 따르듯 단호한 기준 하나가 필요합니다.","positive":"신중하게 살피는 태도 덕분에 섣부른 실수를 피할 수 있습니다.","caution":"망설임이 길어지면 시작할 기회 자체를 놓치기 쉽습니다.","advice":"해야 할 일의 기준과 기한을 먼저 정하고, 정한 뒤에는 흔들리지 않고 실행해 보세요.","message":"망설임엔 기준과 기한을 두세요."},{"guaN":57,"guaName":"손위풍","pos":2,"label":"九二","yinyang":"yang","text":"巽在牀下 用史巫紛若 吉无咎","reading":"손재상하 용사무분약 길무구","modern":"침상 아래에 엎드려 있듯 낮추어 있습니다. 사관과 무당을 많이 쓰면 길하고 허물이 없습니다.","meaning":"아래 괘의 중심 자리에서 한껏 몸을 낮추고 정성을 다하는 모습입니다. 옛날 제사와 점을 맡던 사람들을 여럿 동원한다는 표현은, 마음을 다해 두루 살핀다는 뜻으로 이해할 수 있습니다.","positive":"낮은 자세로 정성껏 준비하면 주변의 신뢰와 도움을 얻기 쉽습니다.","caution":"지나친 공손이 비굴함이나 지나친 의존으로 보이지 않도록 살피세요.","advice":"여러 사람의 의견을 듣고 정성껏 준비하되, 마지막 판단은 스스로 내리세요.","message":"낮추되 정성은 넉넉히 쏟으세요."},{"guaN":57,"guaName":"손위풍","pos":3,"label":"九三","yinyang":"yang","text":"頻巽 吝","reading":"빈손 린","modern":"자주 거듭 굽힙니다. 아쉬움이 있습니다.","meaning":"아래 괘의 끝에서 강한 성격에 눌러 억지로 굽히는 일이 거듭되는 모습입니다. 마음이 내키지 않는 순종은 오래가기 어렵고 스스로도 불편해집니다.","positive":"자신이 어디서 무리하게 맞추고 있는지 돌아볼 기회가 됩니다.","caution":"내키지 않는 양보를 되풀이하면 불만이 쌓이고 체면도 상하기 쉽습니다.","advice":"반복해서 맞추고 있는 일이 있다면, 진심으로 따를 부분과 조율할 부분을 나눠 이야기해 보세요.","message":"억지로 굽히는 일은 줄이세요."},{"guaN":57,"guaName":"손위풍","pos":4,"label":"六四","yinyang":"yin","text":"悔亡 田獲三品","reading":"회망 전획삼품","modern":"후회가 사라집니다. 사냥에서 세 종류의 짐승을 얻습니다.","meaning":"위 괘의 시작 자리에서 유연한 태도가 제자리를 찾아 후회거리가 풀리는 모습입니다. 사냥에서 여러 가지를 얻는다는 표현처럼, 부드럽게 일하면 여러 방면에서 소득을 거두기 쉽습니다.","positive":"윗사람의 뜻을 잘 받들며 균형 있게 일하면 성과가 다양하게 나타납니다.","caution":"성과가 좋아도 이웃과 아랫사람에게 공을 나누는 마음을 잊지 마세요.","advice":"이미 쌓은 신뢰를 바탕으로 맡은 일을 폭넓게 해 보되, 한 번에 욕심내지는 마세요.","message":"유연함이 여러 성과로 돌아옵니다."},{"guaN":57,"guaName":"손위풍","pos":5,"label":"九五","yinyang":"yang","text":"貞吉 悔亡 无不利 无初有終 先庚三日 後庚三日 吉","reading":"정길 회망 무불리 무초유종 선경삼일 후경삼일 길","modern":"곧게 지키면 길합니다. 후회가 사라지고 이롭지 않은 것이 없습니다. 처음은 없어도 끝은 있습니다. 경일 사흘 전과 사흘 후를 살피면 길합니다.","meaning":"위 괘의 중심에서 바른 마음으로 변화를 이끄는 자리입니다. 처음에는 매끄럽지 않을 수 있지만 변화를 앞뒤로 충분히 살피면 좋은 마무리에 이르기 쉽습니다. 경일을 앞뒤로 사흘씩 본다는 것은 변화 전후를 면밀히 점검하라는 비유로 읽을 수 있습니다.","positive":"중심이 서 있어 변화를 주도해도 주변이 따라오기 쉽습니다.","caution":"처음의 서툶에 조급해하면 앞뒤 점검을 놓치기 쉽습니다.","advice":"새로운 방식을 도입하기 전에 준비 사항을, 도입한 뒤에는 결과를 살피는 일정을 함께 잡아 보세요.","message":"변화는 앞뒤를 살피며 이끄세요."},{"guaN":57,"guaName":"손위풍","pos":6,"label":"上九","yinyang":"yang","text":"巽在牀下 喪其資斧 貞凶","reading":"손재상하 상기자부 정흉","modern":"침상 아래에 엎드려 있습니다. 재물과 도끼를 잃으니, 그대로 고집하면 흉합니다.","meaning":"끝자리에서 낮춤이 지나쳐 스스로 쓸 수단과 결단력까지 잃은 모습입니다. 도끼는 결단의 상징으로 읽을 수 있어, 공손함이 도를 넘으면 정작 필요한 순간에 힘을 쓰지 못하게 됩니다.","positive":"지나침을 알아차리면 균형을 되찾을 계기로 삼을 수 있습니다.","caution":"계속 굽히기만 하면 자신의 자원과 주도권을 모두 내주기 쉽습니다.","advice":"내려놓은 권한이나 기준이 있다면 다시 가져오고, 필요할 때는 분명히 의사를 표현하세요.","message":"겸손이 지나쳐 결단까지 잃지 마세요."}],"yong":null},"58":{"n":58,"name":"태위택","han":"兌爲澤","upper":"태","lower":"태","upperHan":"兌","lowerHan":"兌","bits":[1,1,0,1,1,0],"binary":"110110","gua":{"text":"亨 利貞","reading":"형 리정","modern":"형통합니다. 곧고 바르게 함이 이롭습니다.","symbol":"위아래 모두 연못(澤)이 겹쳐 있어, 두 물이 서로 스며들며 윤택하게 하듯 기쁨을 주고받는 모습입니다. 말과 웃음, 배움과 교류의 즐거움을 뜻하는 괘입니다.","situation":"사람들과 대화하고 어울리며 분위기가 밝아지는 국면입니다. 기쁨이 일을 부드럽게 풀어 주지만, 즐거움이 커질수록 달콤한 말이나 이해관계에 마음이 쏠리기도 쉽습니다. 기쁨의 바탕에 바른 마음이 있는지가 결과를 가르기 쉬운 때입니다.","positive":"진심이 담긴 대화와 함께하는 배움이 관계를 넓히고 막힌 일을 풀어 줄 수 있습니다.","caution":"남의 비위를 맞추는 말이나 순간의 즐거움을 좇다 보면 원칙과 중심을 잃기 쉽습니다.","direction":"기쁨을 나누되 그 기쁨이 어디서 오는지 스스로 살펴보세요. 칭찬과 아첨, 호의와 속셈을 구분하며 곧은 태도를 지키는 편이 오래 가는 기쁨을 만듭니다.","message":"바른 마음 위에서 나눈 기쁨이 오래갑니다."},"yao":[{"guaN":58,"guaName":"태위택","pos":1,"label":"初九","yinyang":"yang","text":"和兌 吉","reading":"화태 길","modern":"화합하며 기뻐하니 길합니다.","meaning":"기쁨의 괘가 막 시작되는 자리에서, 아직 누구에게 잘 보일 이유도 속셈도 없이 부드럽게 어울리는 장면입니다. 위에 호응을 구하는 효가 없어 마음이 순수합니다.","positive":"계산 없이 화목하게 어울리는 태도가 편안한 관계의 출발점이 됩니다.","caution":"편안함에 익숙해져 아무하고나 쉽게 휩쓸리지는 않는지 살펴야 합니다.","advice":"새로운 모임이나 관계를 시작할 때는 열린 마음과 부드러운 태도로 다가가 보세요. 이익을 따지기보다 함께 있는 편안함을 먼저 쌓는 것이 좋습니다.","message":"계산 없는 어울림이 좋은 시작입니다."},{"guaN":58,"guaName":"태위택","pos":2,"label":"九二","yinyang":"yang","text":"孚兌 吉 悔亡","reading":"부태 길 회망","modern":"믿음을 바탕으로 기뻐하니 길합니다. 후회가 사라집니다.","meaning":"아래 괘의 한가운데에서 속마음이 곧고 진실한 채로 기쁨을 나누는 장면입니다. 가까이에 유혹하는 존재가 있어도 중심을 잃지 않아 후회할 일이 줄어듭니다.","positive":"진실한 마음이 있으니 주변의 달콤한 분위기 속에서도 흔들림이 적습니다.","caution":"주변의 분위기에 맞추다 보면 어느새 내 기준이 느슨해질 수 있습니다.","advice":"즐거운 자리일수록 내가 지키려는 기준을 한 번 떠올려 보세요. 마음이 진실한지 확인하며 어울리면 후회할 일이 줄어듭니다.","message":"진심이 중심을 잡아 줍니다."},{"guaN":58,"guaName":"태위택","pos":3,"label":"六三","yinyang":"yin","text":"來兌 凶","reading":"래태 흉","modern":"기쁨을 불러들이려 하니 흉합니다.","meaning":"아래 괘의 끝에서 자리가 바르지 않은 채 스스로 즐거움과 호응을 끌어들이려는 장면입니다. 외부의 인정과 즐거움에 기대다 보니 마음이 쉽게 흔들립니다.","positive":"자신의 욕심이 기쁨을 좇고 있음을 알아차리면 방향을 바꿀 여지가 생깁니다.","caution":"인기나 쾌락, 다른 사람의 호의를 얻으려는 마음이 커지면 스스로를 소모하고 어려움이 따르기 쉽습니다.","advice":"지금 내가 즐거움이나 인정을 얻으려고 무리하고 있지는 않은지 돌아보세요. 사람의 호의에 기대기보다 스스로 만족할 수 있는 일에 시간을 써 보세요.","message":"끌어들이는 기쁨은 나를 비웁니다."},{"guaN":58,"guaName":"태위택","pos":4,"label":"九四","yinyang":"yang","text":"商兌 未寧 介疾有喜","reading":"상태 미녕 개질유희","modern":"어떤 기쁨을 택할지 헤아리느라 마음이 편치 못합니다. 나쁜 것을 단호히 멀리하면 기쁨이 있습니다.","meaning":"위 괘의 시작이자 높은 자리와 가까운 경계에서, 윗사람의 뜻을 따를지 아래의 달콤함을 택할지 저울질하는 장면입니다. 마음이 갈리지만 분명히 선을 그으면 기쁨이 찾아옵니다.","positive":"망설이는 시간 속에서 무엇이 바른 기쁨인지 가려낼 기회를 얻습니다.","caution":"결정을 미루며 양쪽을 모두 놓지 않으려 하면 불안만 길어질 수 있습니다.","advice":"고민이 길어진다면 내가 지키고 싶은 기준을 먼저 정하고 그에 맞지 않는 유혹은 과감히 정리해 보세요. 단호함이 마음의 평안을 되찾게 도와줍니다.","message":"가려내는 결단이 마음을 편하게 합니다."},{"guaN":58,"guaName":"태위택","pos":5,"label":"九五","yinyang":"yang","text":"孚于剝 有厲","reading":"부우박 유려","modern":"깎아 내리는 자를 믿으니 위태로움이 있습니다.","meaning":"위 괘의 중심이자 핵심 자리에서 힘이 있지만, 곁의 부드러운 말에 마음을 열면 곧음이 깎여 나갈 수 있는 장면입니다. 높은 자리일수록 달콤한 말의 영향이 큽니다.","positive":"책임 있는 자리이기에 스스로 경계하고 바로잡을 힘도 함께 갖고 있습니다.","caution":"듣기 좋은 말만 하는 사람을 가까이 두면 판단이 서서히 흐려질 수 있습니다.","advice":"나에게 듣기 좋은 말을 하는 사람과 쓴소리를 해 주는 사람을 함께 곁에 두세요. 중요한 결정 앞에서는 달콤한 조언의 의도를 한 번 더 살펴보세요.","message":"듣기 좋은 말일수록 한 번 더 살피세요."},{"guaN":58,"guaName":"태위택","pos":6,"label":"上六","yinyang":"yin","text":"引兌","reading":"인태","modern":"기쁨으로 이끌어 끌어당깁니다.","meaning":"기쁨의 끝에서 자기 즐거움을 위해 다른 이를 끌어들이거나 끌려가는 장면입니다. 흥이 정점에 올라 멈출 지점을 놓치기 쉽습니다. 원문에는 길흉 판단이 따로 적혀 있지 않습니다.","positive":"즐거움이 무르익은 때이니 그 기쁨을 어떻게 마무리할지 선택할 여지가 있습니다.","caution":"흥이 지나쳐 서로를 끌어들이는 즐거움에 머물면 공허함이 남기 쉽습니다.","advice":"분위기가 한창일 때 그 기쁨이 나와 상대에게 정말 도움이 되는지 잠시 멈춰 살펴보세요. 모임이나 즐거움을 끝낼 적당한 때를 스스로 정하는 편이 도움이 됩니다.","message":"즐거움에도 멈출 때를 정해 두세요."}],"yong":null},"59":{"n":59,"name":"풍수환","han":"風水渙","upper":"손","lower":"감","upperHan":"巽","lowerHan":"坎","bits":[0,1,0,0,1,1],"binary":"010011","gua":{"text":"亨 王假有廟 利涉大川 利貞","reading":"형 왕격유묘 리섭대천 리정","modern":"형통합니다. 왕이 사당에 이르니, 큰 강을 건너는 것이 이롭고 곧고 바르게 함이 이롭습니다.","symbol":"위에는 바람(風), 아래에는 물(水)이 있어 바람이 물 위를 지나며 얼음과 막힌 것을 풀고 흩뜨리는 모습입니다. 굳어 있던 것이 풀리고 흩어지는 변화를 뜻합니다.","situation":"굳어 있던 관계나 상황이 풀리면서 한편으로는 마음과 힘이 흩어지기 쉬운 국면입니다. 막혔던 것이 열리는 이로움이 있지만 구심점이 없으면 흩어짐만 남을 수 있습니다. 풀 것은 풀고 모을 것은 다시 모아야 하는 때입니다.","positive":"쌓인 응어리와 막힌 흐름이 풀리며 새로운 일을 시도할 길이 열릴 수 있습니다.","caution":"흩어지는 흐름 속에서 공통의 목적이나 중심이 흐려지면 사람과 힘이 갈라지기 쉽습니다.","direction":"풀어야 할 걱정과 오해는 놓아 주고, 사람들이 다시 모일 만한 가치와 목표를 분명히 하세요. 의식을 치르듯 경건하고 바른 마음의 중심을 세우는 편이 도움이 됩니다.","message":"풀 것은 풀고 마음의 중심은 다시 세우세요."},"yao":[{"guaN":59,"guaName":"풍수환","pos":1,"label":"初六","yinyang":"yin","text":"用拯馬壯 吉","reading":"용증마장 길","modern":"건져 내는 데 튼튼한 말을 쓰니 길합니다.","meaning":"흩어짐이 막 시작될 때 힘센 말에 의지해 위기를 건지는 장면입니다. 아직 문제가 작을 때 곁의 믿을 만한 힘을 빌려 빨리 손쓰는 것이 핵심입니다.","positive":"초기에 대응하면 어긋남이 커지기 전에 바로잡을 수 있습니다.","caution":"작은 균열이라 가볍게 넘기면 나중에 수습하기 어려워질 수 있습니다.","advice":"갈라지는 조짐이 보이면 미루지 말고 믿을 만한 사람이나 든든한 방법의 도움을 받아 일찍 수습해 보세요. 빠른 대화와 도움 요청이 도움이 됩니다.","message":"흩어짐은 작을 때 붙잡는 편이 좋습니다."},{"guaN":59,"guaName":"풍수환","pos":2,"label":"九二","yinyang":"yang","text":"渙奔其机 悔亡","reading":"환분기궤 회망","modern":"흩어지는 때에 안석으로 달려가니 후회가 사라집니다.","meaning":"아래 괘의 중심에서 흩어지는 불안 속에 몸을 기댈 안석, 즉 의지할 자리로 달려가는 장면입니다. 믿을 곳으로 옮겨 가는 선택이 후회를 덜어 줍니다.","positive":"안정된 터전과 믿을 만한 기반으로 옮겨 가면 불안이 가라앉을 수 있습니다.","caution":"위기 속에서 급히 달려가다 보면 의지할 곳을 충분히 따져 보지 못할 수 있습니다.","advice":"흔들릴 때일수록 나를 지탱해 줄 안식처나 기본 습관, 믿을 만한 사람을 먼저 떠올려 보세요. 그곳에 몸을 기대고 숨을 고르면 판단이 한결 맑아집니다.","message":"흔들릴 땐 기댈 자리로 먼저 가세요."},{"guaN":59,"guaName":"풍수환","pos":3,"label":"六三","yinyang":"yin","text":"渙其躬 无悔","reading":"환기궁 무회","modern":"자기 자신을 풀어 놓으니 후회가 없습니다.","meaning":"아래 괘의 끝에서 자기만 챙기려는 마음을 내려놓는 장면입니다. 위쪽의 호응이 있는 자리라, 내 몫과 고집을 풀어낼 때 일이 풀립니다.","positive":"자기중심적인 집착을 내려놓으면 더 큰 흐름과 함께할 수 있습니다.","caution":"나를 풀어 낸다는 이유로 책임까지 놓아 버리지는 않는지 살펴야 합니다.","advice":"내 입장과 체면을 잠시 내려놓고 함께 일하는 사람들의 필요를 먼저 들어 보세요. 집착을 풀되 내가 맡은 책임은 분명히 지키는 편이 좋습니다.","message":"나를 내려놓을 때 길이 열립니다."},{"guaN":59,"guaName":"풍수환","pos":4,"label":"六四","yinyang":"yin","text":"渙其群 元吉 渙有丘 匪夷所思","reading":"환기군 원길 환유구 비이소사","modern":"작은 무리를 풀어 흩으니 크게 길합니다. 흩어서 큰 언덕을 이루니, 평범한 생각으로는 헤아리기 어렵습니다.","meaning":"위 괘의 시작이자 윗자리와 가까운 경계에서 사사로운 패거리를 풀어 더 큰 모임으로 모으는 장면입니다. 작은 편을 가르던 울타리를 허물어 큰 공동체를 만듭니다.","positive":"작은 이해관계를 넘어서면 더 많은 사람이 함께하는 큰 기반이 생길 수 있습니다.","caution":"익숙한 무리를 놓는 데 따르는 아쉬움이 커 결단이 늦어질 수 있습니다.","advice":"나와 가까운 사람들끼리만 뭉치는 구조가 아닌지 돌아보고, 더 넓은 목표 아래 사람들을 이어 주는 역할을 고민해 보세요. 당장은 낯설어도 큰 그림이 열릴 수 있습니다.","message":"작은 편을 풀어야 큰 모임이 됩니다."},{"guaN":59,"guaName":"풍수환","pos":5,"label":"九五","yinyang":"yang","text":"渙汗其大號 渙王居 无咎","reading":"환한기대호 환왕거 무구","modern":"땀이 나듯 큰 명령을 퍼뜨리고, 왕의 쌓아 둔 재물을 흩어 나누니 허물이 없습니다.","meaning":"위 괘의 중심이자 핵심 자리에서 한번 나가면 되돌릴 수 없는 땀처럼 큰 뜻을 널리 알리고, 쌓아 둔 것을 나누어 사람들을 모으는 장면입니다. 중심에 선 사람이 마음을 모으는 역할을 합니다.","positive":"분명한 비전과 나눔이 흩어진 사람들의 마음을 다시 모으는 힘이 됩니다.","caution":"말만 크고 실제로 내놓는 것이 없으면 사람들이 따르기 어렵습니다.","advice":"중요한 방향은 분명하고 진심 있게 전하고, 내가 가진 자원과 기회를 함께 나누는 방안을 생각해 보세요. 한번 말한 약속은 지키는 쪽으로 준비하는 편이 좋습니다.","message":"뜻을 밝히고 나눌 때 마음이 모입니다."},{"guaN":59,"guaName":"풍수환","pos":6,"label":"上九","yinyang":"yang","text":"渙其血 去逖出 无咎","reading":"환기혈 거적출 무구","modern":"피를 흩어 없애듯 상처를 풀어내고, 멀리 두려움에서 벗어나니 허물이 없습니다.","meaning":"흩어짐의 끝에서 오래 이어진 상처와 위험을 멀리 보내고 벗어나는 장면입니다. 긴 갈등과 불안이 정리되며 마무리되는 단계입니다.","positive":"오래된 상처와 두려움에서 거리를 두면 비로소 숨을 돌릴 수 있습니다.","caution":"상처를 풀어내지 못한 채 피하기만 하면 같은 문제가 되풀이될 수 있습니다.","advice":"나를 오래 힘들게 한 갈등이나 위험한 상황에서는 한 걸음 물러나 거리를 두세요. 정리가 필요한 일은 도움을 받아 마무리하는 편이 좋습니다.","message":"상처와 두려움에서 멀어지는 것도 용기입니다."}],"yong":null},"60":{"n":60,"name":"수택절","han":"水澤節","upper":"감","lower":"태","upperHan":"坎","lowerHan":"兌","bits":[1,1,0,0,1,0],"binary":"110010","gua":{"text":"亨 苦節不可貞","reading":"형 고절불가정","modern":"형통합니다. 괴롭기만 한 절제는 오래 지킬 수 없습니다.","symbol":"위에는 물(水), 아래에는 연못(澤)이 있어, 연못이 물을 담는 한도가 정해져 있듯 알맞은 한계를 세우는 모습입니다. 대나무 마디처럼 절제와 조절을 뜻하는 괘입니다.","situation":"시간, 돈, 감정, 에너지에서 기준과 한도를 세워야 하는 국면입니다. 적절한 선이 있으면 일이 무너지지 않고 오래 이어지지만, 너무 빡빡하면 지치고 너무 느슨하면 넘칩니다. 지킬 수 있는 수준의 절제가 중요한 때입니다.","positive":"알맞은 한계가 있으면 힘이 새지 않고 일을 꾸준히 이어 갈 수 있습니다.","caution":"지나치게 혹독한 규칙은 마음을 지치게 해 오히려 오래 지키기 어렵습니다.","direction":"한도를 정하되 내가 실제로 지킬 수 있는 수준인지 점검하세요. 규칙이 괴로움만 낳는다면 목적을 다시 떠올리고 현실에 맞게 조정하는 편이 도움이 됩니다.","message":"지킬 수 있는 절제가 오래갑니다."},"yao":[{"guaN":60,"guaName":"수택절","pos":1,"label":"初九","yinyang":"yang","text":"不出戶庭 无咎","reading":"불출호정 무구","modern":"집 안 뜰 밖으로 나가지 않으니 허물이 없습니다.","meaning":"절제를 막 시작하는 자리에서 때가 아직 열리지 않았음을 알고 삼가며 머무는 장면입니다. 성급히 나서지 않고 준비하는 신중함입니다.","positive":"말과 행동을 아끼며 때를 기다리면 불필요한 실수를 피할 수 있습니다.","caution":"기다림이 두려움이나 게으름으로 굳어 가고 있지는 않은지 살펴야 합니다.","advice":"중요한 일을 시작하기 전에는 말과 계획을 아끼며 준비를 단단히 하세요. 때가 되었는지 판단할 기준을 미리 정해 두면 좋습니다.","message":"나설 때가 아니면 삼가는 것도 지혜입니다."},{"guaN":60,"guaName":"수택절","pos":2,"label":"九二","yinyang":"yang","text":"不出門庭 凶","reading":"불출문정 흉","modern":"대문 밖 뜰에도 나가지 않으니 흉합니다.","meaning":"아래 괘의 중심에서 이미 문이 열리고 나설 때가 되었는데도 지나치게 움츠러들어 기회를 놓치는 장면입니다. 절제가 과해 때를 놓치는 모습입니다.","positive":"신중한 성향 덕분에 안정을 지킬 수 있다는 점은 장점이 됩니다.","caution":"기회가 열렸는데도 몸을 사리면 놓친 때를 되찾기 어려워 어려움이 따를 수 있습니다.","advice":"신중함이 어느새 망설임으로 바뀌지 않았는지 살펴보세요. 준비가 충분하다면 작은 행동부터라도 문밖으로 한 걸음 내디뎌 보는 편이 도움이 됩니다.","message":"때가 열렸다면 문밖으로 나서 보세요."},{"guaN":60,"guaName":"수택절","pos":3,"label":"六三","yinyang":"yin","text":"不節若 則嗟若 无咎","reading":"부절약 즉차약 무구","modern":"절제하지 않으면 탄식하게 됩니다. 누구를 탓할 일이 아니니 허물이 없습니다.","meaning":"아래 괘의 끝에서 자리가 바르지 않아 절제가 풀리고 넘치는 장면입니다. 한도를 넘은 뒤에야 후회하지만, 원인이 내게 있음을 인정하면 허물은 남지 않습니다.","positive":"스스로 한탄하며 돌아보는 순간이 습관을 고치는 계기가 될 수 있습니다.","caution":"한도를 넘은 책임을 남이나 상황 탓으로 돌리면 같은 일이 되풀이되기 쉽습니다.","advice":"과소비나 과로, 지나친 말처럼 넘친 부분이 있다면 책임을 인정하고 지금부터 가능한 작은 한도를 다시 세워 보세요. 자책보다 재설계가 도움이 됩니다.","message":"넘친 뒤엔 탓하기보다 한도를 다시 세우세요."},{"guaN":60,"guaName":"수택절","pos":4,"label":"六四","yinyang":"yin","text":"安節 亨","reading":"안절 형","modern":"편안하게 절제하니 형통합니다.","meaning":"위 괘의 시작이자 윗자리 가까이에서 절제를 억지가 아니라 자연스러운 습관으로 받아들이는 장면입니다. 자리가 바르고 윗사람의 뜻과도 어긋나지 않습니다.","positive":"무리 없이 몸에 밴 절제는 오래 지속되고 일을 순조롭게 합니다.","caution":"익숙해진 방식에만 머물러 환경이 달라진 것을 놓치지 않도록 살펴야 합니다.","advice":"지금 편하게 지키고 있는 좋은 습관과 규칙이 있다면 그대로 이어 가세요. 환경이 바뀌면 그에 맞게 조금씩 조정하면 좋습니다.","message":"자연스러운 절제가 가장 오래갑니다."},{"guaN":60,"guaName":"수택절","pos":5,"label":"九五","yinyang":"yang","text":"甘節 吉 往有尙","reading":"감절 길 왕유상","modern":"달게 절제하니 길합니다. 나아가면 높이 평가받습니다.","meaning":"위 괘의 중심이자 핵심 자리에서 스스로 정한 절제를 기꺼이 따르며 이끄는 장면입니다. 높은 자리에서 먼저 모범을 보이니 사람들이 즐겁게 따릅니다.","positive":"스스로 기꺼이 지키는 기준이 주변의 신뢰와 존중을 불러올 수 있습니다.","caution":"내가 편한 기준을 남에게 그대로 강요하면 반발을 부를 수 있습니다.","advice":"기준을 정할 때는 내가 먼저 즐겁게 지킬 수 있는지 확인하고, 다른 사람에게도 이유를 설명해 공감을 얻어 보세요. 모범을 보이는 것이 가장 큰 설득이 됩니다.","message":"스스로 달게 지키는 절제가 사람을 이끕니다."},{"guaN":60,"guaName":"수택절","pos":6,"label":"上六","yinyang":"yin","text":"苦節 貞凶 悔亡","reading":"고절 정흉 회망","modern":"괴롭게 절제하니, 고집하면 흉합니다. 후회는 사라집니다.","meaning":"절제의 끝에서 지나치게 가혹하게 자신을 몰아붙이는 장면입니다. 그대로 고집하면 어려움이 따르지만, 지나침을 알고 늦추면 후회를 덜 수 있습니다.","positive":"엄격하게 지켜 온 경험은 한도를 다시 조정할 때 좋은 기준이 됩니다.","caution":"고통스러운 절제를 미덕으로 여기며 계속 밀어붙이면 몸과 관계가 상할 수 있습니다.","advice":"너무 힘들게 지키고 있는 규칙이 있다면 목적은 두되 방식은 완화해 보세요. 필요하면 전문가나 주변의 조언을 구하는 것도 도움이 됩니다.","message":"괴로운 절제는 한 걸음 늦추세요."}],"yong":null},"61":{"n":61,"name":"풍택중부","han":"風澤中孚","upper":"손","lower":"태","upperHan":"巽","lowerHan":"兌","bits":[1,1,0,0,1,1],"binary":"110011","gua":{"text":"豚魚吉 利涉大川 利貞","reading":"돈어길 리섭대천 리정","modern":"돼지와 물고기에게까지 미치는 믿음이니 길합니다. 큰 강을 건너는 것이 이롭고 곧고 바르게 함이 이롭습니다.","symbol":"위에는 바람(風), 아래에는 연못(澤)이 있어 바람이 물 위를 지나며 물결을 일으키듯 마음이 서로 감응하는 모습입니다. 가운데가 비어 진실한 믿음이 채워진 괘입니다.","situation":"신뢰와 진정성이 결과를 좌우하는 국면입니다. 기술이나 계산보다 정직한 마음과 꾸준한 약속 이행이 사람을 움직이기 쉽습니다. 믿음이 있으면 어려운 일도 함께 건널 수 있는 때입니다.","positive":"진심은 말이 통하기 어려운 상대에게도 전해져 관계를 열어 주는 힘이 됩니다.","caution":"믿음이 맹목적이 되어 바르지 않은 일까지 따르면 곧음이 흐려질 수 있습니다.","direction":"말보다 행동으로 약속을 지키며 신뢰를 쌓으세요. 믿음의 대상이 바른지 살피고, 마음을 열되 판단의 중심은 잃지 않는 편이 도움이 됩니다.","message":"진심은 꾸준한 행동으로 전해집니다."},"yao":[{"guaN":61,"guaName":"풍택중부","pos":1,"label":"初九","yinyang":"yang","text":"虞吉 有他不燕","reading":"우길 유타불연","modern":"헤아려 믿을 곳을 정하니 길합니다. 다른 마음이 생기면 편안하지 못합니다.","meaning":"믿음이 시작되는 자리에서 누구를 믿을지 차분히 헤아려 한곳에 마음을 두는 장면입니다. 멀리 위쪽의 호응을 바라보며 마음을 정하되, 다른 곳을 기웃거리면 불안해집니다.","positive":"처음에 믿을 대상과 기준을 분명히 하면 이후 관계가 안정됩니다.","caution":"이쪽저쪽을 재다 보면 마음이 갈려 편안하지 못할 수 있습니다.","advice":"중요한 관계나 협력을 시작할 때는 상대의 신뢰성을 천천히 확인한 뒤 한곳에 마음을 두고 성실하게 임해 보세요. 곁눈질로 불안을 키우지 않는 편이 좋습니다.","message":"믿을 곳은 신중히 정하고 한결같이 하세요."},{"guaN":61,"guaName":"풍택중부","pos":2,"label":"九二","yinyang":"yang","text":"鳴鶴在陰 其子和之 我有好爵 吾與爾靡之","reading":"명학재음 기자화지 아유호작 오여이미지","modern":"그늘에서 우는 학에게 새끼가 화답합니다. 내게 좋은 술잔이 있으니 그대와 함께 나누고 싶습니다.","meaning":"아래 괘의 중심에서 꾸밈없는 진심이 소리가 되어 멀리 있는 마음과 저절로 호응하는 장면입니다. 이익이 아니라 서로 나누려는 마음으로 이어진 관계입니다.","positive":"진솔한 마음은 조용히 있어도 뜻이 통하는 사람에게 닿는 힘이 있습니다.","caution":"마음이 통한 기쁨에만 머물러 현실적인 약속과 책임을 소홀히 하지 않도록 살펴야 합니다.","advice":"마음이 통하는 사람이 있다면 먼저 진솔하게 마음을 표현하고 가진 것을 나눠 보세요. 그 관계를 오래 유지할 작은 약속도 함께 정해 두면 좋습니다.","message":"진심의 소리에는 화답하는 이가 있습니다."},{"guaN":61,"guaName":"풍택중부","pos":3,"label":"六三","yinyang":"yin","text":"得敵 或鼓或罷 或泣或歌","reading":"득적 혹고혹파 혹읍혹가","modern":"맞서는 상대를 만나, 북을 치기도 하고 그만두기도 하며 울기도 하고 노래하기도 합니다.","meaning":"아래 괘의 끝에서 자리가 바르지 않고 마음의 중심을 상대의 반응에 맡겨 감정이 오르내리는 장면입니다. 상대의 태도에 따라 기뻤다 슬펐다 흔들립니다.","positive":"감정의 파도를 겪으며 내가 무엇에 기대고 있었는지 알아차릴 수 있습니다.","caution":"상대의 반응에 모든 기분을 걸면 마음이 계속 흔들려 판단이 어려워집니다.","advice":"상대의 반응에 따라 마음이 요동친다면 내 기준과 감정을 따로 적어 정리해 보세요. 신뢰할 수 있는 사람과 이야기를 나누면 균형을 되찾는 데 도움이 됩니다.","message":"기분을 상대에게만 맡기지 마세요."},{"guaN":61,"guaName":"풍택중부","pos":4,"label":"六四","yinyang":"yin","text":"月幾望 馬匹亡 无咎","reading":"월기망 마필망 무구","modern":"달이 거의 보름에 이르렀고, 짝이던 말이 떠나가니 허물이 없습니다.","meaning":"위 괘의 시작이자 높은 자리와 가까운 경계에서 거의 가득 찬 달처럼 신뢰가 무르익은 장면입니다. 사사로운 짝을 놓고 오직 윗자리의 뜻을 향해 나아가니 허물이 없습니다.","positive":"가까운 인연에 매이지 않고 더 큰 믿음을 따르면 신뢰가 깊어집니다.","caution":"가득 차기 직전의 때이니 지나치게 욕심내면 균형이 흔들릴 수 있습니다.","advice":"사사로운 인연이나 소소한 이해보다 공적인 신뢰와 큰 목표를 우선해 보세요. 아쉬움이 남더라도 정리할 관계는 담담히 정리하는 편이 좋습니다.","message":"사사로운 짝을 놓고 큰 믿음을 따르세요."},{"guaN":61,"guaName":"풍택중부","pos":5,"label":"九五","yinyang":"yang","text":"有孚攣如 无咎","reading":"유부련여 무구","modern":"믿음이 있어 서로 단단히 이어지니 허물이 없습니다.","meaning":"위 괘의 중심이자 핵심 자리에서 믿음으로 사람들을 묶어 내는 장면입니다. 가장 중심에 선 사람의 진심이 주변을 단단히 붙들어 줍니다.","positive":"믿음의 중심이 되면 많은 사람이 안정감을 느끼고 협력하기 쉬워집니다.","caution":"묶으려는 마음이 지나치면 서로를 얽어매는 부담이 될 수 있습니다.","advice":"맡은 책임을 성실히 이행해 구성원이 의지할 수 있는 중심이 되어 보세요. 신뢰를 붙들되 상대에게 숨 쉴 여유도 남겨 주면 좋습니다.","message":"믿음으로 이어 주되 얽매지는 마세요."},{"guaN":61,"guaName":"풍택중부","pos":6,"label":"上九","yinyang":"yang","text":"翰音登于天 貞凶","reading":"한음등우천 정흉","modern":"닭 울음소리가 하늘 높이 오르니, 고집하면 흉합니다.","meaning":"믿음의 끝에서 실속 없이 소리만 하늘에 닿는 장면입니다. 알맹이 없이 이름과 말만 앞서면 믿음이 속 빈 껍데기가 됩니다.","positive":"말과 현실의 간격을 확인하면 신뢰를 회복할 방향을 찾을 수 있습니다.","caution":"내용 없이 말만 부풀리고 그것을 고집하면 어려움이 따를 수 있습니다.","advice":"내가 한 말과 약속이 실제 행동으로 이어지고 있는지 점검해 보세요. 과장된 표현은 줄이고 지킬 수 있는 일부터 하나씩 실천하는 편이 좋습니다.","message":"말이 앞서면 믿음이 비어 갑니다."}],"yong":null},"62":{"n":62,"name":"뇌산소과","han":"雷山小過","upper":"진","lower":"간","upperHan":"震","lowerHan":"艮","bits":[0,0,1,1,0,0],"binary":"001100","gua":{"text":"亨 利貞 可小事 不可大事 飛鳥遺之音 不宜上 宜下 大吉","reading":"형 리정 가소사 불가대사 비조유지음 불의상 의하 대길","modern":"형통하고 곧고 바르게 함이 이롭습니다. 작은 일은 할 수 있으나 큰일은 할 수 없습니다. 나는 새가 소리를 남기니, 위로 오르는 것은 마땅치 않고 아래로 내려오는 것이 마땅하여 크게 길합니다.","symbol":"위에는 우레(雷), 아래에는 산(山)이 있어 산 위에서 천둥소리는 크지만 높이 솟지는 못하는 모습입니다. 조금 지나친 것이 알맞다는 뜻의 괘로, 낮고 작은 일에 힘쓸 때를 말합니다.","situation":"큰 도전이나 과시보다 작은 일을 겸손하고 세심하게 챙겨야 하는 국면입니다. 의욕은 크고 소리도 높지만 실제로 오를 수 있는 높이에는 한계가 있습니다. 일상과 기본을 다지는 데 힘을 쓰면 안정감을 얻기 쉬운 때입니다.","positive":"작은 일에서 정성을 다하고 낮은 자세를 지키면 신뢰와 안정을 쌓을 수 있습니다.","caution":"의욕이 앞서 큰일을 무리하게 벌이거나 높은 자리만 좇으면 기반이 흔들리기 쉽습니다.","direction":"큰 목표는 잠시 미루고 지금 할 수 있는 일부터 정확하게 마무리하세요. 공손함과 검소함, 신중함을 평소보다 조금 더 보태는 편이 도움이 됩니다.","message":"높이 오르기보다 낮고 작은 일에 힘쓰세요."},"yao":[{"guaN":62,"guaName":"뇌산소과","pos":1,"label":"初六","yinyang":"yin","text":"飛鳥以凶","reading":"비조이흉","modern":"날아오르려는 새이니 그로 인해 흉합니다.","meaning":"막 시작하는 자리에서 힘이 약한데도 높이 날아오르려 서두르는 장면입니다. 위의 호응에 이끌려 준비 없이 오르다 보면 어려움이 따릅니다.","positive":"서두름의 위험을 일찍 알아차리면 속도를 늦추고 기반을 다질 수 있습니다.","caution":"아직 날개가 자라지 않았는데 높이 오르려 하면 무리가 생겨 어려움이 따르기 쉽습니다.","advice":"의욕이 앞선다면 한 단계 낮은 목표로 나누어 먼저 기초를 다져 보세요. 주변의 기대나 유혹에 서둘러 응하기보다 내 준비 상태를 먼저 점검하는 것이 좋습니다.","message":"서두른 비상은 기반 없이 흔들립니다."},{"guaN":62,"guaName":"뇌산소과","pos":2,"label":"六二","yinyang":"yin","text":"過其祖 遇其妣 不及其君 遇其臣 无咎","reading":"과기조 우기비 불급기군 우기신 무구","modern":"할아버지를 지나쳐 할머니를 만나고, 임금에게는 미치지 못하고 신하를 만나니 허물이 없습니다.","meaning":"아래 괘의 중심에서 한 단계 높은 곳을 지나치려다 알맞은 자리에서 멈추고 자기 분수에 맞는 사람을 만나는 장면입니다. 무리해서 위로 가지 않고 제자리의 사람을 만나 허물을 피합니다.","positive":"욕심내지 않고 자기 위치에 맞는 만남을 택하면 마음이 편안합니다.","caution":"높은 곳으로 가지 못한 아쉬움에 분수를 넘으려는 마음이 생길 수 있습니다.","advice":"높은 사람이나 큰 기회를 직접 얻지 못하더라도 지금 곁에서 도움이 될 사람과 성실하게 협력해 보세요. 분수에 맞는 만남이 오히려 든든한 기반이 됩니다.","message":"분수에 맞는 만남이 길을 안전하게 합니다."},{"guaN":62,"guaName":"뇌산소과","pos":3,"label":"九三","yinyang":"yang","text":"弗過防之 從或戕之 凶","reading":"불과방지 종혹장지 흉","modern":"지나치지 않게 미리 막지 않으면, 따라오던 누군가 해칠 수 있으니 흉합니다.","meaning":"아래 괘의 끝에서 강한 자리에 있으면서 스스로 안전하다고 여겨 방비를 소홀히 하는 장면입니다. 곁에서 따르던 이들 속에서 뜻밖의 위험이 생길 수 있어 미리 살펴야 합니다.","positive":"경계심을 갖고 미리 대비하면 위험을 크게 줄일 수 있습니다.","caution":"자신의 강함을 믿고 방비를 놓으면 가까운 곳에서 예상치 못한 손해를 입기 쉽습니다.","advice":"잘 되고 있다고 느낄 때일수록 허술한 부분과 가까운 관계 속 위험 신호를 점검해 보세요. 작은 일도 기록과 확인 절차를 두는 편이 도움이 됩니다.","message":"믿는 때일수록 미리 대비하세요."},{"guaN":62,"guaName":"뇌산소과","pos":4,"label":"九四","yinyang":"yang","text":"无咎 弗過遇之 往厲必戒 勿用永貞","reading":"무구 불과우지 왕려필계 물용영정","modern":"허물이 없습니다. 지나치지 않고 알맞게 만납니다. 나아가면 위태로우니 반드시 경계해야 하며, 오래 고집하지는 마십시오.","meaning":"위 괘의 시작이자 윗자리 가까운 경계에서 강하게 나서지 않고 부드럽게 알맞은 선에서 만나는 장면입니다. 더 나아가면 위태로우니 조심하고, 한 방식만 오래 고집하지 않는 것이 필요합니다.","positive":"물러설 줄 아는 태도가 윗사람과 주변과의 충돌을 피하게 해 줍니다.","caution":"더 나아가려는 마음이 커지면 위태로움이 따르고 한 방식에 고집하면 유연성을 잃습니다.","advice":"지금은 앞으로 밀어붙이기보다 현재 위치에서 조심스럽게 관계를 맞춰 보세요. 상황이 바뀌면 방식도 바꿀 수 있도록 여지를 남겨 두는 것이 좋습니다.","message":"나서기보다 알맞은 선에서 멈추세요."},{"guaN":62,"guaName":"뇌산소과","pos":5,"label":"六五","yinyang":"yin","text":"密雲不雨 自我西郊 公弋取彼在穴","reading":"밀운불우 자아서교 공익취피재혈","modern":"구름은 빽빽하지만 비는 내리지 않으니 우리 서쪽 들에서 온 것입니다. 공이 줄 달린 화살로 굴속에 있는 이를 잡습니다.","meaning":"위 괘의 중심이자 핵심 자리에서 구름만 가득하고 아직 비가 되지 못하는 장면입니다. 능력이 부족해 큰일을 이루기 어려운 때, 높은 곳에서 호령하기보다 낮은 곳에 숨은 도움을 찾아 쓰는 모습입니다.","positive":"숨어 있는 인재와 조용한 도움을 알아보면 부족한 힘을 보완할 수 있습니다.","caution":"분위기와 준비는 가득한데 결실이 없다는 조급함에 무리하기 쉽습니다.","advice":"지금은 내 힘만으로 큰 결실을 내려 하기보다 곁에서 조용히 도울 사람을 찾아 협력해 보세요. 결과가 늦어지더라도 준비를 쌓아 가는 시간으로 삼는 편이 좋습니다.","message":"구름은 있어도 비가 되려면 때가 필요합니다."},{"guaN":62,"guaName":"뇌산소과","pos":6,"label":"上六","yinyang":"yin","text":"弗遇過之 飛鳥離之 凶 是謂災眚","reading":"불우과지 비조리지 흉 시위재생","modern":"만나야 할 곳을 만나지 못하고 지나쳐 버립니다. 높이 나는 새가 그물에 걸리니 흉합니다. 이를 재앙이라 합니다.","meaning":"지나침의 끝에서 알맞은 선을 넘어 너무 멀리 높이 날아가 버리는 장면입니다. 멈출 곳을 찾지 못한 채 계속 올라가다 스스로 위험에 빠지는 모습입니다.","positive":"지나침의 결과를 알아차리고 속도를 줄이면 피해를 줄일 수 있습니다.","caution":"이미 넘쳤는데도 더 높이, 더 멀리 가려 하면 큰 어려움이 따를 수 있습니다.","advice":"목표나 욕심이 지나치게 커졌다면 한 번 멈추고 현실의 한계와 비교해 보세요. 과한 행동은 되돌리고 낮은 곳에서 다시 안정을 찾는 편이 도움이 됩니다.","message":"넘치는 비상은 멈추고 내려와야 합니다."}],"yong":null},"63":{"n":63,"name":"수화기제","han":"水火旣濟","upper":"감","lower":"리","upperHan":"坎","lowerHan":"離","bits":[1,0,1,0,1,0],"binary":"101010","gua":{"text":"亨小 利貞 初吉終亂","reading":"형소 리정 초길종란","modern":"작은 일이 형통합니다. 곧고 바르게 함이 이롭습니다. 처음은 길하나 끝에는 어지러워집니다.","symbol":"위에는 물(水), 아래에는 불(火)이 있어 불 위에 물이 놓이니 서로 제자리를 얻어 어우러진 모습입니다. 이미 건넜다는 뜻처럼 일이 이루어지고 질서가 잡힌 괘입니다.","situation":"목표를 이루었거나 안정 단계에 이른 국면입니다. 모든 것이 제자리에 있어 보이지만 이럴 때 방심하면 작은 틈에서 어지러움이 생기기 쉽습니다. 성취를 지키고 점검하는 일이 중요한 때입니다.","positive":"질서가 갖춰져 있어 해 둔 일을 바탕으로 안정적으로 유지하고 다듬을 수 있습니다.","caution":"성취에 안주해 점검을 소홀히 하면 작은 균열이 큰 혼란으로 번질 수 있습니다.","direction":"이룬 것을 지키기 위한 점검 체계와 대비책을 미리 마련하세요. 겉치레보다 실속을 챙기고, 잘될 때 일어날 수 있는 문제를 한 번 상상해 보는 편이 도움이 됩니다.","message":"다 이뤘다고 느낄 때 점검을 시작하세요."},"yao":[{"guaN":63,"guaName":"수화기제","pos":1,"label":"初九","yinyang":"yang","text":"曳其輪 濡其尾 无咎","reading":"예기륜 유기미 무구","modern":"수레바퀴를 끌어 당겨 속도를 늦추고 꼬리를 적시니 허물이 없습니다.","meaning":"막 강을 건너기 시작하는 자리에서 서두르지 않고 수레바퀴를 붙잡아 속도를 늦추는 장면입니다. 의욕이 큰 시작에서 일부러 신중하게 내딛는 모습입니다.","positive":"속도를 조절하며 시작하면 큰 실수를 피하고 안정적으로 나아갈 수 있습니다.","caution":"성공이 눈앞이라는 기대에 서두르다 기반이 약해질 수 있습니다.","advice":"일이 잘 풀릴 때일수록 처음부터 속도를 조금 늦추고 기초를 점검해 보세요. 작은 시행착오는 배움으로 받아들이면 좋습니다.","message":"잘 풀릴 때일수록 속도를 조절하세요."},{"guaN":63,"guaName":"수화기제","pos":2,"label":"六二","yinyang":"yin","text":"婦喪其茀 勿逐 七日得","reading":"부상기불 물축 칠일득","modern":"부인이 수레의 가림막을 잃었으나 쫓아가지 않아도 칠 일이면 되찾습니다.","meaning":"아래 괘의 중심에서 바른 자리에 있지만 위의 호응이 곧바로 닿지 않아 소중한 것을 잠시 잃어버린 장면입니다. 조급히 쫓지 않고 기다리면 때가 되어 되돌아옵니다.","positive":"마음의 중심을 지키며 기다리면 잃은 것을 되찾을 가능성이 있습니다.","caution":"잃은 것에 집착해 서둘러 쫓다 보면 오히려 일이 더 꼬일 수 있습니다.","advice":"기회나 평판, 물건을 잠시 놓쳤다면 당황해서 쫓아다니기보다 내 중심을 지키며 차분히 기다려 보세요. 필요한 정리와 준비를 하면서 시간을 보내는 편이 좋습니다.","message":"잃은 것은 쫓지 말고 중심을 지키세요."},{"guaN":63,"guaName":"수화기제","pos":3,"label":"九三","yinyang":"yang","text":"高宗伐鬼方 三年克之 小人勿用","reading":"고종벌귀방 삼년극지 소인물용","modern":"고종이 귀방을 정벌하여 삼 년 만에 이겼습니다. 소인은 쓰지 마십시오.","meaning":"아래 괘의 끝이자 위로 넘어가는 전환기에서 오랜 시간과 힘이 드는 큰일을 치르는 장면입니다. 이룬 뒤에도 일을 벌이면 지치기 쉬우니 신중히 사람을 가려 써야 합니다.","positive":"끈기 있게 오래 노력하면 어려운 과제도 이뤄 낼 힘이 있습니다.","caution":"성과가 있다고 해서 무리하게 일을 벌이거나 사람을 잘못 쓰면 지치고 흔들리기 쉽습니다.","advice":"큰 과제를 오래 이어 가야 한다면 체력과 자원을 아끼며 단계를 나누어 보세요. 중요한 일은 그 일을 감당할 수 있는 사람에게 맡기는 편이 도움이 됩니다.","message":"큰일은 길게 보고 사람을 가려 쓰세요."},{"guaN":63,"guaName":"수화기제","pos":4,"label":"六四","yinyang":"yin","text":"繻有衣袽 終日戒","reading":"수유의녀 종일계","modern":"배에 물이 새면 막을 비단 옷과 헌 옷 조각이 있어도 하루 종일 경계합니다.","meaning":"위 괘의 시작이자 높은 자리와 가까운 경계에서 일이 잘되는 가운데도 작은 틈이 생길 수 있음을 알고 대비하는 장면입니다. 새는 곳을 막을 천을 갖추고 종일 살핍니다.","positive":"미리 대비하고 경계하는 습관이 큰 문제를 막아 줍니다.","caution":"대비가 지나쳐 불안이 커지면 마음이 지치고 판단이 흐려질 수 있습니다.","advice":"안정된 때일수록 작은 문제의 신호를 놓치지 않도록 정기 점검 시간을 정해 보세요. 대비는 하되 불안에 매이지 않도록 점검 목록을 만들어 두면 좋습니다.","message":"작은 틈을 살피는 습관이 큰 배를 지킵니다."},{"guaN":63,"guaName":"수화기제","pos":5,"label":"九五","yinyang":"yang","text":"東鄰殺牛 不如西鄰之禴祭 實受其福","reading":"동린살우 불여서린지약제 실수기복","modern":"동쪽 이웃이 소를 잡아 크게 제사하는 것이 서쪽 이웃의 간소한 제사만 못하니, 실제로 복을 받는 것은 서쪽 이웃입니다.","meaning":"위 괘의 중심이자 핵심 자리에서 성대한 겉치레보다 정성이 담긴 소박함이 낫다는 장면입니다. 이미 이룬 자리에서 과시를 늘리기보다 진심을 지키는 것이 중요합니다.","positive":"형식보다 정성에 힘쓰면 적은 자원으로도 좋은 결과를 얻을 수 있습니다.","caution":"이룬 것을 과시하려는 마음이 커지면 알맹이보다 겉모양에 힘이 쏠리기 쉽습니다.","advice":"성과를 드러내는 일에 많은 비용을 쓰기보다 실제로 필요한 곳에 정성을 쏟아 보세요. 기본과 진심을 지키는 방향으로 자원을 쓰는 편이 도움이 됩니다.","message":"겉치레보다 정성이 복을 부릅니다."},{"guaN":63,"guaName":"수화기제","pos":6,"label":"上六","yinyang":"yin","text":"濡其首 厲","reading":"유기수 려","modern":"머리까지 적시니 위태롭습니다.","meaning":"건너는 일의 끝에서 강에 머리까지 빠진 장면입니다. 이미 이룬 일에 취해 끝까지 나아가다 멈출 곳을 놓치면 위태로울 수 있습니다.","positive":"위태로움을 느끼는 순간이 방향을 바꾸고 안전을 확보할 기회가 됩니다.","caution":"성취의 끝에서 더 멀리 가려 하면 이미 쌓은 것까지 위험해질 수 있습니다.","advice":"이룬 것에 만족하고 더 크게 밀어붙이는 일이 있다면 한 번 멈춰 위험 요소를 점검해 보세요. 필요하다면 발을 물에서 빼고 안전한 곳에서 다시 시작하는 선택도 도움이 됩니다.","message":"이룬 뒤에는 멈출 줄도 알아야 합니다."}],"yong":null},"64":{"n":64,"name":"화수미제","han":"火水未濟","upper":"리","lower":"감","upperHan":"離","lowerHan":"坎","bits":[0,1,0,1,0,1],"binary":"010101","gua":{"text":"亨 小狐汔濟 濡其尾 无攸利","reading":"형 소호흘제 유기미 무유리","modern":"형통합니다. 어린 여우가 거의 다 건너다 꼬리를 적시니 이로울 바가 없습니다.","symbol":"위에는 불(火), 아래에는 물(水)이 있어 불은 위로 물은 아래로 향하며 서로 어긋나 있는 모습입니다. 아직 건너지 못한 미완성의 괘이자 다시 시작되는 변화의 가능성을 담고 있습니다.","situation":"목표가 가까워졌지만 아직 완결되지 않은 국면입니다. 마지막 단계에서 방심하거나 서두르면 어렵게 쌓은 것이 흐트러지기 쉽습니다. 마무리에 집중하며 다음 순환을 준비하는 때입니다.","positive":"아직 이루어지지 않았다는 것은 바로잡고 새로 시도할 여지가 남아 있다는 뜻이기도 합니다.","caution":"거의 끝났다는 마음에 마지막 단계에서 서두르거나 방심하면 힘들게 이룬 일이 흐트러질 수 있습니다.","direction":"남은 일을 목록으로 정리하고 완료 기준을 분명히 하세요. 각 요소를 제자리에 놓으며 차분히 마무리하고, 끝을 다음 시작의 출발점으로 삼는 편이 도움이 됩니다.","message":"마무리가 가까울수록 더 차분하게 하세요."},"yao":[{"guaN":64,"guaName":"화수미제","pos":1,"label":"初六","yinyang":"yin","text":"濡其尾 吝","reading":"유기미 린","modern":"꼬리를 적시니 아쉬움이 있습니다.","meaning":"건너기 시작하는 자리에서 힘과 준비가 부족한 채로 강물에 뛰어들어 꼬리를 적시는 장면입니다. 위의 호응을 믿고 앞뒤를 재지 않고 나선 탓에 아쉬운 결과가 따릅니다.","positive":"초기의 실수를 통해 준비가 부족한 부분을 일찍 알아차릴 수 있습니다.","caution":"역량을 헤아리지 않고 서두르면 시작부터 막혀 아쉬움이 남기 쉽습니다.","advice":"첫 시도에서 부족함이 드러났다면 자책하기보다 어디서 막혔는지 정리해 보세요. 다시 시작하기 전에 준비와 순서를 한 번 더 점검하는 편이 도움이 됩니다.","message":"준비 없는 첫걸음은 아쉬움을 남깁니다."},{"guaN":64,"guaName":"화수미제","pos":2,"label":"九二","yinyang":"yang","text":"曳其輪 貞吉","reading":"예기륜 정길","modern":"수레바퀴를 끌어 당겨 속도를 늦추니, 곧고 바르게 하면 길합니다.","meaning":"아래 괘의 중심에서 강한 힘이 있으면서도 수레바퀴를 붙잡아 속도를 조절하는 장면입니다. 자리가 바르지 않아도 중심을 지키며 때를 기다리면 길합니다.","positive":"힘이 있어도 속도를 조절하는 절제가 안정적인 진행을 돕습니다.","caution":"너무 오래 속도를 늦추다 기회를 놓치지 않도록 살펴야 합니다.","advice":"의욕이 크더라도 일의 속도와 순서를 조절하며 때를 기다려 보세요. 큰 힘을 쓸 시점을 가늠하며 준비를 이어 가는 편이 좋습니다.","message":"힘이 있을수록 속도를 다스리세요."},{"guaN":64,"guaName":"화수미제","pos":3,"label":"六三","yinyang":"yin","text":"未濟 征凶 利涉大川","reading":"미제 정흉 리섭대천","modern":"아직 건너지 못한 때이니 그대로 나아가면 흉하나, 큰 강을 건너는 것은 이롭습니다.","meaning":"아래 괘의 끝에서 자리가 바르지 않은 채 강 한복판에 서 있는 장면입니다. 지금 방식 그대로 서둘러 나아가면 어려움이 따르지만, 준비를 갖추고 힘을 모아 건너면 이로움이 있습니다.","positive":"전환기에 서 있어 방식을 바꾸고 새로운 도움을 얻으면 큰일을 건널 수 있습니다.","caution":"준비되지 않은 채로 정면 돌파를 시도하면 어려움이 따르기 쉽습니다.","advice":"지금의 방식으로 계속 밀어붙이기보다 필요한 도구와 협력자를 갖춘 뒤 건널 방법을 다시 설계해 보세요. 시점과 방법을 바꾸는 선택이 도움이 됩니다.","message":"그대로 가기보다 방법을 바꾸어 건너세요."},{"guaN":64,"guaName":"화수미제","pos":4,"label":"九四","yinyang":"yang","text":"貞吉 悔亡 震用伐鬼方 三年有賞于大國","reading":"정길 회망 진용벌귀방 삼년유상우대국","modern":"곧고 바르게 하면 길하고 후회가 사라집니다. 떨쳐 일어나 귀방을 정벌하여 삼 년 뒤에 큰 나라에서 상을 받습니다.","meaning":"위 괘의 시작이자 높은 자리와 가까운 경계에서 어둠을 벗어나 큰일에 떨쳐 나서는 장면입니다. 오랜 노력이 필요하지만 바른 뜻을 지켜 가면 인정받을 가능성이 열립니다.","positive":"굳은 의지와 끈기로 긴 시간을 견디면 보람과 인정을 얻을 수 있습니다.","caution":"곧 결실이 올 것이라는 기대에 조급해지면 지치거나 방향을 잃기 쉽습니다.","advice":"긴 호흡의 과제라면 단계별 목표를 세우고 바른 방향을 지키며 꾸준히 나아가 보세요. 결과가 나오기까지 시간이 걸린다는 점을 염두에 두면 마음이 한결 편합니다.","message":"바른 뜻으로 오래 가면 보람이 따릅니다."},{"guaN":64,"guaName":"화수미제","pos":5,"label":"六五","yinyang":"yin","text":"貞吉 无悔 君子之光 有孚 吉","reading":"정길 무회 군자지광 유부 길","modern":"곧고 바르게 하면 길하고 후회가 없습니다. 군자의 빛이 있고 믿음이 있으니 길합니다.","meaning":"위 괘의 중심이자 핵심 자리에서 겸손하고 밝은 덕으로 주변의 믿음을 얻는 장면입니다. 아직 완성은 아니어도 중심이 바르고 신뢰가 있어 일이 밝게 풀립니다.","positive":"투명하고 진실한 태도가 사람들의 신뢰와 협력을 이끌어 냅니다.","caution":"빛이 밝다고 자만하면 마지막 점검을 놓칠 수 있습니다.","advice":"내 판단과 행동이 투명하고 진실한지 점검하며 사람들의 신뢰를 지켜 가세요. 성과가 가까워질수록 겸손하게 주변의 의견을 듣는 편이 도움이 됩니다.","message":"밝은 마음과 믿음이 일을 빛나게 합니다."},{"guaN":64,"guaName":"화수미제","pos":6,"label":"上九","yinyang":"yang","text":"有孚于飲酒 无咎 濡其首 有孚失是","reading":"유부우음주 무구 유기수 유부실시","modern":"믿음을 지니고 술을 마시며 즐기면 허물이 없으나, 머리를 적실 만큼 빠지면 믿음이 있어도 옳음을 잃습니다.","meaning":"미완성의 끝에서 오랜 노력 뒤의 여유를 즐기는 장면입니다. 절제하며 즐기면 허물이 없지만 지나치게 취하면 믿음과 판단을 잃어 모처럼 얻은 것까지 흔들립니다.","positive":"긴 과정을 마친 뒤 여유를 누리는 시간은 다음 순환을 위한 힘을 줍니다.","caution":"마무리의 안도감에 지나치게 빠지면 올바른 판단을 놓칠 수 있습니다.","advice":"일을 마친 뒤에는 적당히 쉬고 즐기되 절제할 선을 정해 두세요. 끝을 새로운 시작의 준비 시간으로 삼아 다음 목표를 가볍게 구상해 보세요.","message":"끝의 여유도 절제 속에서 누리세요."}],"yong":null}}};
